					local tbl16 = tbl7.WaterPartStates[child]

					if arg and not tbl16 then
						tbl16 = { child.CanCollide, child.Transparency }
						tbl7.WaterPartStates[child] = tbl16
					end

					if arg then
						child.CanCollide = true

						if child.Transparency ~= 1 and tbl16[2] ~= 1 then
