						end
					elseif tbl16 then
						child.CanCollide = tbl16[1]
						local transparency

						if toggles.CustomWaterT and toggles.CustomWaterT.Value then
							transparency = 1
						else
							transparency = tbl16[2]
						end

						child.Transparency = transparency

						if not (toggles.CustomWaterT and toggles.CustomWaterT.Value) then
