			local function _uniCharacterRoot()
				local _char = _uniLocalPlayer.Character
				return _char and (_char:FindFirstChild("HumanoidRootPart") or _char:FindFirstChild("Torso"))
			end

			local function _uniMakePart(_parent, _name, _size, _cf, _color, _material, _shape, _collide, _query)
				local _part = Instance.new("Part")
				_part.Name = _name
				_part.Size = _size
				_part.CFrame = _cf
				_part.Anchored = true
				_part.CanCollide = _collide == true
				_part.CanTouch = false
				_part.CanQuery = _query ~= false
				_part.Material = _material or Enum.Material.SmoothPlastic
				_part.Color = _color or Color3.fromRGB(180, 180, 180)
				_part.TopSurface = Enum.SurfaceType.Smooth
				_part.BottomSurface = Enum.SurfaceType.Smooth
				if _shape then _part.Shape = _shape end
				_part.Parent = _parent
				return _part
			end

			local function _uniMapOrigin(_name)
				local _root = _uniCharacterRoot()
				local _p = _root and _root.Position or Vector3.new(0, 10, 0)
				if _name == "Forest" then return _p + Vector3.new(0, 0, 520) end
				if _name == "Beach" then return _p + Vector3.new(520, 0, 0) end
				return _p + Vector3.new(-520, 0, 0)
			end

			local function _uniBuildForest(_folder, _center)
				_uniMakePart(_folder, "ForestGround", Vector3.new(360, 4, 360), CFrame.new(_center.X, _center.Y - 4, _center.Z), Color3.fromRGB(66, 111, 53), Enum.Material.Grass, nil, true, false)
				for _i = 1, 28 do
					local _angle = (_i / 28) * math.pi * 2
					local _radius = 80 + ((_i % 4) * 18)
					local _x = _center.X + math.cos(_angle) * _radius
					local _z = _center.Z + math.sin(_angle) * _radius
					local _height = 18 + ((_i * 7) % 18)
					_uniMakePart(_folder, "TreeTrunk", Vector3.new(_height, 5, 5), CFrame.new(_x, _center.Y + _height / 2 - 2, _z) * CFrame.Angles(0, 0, math.rad(90)), Color3.fromRGB(91, 59, 35), Enum.Material.Wood, Enum.PartType.Cylinder, false, false)
					_uniMakePart(_folder, "TreeCanopy", Vector3.new(20, 20, 20), CFrame.new(_x, _center.Y + _height + 4, _z), Color3.fromRGB(41 + (_i % 3) * 8, 105 + (_i % 4) * 6, 48), Enum.Material.Grass, Enum.PartType.Ball, false, false)
					_uniMakePart(_folder, "TreeCanopySmall", Vector3.new(14, 14, 14), CFrame.new(_x + 7, _center.Y + _height + 3, _z - 4), Color3.fromRGB(43, 126, 54), Enum.Material.Grass, Enum.PartType.Ball, false, false)
				end
				for _i = 1, 18 do
					local _x = _center.X + math.cos(_i * 2.4) * (30 + (_i % 5) * 15)
					local _z = _center.Z + math.sin(_i * 2.4) * (30 + (_i % 5) * 15)
					_uniMakePart(_folder, "ForestRock", Vector3.new(4 + (_i % 3) * 2, 3 + (_i % 2) * 2, 5 + (_i % 4)), CFrame.new(_x, _center.Y - 1, _z), Color3.fromRGB(90, 96, 87), Enum.Material.Slate, Enum.PartType.Ball, true, false)
				end
			end

			local function _uniBuildBeach(_folder, _center)
				_uniMakePart(_folder, "BeachSand", Vector3.new(360, 4, 360), CFrame.new(_center.X, _center.Y - 4, _center.Z), Color3.fromRGB(224, 203, 145), Enum.Material.Sand, nil, true, false)
				local _water = _uniMakePart(_folder, "BeachWater", Vector3.new(160, 1, 350), CFrame.new(_center.X + 98, _center.Y - 1.5, _center.Z), Color3.fromRGB(44, 156, 205), Enum.Material.Water, nil, false, false)
				_water.Transparency = 0.28
				for _i = 1, 12 do
					local _angle = (_i / 12) * math.pi * 2
					local _x = _center.X + math.cos(_angle) * (72 + (_i % 3) * 15)
					local _z = _center.Z + math.sin(_angle) * (72 + (_i % 3) * 15)
					_uniMakePart(_folder, "PalmTrunk", Vector3.new(24, 4, 4), CFrame.new(_x, _center.Y + 9, _z) * CFrame.Angles(0, 0, math.rad(90)), Color3.fromRGB(129, 89, 49), Enum.Material.Wood, Enum.PartType.Cylinder, false, false)
					for _j = 1, 5 do
						local _fa = _j * (math.pi * 2 / 5)
						_uniMakePart(_folder, "PalmLeaf", Vector3.new(15, 2, 4), CFrame.new(_x + math.cos(_fa) * 8, _center.Y + 23, _z + math.sin(_fa) * 8) * CFrame.Angles(0, -_fa, math.rad(18)), Color3.fromRGB(43, 121, 57), Enum.Material.Grass, nil, false, false)
					end
				end
				for _i = 1, 4 do
					local _x = _center.X - 70 + _i * 35
					local _z = _center.Z + 45
					_uniMakePart(_folder, "UmbrellaPole", Vector3.new(9, 1, 1), CFrame.new(_x, _center.Y + 2, _z) * CFrame.Angles(0, 0, math.rad(90)), Color3.fromRGB(245, 245, 245), Enum.Material.Metal, Enum.PartType.Cylinder, false, false)
					local _umb = _uniMakePart(_folder, "BeachUmbrella", Vector3.new(12, 3, 12), CFrame.new(_x, _center.Y + 7, _z), ({Color3.fromRGB(225, 75, 70), Color3.fromRGB(68, 142, 222), Color3.fromRGB(249, 218, 95), Color3.fromRGB(120, 190, 120)})[_i], Enum.Material.Fabric, Enum.PartType.Ball, false, false)
					_uniMakePart(_folder, "BeachChair", Vector3.new(5, 1, 9), CFrame.new(_x + 8, _center.Y - 1, _z + 12) * CFrame.Angles(math.rad(-8), 0, 0), Color3.fromRGB(235, 230, 216), Enum.Material.SmoothPlastic, nil, false, false)
				end
			end

			local function _uniSpawnAimTarget(_folder, _center)
				local _targets = _folder:FindFirstChild("Targets")
				if not _targets then return end
				local _x = _center.X + math.random(-70, 70)
				local _y = _center.Y + 8 + math.random(0, 34)
				local _z = _center.Z - 50
				local _target = _uniMakePart(_targets, "AimTarget", Vector3.new(6, 6, 6), CFrame.new(_x, _y, _z), Color3.fromRGB(255, 74, 80), Enum.Material.Neon, Enum.PartType.Ball, false, true)
				_target:SetAttribute("UniAimTarget", true)
				_target:SetAttribute("SpawnedAt", os.clock())
				return _target
			end

			local function _uniBuildAim(_folder, _center)
				_uniMakePart(_folder, "AimGround", Vector3.new(220, 4, 180), CFrame.new(_center.X, _center.Y - 4, _center.Z), Color3.fromRGB(45, 48, 58), Enum.Material.Metal, nil, true, false)
				local _wall = _uniMakePart(_folder, "AimBackWall", Vector3.new(180, 38, 2), CFrame.new(_center.X, _center.Y + 17, _center.Z - 75), Color3.fromRGB(36, 40, 52), Enum.Material.Metal, nil, true, false)
				_wall.CanQuery = false
				for _i = 1, 8 do
					local _x = _center.X - 77 + (_i - 1) * 22
					_uniMakePart(_folder, "TargetStand", Vector3.new(2, 10, 2), CFrame.new(_x, _center.Y + 1, _center.Z - 59), Color3.fromRGB(82, 86, 99), Enum.Material.Metal, nil, false, false)
				end
				local _targets = Instance.new("Folder")
				_targets.Name = "Targets"
				_targets.Parent = _folder
				_uniAimTargets = _targets
				for _i = 1, 10 do _uniSpawnAimTarget(_folder, _center) end
				if _uniAimInputConn then pcall(function() _uniAimInputConn:Disconnect() end) end
				_uniAimInputConn = _uniInput.InputBegan:Connect(function(_input, _processed)
					if _processed or not _uniAimTargets or not _uniAimTargets.Parent then return end
					local _isMouse = _input.UserInputType == Enum.UserInputType.MouseButton1
					local _isTouch = _input.UserInputType == Enum.UserInputType.Touch
					if not _isMouse and not _isTouch then return end
					local _camera = _uniWorkspace.CurrentCamera
					if not _camera then return end
					local _pos = _isTouch and Vector2.new(_input.Position.X, _input.Position.Y) or _uniInput:GetMouseLocation()
					local _ray = _camera:ViewportPointToRay(_pos.X, _pos.Y)
					local _params = RaycastParams.new()
					_params.FilterType = Enum.RaycastFilterType.Include
					_params.FilterDescendantsInstances = {_uniAimTargets}
					local _result = _uniWorkspace:Raycast(_ray.Origin, _ray.Direction * 1000, _params)
					if _result and _result.Instance and _result.Instance:GetAttribute("UniAimTarget") then
						local _hit = _result.Instance
						if os.clock() - _uniAimLastHit < 0.08 then return end
						_uniAimLastHit = os.clock()
						_uniAimHits += 1
						local _parent = _hit.Parent and _hit.Parent.Parent
						local _map = _uniMaps["Aim Training"]
						local _centerNow = _uniCenters["Aim Training"]
						_hit:Destroy()
						if _map and _centerNow then task.delay(0.2, function() if _uniMaps["Aim Training"] then _uniSpawnAimTarget(_map, _centerNow) end end) end
						if _uniAimHits % 5 == 0 then _uniNotify("Aim hits: " .. tostring(_uniAimHits), "Aim Training") end
					end
				end)
			end

			local function _uniBuildMap(_name)
				if _uniMaps[_name] and _uniMaps[_name].Parent then return true end
				local _center = _uniMapOrigin(_name)
				local _folder = Instance.new("Folder")
				_folder.Name = _name:gsub("%s+", "")
				_folder.Parent = _uniRoot
				_uniMaps[_name] = _folder
				_uniCenters[_name] = _center
				if _name == "Forest" then _uniBuildForest(_folder, _center)
				elseif _name == "Beach" then _uniBuildBeach(_folder, _center)
				else _uniBuildAim(_folder, _center) end
				_uniActiveMap = _name
				_uniNotify(_name .. " map built locally.", "Practice Lab")
				return true
			end

			local function _uniClearMap(_name)
				local _folder = _uniMaps[_name]
				if _folder then pcall(function() _folder:Destroy() end) end
				_uniMaps[_name] = nil
				_uniCenters[_name] = nil
				if _name == "Aim Training" then
					_uniAimTargets = nil
					if _uniAimInputConn then pcall(function() _uniAimInputConn:Disconnect() end) _uniAimInputConn = nil end
				end
				if _uniActiveMap == _name then _uniActiveMap = nil end
			end

			local function _uniTeleport(_name)
				local _folder = _uniMaps[_name]
				local _center = _uniCenters[_name]
				if not _folder or not _center then _uniNotify("Load the " .. _name .. " map first.", "Practice Lab") return end
				local _root = _uniCharacterRoot()
				if not _root then _uniNotify("Character root part is not ready.", "Practice Lab") return end
				if not _uniSavedCFrame then _uniSavedCFrame = _root.CFrame end
				if _name == "Aim Training" then
					_root.CFrame = CFrame.lookAt(_center + Vector3.new(0, 4, 55), _center + Vector3.new(0, 8, -55))
				else
					_root.CFrame = CFrame.new(_center + Vector3.new(0, 5, 0))
				end
				_uniActiveMap = _name
				_uniNotify("Teleported to " .. _name .. ".", "Practice Lab")
			end

			local function _uniUnloadAll()
				_uniClearMap("Forest")
				_uniClearMap("Beach")
				_uniClearMap("Aim Training")
			end

			_uniMapBox:AddToggle("UniForestMap", { Text = "Load Forest Map", Default = false, Callback = function(_v) if _v then _uniBuildMap("Forest") else _uniClearMap("Forest") end end })
			_uniMapBox:AddToggle("UniBeachMap", { Text = "Load Beach Map", Default = false, Callback = function(_v) if _v then _uniBuildMap("Beach") else _uniClearMap("Beach") end end })
