			_uniMapBox:AddButton({ Text = "Return to Saved Position", Func = function() local _root = _uniCharacterRoot() if _root and _uniSavedCFrame then _root.CFrame = _uniSavedCFrame _uniSavedCFrame = nil else _uniNotify("No saved position is available.", "Practice Lab") end end })
			_uniMapBox:AddButton({ Text = "Unload All Local Maps", Func = function() _uniUnloadAll() if toggles.UniForestMap then toggles.UniForestMap:SetValue(false) end if toggles.UniBeachMap then toggles.UniBeachMap:SetValue(false) end if toggles.UniAimMap then toggles.UniAimMap:SetValue(false) end _uniNotify("All local maps removed.", "Practice Lab") end })

			_uniPracticeBox:AddButton({ Text = "Reset Aim Hits", Func = function() _uniAimHits = 0 _uniNotify("Aim hit counter reset.", "Aim Training") end })
			local _uniBestKickLoop = false
			local _uniKickLoopGeneration = 0
			_uniPracticeBox:AddToggle("UniBestKickLoop", { Text = "BestKickLoop (Training Targets Only)", Default = false, Callback = function(_v)
				_uniBestKickLoop = _v
				_uniKickLoopGeneration += 1
				local _generation = _uniKickLoopGeneration
				if not _v then return end
				if not (_uniMaps["Aim Training"] and _uniMaps["Aim Training"]:FindFirstChild("Targets")) then
					_uniBestKickLoop = false
					if toggles.UniBestKickLoop then toggles.UniBestKickLoop:SetValue(false) end
					_uniNotify("Load Aim Training first.", "Aim Training")
					return
				end
				_uniNotify("BestKickLoop practice started on local targets only.", "Aim Training")
				task.spawn(function()
					local _phase = 0
					while _uniBestKickLoop and _generation == _uniKickLoopGeneration do
						_phase += 0.18
						local _folder = _uniMaps["Aim Training"]
						local _targets = _folder and _folder:FindFirstChild("Targets")
						if not _targets then break end
						for _i, _target in ipairs(_targets:GetChildren()) do
							if _target:IsA("BasePart") then
								local _baseY = _target:GetAttribute("UniBaseY")
								if not _baseY then _baseY = _target.Position.Y _target:SetAttribute("UniBaseY", _baseY) end
								_target.Position = Vector3.new(_target.Position.X, _baseY + math.abs(math.sin(_phase + _i)) * 12, _target.Position.Z)
							end
						end
						task.wait(0.08)
					end
				end)
			end })
			_uniPracticeBox:AddButton({ Text = "BlobKill Test (Targets Only)", Func = function()
				local _folder = _uniMaps["Aim Training"]
				local _center = _uniCenters["Aim Training"]
				if not _folder or not _center then _uniNotify("Load Aim Training first.", "Aim Training") return end
				local _targets = _folder:FindFirstChild("Targets")
				if _targets then for _, _target in ipairs(_targets:GetChildren()) do _target:Destroy() end end
				for _i = 1, 10 do _uniSpawnAimTarget(_folder, _center) end
				_uniNotify("Practice targets reset. No players or server objects were affected.", "Aim Training")
			end })
			_uniPracticeBox:AddButton({ Text = "RagdollKill Test (Targets Only)", Func = function()
				local _folder = _uniMaps["Aim Training"]
				if not _folder then _uniNotify("Load Aim Training first.", "Aim Training") return end
