			local function _uniStopDance(_slot)
				local _track = _uniDanceTracks[_slot]
				if _track then pcall(function() _track:Stop(0.15) _track:Destroy() end) end
				_uniDanceTracks[_slot] = nil
				local _animation = _uniDanceAnimations[_slot]
				if _animation then pcall(function() _animation:Destroy() end) end
				_uniDanceAnimations[_slot] = nil
			end
			local function _uniPlayDance(_slot, _style)
				_uniStopDance(_slot)
				local _character = _uniLocalPlayer.Character
				local _humanoid = _character and _character:FindFirstChildOfClass("Humanoid")
				if not _humanoid then _uniNotify("Character is not ready for animation.", "Dance") return end
				local _animator = _humanoid:FindFirstChildOfClass("Animator")
				if not _animator then _animator = Instance.new("Animator") _animator.Parent = _humanoid end
				local _anim = Instance.new("Animation")
				_anim.AnimationId = "rbxassetid://" .. tostring(_uniDanceIds[_style] or _uniDanceIds["Dance 1"])
				local _ok, _track = pcall(function() return _animator:LoadAnimation(_anim) end)
				if not _ok or not _track then _anim:Destroy() _uniNotify("Dance animation could not be loaded in this game.", "Dance") return end
				_track.Looped = true
				_track.Priority = Enum.AnimationPriority.Action
				_uniDanceAnimations[_slot] = _anim
				_uniDanceTracks[_slot] = _track
				_track:Play(0.15)
			end
			_uniDanceBox:AddDropdown("UniDanceV1Style", { Text = "Dance V1 Style", Values = { "Dance 1", "Dance 2", "Dance 3" }, Default = 1, Multi = false, Callback = function(_v) _uniDanceV1Style = _v if _uniDanceV1On then _uniPlayDance("V1", _v) end end })
			_uniDanceBox:AddToggle("UniDanceV1Toggle", { Text = "Dance V1", Default = false, Callback = function(_v) _uniDanceV1On = _v if _v then _uniPlayDance("V1", _uniDanceV1Style) else _uniStopDance("V1") end end })
			_uniDanceBox:AddDropdown("UniDanceV2Style", { Text = "Dance V2 Style", Values = { "Dance 1", "Dance 2", "Dance 3" }, Default = 2, Multi = false, Callback = function(_v) _uniDanceV2Style = _v if _uniDanceV2On then _uniPlayDance("V2", _v) end end })
			_uniDanceBox:AddToggle("UniDanceV2Toggle", { Text = "Dance V2", Default = false, Callback = function(_v) _uniDanceV2On = _v if _v then _uniPlayDance("V2", _uniDanceV2Style) else _uniStopDance("V2") end end })
			_uniDanceBox:AddToggle("UniRobotMeLocal", { Text = "Robot Me (Local Dance 3)", Default = false, Callback = function(_v) if _v then _uniPlayDance("Robot", "Dance 3") else _uniStopDance("Robot") end end })
			_uniLocalPlayer.CharacterAdded:Connect(function()
				task.wait(0.8)
				if _uniDanceV1On then _uniPlayDance("V1", _uniDanceV1Style) end
				if _uniDanceV2On then _uniPlayDance("V2", _uniDanceV2Style) end
				if toggles.UniRobotMeLocal and toggles.UniRobotMeLocal.Value then _uniPlayDance("Robot", "Dance 3") end
			end)

			local function _uniReadPing()
				local _stats = game:GetService("Stats")
				local _network = _stats:FindFirstChild("Network")
				local _server = _network and _network:FindFirstChild("ServerStatsItem")
				local _dataPing = _server and _server:FindFirstChild("Data Ping")
				if not _dataPing then return nil end
				local _ok, _value = pcall(function() return _dataPing:GetValue() end)
				return _ok and tonumber(_value) or nil
			end
			local function _uniStartMonitor()
				_uniMonitorTask += 1
				local _generation = _uniMonitorTask
				task.spawn(function()
					local _pingWarned = false
					local _lineWarned = false
					while _generation == _uniMonitorTask and (_uniPacketMonitor or _uniLineMonitor) do
						if _uniPacketMonitor then
							local _ping = _uniReadPing()
							if _ping and _ping >= 250 and not _pingWarned then _uniNotify("High client ping: " .. math.floor(_ping) .. " ms", "Packet Lag Monitor") _pingWarned = true end
							if _ping and _ping < 200 then _pingWarned = false end
						end
						if _uniLineMonitor then
							local _grabParts = _uniWorkspace:FindFirstChild("GrabParts")
							local _hasLine = _grabParts ~= nil
							if _hasLine and not _lineWarned then _uniNotify("A grab-line object is present locally.", "Line Lag Monitor") _lineWarned = true end
							if not _hasLine then _lineWarned = false end
						end
						task.wait(1)
					end
				end)
			end
			_uniMonitorBox:AddToggle("UniPacketLagMonitor", { Text = "Packet Lag Monitor (Local)" , Default = false, Callback = function(_v) _uniPacketMonitor = _v _uniStartMonitor() end })
			_uniMonitorBox:AddToggle("UniLineLagMonitor", { Text = "Line Lag Monitor (Local)", Default = false, Callback = function(_v) _uniLineMonitor = _v _uniStartMonitor() end })
			_uniMonitorBox:AddButton({ Text = "Enable RSC Shaders", Func = function() if toggles.ShadersT then toggles.ShadersT:SetValue(true) else _uniNotify("Open the Visual tab and enable Shaders there.", "Shaders") end end })
		end
		-- ===== End unified local sandbox additions =====

	fn18("Script loaded in " .. math.round((tick() - getgenv().LoadTime) * 100) / 100 .. " seconds", "Resonance", 71450094482101)
	getgenv().LoadTime = nil

	return {
		copyright = "Copyright (c) 2026 Project Resonance. All rights reserved.",
	}
end
]====]
sources.Bootstrap = [====[
local sources = ...
local env = getgenv and getgenv() or _G
if env.ResonanceRunning or env.ResonanceStarting then
    warn("Resonance is already running or starting")
end
assert(type(loadstring) == "function", "This executor does not support loadstring")
assert(type(getgenv) == "function", "This executor does not support getgenv")
env.ResonanceStarting = true
local cleanup
local function registerCleanup(fn) cleanup = fn end
local cache = {}
local loading = {}
local function requireModule(name)
    if cache[name] then return cache[name] end
    assert(not loading[name], "Circular module dependency: " .. tostring(name))
    assert(type(sources[name]) == "string", "Missing module: " .. tostring(name))
    loading[name] = true
    local chunk, message = loadstring(sources[name], "@Resonance/" .. name)
    assert(chunk, message)
    local ok, result = pcall(chunk, requireModule)
    loading[name] = nil
    assert(ok, result)
    assert(type(result) == "table", "Invalid module: " .. name)
    cache[name] = result
    return result
end
local reloadPath
local ok, result = xpcall(function()
    local introOk, introError = pcall(function()
        local played, message = requireModule("Intro").Play()
        assert(played, message)
    end)
    if not introOk then warn("Resonance intro: " .. tostring(introError)) end
    if type(writefile) == "function" and type(readfile) == "function" then
        local success = pcall(function()
            local lines = {"local sources = {}"}
            for _, name in ipairs({"Intro", "Library", "ThemeManager", "SaveManager", "Icons", "Main", "Bootstrap", "Notices"}) do
                lines[#lines + 1] = string.format("sources[%q] = %q", name, sources[name])
            end
            lines[#lines + 1] = 'local run, message = loadstring(sources.Bootstrap, "@Resonance/Bootstrap"); assert(run, message); return run(sources)'
            writefile("ResonanceRestored.lua", table.concat(lines, "\n"))
            assert(type(readfile("ResonanceRestored.lua")) == "string")
        end)
        if success then reloadPath = "ResonanceRestored.lua" end
    end
    local chunk, message = loadstring(sources.Main, "@Resonance/Main")
    assert(chunk, message)
    return chunk(requireModule, reloadPath, registerCleanup)
end, function(message)
    if debug and debug.traceback then return debug.traceback(tostring(message), 2) end
    return tostring(message)
end)
env.ResonanceStarting = false
if not ok then
    if cleanup then pcall(cleanup) end
    env.ResonanceRunning = false
    warn("Resonance initialization failed: " .. tostring(result))
    return nil, result
end
return result
