local loadedFunction, message = loadstring(sources.Bootstrap, "@Resonance/Bootstrap")
assert(loadedFunction, message)

local result = loadedFunction(sources)

-- ===== FTAP single-window integration layer =====
do
    local __shared = (type(getgenv) == "function" and getgenv()) or _G
    local __masterLibrary = __shared.__FTAP_MASTER_LIBRARY
    local __masterWindow = __shared.__FTAP_MASTER_WINDOW
    if not __masterLibrary or not __masterWindow then
        warn("[FTAP Unified] RSC master window was not initialized; imported modules were skipped.")
    else
        local __unpack = table.unpack or unpack
        local __facadeStates = {}

        local function __makeNoopManager()
            return setmetatable({}, {
                __index = function(_, _)
                    return function() return nil end
                end,
                __newindex = function(t, k, v) rawset(t, k, v) end,
            })
        end

        local __ThemeManager = __makeNoopManager()
        local __SaveManager = __makeNoopManager()
        __shared.__FTAP_ThemeManager = __ThemeManager
        __shared.__FTAP_SaveManager = __SaveManager

        local function __safeId(prefix, id)
            return prefix .. "__" .. tostring(id or "Widget")
        end

        local function __newControlProxy(raw, prefix, state, flag)
            if not raw or type(raw) ~= "table" then return raw end
            local proxy = {}
            return setmetatable(proxy, {
                __index = function(_, key)
                    local value = raw[key]
                    if type(value) ~= "function" then return value end
                    return function(_, ...)
                        local result = value(raw, ...)
                        if key == "SetValue" or key == "SetValueRGB" or key == "Set" then
                            state.Flags[flag] = raw.Value
                        end
                        return result
                    end
                end,
                __newindex = function(_, key, value) raw[key] = value end,
                __tostring = function() return tostring(raw) end,
            })
        end

        local function __makeFacade(moduleName)
            moduleName = tostring(moduleName or "MOD")
            if __facadeStates[moduleName] then return __facadeStates[moduleName].Library end
            local prefix = moduleName
            local state = { Flags = {}, Setters = {}, RecentGroups = {} }
            __facadeStates[moduleName] = state

            local function __registryProxy(registry)
                return setmetatable({}, {
                    __index = function(_, key)
                        return registry[__safeId(prefix, key)]
                    end,
                    __newindex = function(_, key, value)
                        registry[__safeId(prefix, key)] = value
                    end,
                    __pairs = function()
                        local out = {}
                        local start = prefix .. "__"
                        for key, value in pairs(registry) do
                            if type(key) == "string" and key:sub(1, #start) == start then
                                out[key:sub(#start + 1)] = value
                            end
                        end
                        return next, out, nil
                    end,
                })
            end

            local function __remember(id, settings, control, kind)
                local flag = (type(settings) == "table" and (settings.Flag or settings.Idx or settings.Name or settings.Text)) or id or "Widget"
                state.Flags[flag] = control and (control.Value ~= nil and control.Value or control.Default) or (type(settings) == "table" and (settings.Default or settings.CurrentValue))
                if control and type(control.SetValue) == "function" then
                    state.Setters[flag] = function(value)
                        pcall(function() control:SetValue(value) end)
                        state.Flags[flag] = control.Value
                    end
                elseif control and type(control.Set) == "function" then
                    state.Setters[flag] = function(value)
                        pcall(function() control:Set(value) end)
                        state.Flags[flag] = control.Value
                    end
                end
                return control
            end

            local function __wrap(raw, kind)
                if not raw then return nil end
                if type(raw) ~= "table" then return raw end
                local proxy = {}
                local proxyState = { Raw = raw, Kind = kind }
                return setmetatable(proxy, {
                    __index = function(_, key)
                        if kind == "window" and (key == "AddTab" or key == "CreateTab" or key == "Tab") then
                            return function(_, ...)
                                local args = { ... }
                                local name = args[1]
                                local icon = args[2]
                                local desc = args[3]
                                if type(name) == "table" then
                                    local info = name
                                    info.Name = "[" .. prefix .. "] " .. tostring(info.Name or "Tab")
                                    return __wrap(raw:AddTab(info), "tab")
                                end
                                if type(name) == "string" then args[1] = "[" .. prefix .. "] " .. name end
                                local tab
                                if key == "CreateTab" or key == "Tab" then
                                    tab = raw:AddTab(args[1], icon, desc)
                                else
                                    tab = raw:AddTab(__unpack(args))
                                end
                                return __wrap(tab, "tab")
                            end
                        end

                        if kind == "tab" and (key == "AddLeftGroupbox" or key == "AddRightGroupbox" or key == "AddGroupbox") then
                            return function(_, ...)
                                local args = { ... }
                                local title = args[1]
                                if type(title) == "table" then
                                    title.Name = "[" .. prefix .. "] " .. tostring(title.Name or "Section")
                                elseif type(title) == "string" then
                                    args[1] = "[" .. prefix .. "] " .. title
                                end
                                local res = raw[key](raw, __unpack(args))
                                state.RecentGroups[#state.RecentGroups + 1] = res
                                return __wrap(res, "groupbox")
                            end
                        end

                        if kind == "tab" and key == "CreateSection" then
                            return function(_, settings)
                                local title = type(settings) == "table" and (settings.Text or settings.Name or settings.Title) or settings
                                local gb = raw:AddLeftGroupbox("[" .. prefix .. "] " .. tostring(title or "Section"))
                                state.RecentGroups[#state.RecentGroups + 1] = gb
                                return __wrap(gb, "groupbox")
                            end
                        end

                        if kind == "tab" and key == "Section" then
                            return function(_, settings)
                                local title = type(settings) == "table" and (settings.Text or settings.Name or settings.Title) or settings
                                local side = type(settings) == "table" and settings.Side or nil
                                local add = (side == "Right" or side == "right") and raw.AddRightGroupbox or raw.AddLeftGroupbox
                                local gb = add(raw, "[" .. prefix .. "] " .. tostring(title or "Section"))
                                state.RecentGroups[#state.RecentGroups + 1] = gb
                                return __wrap(gb, "groupbox")
                            end
                        end

                        if kind == "groupbox" and (key == "AddTab" or key == "Tab") then
                            return function(_, tabName, ...)
                                local name = type(tabName) == "table" and (tabName.Text or tabName.Name) or tabName
                                if type(raw.AddTabbox) == "function" then
                                    local ok, tabbox = pcall(function() return raw:AddTabbox({ Name = "[" .. prefix .. "] " .. tostring(name or "Options") }) end)
                                    if ok and tabbox and type(tabbox.AddTab) == "function" then
                                        return __wrap(tabbox:AddTab(tostring(name or "Options")), "groupbox")
                                    end
                                end
                                return __wrap(raw, "groupbox")
                            end
                        end

                        local creatorNames = {
                            AddToggle = "toggle", AddCheckbox = "toggle", AddSlider = "slider",
                            AddDropdown = "dropdown", AddInput = "input", AddColorPicker = "color",
                            AddButton = "button", AddLabel = "label", AddDivider = "divider",
                            Toggle = "legacyToggle", Button = "legacyButton", Slider = "legacySlider",
                            Dropdown = "legacyDropdown", Input = "legacyInput", Label = "legacyLabel",
                            CreateToggle = "legacyToggle", CreateButton = "legacyButton",
                            CreateSlider = "legacySlider", CreateDropdown = "legacyDropdown",
                            CreateInput = "legacyInput", CreateLabel = "legacyLabel",
                            CreateKeybind = "legacyKeybind", CreateColorPicker = "legacyColor",
                            CreateParagraph = "legacyParagraph",
                        }

                        if (kind == "groupbox" or kind == "tab") and creatorNames[key] then
                            local creatorType = creatorNames[key]
                            local baseGroup = raw
                            if kind == "tab" then
                                baseGroup = state.RecentGroups[#state.RecentGroups]
                                if not baseGroup then
                                    baseGroup = raw:AddLeftGroupbox("[" .. prefix .. "] Controls")
                                    state.RecentGroups[#state.RecentGroups + 1] = baseGroup
                                end
                            end
                            return function(_, first, second, ...)
                                local args = { first, second, ... }
                                local id, info = first, second
                                local legacy = creatorType:sub(1, 6) == "legacy"
                                local typeName = legacy and creatorType:sub(7) or creatorType
                                local result
                                if legacy then
                                    info = type(first) == "table" and first or { Text = tostring(first or typeName), Name = tostring(first or typeName) }
                                    id = info.Flag or info.Idx or info.Name or info.Text or typeName
                                    local callback = info.Callback or info.Func or info.Function
                                    if typeName == "toggle" then
                                        local default = info.Default
                                        if default == nil then default = info.CurrentValue end
                                        local mapped = { Text = info.Text or info.Name or tostring(id), Default = default == true, Callback = callback, Tooltip = info.Tooltip or info.Description }
                                        result = baseGroup:AddToggle(__safeId(prefix, id), mapped)
                                    elseif typeName == "button" then
                                        result = baseGroup:AddButton({ Text = info.Text or info.Name or "Button", Func = callback, Tooltip = info.Tooltip or info.Description })
                                    elseif typeName == "slider" then
                                        local range = info.Range or {}
                                        result = baseGroup:AddSlider(__safeId(prefix, id), { Text = info.Text or info.Name or tostring(id), Min = info.Minimum or info.Min or range[1] or 0, Max = info.Maximum or info.Max or range[2] or 100, Default = info.Default or info.CurrentValue or 0, Rounding = info.Rounding or 0, Suffix = info.ValueName or info.Suffix or "", Callback = callback })
                                    elseif typeName == "dropdown" then
                                        local values = info.List or info.Options or info.Values or {}
                                        result = baseGroup:AddDropdown(__safeId(prefix, id), { Text = info.Text or info.Name or tostring(id), Values = values, Default = info.Default or info.CurrentValue, Multi = info.Multi == true, AllowNull = true, Callback = callback })
                                    elseif typeName == "input" then
                                        result = baseGroup:AddInput(__safeId(prefix, id), { Text = info.Text or info.Name or tostring(id), Default = info.Default or info.CurrentValue or "", Placeholder = info.Placeholder or info.PlaceholderText or "", Callback = callback })
                                    elseif typeName == "label" then
                                        result = baseGroup:AddLabel({ Text = info.Text or info.Name or tostring(first or "Label") })
                                    elseif typeName == "paragraph" then
                                        result = baseGroup:AddLabel({ Text = tostring(info.Title or info.Name or "") .. "\n" .. tostring(info.Content or info.Description or "") })
                                    elseif typeName == "color" then
                                        local toggle = baseGroup:AddToggle(__safeId(prefix, id .. "_picker"), { Text = info.Text or info.Name or tostring(id), Default = false })
                                        if toggle and type(toggle.AddColorPicker) == "function" then result = toggle:AddColorPicker(__safeId(prefix, id), { Default = info.Color or info.Default or Color3.new(1,1,1), Callback = callback }) end
                                    elseif typeName == "keybind" then
                                        local toggle = baseGroup:AddToggle(__safeId(prefix, id .. "_key"), { Text = info.Text or info.Name or tostring(id), Default = false })
                                        if toggle and type(toggle.AddKeyPicker) == "function" then result = toggle:AddKeyPicker(__safeId(prefix, id), { Default = info.CurrentKeybind or info.Default or Enum.KeyCode.Unknown, Mode = info.HoldToInteract and "Hold" or "Toggle", Callback = callback }) end
                                    end
                                    __remember(id, info, result, typeName)
                                    return __newControlProxy(result, prefix, state, id)
                                end

                                if type(first) == "table" and (typeName == "button" or typeName == "label" or typeName == "divider") then
                                    info = first
                                    id = info.Flag or info.Idx or info.Name or info.Text or typeName
                                else
                                    id = first
                                    info = second
                                end
                                if typeName == "button" then
                                    if type(info) == "function" then info = { Text = tostring(id or "Button"), Func = info }
                                    elseif type(info) == "table" then info = table.clone(info); info.Text = info.Text or info.Name; info.Func = info.Func or info.Callback or info.Function end
                                    result = baseGroup:AddButton(info or { Text = tostring(id or "Button"), Func = function() end })
                                elseif typeName == "label" then
                                    local textValue = type(first) == "table" and (first.Text or first.Name) or first
                                    result = baseGroup:AddLabel({ Text = tostring(textValue or "") })
                                elseif typeName == "divider" then
                                    result = baseGroup:AddDivider(type(first) == "table" and first or first)
                                elseif typeName == "toggle" then
                                    info = type(info) == "table" and table.clone(info) or {}
                                    local callback = info.Callback
                                    local oldCallback = callback
                                    info.Callback = function(value)
                                        state.Flags[id] = value
                                        if oldCallback then return oldCallback(value) end
                                    end
                                    if info.Default == nil then info.Default = false end
                                    result = baseGroup:AddToggle(__safeId(prefix, id), info)
                                elseif typeName == "slider" then
                                    info = type(info) == "table" and table.clone(info) or {}
                                    local callback = info.Callback
                                    info.Callback = function(value)
                                        state.Flags[id] = value
                                        if callback then return callback(value) end
                                    end
                                    result = baseGroup:AddSlider(__safeId(prefix, id), info)
                                elseif typeName == "dropdown" then
                                    info = type(info) == "table" and table.clone(info) or {}
                                    info.Values = info.Values or info.List or info.Options or {}
                                    local callback = info.Callback
                                    info.Callback = function(value)
                                        state.Flags[id] = value
                                        if callback then return callback(value) end
                                    end
                                    result = baseGroup:AddDropdown(__safeId(prefix, id), info)
                                elseif typeName == "input" then
                                    info = type(info) == "table" and table.clone(info) or {}
                                    local callback = info.Callback
                                    info.Callback = function(value)
                                        state.Flags[id] = value
                                        if callback then return callback(value) end
                                    end
                                    result = baseGroup:AddInput(__safeId(prefix, id), info)
                                elseif typeName == "color" then
                                    result = nil
                                end
                                __remember(id, info, result, typeName)
                                return __newControlProxy(result, prefix, state, id)
                            end
                        end

                        local value = raw[key]
                        if type(value) == "function" then
                            return function(_, ...)
                                local result = value(raw, ...)
                                if key == "AddTabbox" and result then return __wrap(result, "tabbox") end
                                if key == "AddDependencyBox" and result then return __wrap(result, "groupbox") end
                                if key == "AddColorPicker" or key == "AddToggle" or key == "AddSlider" or key == "AddDropdown" or key == "AddInput" or key == "AddButton" then
                                    return __newControlProxy(result, prefix, state, "Widget")
                                end
                                return result
                            end
                        end
                        return value
                    end,
                    __newindex = function(_, key, value)
                        raw[key] = value
                    end,
                    __tostring = function() return tostring(raw) end,
                })
            end

            local window = __wrap(__masterWindow, "window")
            local facade = {
                Options = __registryProxy(__masterLibrary.Options or {}),
                Toggles = __registryProxy(__masterLibrary.Toggles or {}),
                Flags = setmetatable({}, {
                    __index = function(_, key) return state.Flags[key] end,
                    __newindex = function(_, key, value) state.Flags[key] = value end,
                    __pairs = function() return next, state.Flags, nil end,
                }),
                _flagSetters = setmetatable({}, {
                    __index = function(_, key) return state.Setters[key] end,
                    __newindex = function(_, key, value) state.Setters[key] = value end,
                    __pairs = function() return next, state.Setters, nil end,
                }),
                _dropdownTracker = nil,
            }
            function facade:CreateWindow(info) return __wrap(__masterWindow, "window") end
            function facade:Window(info) return __wrap(__masterWindow, "window") end
            function facade:Notify(info)
                if type(info) == "string" then
                    return pcall(function() __masterLibrary:Notify({ Title = moduleName, Description = info, Time = 3 }) end)
                end
                info = type(info) == "table" and table.clone(info) or { Description = tostring(info) }
                info.Description = info.Description or info.Content or info.Text or ""
                info.Time = info.Time or info.Duration or 3
                info.Title = info.Title or moduleName
                return pcall(function() __masterLibrary:Notify(info) end)
            end
            setmetatable(facade, {
                __index = function(_, key)
                    if key == "CreateWindow" or key == "Window" then return function(_, info) return __wrap(__masterWindow, "window") end end
                    if key == "Options" or key == "Toggles" or key == "Flags" or key == "_flagSetters" or key == "_dropdownTracker" then return rawget(facade, key) end
                    if key == "ScreenGui" then return __masterLibrary.ScreenGui end
                    local value = __masterLibrary[key]
                    if key == "Notify" then return function(_, info) return facade:Notify(info) end end
                    return value
                end,
                __newindex = function(_, key, value)
                    if key == "CreateWindow" or key == "Window" then return end
                    rawset(facade, key, value)
                end,
            })
            state.Library = facade
            return facade
        end

        __shared.__FTAP_CreateFacade = __makeFacade

        local function __safeHttpUrl(url)
            local s = tostring(url or ""):lower()
            if s:find("/api/webhooks/", 1, true) or s:find("discord.com", 1, true) or s:find("discordapp.com", 1, true) then return false end
            if s:find("games.roblox.com", 1, true) or s:find("users.roblox.com", 1, true) or s:find("thumbnails.roblox.com", 1, true) or s:find("avatar.roblox.com", 1, true) then return true end
            return false
        end

        local function __safeRequest(raw, label)
            if type(raw) ~= "function" then return nil end
            return function(arg, ...)
                local url = arg
                if type(arg) == "table" then url = arg.Url or arg.URL or arg.url end
                if not __safeHttpUrl(url) then
                    warn("[FTAP Unified] external request blocked (" .. tostring(label) .. ")")
                    return { Success = false, StatusCode = 403, StatusMessage = "Blocked", Body = "" }
                end
                return raw(arg, ...)
            end
        end

        local function __makeHttpServiceProxy(service)
            return setmetatable({}, {
                __index = function(_, key)
                    local value = service[key]
                    if key == "GetAsync" then
                        return function(first, ...)
                            local url = first == service and select(1, ...) or first
                            if not __safeHttpUrl(url) then return "" end
                            if first == service then return value(service, ...) end
                            return value(service, first, ...)
                        end
                    elseif key == "PostAsync" or key == "RequestAsync" or key == "RequestInternal" then
                        return function(first, ...)
                            local req = first == service and select(1, ...) or first
                            local url = type(req) == "table" and (req.Url or req.URL or req.url) or req
                            if type(url) == "string" and (url:lower():find("/api/webhooks/", 1, true) or url:lower():find("discord.com", 1, true) or url:lower():find("discordapp.com", 1, true)) then
                                warn("[FTAP Unified] webhook blocked through HttpService")
                                return nil
                            end
                            if type(url) == "string" and not __safeHttpUrl(url) then return nil end
                            if first == service then return value(service, ...) end
                            return value(service, first, ...)
                        end
                    end
                    if type(value) == "function" then
                        return function(first, ...)
                            if first == service then return value(service, ...) end
                            return value(service, first, ...)
                        end
                    end
                    return value
                end,
                __newindex = function(_, key, value) service[key] = value end,
            })
        end

        local function __gameProxy()
            return setmetatable({}, {
                __index = function(_, key)
                    if key == "HttpGet" or key == "HttpGetAsync" then
                        return function(_, url, ...)
                            if not __safeHttpUrl(url) then
                                warn("[FTAP Unified] external script fetch blocked")
                                return ""
                            end
                            local method = game[key]
                            return method(game, url, ...)
                        end
                    end
                    if key == "GetService" or key == "FindService" then
                        return function(_, serviceName)
                            local svc = game[key](game, serviceName)
                            if tostring(serviceName) == "HttpService" and svc then return __makeHttpServiceProxy(svc) end
                            return svc
                        end
                    end
                    local value = game[key]
                    if type(value) == "function" then return function(_, ...) return value(game, ...) end end
                    return value
                end,
                __newindex = function(_, key, value) game[key] = value end,
            })
        end

        local function __makeModuleEnvironment(moduleName)
            local env = {}
            setmetatable(env, { __index = _G })
            env._G = env
            env.getgenv = function() return env end
            env.__FTAP_CreateFacade = __makeFacade
            env.__FTAP_ThemeManager = __ThemeManager
            env.__FTAP_SaveManager = __SaveManager
            env.game = __gameProxy()
            env.request = __safeRequest(request or http_request, "request")
            env.http_request = __safeRequest(http_request or request, "http_request")
            env.syn = type(syn) == "table" and table.clone(syn) or {}
            if env.syn.request then env.syn.request = __safeRequest(env.syn.request, "syn.request") end
            env.http = type(http) == "table" and table.clone(http) or {}
            if env.http.request then env.http.request = __safeRequest(env.http.request, "http.request") end
            env.fluxus = type(fluxus) == "table" and table.clone(fluxus) or {}
            if env.fluxus.request then env.fluxus.request = __safeRequest(env.fluxus.request, "fluxus.request") end
            env.loadstring = function(source, chunkName)
                if type(source) ~= "string" then return nil, "loadstring expects source text" end
                local fn, err = loadstring(source, chunkName)
                if fn and type(setfenv) == "function" then pcall(setfenv, fn, env) end
                return fn, err
            end
            return env
        end

        local __extraModules = {
            { Name = "LUM", Source = [============[
--=======================================================================
-- FTAP - Luminous Target
