--=======================================================================
-- Anti Banana
--=======================================================================
do
    local myToysFolder     = Workspace:WaitForChild(LocalPlayer.Name .. "SpawnedInToys")

    local function getCharacter(player)
        local char = player.Character
        if not char then
            if player.CharacterAdded then
                char = player.CharacterAdded:Wait() or nil
            else
                char = nil
            end
        end
        return char
    end

    local function getHumanoidRootPart(character)
        return character and character:FindFirstChild("HumanoidRootPart") or nil
    end

    local function ragdollFall()
        local rootPart = getHumanoidRootPart(getCharacter(LocalPlayer))
        if rootPart and RagdollRemote then
            RagdollRemote:FireServer(rootPart, 1)
        end
    end

    local function spawnToy(toyName, cframe)
        if SpawnRemote then
            task.spawn(function()
                pcall(function()
                    SpawnRemote:InvokeServer(toyName, cframe, Vector3.new(0, 0, 0))
                end)
            end)
            
            local startTime = tick()
            local toy = myToysFolder:FindFirstChild(toyName)
            while not toy and (tick() - startTime < 3) do
                task.wait(0.05)
                toy = myToysFolder:FindFirstChild(toyName)
            end
            return toy
        end
    end

    local function destroyToy(toy)
        task.spawn(function()
            pcall(function()
                if DestroyRemote and toy and toy.Parent then
                    DestroyRemote:FireServer(toy)
                end
            end)
        end)
    end

    local function setNetworkOwner(part, cframe)
        task.spawn(function()
            pcall(function()
                if SetNetworkOwner then
                    SetNetworkOwner:FireServer(part, cframe)
                end
            end)
        end)
    end

    local function antiBananaDeleteLegs()
        local char = getCharacter(LocalPlayer)
        if not char then return end

        local hum = char:FindFirstChildOfClass("Humanoid")
        if hum then
            hum.PlatformStand = false
        end

        task.spawn(function()
            ragdollFall()
        end)
        
        task.wait(0.4) 
        
        char = getCharacter(LocalPlayer)
        if not char then return end
        
        local rightLeg = char:FindFirstChild("Right Leg") or char:FindFirstChild("RightUpperLeg")
        local leftLeg = char:FindFirstChild("Left Leg") or char:FindFirstChild("LeftUpperLeg")
        
        if rightLeg and leftLeg then
            local clonedLeg = rightLeg:Clone()
            clonedLeg.Parent = char
            
            for _, v in ipairs(clonedLeg:GetChildren()) do
                if v:IsA("Constraint") or v.Name:find("Socket") then
                    v:Destroy()
                end
            end
            
            task.wait(0.1) 
            rightLeg.CFrame = CFrame.new(0, -59999, 0)
            leftLeg.CFrame = CFrame.new(0, -59999, 0)
            task.wait(0.1)
            
            local hrp = getHumanoidRootPart(char)
            if hrp then

                local highCFrame = CFrame.new(hrp.Position.X, 999999, hrp.Position.Z)
                local cup = spawnToy("CupMugBrown", highCFrame)
                
                if cup and cup:FindFirstChild("Hitbox") then
                    setNetworkOwner(hrp, CFrame.new(cup.Hitbox.Position))
                    task.wait(0.1)
                    destroyToy(cup)
                end
            end
            
            clonedLeg.CFrame = CFrame.new(0, 9999999, 0)
            pcall(function()
                clonedLeg.Massless = true
            end)
            
            if hum then
                hum.AutoRotate = true
                hum:ChangeState(Enum.HumanoidStateType.GettingUp)
            end
        end
    end

    local antiBananaEnabled = false

    LocalPlayer.CharacterAdded:Connect(function(newCharacter)
        if not antiBananaEnabled then return end

        local hrp = newCharacter:WaitForChild("HumanoidRootPart", 3)
        local humanoid = newCharacter:WaitForChild("Humanoid", 3)
        
        if hrp and humanoid then
            task.wait(0.3)
            antiBananaDeleteLegs()
        end
    end)

    AntiGroupbox:AddCheckbox("AntiBanana", {
        Text    = "Anti Banana",
        Default = false,
        Callback = function(Value)
            antiBananaEnabled = Value
            if Value then
                antiBananaDeleteLegs()
            else
                local char = getCharacter(LocalPlayer)
                if char then
                    local hum = char:FindFirstChildOfClass("Humanoid")
                    if hum then
                        hum.Health = 0
                    end
                end
            end
        end
    })
end
--=======================================================================
-- Anti Lag & Auto Anti Lag
--=======================================================================
do
    local antiLagT = false
    local autoAntiLagT = true
    local fps = 60
    local pingThreshold = 200
    local fpsThreshold = 30

    local function antiLagF()
        local char = LocalPlayer.Character or LocalPlayer.CharacterAdded:Wait()

        local scriptTarget = LocalPlayer.PlayerScripts:FindFirstChild("CharacterAndBeamMove")
        if not scriptTarget then return end

        scriptTarget.Disabled = antiLagT
    end

    LocalPlayer.CharacterAdded:Connect(function()
        task.wait(1)
        if antiLagT then
            antiLagF()
        end
    end)

    local Toggle = AntiGroupbox:AddCheckbox("AntiLagToggle", {
        Text = "Anti Lag",
        Default = false,
        Callback = function(Value)
            antiLagT = Value
            antiLagF()
        end
    })

    RunService.RenderStepped:Connect(function(dt)
        if dt > 0 then
            fps = math.floor(1 / dt)
        end
    end)

    task.spawn(function()
        while task.wait(0.5) do
            if autoAntiLagT and not antiLagT then
                local currentPing = math.floor(Stats.Network.ServerStatsItem["Data Ping"]:GetValue())
                local reason = ""

                if currentPing >= pingThreshold then
                    reason = "High Ping (" .. currentPing .. "ms)"
                elseif fps <= fpsThreshold then
                    reason = "Low FPS (" .. fps .. ")"
                end

                if reason ~= "" then
                    antiLagT = true

                    if Toggle then
                        Toggle:SetValue(true)
                    end

                    antiLagF()

                    local sound = Instance.new("Sound")
                    sound.SoundId = "rbxassetid://17208361335"
                    sound.Volume = 10
                    sound.Parent = game.Players.LocalPlayer.PlayerGui
                    sound:Play()
                    game.Debris:AddItem(sound, 5)

                    Library:Notify({
                        Title = "<b>Auto Anti Lag</b>",
                        Description = "<b>" .. reason .. "</b> — Anti Lag enabled.",
                        Icon = "11738671901",
                        Time = 5,
                    })
                end
            end
        end
    end)

    local AutoToggle = AntiGroupbox:AddCheckbox("AutoAntiLagToggle", {
        Text = "Auto Anti Lag",
        Default = true,
        Callback = function(Value)
            autoAntiLagT = Value

            if not Value and antiLagT and not Toggle.Value then
                antiLagT = false
                antiLagF()
                Toggle:SetValue(false)
            end
        end
    })
end
--=======================================================================
-- Auto Reset
--=======================================================================
do
    local connections = {}

    AntiGroupbox:AddCheckbox("AutoReset", {
        Text = "Auto Reset",
        Default = false,
        Callback = function(value)
            if value then
                connections["AutoReset"] = ReplicatedStorage.GameCorrectionEvents.GameCorrectionsNotify.OnClientEvent:Connect(function(result)
                    if result == "Flying" then
                        local character = LocalPlayer.Character
                        local humanoid = character and character:FindFirstChildOfClass("Humanoid")

                        if not humanoid or humanoid.Health <= 0 then
                            return
                        end

                        local sound = Instance.new("Sound")
                        sound.SoundId = "rbxassetid://131390520971848"
                        sound.Volume = 10
                        sound.Parent = SoundService
                        sound:Play()
                        game.Debris:AddItem(sound, 5)

                     Library:Notify({
                         Title = "<b>Anti Reset</b>",
                         Description = "<b>Flying</b> detected — resetting.",
                         Icon = "122389431578458",
                         Time = 5,
                         IconSize = 32,
                      })

                        humanoid:ChangeState(Enum.HumanoidStateType.Dead)
                    end
                end)
            else
                if connections["AutoReset"] then
                    connections["AutoReset"]:Disconnect()
                    connections["AutoReset"] = nil
                end
            end
        end
    })

    Toggles.AutoReset:SetValue(true)
end
--=======================================================================
-- Anti Gucci [Blobman]
--=======================================================================
do
    local AutoGucciT = false
    local sitJumpT = false
    local ragdollLoopD = false

    local blobmanInstanceS = nil
    local blobConnection = nil
    local respawnConnection = nil
    local isTogglingOff = false

    local jumpConnection = nil
    local jumpLoopRunning = false
    local lastJumpTick = 0
    local spaceWasDown = false
    local JUMP_COOLDOWN = 0.1

    if not (DestroyRemote and SpawnRemote and RagdollRemote and Struggle and SetNetworkOwner) then
        return
    end

    local function isChatting()
        return UserInputService:GetFocusedTextBox() ~= nil
    end

    local function tryJump()
        if isChatting() then return end

        local now = tick()
        if now - lastJumpTick < JUMP_COOLDOWN then return end

        local char = LocalPlayer.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if not hum or hum.Health <= 0 then return end

        if hum.FloorMaterial == Enum.Material.Air then return end

        lastJumpTick = now

        hum:ChangeState(Enum.HumanoidStateType.Jumping)
    end

    local function startJumpLoop()
        if jumpConnection then
            jumpConnection:Disconnect()
            jumpConnection = nil
        end

        jumpConnection = UserInputService.JumpRequest:Connect(function()
            tryJump()
        end)

        if not jumpLoopRunning then
            jumpLoopRunning = true
            spaceWasDown = false
            task.spawn(function()
                while jumpLoopRunning do
                    local isDown = UserInputService:IsKeyDown(Enum.KeyCode.Space)
                    if isDown and not spaceWasDown then
                        tryJump()
                    end
                    spaceWasDown = isDown
                    RunService.RenderStepped:Wait()
                end
            end)
        end
    end

    local function stopJumpLoop()
        if jumpConnection then
            jumpConnection:Disconnect()
            jumpConnection = nil
        end
        jumpLoopRunning = false
        spaceWasDown = false
    end

    startJumpLoop()

    local function destroySeat(targetBlobman)
        if not targetBlobman or not targetBlobman.Parent then return end
        local seat = targetBlobman:FindFirstChildWhichIsA("VehicleSeat")
                      or targetBlobman:FindFirstChildOfClass("VehicleSeat")
        if seat then
            pcall(function()
                DestroyRemote:FireServer(seat)
            end)
            seat:Destroy()
        end
    end

    local function recoverCharacterClean()
        pcall(function()
            local char = LocalPlayer.Character
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            if hum then
                Struggle:FireServer(LocalPlayer)
                hum.PlatformStand = false
                hum.Sit = true
                task.wait(0.01)
                hum.Sit = false
            end
        end)
    end

    local function executeRagdollAndRecover()
        local char = LocalPlayer.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        local hum = char and char:FindFirstChildOfClass("Humanoid")

        if hrp then
            task.spawn(function()
                RagdollRemote:FireServer(hrp, 0.2)
                if hum then
                    hum.PlatformStand = true
                end
                task.wait(0.02)
                recoverCharacterClean()
            end)
        end
    end

    local function bindBlobDestroyRagdoll(blob)
        if blobConnection then
            blobConnection:Disconnect()
            blobConnection = nil
        end

        if not blob then return end

        blobConnection = blob.AncestryChanged:Connect(function(_, parent)
            if not parent then
                if blobConnection then
                    blobConnection:Disconnect()
                    blobConnection = nil
                end

                if AutoGucciT or isTogglingOff then return end
                executeRagdollAndRecover()
                blobmanInstanceS = nil
            end
        end)
    end

    local function spawnBlobmanF()
        local char = LocalPlayer.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        if not hrp then return false end

        if blobmanInstanceS and blobmanInstanceS.Parent
           and blobmanInstanceS:IsDescendantOf(Workspace) then
            return true
        end

        local inv = Workspace:FindFirstChild(LocalPlayer.Name .. "SpawnedInToys")
        local blob = inv and inv:FindFirstChild("CreatureBlobman")
        if blob then
            blobmanInstanceS = blob
            return true
        end

        if SpawnRemote then
            task.spawn(function()
                pcall(function()
                    SpawnRemote:InvokeServer(
                        "CreatureBlobman",
                        CFrame.new(192, 324, 389),
                        Vector3.new(0, 0, 0)
                    )
                end)
            end)

            local tries = 0
            repeat
                if not AutoGucciT then return false end
                task.wait(0.05)
                inv = Workspace:FindFirstChild(LocalPlayer.Name .. "SpawnedInToys")
                blobmanInstanceS = inv and inv:FindFirstChild("CreatureBlobman")
                tries += 1
            until (blobmanInstanceS and blobmanInstanceS.Parent) or tries > 60

            if not blobmanInstanceS or not blobmanInstanceS.Parent then
                return false
            end
        else
            return false
        end
        return true
    end

    local function ragdollLoopF()
        if ragdollLoopD then return end
        ragdollLoopD = true

        while sitJumpT and AutoGucciT do
            local char = LocalPlayer.Character
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            if char and hrp then
                RagdollRemote:FireServer(hrp, 0)
            end
            task.wait()
        end
        ragdollLoopD = false
    end

    local function sitJumpF()
        local char = LocalPlayer.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if not char or not hum then return false end

        local seat = blobmanInstanceS
                     and blobmanInstanceS:FindFirstChildWhichIsA("VehicleSeat")
        if seat and seat.Occupant ~= hum then
            seat:Sit(hum)

            local hrp = char:FindFirstChild("HumanoidRootPart")
            local blobHRP = blobmanInstanceS
                            and blobmanInstanceS:FindFirstChild("HumanoidRootPart")
            if hrp and blobHRP then
                pcall(function()
                    SetNetworkOwner:FireServer(blobHRP, hrp)
                end)
            end

            sitJumpT = false
            task.defer(function()
                destroySeat(blobmanInstanceS)
            end)
            return true
        end
        return false
    end

    local function AutoGucciF()
        while AutoGucciT do
            pcall(function()
                if not AutoGucciT then return end
                if not spawnBlobmanF() then
                    task.wait(0.5)
                    return
                end

                local char = LocalPlayer.Character
                if not char then task.wait(0.05) return end

                local hrp = char:WaitForChild("HumanoidRootPart", 2)
                local hum = char:WaitForChild("Humanoid", 2)
                if not hrp or not hum then return end

                local rag = hum:FindFirstChild("Ragdolled")
                local held = LocalPlayer:FindFirstChild("IsHeld")

                if not blobmanInstanceS or not AutoGucciT then return end

                bindBlobDestroyRagdoll(blobmanInstanceS)

                local OCF = hrp.CFrame

                if not sitJumpT then
                    task.spawn(sitJumpF)
                    sitJumpT = true
                end

                task.spawn(ragdollLoopF)
                task.wait(0.15)
                if not AutoGucciT then return end
                if hrp and hrp.Parent then
                    hrp.CFrame = OCF
                end

                local successCheck = true
                sitJumpT = false

                RagdollRemote:FireServer(hrp, 0.001)

                while successCheck and AutoGucciT do
                    if not blobmanInstanceS
                       or not blobmanInstanceS.Parent
                       or not blobmanInstanceS:IsDescendantOf(Workspace) then
                        if hrp and hrp.Parent and not isTogglingOff then
                            executeRagdollAndRecover()
                        end
                        blobmanInstanceS = nil
                        successCheck = false
                        break
                    end

                    if hum.Health <= 0 then
                        if blobmanInstanceS then
                            DestroyRemote:FireServer(blobmanInstanceS)
                        end
                        successCheck = false
                        break
                    end

                    local currentSeat = blobmanInstanceS:FindFirstChildWhichIsA("VehicleSeat")
                    if currentSeat and currentSeat.Occupant ~= nil
                       and currentSeat.Occupant ~= hum then
                        DestroyRemote:FireServer(blobmanInstanceS)
                        if hrp and hrp.Parent and not isTogglingOff then
                            executeRagdollAndRecover()
                        end
                        blobmanInstanceS = nil
                        successCheck = false
                        break
                    end

                    if (rag and rag.Value == true) or (held and held.Value == true) then
                        while ((rag and rag.Value == true) or (held and held.Value == true))
                              and AutoGucciT do
                            Struggle:FireServer()
                            task.wait()
                        end
                        successCheck = false
                        break
                    end

                    local blobHRP = blobmanInstanceS:FindFirstChild("HumanoidRootPart")
                    if blobHRP then
                        blobHRP.CFrame = CFrame.new(192, 324, 389)
                    end
                    task.wait()
                end

                if not successCheck then
                    if not isTogglingOff then
                        recoverCharacterClean()
                    end
                    sitJumpT = false
                    task.wait(0.05)
                end
            end)
            task.wait()
        end
    end

    local function toggleGucci(state)
        if AutoGucciT == state then return end
        AutoGucciT = state

        if AutoGucciT then
            isTogglingOff = false
            if respawnConnection then
                respawnConnection:Disconnect()
                respawnConnection = nil
            end

            respawnConnection = LocalPlayer.CharacterAdded:Connect(function(newCharacter)
                if AutoGucciT then
                    if blobmanInstanceS then
                        pcall(function()
                            DestroyRemote:FireServer(blobmanInstanceS)
                        end)
                        blobmanInstanceS = nil
                    end
                    sitJumpT = false

                    task.spawn(function()
                        local hum = newCharacter:WaitForChild("Humanoid", 5)
                        local hrp = newCharacter:WaitForChild("HumanoidRootPart", 5)

                        if not hum or not hrp then return end

                        task.wait(1.5)

                        if AutoGucciT and hum.Health > 0 then
                            task.spawn(AutoGucciF)
                        end
                    end)
                end
            end)

            task.spawn(AutoGucciF)
        else
            isTogglingOff = true

            if respawnConnection then
                respawnConnection:Disconnect()
                respawnConnection = nil
            end
            if blobConnection then
                blobConnection:Disconnect()
                blobConnection = nil
            end

            local currentBlob = blobmanInstanceS
            blobmanInstanceS = nil

            if currentBlob then
                pcall(function()
                    DestroyRemote:FireServer(currentBlob)
                end)
            end

            executeRagdollAndRecover()
            sitJumpT = false

            task.delay(0.2, function()
                isTogglingOff = false
            end)
        end
    end

    GucciGroupbox:AddCheckbox("AntiGucci", {
        Text = "Anti Gucci [Blob]",
        Default = false,
        Callback = function(Value)
            toggleGucci(Value)
        end
    })
end
--=======================================================================
-- Anti Gucci [train]
--=======================================================================
do
    local antiGucciConnectionTrain
    local safePositionTrain
    local restoreFramesTrain = 0
    local jumpConnectionTrain = nil

    local autoGucciActiveTrain = false
    local trainLoopRunning = false
    local respawnConnectionTrain = nil
    local startingTrain = false 

    local function startAntiGucciTrain()
        if startingTrain then return end
        startingTrain = true

        local character = LocalPlayer.Character or LocalPlayer.CharacterAdded:Wait()
        local humanoid = character:WaitForChild("Humanoid")
        local rootPart = character:WaitForChild("HumanoidRootPart")
        safePositionTrain = rootPart.Position

        if antiGucciConnectionTrain then
            antiGucciConnectionTrain:Disconnect()
            antiGucciConnectionTrain = nil
        end
        if jumpConnectionTrain then
            jumpConnectionTrain:Disconnect()
            jumpConnectionTrain = nil
        end

        local folder = Workspace.Map.AlwaysHereTweenedObjects
        local train = folder and folder:FindFirstChild("Train")
        local seat

        if train then
            for _, d in ipairs(train:GetDescendants()) do
                if d:IsA("Seat") then
                    seat = d
                    break
                end
            end
        end

        if seat then
            rootPart.CFrame = seat.CFrame + Vector3.new(0, 2, 0)
            seat:Sit(humanoid)
        end

        jumpConnectionTrain = humanoid:GetPropertyChangedSignal("Jump"):Connect(function()
            if humanoid.Jump and humanoid.Sit then
                restoreFramesTrain = 15
                safePositionTrain = rootPart.Position
            end
        end)

        antiGucciConnectionTrain = RunService.Heartbeat:Connect(function()
            if not rootPart or not rootPart.Parent or not humanoid or not humanoid.Parent then
                return
            end
            RagdollRemote:FireServer(rootPart, 0)
            if restoreFramesTrain > 0 then
                rootPart.CFrame = CFrame.new(safePositionTrain)
                restoreFramesTrain = restoreFramesTrain - 1
            end
        end)

        task.spawn(function()
            while humanoid and humanoid.Parent and humanoid.Sit do
                task.wait(1)
            end
            task.wait(0.5)
            if rootPart and rootPart.Parent then
                rootPart.CFrame = CFrame.new(safePositionTrain)
            end
        end)

        task.wait(0.1)  
        startingTrain = false
    end

    local function stopAntiGucciTrain()
        if antiGucciConnectionTrain then
            antiGucciConnectionTrain:Disconnect()
            antiGucciConnectionTrain = nil
        end
        if jumpConnectionTrain then
            jumpConnectionTrain:Disconnect()
            jumpConnectionTrain = nil
        end
        local trainFolder = Workspace.Map.AlwaysHereTweenedObjects
        if trainFolder and trainFolder:FindFirstChild("Train") then
            ResetPlayer(LocalPlayer)
        end
    end

    local function startTrainAutoLoop()
        if trainLoopRunning then return end
        trainLoopRunning = true

        task.spawn(function()
            while autoGucciActiveTrain do
                local trainFolder = Workspace.Map.AlwaysHereTweenedObjects
                local trainExists = trainFolder and trainFolder:FindFirstChild("Train")

                if trainExists then

                    if not antiGucciConnectionTrain and not startingTrain then
                        startAntiGucciTrain()
                    end
                else
                    if antiGucciConnectionTrain then
                        stopAntiGucciTrain()
                    end

                    local retries = 0
                    repeat
                        task.wait(0.2)
                        retries = retries + 1
                        trainFolder = Workspace.Map.AlwaysHereTweenedObjects
                    until (trainFolder and trainFolder:FindFirstChild("Train"))
                          or retries > 25
                          or not autoGucciActiveTrain

                    if autoGucciActiveTrain
                       and trainFolder
                       and trainFolder:FindFirstChild("Train")
                       and not antiGucciConnectionTrain
                       and not startingTrain then
                        startAntiGucciTrain()
                    end
                end

                task.wait(0.5)
            end

            trainLoopRunning = false
        end)
    end

    GucciGroupbox:AddCheckbox("AutoGucciTrain", {
        Text = "Anti Gucci [Train]",
        Default = false,
        Callback = function(Value)
            autoGucciActiveTrain = Value
            if Value then
                if respawnConnectionTrain then
                    respawnConnectionTrain:Disconnect()
                    respawnConnectionTrain = nil
                end

                respawnConnectionTrain = LocalPlayer.CharacterAdded:Connect(function(newCharacter)
                    if autoGucciActiveTrain then
                        if antiGucciConnectionTrain then
                            antiGucciConnectionTrain:Disconnect()
                            antiGucciConnectionTrain = nil
                        end
                        if jumpConnectionTrain then
                            jumpConnectionTrain:Disconnect()
                            jumpConnectionTrain = nil
                        end
                        startingTrain = false

                        task.spawn(function()
                            local hum = newCharacter:WaitForChild("Humanoid", 5)
                            local hrp = newCharacter:WaitForChild("HumanoidRootPart", 5)
                            if not hum or not hrp then return end

                            task.wait(1.5)

                            if autoGucciActiveTrain and hum.Health > 0 then
                                if not antiGucciConnectionTrain and not startingTrain then
                                    startAntiGucciTrain()
                                end
                            end
                        end)
                    end
                end)

                startAntiGucciTrain()
                startTrainAutoLoop()
            else
                autoGucciActiveTrain = false
                startingTrain = false

                if respawnConnectionTrain then
                    respawnConnectionTrain:Disconnect()
                    respawnConnectionTrain = nil
                end

                stopAntiGucciTrain()
            end
        end
    })
end
--=======================================================================
-- Anti Input Lag
--=======================================================================
do
    local ToyList = {
        ["Coconut"]     = "FoodCoconut",
        ["Banana"]      = "FoodBanana",
        ["Fries"]       = "FoodFrenchFries",
        ["MeatStick"]   = "FoodMeatStick",
        ["Poop"]        = "PoopPile",
        ["Donut"]       = "FoodDonut",
        ["Cake"]        = "FoodCakePink",
        ["Burger"]      = "FoodHamburger",
        ["Pizza"]       = "FoodPizzaCheese",
        ["Hotdog"]      = "FoodHotdog",
        ["Mushroom"]    = "FoodMushroomPoison",
        ["Pepperoni"]   = "FoodPizzaPepperoni",
        ["Bread"]       = "FoodBread",
        ["Egg"]         = "FoodDippyEgg",
        ["Mayo"]        = "FoodMayonnaise",
        ["SparklePoop"] = "PoopPileSparkle",
        ["Banjo"]       = "InstrumentGuitarBanjo",
        ["Violin"]      = "InstrumentGuitarViolin",
        ["Ukulele"]     = "InstrumentGuitarUkulele",
        ["Sax"]         = "InstrumentWoodwindSaxophone",
        ["Vuvuzela"]    = "InstrumentBrassVuvuzela",
        ["Bongos"]      = "InstrumentDrumBongos",
        ["Mic"]         = "InstrumentVoiceMicrophone",
        ["Piano"]       = "InstrumentPianoMelodica",
        ["WhiteMug"]    = "CupMugWhite",
        ["Ocarina"]     = "InstrumentWoodwindOcarina",
        ["BrownMug"]    = "CupMugBrown",
        ["Trumpet"]     = "InstrumentBrassTrumpet",
        ["Snare"]       = "InstrumentDrumSnare",
        ["Lyre"]        = "InstrumentGuitarLyre",
    }

    local DropdownValues = {}
    for shortName, _ in pairs(ToyList) do
        table.insert(DropdownValues, shortName)
    end
    table.sort(DropdownValues)

    local SelectedToy = ToyList["Banana"] or ToyList[DropdownValues[1]]

    local HoldDuration = 0.02
    local CycleSpeed = 0.02

    local function ClearToys()
        local plr = Players.LocalPlayer
        local inv = Workspace:FindFirstChild(plr.Name .. "SpawnedInToys")
        if inv then
            for _, v in pairs(inv:GetChildren()) do
                if v.Name == SelectedToy then
                    pcall(function()
                        if DestroyRemote then
                            DestroyRemote:FireServer(v)
                        else
                            v:Destroy()
                        end
                    end)
                end
            end
        end
    end
        
    GucciGroupbox:AddDivider()
    GucciGroupbox:AddDropdown("AntiInputLagToy", {
        Text = "Select Toy",
        Values = DropdownValues,
        Default = "Banana",
        Callback = function(Value)
            ClearToys()
            SelectedToy = ToyList[Value]
        end
    })

    GucciGroupbox:AddCheckbox("AntiInputLag", {
        Text = "Anti Input Lag",
        Default = false,
        Callback = function(Value)
            _G.InstantLagActive = Value

            if Value then
                task.spawn(function()
                    local plr = game.Players.LocalPlayer
                    local RS = game:GetService("ReplicatedStorage")
                    local SpawnRemote = RS:WaitForChild("MenuToys"):WaitForChild("SpawnToyRemoteFunction")

                    while _G.InstantLagActive do
                        local char = plr.Character
                        local hrp = char and char:FindFirstChild("HumanoidRootPart")
                        
                        if hrp then
                            local toysFolder = workspace:FindFirstChild(plr.Name.."SpawnedInToys")
                            local name = SelectedToy
                            local item = toysFolder and toysFolder:FindFirstChild(name)

                            if item then
                                local holdPart = item:FindFirstChild("HoldPart")
                                local holdingPlayer = holdPart and holdPart:FindFirstChild("HoldingPlayer")
                                if holdingPlayer and holdingPlayer.Value and holdingPlayer.Value ~= plr then
                                    item = nil
                                end
                            end

                            for _, obj in pairs(workspace:GetChildren()) do
                                if obj.Name == "Shuriken" and obj:IsA("Model") then
                                    for _, part in pairs(obj:GetDescendants()) do
                                        if part:IsA("BasePart") then 
                                            part.CanCollide = false 
                                            part.Massless = true 
                                        end
                                    end
                                end
                            end

                            if not item or not item.Parent then
                                task.spawn(function()
                                    pcall(function()
                                        SpawnRemote:InvokeServer(name, hrp.CFrame * CFrame.new(0, -12, 0), Vector3.zero)
                                    end)
                                end)
                                task.wait(0.1)
                            else
                                local holdPart = item:FindFirstChild("HoldPart")
                                if holdPart then
                                    for _, v in pairs(item:GetDescendants()) do
                                        if v:IsA("BasePart") then 
                                            v.CanCollide = false 
                                            v.Massless = true 
                                        end
                                    end

                                    task.spawn(function()
                                        pcall(function()
                                            holdPart.HoldItemRemoteFunction:InvokeServer(item, char)
                                        end)
                                    end)

                                    task.wait(HoldDuration)

                                    task.spawn(function()
                                        pcall(function()
                                            holdPart.DropItemRemoteFunction:InvokeServer(
                                                item, 
                                                CFrame.new(0, 5000, 0), 
                                                Vector3.zero
                                            )
                                        end)
                                    end)
                                end
                            end
                        end
                        task.wait(CycleSpeed)
                    end
                end)
            else
                ClearToys()
            end
        end
    })
end
--=======================================================================
-- Anti Hold Item Part
--=======================================================================
do
    local AllowedItems = {
        FoodHamburger = true, FoodCoconut = true, FoodPizzaCheese = true,
        FoodPizzaPepperoni = true, FoodHotdog = true, FoodMushroomPoison = true,
        FoodBread = true, FoodDippyEgg = true, FoodMayonnaise = true,
        FoodFrenchFries = true, FoodMeatStick = true, FoodDonut = true,
        FoodCakePink = true, FoodBanana = true, FoodBroccoli = true,
        FoodSodaCan = true,

        InstrumentGuitarBanjo = true, InstrumentGuitarViolin = true,
        InstrumentGuitarUkulele = true, InstrumentWoodwindSaxophone = true,
        InstrumentWoodwindOcarina = true, InstrumentBrassVuvuzelaQwizik = true,
        InstrumentBrassTrumpet = true, InstrumentDrumBongos = true,
        InstrumentDrumSnare = true, InstrumentPianoMelodica = true,
        InstrumentVoiceMicrophone = true, InstrumentBrassBugle = true,
        InstrumentBrassVuvuzela = true, InstrumentGuitarAcoustic = true,
        InstrumentGuitarLyre = true, InstrumentPianoKeyboard = true,

        CupMugWhite = true, CupMugBrown = true,
        PoopPile = true, PoopPileSparkle = true,
    }

    local TICK_RATE = 0.05

    local State = {
        enabled = false,
        items = {},
        itemSet = {},
        descendantConn = nil,  
        loopRunning = false,
    }

    local function addItem(obj)
        if not obj or not obj.Parent then return end
        if not AllowedItems[obj.Name] then return end
        if not obj:IsA("Model") then return end
        if State.itemSet[obj] then return end
        State.itemSet[obj] = true
        State.items[#State.items + 1] = obj
    end

    local function scanAll()
        for _, v in ipairs(workspace:GetDescendants()) do
            addItem(v)
        end
    end

    local function startDescendantListener()
        if State.descendantConn then
            State.descendantConn:Disconnect()
            State.descendantConn = nil
        end
        State.descendantConn = workspace.DescendantAdded:Connect(function(obj)
            if not State.enabled then return end
            if AllowedItems[obj.Name] and obj:IsA("Model") then
                addItem(obj)
            end
        end)
    end

    local function processLoop()
        if State.loopRunning then return end
        State.loopRunning = true

        task.spawn(function()
            local plr = game.Players.LocalPlayer

            while State.enabled do
                local loopStart = os.clock()

                local char = plr.Character
                local hrp = char and char:FindFirstChild("HumanoidRootPart")

                if hrp then
                    for i = #State.items, 1, -1 do
                        local b = State.items[i]

                        if not b or not b.Parent then
                            State.itemSet[b] = nil
                            table.remove(State.items, i)
                        else
                            local hp = b:FindFirstChild("HoldPart")
                            if hp then
                                pcall(function()
                                    hp.HoldItemRemoteFunction:InvokeServer(b, char)
                                end)
                                pcall(function()
                                    hp.DropItemRemoteFunction:InvokeServer(
                                        b,
                                        CFrame.new(hrp.Position + Vector3.new(0, -2000, 0)),
                                        Vector3.new(0, 0, 0)
                                    )
                                end)
                            end
                        end
                    end
                end

                local elapsed = os.clock() - loopStart
                local waitTime = TICK_RATE - elapsed
                task.wait(waitTime > 0 and waitTime or nil)
            end

            State.loopRunning = false
        end)
    end

    GucciGroupbox:AddCheckbox("Remove AntiInputLag", {
        Text = "Anti Hold Item Part",
        Default = false,
        Callback = function(on)
            if on then
                State.enabled = true

                State.items = {}
                State.itemSet = {}
                scanAll()

                startDescendantListener()

                processLoop()
            else
                State.enabled = false

                if State.descendantConn then
                    State.descendantConn:Disconnect()
                    State.descendantConn = nil
                end

                State.items = {}
                State.itemSet = {}

            end
        end,
    })
end
--=======================================================================
-- Barrier Break
--=======================================================================
do
    AntiETCGroupbox:AddButton({
        Text = "Break Barrier",
        Func = function()
            local player = LocalPlayer
            if not player then
                OrionLib:MakeNotification({Name="Error", Content="Player not found", Time = 4})
                return
            end

            if not (player.Character and player.Character:FindFirstChild("HumanoidRootPart")) then  
                OrionLib:MakeNotification({Name="Error", Content="Character not ready", Time = 4})  
                return  
            end  

            local humanoid = player.Character and player.Character:FindFirstChildOfClass("Humanoid")  
            local originalWalkSpeed, originalJumpPower  
            if humanoid then  
                originalWalkSpeed = humanoid.WalkSpeed  
                originalJumpPower = humanoid.JumpPower  
                pcall(function() humanoid.WalkSpeed = 0 humanoid.JumpPower = 0 end)  
            end  

            local success, err = pcall(function()  
                local hrp = player.Character.HumanoidRootPart  
                local originalCFrame = hrp.CFrame  

                hrp.CFrame = CFrame.new(246.052, -7.35, 431.821)  
                task.wait(0.05)  

                SpawnRemote:InvokeServer(  
                    "InstrumentWoodwindOcarina",  
                    CFrame.new(184.148834, -5.54824972, 498.136749,  
                        0.829037189, -0.214714944, 0.516328275,  
                        0, 0.923344612, 0.383972496,  
                        -0.559193552, -0.318327487, 0.765486956),  
                    Vector3.new(0, 34, 0)  
                )  

                task.wait(0.2)  

                local toyFolder = Workspace:FindFirstChild(player.Name .. "SpawnedInToys")  
                if not toyFolder then error("SpawnedInToys folder not found") end  

                local ocarina = toyFolder:FindFirstChild("InstrumentWoodwindOcarina")  
                if not ocarina then error("InstrumentWoodwindOcarina not found") end  

                if ocarina:FindFirstChild("HoldPart") and ocarina.HoldPart:FindFirstChild("HoldItemRemoteFunction") then  
                    pcall(function()  
                        ocarina.HoldPart.HoldItemRemoteFunction:InvokeServer(ocarina, player.Character)  
                    end)  
                    task.wait(0.2)  
                end  

                player.Character.HumanoidRootPart.CFrame = CFrame.new(304.06, 25.77, 488.54)  
                task.wait(0.05)  

                DestroyRemote:FireServer(ocarina)  

                task.wait(0.05)  

                if player.Character and player.Character:FindFirstChild("HumanoidRootPart") then  
                    player.Character.HumanoidRootPart.CFrame = originalCFrame  
                end  

                OrionLib:MakeNotification({Name="Success", Content="Barrier break executed", Time = 3})  
            end)  

            local function tryRestore()  
                if originalWalkSpeed == nil and originalJumpPower == nil then return end  
                local curHum = player.Character and player.Character:FindFirstChildOfClass("Humanoid")  
                if curHum then  
                    pcall(function()  
                        if originalWalkSpeed ~= nil then curHum.WalkSpeed = originalWalkSpeed end  
                        if originalJumpPower ~= nil then curHum.JumpPower = originalJumpPower end  
                    end)  
                end  
            end  

            tryRestore()  

            if not success then  
                OrionLib:MakeNotification({Name="Error", Content=tostring(err), Time = 6})  
            end  
        end
    })
end
--=======================================================================
-- Noclip Barrier
--=======================================================================
do
	local barrierNoclipActive = false
	local barrierConnection = nil

	local function setBarrierNoclip(state)
		local plots = Workspace:FindFirstChild("Plots")
		if not plots then return end

		for index = 1, 5 do
			local plot = plots:FindFirstChild("Plot" .. index)
			local barrier = plot and plot:FindFirstChild("Barrier")
			if barrier then
				for _, part in ipairs(barrier:GetDescendants()) do
					if part:IsA("BasePart") then
						part.CanCollide = not state
					end
				end
			end
		end
	end

	AntiETCGroupbox:AddCheckbox("barriernoclip", {
		Text = "Noclip barrier",
		Default = false,
		Callback = function(value)
			barrierNoclipActive = value
			if barrierConnection then barrierConnection:Disconnect() barrierConnection = nil end

			setBarrierNoclip(value)

			if value then

				barrierConnection = RunService.Stepped:Connect(function()
					if barrierNoclipActive then
						setBarrierNoclip(true)
					end
				end)
			else
				setBarrierNoclip(false)
			end
		end
	})
end
--=======================================================================
-- Ocean Walk
--=======================================================================
do
	local oceanWallActive = false
	local oceanTransparency = 0.5
	local oceanConnection = nil

	local function getOceanObject()
		local map = Workspace:FindFirstChild("Map")
		local tweenedObjects = map and map:FindFirstChild("AlwaysHereTweenedObjects")
		local oceanGroup = tweenedObjects and tweenedObjects:FindFirstChild("Ocean")
		return oceanGroup and oceanGroup:FindFirstChild("Object")
	end

	local function applyProperties(part, value)
		if not part:IsA("BasePart") then return end
		part.CanCollide = value
		part.CanTouch = value
		part.CanQuery = value

		if value then
			part.Transparency = oceanTransparency
		else
			part.Transparency = 0
		end
	end

	local function updateOcean(value)
		local oceanObject = getOceanObject()
		if not oceanObject then return end

		if oceanObject:IsA("BasePart") then
			applyProperties(oceanObject, value)
		end

		for _, descendantPart in ipairs(oceanObject:GetDescendants()) do
			applyProperties(descendantPart, value)
		end
	end

	AntiETCGroupbox:AddCheckbox("OceanWalk", {
		Text = "Ocean Walk",
		Default = false,
		Callback = function(value)
			oceanWallActive = value
			if oceanConnection then oceanConnection:Disconnect() oceanConnection = nil end

			updateOcean(value)

			if value then

				oceanConnection = Workspace.DescendantAdded:Connect(function(descendant)
					if oceanWallActive then
						local oceanObject = getOceanObject()
						if oceanObject and (descendant == oceanObject or descendant:IsDescendantOf(oceanObject)) then
							applyProperties(descendant, true)
						end
					end
				end)
			else
				updateOcean(false)
			end
		end
	})
end
