--=======================================================================
-- Scroll Extend Grab
--=======================================================================
do
	local lineDistanceValue = 11
	local increaseLineExtendValue = 7
	local infiniteLineExtendEnabled = false

	local inputChangedConnection = nil
	local childAddedConnection = nil

	local function startInfiniteLineExtend()
		if not inputChangedConnection then
			inputChangedConnection = UserInputService.InputChanged:Connect(function(input)
				if not infiniteLineExtendEnabled then return end

				if input.UserInputType == Enum.UserInputType.MouseWheel then
					if lineDistanceValue < 11 then
						lineDistanceValue = 11
					end

					if input.Position.Z > 0 then
						lineDistanceValue = lineDistanceValue + increaseLineExtendValue
					elseif input.Position.Z < 0 then
						lineDistanceValue = lineDistanceValue - increaseLineExtendValue
					end
				end
			end)
		end

		if not childAddedConnection then
			childAddedConnection = Workspace.ChildAdded:Connect(function(addedChild)
				if not infiniteLineExtendEnabled then return end

				if addedChild.Name == "GrabParts" and addedChild:IsA("Model") then
					local grabPartsModel = addedChild
					local grabPart = grabPartsModel:WaitForChild("GrabPart", 2)
					local dragPart = grabPartsModel:WaitForChild("DragPart", 2)

					if not dragPart then return end

					local currentCamera = Workspace.CurrentCamera
					local clonedDragPart = dragPart:Clone()
					clonedDragPart.Name = "DragPart1"

					local dragAttachment = clonedDragPart:FindFirstChild("DragAttach")
					local alignPosition = clonedDragPart:FindFirstChild("AlignPosition")

					if alignPosition and dragAttachment then
						alignPosition.Attachment1 = dragAttachment
					end

					clonedDragPart.Parent = grabPartsModel

					if currentCamera then
						lineDistanceValue = (clonedDragPart.Position - currentCamera.CFrame.Position).Magnitude
					end

					local alignOrientation = clonedDragPart:FindFirstChild("AlignOrientation")
					if alignOrientation then
						alignOrientation.Enabled = false
					end

					local dragAlignPosition = dragPart:FindFirstChild("AlignPosition")
					if dragAlignPosition then
						dragAlignPosition.Enabled = false
					end

					task.spawn(function()
						while grabPartsModel.Parent and infiniteLineExtendEnabled do
							if Workspace.CurrentCamera then
								local cameraCFrame = Workspace.CurrentCamera.CFrame
								clonedDragPart.Position = cameraCFrame.Position + cameraCFrame.LookVector * lineDistanceValue
							end
							RunService.RenderStepped:Wait()
						end
						lineDistanceValue = 11
					end)
				end
			end)
		end
	end

	local function stopInfiniteLineExtend()
		if inputChangedConnection then
			inputChangedConnection:Disconnect()
			inputChangedConnection = nil
		end

		if childAddedConnection then
			childAddedConnection:Disconnect()
			childAddedConnection = nil
		end

		lineDistanceValue = 11
	end

	LineGroupbox:AddSlider("ScrollForceSlider", {
		Text = "Strength",
		Default = 0,
		Min = 0,
		Max = 100,
		Rounding = 0,
		Callback = function(value)
			increaseLineExtendValue = value
		end
	})

	LineGroupbox:AddCheckbox("ExtendLineToggle", {
		Text = "Scroll Extend Line",
		Default = false,
		Callback = function(value)
			infiniteLineExtendEnabled = value

			if value then
				startInfiniteLineExtend()
			else
				stopInfiniteLineExtend()
			end
		end
	})
end
--=======================================================================
-- Grab
--=======================================================================
local LoopGrabAuraActive = false
local LoopGrabAuraThread = nil
local LoopGrabAuraRange = math.huge

local function LoopGrabAuraFunction()
	while LoopGrabAuraActive do
		local myChar = LocalPlayer.Character
		if not myChar then
			task.wait(0.5)
			continue
		end

		local myHRP = myChar:FindFirstChild("HumanoidRootPart")
		if not myHRP then
			task.wait(0.5)
			continue
		end

		for _, player in ipairs(Players:GetPlayers()) do
			if player == LocalPlayer then continue end

			local char = player.Character
			if not char then continue end

			local hrp = char:FindFirstChild("HumanoidRootPart")
			if not hrp then continue end

			local hum = char:FindFirstChild("Humanoid")
			if not hum or hum.Health <= 0 then continue end

			local distance = (myHRP.Position - hrp.Position).Magnitude
			if distance <= LoopGrabAuraRange then
				pcall(function()
					if SetNetworkOwner then
						SetNetworkOwner:FireServer(hrp, CFrame.lookAt(myHRP.Position, hrp.Position))
					end
				end)
			end
		end

		task.wait(0.1)
	end
end

local function StartLoopGrabAura()
	if not SetNetworkOwner then return end
	if LoopGrabAuraActive then return end
	LoopGrabAuraActive = true
	LoopGrabAuraThread = task.spawn(LoopGrabAuraFunction)
end

local function StopLoopGrabAura()
	LoopGrabAuraActive = false
	if LoopGrabAuraThread then
		task.cancel(LoopGrabAuraThread)
		LoopGrabAuraThread = nil
	end
end
--=======================================================================
-- Air
--=======================================================================
local AirAuraActive = false
local AirAuraRange = 29
local AirAuraConnection = nil

local function AirAuraIsFriend(player)
	return false
end

local function AirAuraCanInteract(targetChar)
	return true
end

local function AirAuraHandlePartOwner(targetChar, callback)
	local root = targetChar:FindFirstChild("HumanoidRootPart")
	if root and SetNetworkOwner then
		pcall(function()
			SetNetworkOwner:FireServer(root, root.CFrame)
		end)
		callback()
	end
end

local function AirAuraPerform()
	AirAuraConnection = RunService.Heartbeat:Connect(function()
		if not AirAuraActive then return end

		local c = LocalPlayer.Character
		local hrp = c and c:FindFirstChild("HumanoidRootPart")
		if not hrp then return end

		for _, player in ipairs(Players:GetPlayers()) do
			if player ~= LocalPlayer and not AirAuraIsFriend(player) then
				local targetChar = player.Character
				if targetChar and AirAuraCanInteract(targetChar) then
					local tRoot = targetChar:FindFirstChild("HumanoidRootPart")
					local tHum = targetChar:FindFirstChild("Humanoid")

					if tRoot and tHum and tHum.Health > 0 and (hrp.Position - tRoot.Position).Magnitude <= AirAuraRange then
						pcall(function()
							if SetNetworkOwner then
								SetNetworkOwner:FireServer(tRoot, tRoot.CFrame)
							end
							if DestroyGrabLine then
								DestroyGrabLine:FireServer(tRoot)
							end
						end)

						AirAuraHandlePartOwner(targetChar, function()
							for _, part in ipairs(targetChar:GetChildren()) do
								if part:IsA("BasePart") then
									part.AssemblyLinearVelocity = Vector3.new(0, 150, 0)
								end
							end

							local bodyVelocity = tRoot:FindFirstChild("FlyAuraVelocity")
							if not bodyVelocity then
								bodyVelocity = Instance.new("BodyVelocity")
								bodyVelocity.Name = "FlyAuraVelocity"
								bodyVelocity.Velocity = Vector3.new(0, 100, 0)
								bodyVelocity.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
								bodyVelocity.P = 10000
								bodyVelocity.Parent = tRoot

								task.delay(1.5, function()
									if bodyVelocity and bodyVelocity.Parent then
										bodyVelocity:Destroy()
									end
								end)
							end
						end)
					end
				end
			end
		end
	end)
end

local function StartAirAura()
	if AirAuraActive then return end
	AirAuraActive = true
	if not AirAuraConnection then
		AirAuraPerform()
	end
end

local function StopAirAura()
	AirAuraActive = false
	if AirAuraConnection then
		AirAuraConnection:Disconnect()
		AirAuraConnection = nil
	end
end
--=======================================================================
-- Extreme Fly
--=======================================================================
local ExtremeFlyAuraActive = false
local ExtremeFlyAuraRange = 29
local ExtremeFlyAuraConnection = nil

local function ExtremeFlyAuraIsFriend(player)
	return false
end

local function ExtremeFlyAuraCanInteract(targetChar)
	return true
end

local function ExtremeFlyAuraHandlePartOwner(targetChar, callback)
	local root = targetChar:FindFirstChild("HumanoidRootPart")
	if root and SetNetworkOwner then
		pcall(function()
			SetNetworkOwner:FireServer(root, root.CFrame)
		end)
		callback()
	end
end

local function ExtremeFlyAuraPerform()
	ExtremeFlyAuraConnection = RunService.Heartbeat:Connect(function()
		if not ExtremeFlyAuraActive then return end

		local c = LocalPlayer.Character
		local hrp = c and c:FindFirstChild("HumanoidRootPart")
		if not hrp then return end

		for _, player in ipairs(Players:GetPlayers()) do
			if player ~= LocalPlayer and not ExtremeFlyAuraIsFriend(player) then
				local targetChar = player.Character
				if targetChar and ExtremeFlyAuraCanInteract(targetChar) then
					local tRoot = targetChar:FindFirstChild("HumanoidRootPart")
					local tHum = targetChar:FindFirstChild("Humanoid")

					if tRoot and tHum and tHum.Health > 0 and (hrp.Position - tRoot.Position).Magnitude <= ExtremeFlyAuraRange then
						pcall(function()
							if SetNetworkOwner then
								SetNetworkOwner:FireServer(tRoot, tRoot.CFrame)
							end
							if DestroyGrabLine then
								DestroyGrabLine:FireServer(tRoot)
							end
						end)

						ExtremeFlyAuraHandlePartOwner(targetChar, function()
							for _, part in ipairs(targetChar:GetChildren()) do
								if part:IsA("BasePart") then
									part.AssemblyLinearVelocity = Vector3.new(0, 99999, 0)
								end
							end

							local bodyVelocity = tRoot:FindFirstChild("FlyAuraVelocity")
							if not bodyVelocity then
								bodyVelocity = Instance.new("BodyVelocity")
								bodyVelocity.Name = "FlyAuraVelocity"
								bodyVelocity.Velocity = Vector3.new(0, 99999, 0)
								bodyVelocity.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
								bodyVelocity.P = 1000000
								bodyVelocity.Parent = tRoot

								task.delay(1.5, function()
									if bodyVelocity and bodyVelocity.Parent then
										bodyVelocity:Destroy()
									end
								end)
							end
						end)
					end
				end
			end
		end
	end)
end

local function StartExtremeFlyAura()
	if ExtremeFlyAuraActive then return end
	ExtremeFlyAuraActive = true
	if not ExtremeFlyAuraConnection then
		ExtremeFlyAuraPerform()
	end
end

local function StopExtremeFlyAura()
	ExtremeFlyAuraActive = false
	if ExtremeFlyAuraConnection then
		ExtremeFlyAuraConnection:Disconnect()
		ExtremeFlyAuraConnection = nil
	end
end
--=======================================================================
-- Telekinesis
--=======================================================================
local TelekinesisBodies = {}
local TelekinesisActive = false
local TornadoOffset, TornadoHeight, TornadoSpeed = 10, 5, 0.1
local TornadoFollowPlayer, TelekinesisFallback = "", Vector3.new(0, 10, 0)

local function TelekinesisClearBodies()
	for _, v in pairs(TelekinesisBodies) do
		if v and v.Parent then
			v:Destroy()
		end
	end
	TelekinesisBodies = {}
end

local function TelekinesisApplyMotion(part, cframe, angle, radius, height)
	if not part or part.Anchored then return end

	local bp = part:FindFirstChild("TornadoAuraVelocity")
	if not bp then
		bp = Instance.new("BodyPosition")
		bp.Name = "TornadoAuraVelocity"
		bp.MaxForce = Vector3.new(1e6, 1e6, 1e6)
		bp.P = 50000
		bp.D = 1250
		bp.Parent = part
		table.insert(TelekinesisBodies, bp)
	end
	bp.Position = Vector3.new(
		cframe.Position.X + math.cos(angle) * radius,
		cframe.Position.Y + height,
		cframe.Position.Z + math.sin(angle) * radius
	)

	local bav = part:FindFirstChild("TornadoAuraAngularVelocity")
	if not bav then
		bav = Instance.new("BodyAngularVelocity")
		bav.Name = "TornadoAuraAngularVelocity"
		bav.MaxTorque = Vector3.new(1e5, 1e5, 1e5)
		bav.AngularVelocity = Vector3.new(0, TornadoSpeed * 10, 0)
		bav.Parent = part
	else
		bav.AngularVelocity = Vector3.new(0, TornadoSpeed * 10, 0)
	end
end

local function TelekinesisSetNetworkOwnerPart(part)
	if not part or part.Anchored then return end
	pcall(function()
		if SetNetworkOwner then
			SetNetworkOwner:FireServer(part, part.CFrame)
		end
	end)
	part:SetAttribute("SetNetworkDone", true)
end

local function TelekinesisGetPlayerRoot(player)
	local char = player.Character
	if char then
		return char:FindFirstChild("HumanoidRootPart")
	end
end

local function TelekinesisProcessTargets(centerCFrame, angle)
	local lpRoot = TelekinesisGetPlayerRoot(LocalPlayer)
	local lpPos = lpRoot and lpRoot.Position or TelekinesisFallback

	for _, p in pairs(Players:GetPlayers()) do
		if p ~= LocalPlayer then
			local root = TelekinesisGetPlayerRoot(p)
			if root and not root.Anchored then
				if (lpPos - root.Position).Magnitude <= 29 then
					TelekinesisApplyMotion(root, centerCFrame, angle, TornadoOffset, TornadoHeight)
					TelekinesisSetNetworkOwnerPart(root)
				end
			end
		end
	end
end

RunService.Heartbeat:Connect(function()
	if not TelekinesisActive then
		TelekinesisClearBodies()
		return
	end

	local centerCFrame
	if TornadoFollowPlayer ~= "" then
		local tp = Players:FindFirstChild(TornadoFollowPlayer)
		centerCFrame = tp and TelekinesisGetPlayerRoot(tp) and TelekinesisGetPlayerRoot(tp).CFrame or CFrame.new(TelekinesisFallback)
	else
		local root = TelekinesisGetPlayerRoot(LocalPlayer)
		centerCFrame = root and root.CFrame or CFrame.new(TelekinesisFallback)
	end

	local angle = (tick() * TornadoSpeed * 2 * math.pi) % (2 * math.pi)
	TelekinesisProcessTargets(centerCFrame, angle)
end)

local function StartTelekinesisAura()
	TelekinesisActive = true
end

local function StopTelekinesisAura()
	TelekinesisActive = false
	TelekinesisClearBodies()
end
--=======================================================================
-- Remove Anti Kick
--=======================================================================
local DestroyAntiKickActive = false
local DestroyAntiKickThread = nil
local DestroyAntiKickRange = math.huge

local function DestroyAntiKickFunction()
	while DestroyAntiKickActive do
		local myChar = LocalPlayer.Character
		if not myChar then
			task.wait(0.5)
			continue
		end

		local myHRP = myChar:FindFirstChild("HumanoidRootPart")
		if not myHRP then
			task.wait(0.5)
			continue
		end

		for _, player in ipairs(Players:GetPlayers()) do
			if player == LocalPlayer then continue end

			local char = player.Character
			if not char then continue end

			local hrp = char:FindFirstChild("HumanoidRootPart")
			if not hrp then continue end

			local hum = char:FindFirstChild("Humanoid")
			if not hum or hum.Health <= 0 then continue end

			local distance = (myHRP.Position - hrp.Position).Magnitude
			if distance <= DestroyAntiKickRange then
				local target = player

				if target and target.Parent then
					local SetNetOwner = SetNetworkOwner or (ReplicatedStorage:FindFirstChild("GrabEvents") and ReplicatedStorage.GrabEvents:FindFirstChild("SetNetworkOwner"))

					if SetNetOwner then
						local spawned = workspace:FindFirstChild(target.Name .. "SpawnedInToys")

						if spawned then
							local toysToCheck = {"NinjaKunai", "NinjaShuriken", "AntiKick"}

							for _, toyName in ipairs(toysToCheck) do
								local toy = spawned:FindFirstChild(toyName)
								if toy then
									local soundPart = toy:FindFirstChild("SoundPart")
									if soundPart then
										pcall(function()
											SetNetOwner:FireServer(soundPart, soundPart.CFrame)
										end)

										local partOwner = soundPart:FindFirstChild("PartOwner")
										if partOwner and partOwner.Value == LocalPlayer.Name then
											pcall(function()
												soundPart.CFrame = CFrame.new(0, 1000, 0)
											end)
										end
									end
								end
							end
						end
					end
				end
			end
		end

		task.wait(0.1)
	end
end

local function StartDestroyAntiKickAura()
	local SetNetOwner = SetNetworkOwner or (ReplicatedStorage:FindFirstChild("GrabEvents") and ReplicatedStorage.GrabEvents:FindFirstChild("SetNetworkOwner"))
	if not SetNetOwner then return end
	if DestroyAntiKickActive then return end
	DestroyAntiKickActive = true
	DestroyAntiKickThread = task.spawn(DestroyAntiKickFunction)
end

local function StopDestroyAntiKickAura()
	DestroyAntiKickActive = false
	if DestroyAntiKickThread then
		task.cancel(DestroyAntiKickThread)
		DestroyAntiKickThread = nil
	end
end
--=======================================================================
-- Aura Mode
--=======================================================================
do
	local AuraModes = {
		"Grab",
		"Kick",
		"Air",
		"Telekinesis",
		"Remove Anti Kick"
	}

	local SelectedAuraMode = AuraModes[1]
	local AuraEnabled = false

	local function StopAllAuras()
		StopLoopGrabAura()
		StopAirAura()
		StopExtremeFlyAura()
		StopTelekinesisAura()
		StopDestroyAntiKickAura()
	end

	local function StartAuraByMode(mode)
		if mode == "Grab" then
			StartLoopGrabAura()
		elseif mode == "Kick" then
			StartExtremeFlyAura()
		elseif mode == "Air" then
			StartAirAura()
		elseif mode == "Telekinesis" then
			StartTelekinesisAura()
		elseif mode == "Remove Anti Kick" then
			StartDestroyAntiKickAura()
		end
	end

	AuraGroupbox:AddDropdown("AuraModeDropdown", {
		Text = "Aura Mode",
		Values = AuraModes,
		Default = 1,
		Multi = false,
		Callback = function(Value)
			SelectedAuraMode = Value

			if AuraEnabled then
				StopAllAuras()
				StartAuraByMode(SelectedAuraMode)
			end
		end
	})

	AuraGroupbox:AddCheckbox("AuraModeToggle", {
		Text = "Toggle",
		Default = false,
		Callback = function(Value)
			AuraEnabled = Value

			if Value then
				StopAllAuras()
				StartAuraByMode(SelectedAuraMode)
			else
				StopAllAuras()
			end
		end
	})
end
