Players.PlayerRemoving:Connect(updateRemoveDropdown)
--=======================================================================
-- Remove Anti Kick
--=======================================================================
do
    local antiAntiKickActive = false
    local antiKickThread = nil

    local function startAntiAntiKick()
        if antiKickThread then
            task.cancel(antiKickThread)
            antiKickThread = nil
        end

        antiKickThread = task.spawn(function()
            local lastCheck = 0
            
            while antiAntiKickActive do
                local now = tick()
                
                if now - lastCheck >= 0.3 then
                    lastCheck = now
                    
                    local target = removeSelectedPlayer
                    
                    if target and target.Parent then
                        local SetNetOwner = SetNetworkOwner or (ReplicatedStorage:FindFirstChild("GrabEvents") and ReplicatedStorage.GrabEvents:FindFirstChild("SetNetworkOwner"))
                        
                        if SetNetOwner then
                            local spawned = workspace:FindFirstChild(target.Name .. "SpawnedInToys")
                            
                            if spawned then
                                local toysToCheck = {"NinjaKunai", "NinjaShuriken", "AntiKick"}
                                
                                for _, toyName in ipairs(toysToCheck) do
                                    local toy = spawned:FindFirstChild(toyName)
                                    if toy then
                                        local soundPart = toy:FindFirstChild("SoundPart")
                                        if soundPart then
                                            pcall(function()
                                                SetNetOwner:FireServer(soundPart, soundPart.CFrame)
                                            end)
                                            
                                            local partOwner = soundPart:FindFirstChild("PartOwner")
                                            if partOwner and partOwner.Value == LocalPlayer.Name then
                                                pcall(function()
                                                    soundPart.CFrame = CFrame.new(0, 1000, 0)
                                                end)
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
                
                RunService.Heartbeat:Wait()
            end
        end)
    end

    RemoveGroupbox:AddCheckbox("DestroyAntiKickToggle", {
        Text = "Remove Anti Kick",
        Default = false,
        Callback = function(Value)
            antiAntiKickActive = Value
            if Value then
                if not removeSelectedPlayer then
                    if Toggles and Toggles.DestroyAntiKickToggle then
                        Toggles.DestroyAntiKickToggle:SetValue(false)
                    end
                    antiAntiKickActive = false
                    return
                end
                startAntiAntiKick()
            else
                if antiKickThread then
                    task.cancel(antiKickThread)
                    antiKickThread = nil
                end
            end
        end
    })
end
--=======================================================================
-- Remove Gucci
--=======================================================================
do
    local DestroyTargetGucciActive = false
    local SafeSpot = nil
    local folderName = nil

    RemoveGroupbox:AddCheckbox("DestroyTargetGucci", {
        Text = "Remove Gucci [Blob]",
        Default = false,
        Callback = function(Value)
            DestroyTargetGucciActive = Value

            if Value then
                local target = removeSelectedPlayer
                if not target then
                    if Toggles and Toggles.DestroyTargetGucci then
                        Toggles.DestroyTargetGucci:SetValue(false)
                    end
                    DestroyTargetGucciActive = false
                    return
                end

                local char = LocalPlayer.Character
                local root = char and char:FindFirstChild("HumanoidRootPart")
                if not root then
                    if Toggles and Toggles.DestroyTargetGucci then
                        Toggles.DestroyTargetGucci:SetValue(false)
                    end
                    DestroyTargetGucciActive = false
                    return
                end
                SafeSpot = root.CFrame

                folderName = target.Name .. "SpawnedInToys"

                task.spawn(function()
                    while DestroyTargetGucciActive do

                        target = removeSelectedPlayer
                        if not target or not target.Parent then
                            DestroyTargetGucciActive = false
                            if Toggles and Toggles.DestroyTargetGucci then
                                Toggles.DestroyTargetGucci:SetValue(false)
                            end
                            break
                        end

                        folderName = target.Name .. "SpawnedInToys"
                        local toysFolder = workspace:FindFirstChild(folderName)
                        if toysFolder then
                            for _, obj in ipairs(toysFolder:GetChildren()) do
                                if not DestroyTargetGucciActive then break end

                                if obj.Name == "CreatureBlobman" then
                                    local seat = obj:FindFirstChild("VehicleSeat")
                                        or obj:FindFirstChildWhichIsA("VehicleSeat", true)

                                    if seat then
                                        local myChar = LocalPlayer.Character
                                        local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
                                        local myHum  = myChar and myChar:FindFirstChild("Humanoid")

                                        if myRoot and myHum and myHum.SeatPart ~= seat then

                                            local magnetConn
                                            magnetConn = RunService.Stepped:Connect(function()
                                                if myRoot and seat then
                                                    myRoot.CFrame = seat.CFrame
                                                    myRoot.Velocity = Vector3.zero
                                                    if obj.PrimaryPart then
                                                        obj.PrimaryPart.Velocity    = Vector3.zero
                                                        obj.PrimaryPart.RotVelocity = Vector3.zero
                                                    end
                                                end
                                            end)

                                            local sitStart = tick()
                                            while tick() - sitStart < 1 do
                                                if not DestroyTargetGucciActive then break end
                                                if myHum.SeatPart == seat then break end
                                                seat:Sit(myHum)
                                                task.wait()
                                            end

                                            magnetConn:Disconnect()

                                            if myHum.SeatPart == seat then
                                                task.wait(0.3)
                                                myHum.Sit = false
                                                myHum.Jump = true
                                                task.wait(0.05)
                                                myRoot.CFrame    = SafeSpot
                                                myRoot.Velocity  = Vector3.zero
                                                task.wait(0.5)
                                                
                                                pcall(function()
                                                    Camera.CameraType = Enum.CameraType.Custom
                                                    Camera.CameraSubject = myChar:FindFirstChild("Humanoid")
                                                end)
                                            else
                                                myRoot.CFrame = SafeSpot
                                            end
                                        end
                                    end
                                end
                            end
                        end

                        task.wait(1)   
                    end
                end)
            else
                pcall(function()
                    Camera.CameraType = Enum.CameraType.Custom
                    Camera.CameraSubject = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("Humanoid")
                end)
            end
        end
    })
end
