-- Name & Profile Esp
--=======================================================================
do
	local nameEspEnabled = false
	local nameEspCache = {}
	local profileEspEnabled = false
	local profileEspCache = {}
	local selectedFont = Enum.Font.SourceSansBold 

	local function applyName(player, character)
		if not nameEspEnabled or player == LocalPlayer or not character then return end

		if nameEspCache[player] then
			nameEspCache[player]:Destroy()
			nameEspCache[player] = nil
		end

		local headPart = character:WaitForChild("Head", 5)
		if not headPart or not nameEspEnabled then return end

		if headPart:FindFirstChild("NameESP") then
			headPart.NameESP:Destroy()
		end

		local billboardGui = Instance.new("BillboardGui")
		billboardGui.Name = "NameESP"
		billboardGui.Size = UDim2.new(0, 200, 0, 40)
		billboardGui.Adornee = headPart
		billboardGui.AlwaysOnTop = true
		billboardGui.StudsOffset = Vector3.new(0, 2, 0)

		local textLabel = Instance.new("TextLabel")
		textLabel.Size = UDim2.new(1, 0, 1, 0)
		textLabel.BackgroundTransparency = 1
		textLabel.Text = player.DisplayName .. " (@" .. player.Name .. ")"
		textLabel.TextColor3 = Color3.fromRGB(255, 255, 255)
		textLabel.TextStrokeTransparency = 0
		textLabel.TextScaled = false
		textLabel.TextSize = 14
		textLabel.Font = selectedFont 
		textLabel.Parent = billboardGui
		billboardGui.Parent = headPart

		nameEspCache[player] = billboardGui
	end

	local function applyProfile(player, character)
		if not profileEspEnabled or player == LocalPlayer or not character then return end

		if profileEspCache[player] then
			profileEspCache[player]:Destroy()
			profileEspCache[player] = nil
		end

		local headPart = character:WaitForChild("Head", 5)
		if not headPart or not profileEspEnabled then return end

		if headPart:FindFirstChild("ProfileESP") then
			headPart.ProfileESP:Destroy()
		end

		local userId = player.UserId
		local thumbType = Enum.ThumbnailType.HeadShot
		local thumbSize = Enum.ThumbnailSize.Size420x420
		local content, isReady = Players:GetUserThumbnailAsync(userId, thumbType, thumbSize)

		local billboardGui = Instance.new("BillboardGui")
		billboardGui.Name = "ProfileESP"
		billboardGui.Size = UDim2.new(0, 80, 0, 110)
		billboardGui.Adornee = headPart
		billboardGui.AlwaysOnTop = true
		billboardGui.StudsOffset = Vector3.new(0, 2.5, 0)

		local imageLabel = Instance.new("ImageLabel")
		imageLabel.Size = UDim2.new(1, 0, 0, 80)
		imageLabel.BackgroundTransparency = 1
		imageLabel.Image = content
		imageLabel.Parent = billboardGui

		local textLabel = Instance.new("TextLabel")
		textLabel.Size = UDim2.new(1, 0, 0, 30)
		textLabel.Position = UDim2.new(0, 0, 0, 80)
		textLabel.BackgroundTransparency = 1
		textLabel.Text = player.DisplayName .. " (@" .. player.Name .. ")"
		textLabel.TextColor3 = Color3.fromRGB(255, 255, 255)
		textLabel.TextStrokeTransparency = 0
		textLabel.TextScaled = true
		textLabel.TextSize = 12
		textLabel.Font = selectedFont 
		textLabel.Parent = billboardGui

		billboardGui.Parent = headPart

		profileEspCache[player] = billboardGui
	end

	local function trackNamePlayer(player)
		if player == LocalPlayer then return end

		if player.Character then
			task.spawn(applyName, player, player.Character)
		end

		player.CharacterAdded:Connect(function(character)
			task.spawn(applyName, player, character)
		end)
	end

	local function trackProfilePlayer(player)
		if player == LocalPlayer then return end

		if player.Character then
			task.spawn(applyProfile, player, player.Character)
		end

		player.CharacterAdded:Connect(function(character)
			task.spawn(applyProfile, player, character)
		end)
	end
	
	VisualGroupbox:AddDivider()
	local fontDropdown = VisualGroupbox:AddDropdown("FontDropdown", {
		Text = "Font",
		Values = {
			"SourceSansBold",
			"GothamBold",
			"ArialBold",
			"FredokaOne",
			"Jura"
		},
		Default = 1,
		Multi = false,
		Callback = function(value)
			selectedFont = Enum.Font[value]

			if nameEspEnabled then
				for player, billboard in pairs(nameEspCache) do
					if billboard then billboard:Destroy() end
				end
				nameEspCache = {}
				
				for _, player in pairs(Players:GetPlayers()) do
					if player ~= LocalPlayer and player.Character then
						task.spawn(applyName, player, player.Character)
					end
				end
			end

			if profileEspEnabled then
				for player, billboard in pairs(profileEspCache) do
					if billboard then billboard:Destroy() end
				end
				profileEspCache = {}
				
				for _, player in pairs(Players:GetPlayers()) do
					if player ~= LocalPlayer and player.Character then
						task.spawn(applyProfile, player, player.Character)
					end
				end
			end
		end
	})
	
	local nameToggle = VisualGroupbox:AddCheckbox("NameToggle", {
		Text = "Name ESP",
		Default = false,
		Callback = function(value)
			nameEspEnabled = value
			if not value then
				for player, billboard in pairs(nameEspCache) do
					if billboard then billboard:Destroy() end
				end
				nameEspCache = {}
			else
				for _, player in pairs(Players:GetPlayers()) do
					if player ~= LocalPlayer and player.Character then
						task.spawn(applyName, player, player.Character)
					end
				end
			end
		end
	})

	local profileToggle = VisualGroupbox:AddCheckbox("ProfileToggle", {
		Text = "Profile & Name ESP",
		Default = false,
		Callback = function(value)
			profileEspEnabled = value
			if not value then
				for player, billboard in pairs(profileEspCache) do
					if billboard then billboard:Destroy() end
				end
				profileEspCache = {}
			else
				for _, player in pairs(Players:GetPlayers()) do
					if player ~= LocalPlayer and player.Character then
						task.spawn(applyProfile, player, player.Character)
					end
				end
			end
		end
	})

	for _, player in pairs(Players:GetPlayers()) do
		trackNamePlayer(player)
		trackProfilePlayer(player)
	end

	Players.PlayerAdded:Connect(function(player)
		trackNamePlayer(player)
		trackProfilePlayer(player)
	end)

	Players.PlayerRemoving:Connect(function(player)
		if nameEspCache[player] then
			nameEspCache[player]:Destroy()
			nameEspCache[player] = nil
		end
		if profileEspCache[player] then
			profileEspCache[player]:Destroy()
			profileEspCache[player] = nil
		end
	end)
end
--=======================================================================
-- Field of View & Zoom
--=======================================================================
do
	local currentCamera = Workspace.CurrentCamera
	local defaultFieldOfView = 70
	local targetFOV = defaultFieldOfView
	local currentFOV = defaultFieldOfView
	local tweenInfo = TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
	local isFOVEnabled = false
	local renderSteppedConnection = nil
	local savedFOVValue = defaultFieldOfView
	
	local minZoomFOV = 70  
	local maxZoomFOV = 10   
	local isHoldingZoom = false
	local zoomRenderConnection = nil
	local holdStartTime = 0
	local isKeyPressed = false
	local isZoomActive = false
	local originalMouseSensitivity = nil

	if currentCamera then
		currentCamera.FieldOfView = defaultFieldOfView
	end

	local function updateMouseSensitivity()
		local camera = Workspace.CurrentCamera
		if not camera then return end
		
		if isZoomActive then
			local zoomRatio = (minZoomFOV - camera.FieldOfView) / (minZoomFOV - maxZoomFOV)
			local sensitivityMultiplier = 1 - (zoomRatio * 0.85) 
			
			UserInputService.MouseDeltaSensitivity = (originalMouseSensitivity or UserInputService.MouseDeltaSensitivity) * sensitivityMultiplier
		else
			if originalMouseSensitivity then
				UserInputService.MouseDeltaSensitivity = originalMouseSensitivity
				originalMouseSensitivity = nil
			end
		end
	end

	local function startFOVControl()
		if renderSteppedConnection then
			renderSteppedConnection:Disconnect()
			renderSteppedConnection = nil
		end

		targetFOV = savedFOVValue
		currentFOV = defaultFieldOfView

		renderSteppedConnection = RunService.RenderStepped:Connect(function(deltaTime)
			if isZoomActive then return end
			
			local camera = Workspace.CurrentCamera
			if camera and math.abs(currentFOV - targetFOV) > 0.1 then
				local alpha = 1 - math.exp(-15 * deltaTime) 
				currentFOV = currentFOV + (targetFOV - currentFOV) * alpha
				camera.FieldOfView = currentFOV
			elseif camera and math.abs(currentFOV - targetFOV) <= 0.1 then
				currentFOV = targetFOV
				camera.FieldOfView = targetFOV
			end
		end)
	end

	local function stopFOVControl()
		if renderSteppedConnection then
			renderSteppedConnection:Disconnect()
			renderSteppedConnection = nil
		end
		
		if not isZoomActive then
			local camera = Workspace.CurrentCamera
			if camera then
				camera.FieldOfView = defaultFieldOfView
				currentFOV = defaultFieldOfView
			end
		end
	end

	local function stopZoomRender()
		if zoomRenderConnection then
			zoomRenderConnection:Disconnect()
			zoomRenderConnection = nil
		end
	end

	local function startZoom()
		if isZoomActive then return end
		
		isZoomActive = true
		
		local camera = Workspace.CurrentCamera
		if not camera then return end
		
		if renderSteppedConnection then
			renderSteppedConnection:Disconnect()
			renderSteppedConnection = nil
		end

		originalMouseSensitivity = UserInputService.MouseDeltaSensitivity
		
		currentFOV = camera.FieldOfView
	end

	local function stopZoom()
		if not isZoomActive then return end
		
		isZoomActive = false
		isHoldingZoom = false
		
		local camera = Workspace.CurrentCamera
		if not camera then return end
		
		stopZoomRender()
		
		if originalMouseSensitivity then
			UserInputService.MouseDeltaSensitivity = originalMouseSensitivity
			originalMouseSensitivity = nil
		end
		
		if isFOVEnabled then
			targetFOV = savedFOVValue
			currentFOV = camera.FieldOfView
			startFOVControl()
		else
			camera.FieldOfView = defaultFieldOfView
			currentFOV = defaultFieldOfView
		end
	end

	local function updateZoomHold()
		if not isHoldingZoom or not isZoomActive then return end
		
		local camera = Workspace.CurrentCamera
		if not camera then return end
		
		local holdDuration = tick() - holdStartTime

		local zoomProgress = math.clamp(holdDuration / 1.0, 0, 1)

		local targetZoomFOV = minZoomFOV - ((minZoomFOV - maxZoomFOV) * zoomProgress)

		camera.FieldOfView = camera.FieldOfView + (targetZoomFOV - camera.FieldOfView) * 0.2

		currentFOV = camera.FieldOfView
		
		updateMouseSensitivity()
	end

	CameraGroupbox:AddSlider("FieldOfViewSlider", {
		Text = "Field of View",
		Default = defaultFieldOfView,
		Min = 40,
		Max = 120,
		Rounding = 0,
		Callback = function(value)
			savedFOVValue = value
			
			if isFOVEnabled and not isZoomActive then
				targetFOV = value
			end
		end
	})

	CameraGroupbox:AddCheckbox("FOVToggle", {
		Text = "Toggle",
		Default = false,
		Callback = function(value)
