local MusicPlayer = {}
MusicPlayer.Database = {}
pcall(function()
	local function hasNonAscii(str)
		for i = 1, #str do
			if str:byte(i) > 127 then
				return true
			end
		end
		return false
	end

	for _, file in ipairs(listfiles("lunaBGM")) do
		print("[ovitar BGM] Scanned file:", tostring(file))
		if file:sub(-4):lower() == ".mp3" then
			local cleanPath = file:gsub("^workspace[/\\]", ""):gsub("\\", "/")
			if isfile(cleanPath) then
				local filename = cleanPath:match("[^/]+$")
				local name = filename:gsub("%.mp3$", ""):gsub("%.ft2$", "")
				
				if hasNonAscii(filename) then
					warn("[ovitar BGM] Skipping file (non-ASCII/Korean characters) to prevent executor crash: " .. filename)
				else
					table.insert(MusicPlayer.Database, {cleanPath, name})
					print("[ovitar BGM] Loaded song:", name, "->", cleanPath)
				end
			end
		end
	end
end)

-- Fisher-Yates shuffle to randomize the song order on startup!
if #MusicPlayer.Database > 1 then
	math.randomseed(os.time())
	for i = #MusicPlayer.Database, 2, -1 do
		local j = math.random(1, i)
		MusicPlayer.Database[i], MusicPlayer.Database[j] = MusicPlayer.Database[j], MusicPlayer.Database[i]
	end
end


MusicPlayer.Switching = false
MusicPlayer.Last = 1
MusicPlayer.PlayMusic = function(i)
	if #MusicPlayer.Database == 0 then return end
	if MusicPlayer.Switching then return end
	MusicPlayer.Switching = true
	local last = MusicPlayer.LastMusic
	if not i then
		i = last
		while i == last do
			i = math.random(1, #MusicPlayer.Database)
			task.wait()
		end
	end
	MusicPlayer.LastMusic = i
	local hi = MusicPlayer.Database[i]
	local soundid, soundname = hi[1], hi[2]
	local s, id = pcall(isfile, soundid)
	if s and id then
		s, id = pcall(getcustomasset, soundid)
		if s then
			soundid = id
		else
			soundid = ""
		end
	else
		soundid = ""
	end
	if #soundid == 0 then
		MusicPlayer.Switching = false
		return MusicPlayer.PlayMusic()
	end
	UISound.Music.SoundId = soundid
	UISound.Music.Name = soundname
	
	_G.BgmIgnoreCallback = true
	pcall(function()
		if _G.BgmDropdown then
			_G.BgmDropdown:SetValue(soundname)
		end
	end)
	_G.BgmIgnoreCallback = false
	
	UISound.Music:Stop()
	task.wait()
	UISound.Music.TimePosition = 0
	task.wait()
	UISound.Music:Play()
	task.wait()
	MusicPlayer.Switching = false
end
UISound.Music.Ended:Connect(function()
	MusicPlayer.PlayMusic()
end)

