-- Make Entire TopStatusGui Draggable with Smooth Mouse Input
do
	local UserInputService = game:GetService("UserInputService")
	local dragging = false
	local dragInput, dragStart, startPos

	local function update(input)
		local delta = input.Position - dragStart
		TopStatusGui.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
	end

	Pill1.InputBegan:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			dragging = true
			dragStart = input.Position
			startPos = TopStatusGui.Position

			input.Changed:Connect(function()
				if input.UserInputState == Enum.UserInputState.End then
					dragging = false
				end
			end)
		end
	end)

	Pill2.InputBegan:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			dragging = true
			dragStart = input.Position
			startPos = TopStatusGui.Position

			input.Changed:Connect(function()
				if input.UserInputState == Enum.UserInputState.End then
					dragging = false
				end
			end)
		end
	end)

	UserInputService.InputChanged:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
			if dragging then
				update(input)
			end
		end
	end)
end

local FrameTimer = tick()
local FrameCounter = 0
local FPS = 60

local WatermarkConnection = rs2.Heartbeat:Connect(function()
    FrameCounter += 1

    if (tick() - FrameTimer) >= 1 then
        FPS = FrameCounter
        FrameTimer = tick()
        FrameCounter = 0
    end

    local pingVal = math.floor(game:GetService('Stats').Network.ServerStatsItem['Data Ping']:GetValue())
    local fpsVal = math.floor(FPS)
    local clockTime = os.date("%H:%M:%S")
    local plrName = plr.DisplayName or plr.Name

    -- Dynamic Colors for FPS & Ping Status Dots (Obsidian Neon Glow Palette)
    local fpsDotColor = (fpsVal >= 60 and "rgb(52,211,153)") or (fpsVal >= 30 and "rgb(251,191,36)") or "rgb(248,113,113)"
    local pingDotColor = (pingVal <= 80 and "rgb(52,211,153)") or (pingVal <= 150 and "rgb(251,191,36)") or "rgb(248,113,113)"

    -- Numbers are pure WHITE, separators are Obsidian Slate, ONLY dots remain colored!
    StatsText.Text = ('<b><font color="rgb(245,245,250)">%s</font></b> <font color="rgb(110,100,140)">|</font> <font color="%s">●</font> <b><font color="rgb(245,245,250)">%s</font></b> <font color="rgb(160,160,180)">fps</font> <font color="rgb(110,100,140)">|</font> <font color="rgb(220,220,235)">%s</font> <font color="rgb(110,100,140)">|</font> <font color="%s">●</font> <b><font color="rgb(245,245,250)">%s</font></b><font color="rgb(160,160,180)">ms</font>'):format(
        plrName,
        fpsDotColor, fpsVal,
        clockTime,
        pingDotColor, pingVal
    )
end)

