            if not main then return end
            
            local fr
            for _, v in ipairs(main:GetChildren()) do
                if v:IsA("Frame") and (v.Position == UDim2.new(0, 0, 0, 0) or v:FindFirstChildOfClass("ImageLabel")) then
                    fr = v
                    break
                end
            end
            
            if not fr then
                fr = main:FindFirstChildOfClass("Frame")
            end
            
            if fr and not fr:FindFirstChild("SantaHatDecoration") then
                local logoImg = fr:FindFirstChildOfClass("ImageLabel")
                local clone
                if logoImg then
                    clone = logoImg:Clone()
                else
                    clone = Instance.new("ImageLabel")
