processed = {}
redBoxes = {}
LBox:AddToggle("PCLDESP", {
    Text = "PCLD ESP",
    --Tooltip = "This is a tooltip",
    --DisabledTooltip = "I am disabled!",
    Default = false,
    Callback = function(Value)
        PcldViewT = Value
        
        if descendantConn then
            descendantConn:Disconnect()
            descendantConn = nil
            workspace:SetAttribute("PcldViewDescendantConn", false)
        end

        if PcldViewT then
            for _, obj in ipairs(workspace:GetChildren()) do
                if (obj.Name == "PlayerCharacterLocationDetector" or obj.Name == "me") and obj:IsA("BasePart") then
                    if not processed[obj] then
                        local box = Instance.new("SelectionBox")
                        box.Adornee = obj
                        box.LineThickness = 0.005
                        box.SurfaceTransparency = 1
                        box.SurfaceColor3 = Color3.fromRGB(255, 255, 255)
                        box.Color3 = Color3.fromRGB(255, 255, 255)
                        box.Parent = obj
                        processed[obj] = true
                        redBoxes[obj] = box
                    end
                end
            end

            descendantConn = workspace.DescendantAdded:Connect(function(obj)
                if PcldViewT and (obj.Name == "PlayerCharacterLocationDetector" or obj.Name == "me") and obj:IsA("BasePart") then
                    if not processed[obj] then
                        local box = Instance.new("SelectionBox")
                        box.Adornee = obj
                        box.LineThickness = 0.005
                        box.SurfaceTransparency = 1
                        box.SurfaceColor3 = Color3.fromRGB(255, 255, 255)
                        box.Color3 = Color3.fromRGB(255, 255, 255)
                        box.Parent = obj
                        processed[obj] = true
                        redBoxes[obj] = box
                    end
                end
            end)

            workspace.DescendantRemoving:Connect(function(obj)
                if redBoxes[obj] then
                    redBoxes[obj]:Destroy()
                    redBoxes[obj] = nil
                    processed[obj] = nil
                end
            end)
        else
            for obj, box in pairs(redBoxes) do
                if box then box:Destroy() end
            end
            redBoxes = {}
            processed = {}
        end
    end
})

LBox:AddToggle("StickyPartESP", {
    Text = "쿠나이 ESP",
    Default = false,
    Callback = function(Value)
        ViewToolT = Value

        if ViewToolC then 
            ViewToolC:Disconnect()
            ViewToolC = nil 
        end

        if Value then
            local lastCheck = 0
            local checkInterval = 0.5

            local toolsList = {"NinjaKunai", "NinjaShuriken", "NinjaKatana", "ToolCleaver", "ToolDiggingForkRusty", "ToolPencil", "ToolPickaxe"}
            local cpfList = {}-- {"Campfire"}

            local allHighlights = {}

            ViewToolC = rs2.Heartbeat:Connect(function()
                if tick() - lastCheck < checkInterval then return end
                lastCheck = tick()

                local folders = {}
                for _, folder in ipairs(workspace:GetChildren()) do
                    if folder:IsA("Folder") and folder.Name:match("SpawnedInToys$") then
                        table.insert(folders, folder)
                    end
                end

                if workspace:FindFirstChild("PlotItems") then
                    for i = 1, 5 do
                        local p = workspace.PlotItems:FindFirstChild("Plot" .. i)
                        if p then table.insert(folders, p) end
                    end
                end

                for _, folder in ipairs(folders) do
                    for _, item in ipairs(folder:GetChildren()) do
                        if item:IsA("Model") then
                            local targetPartName = nil

                            if table.find(toolsList, item.Name) then
                                targetPartName = "StickyPart"
                            elseif table.find(cpfList, item.Name) then
                                targetPartName = "FirePlayerPart"
                            end

                            if targetPartName then
                                if not item:FindFirstChild("Highlight_ESP") then
                                    local hl = Instance.new("Highlight")
                                    hl.Name = "Highlight_ESP"
                                    hl.Adornee = item
                                    hl.FillTransparency = 1
                                    hl.OutlineTransparency = 0
                                    hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop

                                    if item.Parent and item.Parent.Name:match("^Plot") then
                                        hl.OutlineColor = Color3.fromRGB(234, 215, 198)
                                    --elseif item.Name == "Campfire" then
                                    --    hl.OutlineColor = Color3.fromRGB(105, 102, 92)
                                    else
                                        hl.OutlineColor = Color3.fromRGB(255, 255, 255)
                                    end

                                    hl.Parent = item
                                    table.insert(allHighlights, hl)
                                end
                            end
                        end
                    end
                end
            end)

            ViewToolC_Cleanup = function()
                for _, hl in ipairs(allHighlights) do
                    if hl and hl.Parent then
                        hl:Destroy()
                    end
                end
                allHighlights = {}
            end
        else
            if ViewToolC_Cleanup then
                ViewToolC_Cleanup()
                ViewToolC_Cleanup = nil
            end
        end
    end
})

