LBox:AddToggle("AntiInPutLag", {
    Text = "안티 인풋 랙",
    Default = false,
    Callback = function(Value)
        if AntiInPutLagS.SetDisabled then AntiInPutLagS:SetDisabled(not Value) end
        if Value then
            if InPutLagC then InPutLagC:Disconnect() end
            InPutLagC = rs2.PreSimulation:Connect(function()
                if not pp.char or not pp.hrp then return end
                local inputlagFF = (toys and toys:FindFirstChild("inputlag")) or (inv and inv:FindFirstChild("inputlag")) or (toys and toys:FindFirstChild("FoodMayonnaise")) or (inv and inv:FindFirstChild("FoodMayonnaise"))
                if not inputlagFF then
                    task.spawn(function() rs.MenuToys.SpawnToyRemoteFunction:InvokeServer("FoodMayonnaise", CFrame.new(0,7777777777,0), Vector3.new(0,7777777777,0)) end)
                    return
                end
                if inputlagFF.Name ~= "inputlag" then inputlagFF.Name = "inputlag" end
                if AntiInPutLagV == "Loop" then
                    if not LastInputLagLoop then LastInputLagLoop = 0 end
                    if os.clock() - LastInputLagLoop >= 0.05 then
                        LastInputLagLoop = os.clock()
                        inputlagFF.HoldPart.HoldItemRemoteFunction:InvokeServer(inputlagFF, pp.char)
                        inputlagFF.HoldPart.DropItemRemoteFunction:InvokeServer(inputlagFF, CFrame.new(0,7777777777,0), Vector3.new(0,7777777777,0))
                    end
                elseif not isnetworkowner(pp.hrp) and not pp.rag.Value and isHeld.Value then
                    inputlagFF.HoldPart.HoldItemRemoteFunction:InvokeServer(inputlagFF, pp.char)
                    rs.MenuToys.DestroyToy:FireServer(inputlagFF)
                    inputlagFF.HoldPart.DropItemRemoteFunction:InvokeServer(inputlagFF, CFrame.new(0,7777777777,0), Vector3.new(0,7777777777,0))
                elseif AntiInPutLagV == "None" and not isnetworkowner(pp.hrp) and pp.rag.Value then
                    inputlagFF.HoldPart.HoldItemRemoteFunction:InvokeServer(inputlagFF, pp.char)
                    inputlagFF.HoldPart.DropItemRemoteFunction:InvokeServer(inputlagFF, CFrame.new(0,7777777777,0), Vector3.new(0,7777777777,0))
                end
            end)
        else
            if InPutLagC then
                InPutLagC:Disconnect()
                InPutLagC = nil
                local inputlagFF = (toys and toys:FindFirstChild("inputlag")) or (inv and inv:FindFirstChild("inputlag"))
                if inputlagFF then rs.MenuToys.DestroyToy:FireServer(inputlagFF) end
            end
        end
    end
})

