LBox:AddToggle("AntiKick", {
    Text = "안티 킥",
    Default = false,
    Callback = function(Value)
        if AntiKickResetC then AntiKickResetC:Disconnect() AntiKickResetC = nil end
        AntiFlyingValue = Value
        if AntiFlyingS.SetDisabled then AntiFlyingS:SetDisabled(not Value) end
        if Value then
            repeat task.wait() until AntiFlyingValue and AntiFlyingS and AntiFlyingS.Value
            if AntiFlyingValue then
                AntiKickResetC = rs.GameCorrectionEvents.GameCorrectionsNotify.OnClientEvent:Connect(function(Type)
                    if not AntiFlyingS.Value["Reset"] then return end
                    if Type == "Flying" and AntiFlyingValue then
                        if pp.hum then rs.CharacterEvents.Struggle:FireServer() pp.hum.Health = 0 end
                    end
                end)
            end
            if AntiFlyingValue then
                if pp.char and pp.hum and pp.hum.Health > 0 and AntiFlyingS.Value["PlayerCharacterLocationDetector"] then
                    pp.hum:ChangeState(Enum.HumanoidStateType.Dead)
                    pp.hum.Health = 0
                end
                task.spawn(function()
                    while AntiFlyingValue and task.wait() do
                        if not AntiFlyingS.Value["PlayerCharacterLocationDetector"] then continue end
                        local needsReset = false
                        local myPO = nil
                        local PO_Name = string.format("[ %s ] ( @%s )", plr.DisplayName, plr.Name)
                        for _, obj in ipairs(workspace:GetChildren()) do
                            if obj.Name == "PlayerCharacterLocationDetector" and obj:FindFirstChild(PO_Name) then myPO = obj break end
                        end
                        if myPO then needsReset = true end
                        if needsReset then
                            Library:Notify({Title = "[ ovitar ]", Description = "I THINK YOU NEED A RESET.", BigIcon = "circle-question-mark", IconColor = Color3.new(1,1,1), Time = 3})
                            Sound(SoundIDDT, SoundVolumEET)
                        end
                        if pp.hum == 0 then needsReset = false
                        elseif myPO then task.wait(3) needsReset = true end
                        if needsReset then continue end
                        local Pchar = plr.CharacterAdded:Wait()
                        local Phum = Pchar:WaitForChild("Humanoid")
                        repeat
                            if not AntiFlyingValue or not AntiFlyingS.Value["PlayerCharacterLocationDetector"] then break end
                            Phum:ChangeState(Enum.HumanoidStateType.Dead)
                            Phum.Health = 0
                            task.wait()
                        until Phum.Health == 0 or not AntiFlyingValue or not AntiFlyingS.Value["PlayerCharacterLocationDetector"]
                        needsReset = false
                        task.wait(3.5)
                    end
                end)
            end
            if AntiFlyingValue then
                task.spawn(function()
                    while AntiFlyingValue and task.wait() do
                        if not AntiFlyingS.Value["NinjaShuriken"] then continue end
                        local myPO = nil
                        local PO_Name = string.format("[ %s ] ( @%s )", plr.DisplayName, plr.Name)
                        for _, obj in ipairs(workspace:GetChildren()) do
                            if obj.Name == "PlayerCharacterLocationDetector" and obj:FindFirstChild(PO_Name) then myPO = obj break end
                        end
                        if pp.char and myPO and pp.hrp and pp.raghit then
                            local tn = "NinjaShuriken"
                            local tnf = (toys and toys:FindFirstChild(tn)) or (inv and inv:FindFirstChild(tn))
                            if not tnf and ctoy.Value then
                                task.spawn(function() rs.MenuToys.SpawnToyRemoteFunction:InvokeServer(tn, myPO.CFrame * CFrame.new(0, 3, 20), Vector3.zero) end)
                                tnf = toys:WaitForChild(tn, 0.5) or (inv and inv:WaitForChild(tn, 0.5))
                            end
                            if tnf then
                                local sPart = tnf:WaitForChild("StickyPart", 0.5)
                                local sPartPO = tnf:FindFirstChild("PartOwner") -- ?.. How
                                if sPart then
                                    if not sPartPO then rs.GrabEvents.SetNetworkOwner:FireServer(sPart, CFrame.lookAt(myPO.Position, sPart.Position)) end
                                    if sPartPO and sPartPO.Value ~= plr.Name then rs.MenuToys.DestroyToy:FireServer(tnf) end
                                    rs.PlayerEvents.StickyPartEvent:FireServer(sPart, pp.raghit, CFrame.new(0.1, -0.3, 0.3) * CFrame.Angles(math.rad(90), 0, 0))
                                    task.wait(0.3)
                                    while AntiFlyingValue and tnf.Parent and task.wait() do
                                        if not AntiFlyingS.Value["NinjaShuriken"] then break end
                                        local weld = sPart:FindFirstChild("StickyWeld")
                                        if not weld or weld.Part1 ~= pp.raghit then break end
                                    end
                                    rs.MenuToys.DestroyToy:FireServer(tnf)
                                end
                            end
                        end
                    end
                end)
            end
            if AntiFlyingValue then
                task.spawn(function()
                    while AntiFlyingValue and task.wait() do
                        if not AntiFlyingS.Value["ToolPencil"] then continue end
                        local myPO = nil
                        local PO_Name = string.format("[ %s ] ( @%s )", plr.DisplayName, plr.Name)
                        for _, obj in ipairs(workspace:GetChildren()) do
                            if obj.Name == "PlayerCharacterLocationDetector" and obj:FindFirstChild(PO_Name) then myPO = obj break end
                        end
                        if pp.char and myPO and pp.hrp and pp.raghit then
                            local tn = "ToolPencil"
                            local tnf = (toys and toys:FindFirstChild(tn)) or (inv and inv:FindFirstChild(tn))
                            if not tnf and ctoy.Value then
                                task.spawn(function() rs.MenuToys.SpawnToyRemoteFunction:InvokeServer(tn, myPO.CFrame * CFrame.new(0, 3, 20), Vector3.zero) end)
                                tnf = toys:WaitForChild(tn, 0.5) or (inv and inv:WaitForChild(tn, 0.5))
                            end
                            if tnf then
                                local sPart = tnf:WaitForChild("StickyPart", 0.5)
                                local sdPart = tnf:WaitForChild("SoundPart", 0.5)
                                local sPartPO = tnf:FindFirstChild("PartOwner") -- ?.. How
                                if sPart then
                                    if not sPartPO then rs.GrabEvents.SetNetworkOwner:FireServer(sdPart, CFrame.lookAt(myPO.Position, sdPart.Position)) end
                                    if sPartPO and sPartPO.Value ~= plr.Name then rs.MenuToys.DestroyToy:FireServer(tnf) end
                                    rs.PlayerEvents.StickyPartEvent:FireServer(sPart, pp.raghit, CFrame.new(0.05, -1.2, -0.3) * CFrame.Angles(math.rad(180), 0, 0))
                                    task.wait(0.3)
                                    while AntiFlyingValue and tnf.Parent and task.wait() do
                                        if not AntiFlyingS.Value["ToolPencil"] then break end
                                        local weld = sPart:FindFirstChild("StickyWeld")
                                        if not weld or weld.Part1 ~= pp.raghit then break end
                                    end
                                    rs.MenuToys.DestroyToy:FireServer(tnf)
                                end
                            end
                        end
                    end
                end)
            end
        else
            local AntiKickToy = (toys and toys:FindFirstChild("NinjaShuriken")) or (inv and inv:FindFirstChild("NinjaShuriken"))
            if AntiKickToy then rs.MenuToys.DestroyToy:FireServer(AntiKickToy) end
            local AntiKickToy2 = (toys and toys:FindFirstChild("ToolPencil")) or (inv and inv:FindFirstChild("ToolPencil"))
            if AntiKickToy2 then rs.MenuToys.DestroyToy:FireServer(AntiKickToy2) end
        end
    end
})

