    ValueImages = {Reset = "rbxassetid://21536892", NinjaShuriken = "rbxassetid://140368128539182", ToolPencil = "rbxassetid://92908917595707", PlayerCharacterLocationDetector = "rbxassetid://114641492965605"},
    Multi = true,
