RBox:AddToggle("LoopBlobmanSit", {
    Text = "루프 블룹맨 앉기",
    Default = false,
    Callback = function(Value)
        if LoopBlobmanSitC then LoopBlobmanSitC:Disconnect() end
        if not Value then return end

        LoopBlobmanSitC = rs2.PreSimulation:Connect(function()
            if not (pp.char and pp.hrp) or pp.hum.SeatPart or BLOBSIT then return end

            local targetSeat, mineOccupied, otherEmpty = nil, nil, nil

            for _, player in ipairs(game.Players:GetPlayers()) do
                if not inv then continue end

                for _, item in ipairs(inv:GetChildren()) do
                    if item.Name == "CreatureBlobman" then
                        local seat = item:FindFirstChild("VehicleSeat")
                        if not seat then continue end

                        if player == plr then
                            if not seat.Occupant then targetSeat = seat break
                            else mineOccupied = seat end
                        elseif not seat.Occupant then
                            otherEmpty = seat
                        end
                    end
                end
                if targetSeat then break end
            end

            targetSeat = targetSeat or mineOccupied or otherEmpty

            if not targetSeat then
                task.spawn(function() rs.MenuToys.SpawnToyRemoteFunction:InvokeServer("CreatureBlobman", pp.torso.CFrame * CFrame.new(0, 0, 20), Vector3.zero) end)
                return
            end

            local dist = (pp.torso.Position - targetSeat.Position).Magnitude
            if dist > 13 then
                targetSeat:Sit(pp.hum)
            else
                if pp.hum.Sit then pp.hum.Sit = false end
                local prompt = targetSeat:FindFirstChild("ProximityPrompt")
                if prompt then fireproximityprompt(prompt, 0) end
            end
        end)
    end
})

