                                local inputConnection
                                inputConnection = uis.InputBegan:Connect(function(inp, char)
                                    if inp.UserInputType == Enum.UserInputType.MouseButton2 then
                                        local velocityObj = Instance.new("BodyVelocity")
                                        velocityObj.Parent = part_to_impulse
                                        velocityObj.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
                                        velocityObj.Velocity = cam.CFrame.lookVector * FlingV

                                        wait(0.1)
                                        velocityObj.Parent = workspace
                                        velocityObj:Destroy()

                                        inputConnection:Disconnect()

                                        for i, conn in ipairs(connections) do
                                            if conn == inputConnection then
                                                table.remove(connections, i)
                                                break
                                            end
                                        end
                                    end
                                end)
                                table.insert(connections, inputConnection)
                            end
                        end)
                        table.insert(connections, propConnection)
                    end
                end
            end)
            table.insert(connections, childAddedConnection)
        else
            for _, conn in ipairs(connections) do
                if conn and conn.Connected then
                    conn:Disconnect()
                end
            end
            connections = {}
        end
    end
})

