local infLineExtendConnections = {}
LBox:AddToggle("ExtendLine", {
    Text = "줄 길이",
    Default = false,
    Callback = function(Value)
        if LineS.SetDisabled then 
            LineS:SetDisabled(not Value) 
        end

        if Value then
            local inputConnection = uis.InputChanged:Connect(function(input)
                if input.UserInputType == Enum.UserInputType.MouseWheel then
                    if lineDistanceV < 11 then
                        lineDistanceV = 11
                    end

                    if input.Position.Z > 0 then
                        lineDistanceV = lineDistanceV + LineV
                    elseif input.Position.Z < 0 then
                        lineDistanceV = lineDistanceV - LineV
                    end
                end
            end)
            table.insert(infLineExtendConnections, inputConnection)

            local childConnection = workspace.ChildAdded:Connect(function(child)
                if child.Name == "GrabParts" and child:IsA("Model") then
                    if Value and uis.MouseEnabled then
                        local grabPartsModel = child

                        grabPartsModel:WaitForChild("GrabPart")
                        grabPartsModel:WaitForChild("DragPart")
                    
                        local clonedDragPart = grabPartsModel.DragPart:Clone()
                        clonedDragPart.Name = "DragPart1"
                        clonedDragPart.AlignPosition.Attachment1 = clonedDragPart.DragAttach
                        clonedDragPart.Parent = grabPartsModel
                
                        lineDistanceV = (clonedDragPart.Position - cam.CFrame.Position).Magnitude
    
                        clonedDragPart.AlignOrientation.Enabled = false
                        grabPartsModel.DragPart.AlignPosition.Enabled = false

                        local running = true
                        task.spawn(function()
                            while running and grabPartsModel.Parent and Value do
                                pcall(function()
                                    clonedDragPart.Position = cam.CFrame.Position + cam.CFrame.LookVector * lineDistanceV
                                end)
                                task.wait()
                            end

                            lineDistanceV = 0
                            pcall(function()
                                if clonedDragPart and clonedDragPart.Parent then
                                    clonedDragPart:Destroy()
                                end
                            end)
                        end)

                        table.insert(infLineExtendConnections, {
                            Disconnect = function()
                                running = false
                                pcall(function()
                                    if clonedDragPart and clonedDragPart.Parent then
                                        clonedDragPart:Destroy()
                                    end
                                end)
                            end
                        })
                    end
                end
            end)
            table.insert(infLineExtendConnections, childConnection)

        else
            for _, conn in ipairs(infLineExtendConnections) do
                pcall(function()
                    if conn.Connected ~= nil then
                        if conn.Connected then
                            conn:Disconnect()
                        end
                    elseif conn.Disconnect then
                        conn:Disconnect()
                    end
                end)
            end
            infLineExtendConnections = {}

            lineDistanceV = 0

            pcall(function()
                local grabParts = workspace:FindFirstChild("GrabParts", true)
                if grabParts then
                    if grabParts:FindFirstChild("DragPart1") then
                        grabParts.DragPart1:Destroy()
                    end
                    if grabParts:FindFirstChild("DragPart") then
                        grabParts.DragPart.AlignPosition.Enabled = true
                    end
                end
            end)
        end
    end
})

