local RBox = Tab.Grab:AddRightGroupbox("Aura [WIP]", "blend")

RBox:AddToggle("AntiSeatedAura", {
    Text = "안티 앉기 아우라",
    Default = false,
    Callback = function(Value)
        if AntiSeatedAuraC then AntiSeatedAuraC:Disconnect(); AntiSeatedAuraC = nil end
        if not Value then return end

        AntiSeatedAuraC = rs2.Heartbeat:Connect(function()
            if not (pp.char and pp.torso) then return end

            for _, p in ipairs(Players:GetPlayers()) do
                local c = p.Character
                local t = c and c:FindFirstChild("Torso")
                local h = c and c:FindFirstChild("Humanoid")

                if p ~= plr and not table.find(OwnerName, p.Name) and h and h.SeatPart and t then
                    if (t.Position - pp.torso.Position).Magnitude <= 30 then rs.GrabEvents.SetNetworkOwner:FireServer(t, CFrame.lookAt(pp.torso.Position, t.Position)) end
                end
            end
        end)
    end
})

RBox:AddToggle("AntiStickyPartAura", {
    Text = "안티 킥 안티 아우라",
    Default = false,
    Callback = function(Value)
        if Value then
            if AntiStickyPartAuraC then AntiStickyPartAuraC:Disconnect() end

            AntiStickyPartAuraC = rs2.Heartbeat:Connect(function()
                if not pp.char or not pp.torso then return end

                for _, target in ipairs(Players:GetPlayers()) do
                    if target == plr then continue end
                    if table.find(OwnerName, target.Name) then continue end

                    local spawned = workspace:FindFirstChild(target.Name .. "SpawnedInToys")
                    if spawned then
                        for _, item in ipairs(spawned:GetChildren()) do

                            if AntiStickyPartAuraV[item.Name] then 
                                    local sticky = item:FindFirstChild("StickyPart")
                                    local sound = item:FindFirstChild("SoundPart")
                                    if sticky and sound then
                                        local dist = (sound.Position - pp.torso.Position).Magnitude

                                        if dist <= 30 then
                                            sticky.CanTouch = false
                                            if not sound.CanTouch then rs.GrabEvents.SetNetworkOwner:FireServer(sticky, CFrame.lookAt(pp.torso.Position, sticky.Position)) end
                                        end
                                    end
                            end
                        end
                    end
                end
            end)
        else
            if AntiStickyPartAuraC then
                AntiStickyPartAuraC:Disconnect()
                AntiStickyPartAuraC = nil
            end
        end
    end
})

