local LBox = Tab.Combat:AddLeftGroupbox("Target", "list")

TargetList = LBox:AddDropdown("SelectTarget", {
    Values = {},
    ValueImages = targetValueImages,
    Multi = true,
    Searchable = true,

    Callback = function(Value)

        currentTargets = {}

        for display, selected in pairs(Value) do
            if selected then
                local rawName = targetDisplayMap[display] or display
                table.insert(currentTargets, rawName)
            end
        end

        while #currentTargets > MAX_TARGETS do
            table.remove(currentTargets)
        end
    end
})

