local LBox = Tab.Combat:AddLeftGroupbox("Ragdoll", "star")

LBox:AddToggle("LoopRagdoll", {
    Text = "Loop Ragdoll",
    CurrentValue = false,
    Callback = function(Value)
        LoopRagdollActive = Value
        if LoopRagdollS.SetDisabled then LoopRagdollS:SetDisabled(not Value) end
        if Value then
            task.spawn(function()
                while LoopRagdollActive do
                    if LoopRagdollS.Value == "BallSnowball" then
                        if not pp.char or not pp.torso then task.wait(0.1) continue end
                        task.spawn(function() rs.MenuToys.SpawnToyRemoteFunction:InvokeServer("BallSnowball", pp.torso.CFrame * CFrame.new(0,10,20), Vector3.zero) end)
                        local stick = tick()
                        repeat task.wait() until inv and inv:FindFirstChild("BallSnowball") or tick() - stick > 0.2 or not LoopRagdollActive
                        if not LoopRagdollActive then break end
                        local snowball = inv and inv:FindFirstChild("BallSnowball")
                        if not snowball then task.wait(0.1) continue end
                        local stick2 = tick()
                        repeat task.wait() until (snowball and snowball:FindFirstChild("SoundPart")) or not snowball or tick() - stick2 > 0.2 or not LoopRagdollActive
                        if not LoopRagdollActive then break end
                        if not snowball or not snowball.Parent then task.wait(0.1) continue end
                        local SoundPart = snowball:FindFirstChild("SoundPart")
                        if not SoundPart then task.wait(0.1) continue end
                        local stick3 = tick()
                        repeat task.wait()
                            if not snowball or not snowball.Parent or not SoundPart or not SoundPart.Parent then break end
                            rs.GrabEvents.SetNetworkOwner:FireServer(SoundPart, CFrame.lookAt(pp.torso.Position, SoundPart.Position))
                        until SoundPart:FindFirstChild("PartOwner") or tick() - stick3 > 0.5 or not LoopRagdollActive
                        if not LoopRagdollActive then break end
                        if not snowball or not snowball.Parent or not SoundPart or not SoundPart.Parent then task.wait(0.1) continue end
                        local targets    = getAliveTargets(1)
                        local targetName = targets[1]
                        if not targetName then task.wait(0.1) continue end
                        local targetPlr   = getPlayer(targetName)
                        local targetChar  = targetPlr and targetPlr.Character
                        local targetTorso = targetChar and (targetChar:FindFirstChild("Torso") or targetChar:FindFirstChild("UpperTorso") or targetChar:FindFirstChild("HumanoidRootPart"))
                        local targetHum   = targetChar and targetChar:FindFirstChild("Humanoid")
                        if not targetTorso or not targetHum or targetHum.Health == 0 then task.wait(0.1) continue end
                        SoundPart.CFrame = targetTorso.CFrame
                        task.wait(0.15)
                        if not snowball or not snowball.Parent then task.wait(0.1) continue end
                        rs.BombEvents.BombExplode:FireServer({Radius = 0, Color = Color3.new(0,0,0), TimeLength = 0, Model = snowball, Type = "SnowPoof", ExplodesByFire = false, MaxForcePerStudSquared = 0, Hitbox = SoundPart, ImpactSpeed = 0, ExplodesByPointy = false, DestroysModel = true, PositionPart = SoundPart}, Vector3.new(0,0,0))
                        local ctoyWait = tick()
                        repeat task.wait() until ctoy.Value or tick() - ctoyWait > 1 or not LoopRagdollActive
                    elseif LoopRagdollS.Value == "FoodBanana" then
                        local currentBanana = inv and inv:FindFirstChild("LoopRagdollBanana")
                        local currentPeel, hitboxPart, SoundPart, bp
                        if not currentBanana then
                            task.spawn(function() rs.MenuToys.SpawnToyRemoteFunction:InvokeServer("FoodBanana", pp.torso.CFrame * CFrame.new(0, 5, 20), Vector3.new(0, 170, 0)) end)
                            currentBanana = inv and inv:WaitForChild("FoodBanana", 0.1)
                            if not currentBanana then task.wait(0.1) continue end
                            currentBanana.Name = "LoopRagdollBanana"
                            local holdPart   = currentBanana:WaitForChild("HoldPart", 0.1)
                            local holdRemote = holdPart and holdPart:WaitForChild("HoldItemRemoteFunction", 0.1)
                            if holdRemote then task.spawn(function() holdRemote:InvokeServer(currentBanana, pp.char) end) end
                            rs.HoldEvents.Use:FireServer(currentBanana)
                            for _, v in ipairs(currentBanana:GetDescendants()) do
                                if v:IsA("BasePart") then v.CanCollide = false end
                            end
                            task.wait(3)
                            local dropRemote = holdPart and holdPart:WaitForChild("DropItemRemoteFunction", 3)
                            if dropRemote then task.spawn(function() dropRemote:InvokeServer(currentBanana, pp.torso.CFrame, Vector3.new(0, 10, 10)) end) end
                            task.wait(0.1)
                            for _, v in ipairs(currentBanana:GetDescendants()) do
                                if v:IsA("BasePart") then v.CanCollide = false end
                            end
                            for _, peel in ipairs(currentBanana:GetChildren()) do
                                if peel.Name == "BananaPeel" and peel:IsA("BasePart") and (peel.Color == Color3.fromRGB(163, 162, 165) or peel.Color == Color3.fromRGB(13, 13, 13)) then
                                    currentPeel = peel
                                    break
                                end
                            end
                            if not currentPeel then task.wait(0.1) continue end
                            currentPeel.Size = Vector3.new(2, 2, 1)
                            hitboxPart = currentBanana:WaitForChild("HitboxPart", 0.1)
                            SoundPart  = currentBanana:FindFirstChild("SoundPart")
                            if SoundPart then
                                bp          = Instance.new("BodyPosition")
                                bp.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
                                bp.Position = Vector3.new(0, 0, 9999)
                                bp.Parent   = SoundPart
                                task.spawn(function()
                                    repeat
                                        task.wait()
                                        rs.GrabEvents.SetNetworkOwner:FireServer(SoundPart, CFrame.lookAt(pp.hrp.Position, SoundPart.Position))
                                        local po = SoundPart:FindFirstChild("PartOwner")
                                        if po and po.Value == plr.Name then break end
                                    until not LoopRagdollActive or LoopRagdollS.Value ~= "FoodBanana" or not SoundPart.Parent
                                    rs.GrabEvents.DestroyGrabLine:FireServer(SoundPart)
                                end)
                            end
                        else
                            for _, peel in ipairs(currentBanana:GetChildren()) do
                                if peel.Name == "BananaPeel" and peel:IsA("BasePart") and (peel.Color == Color3.fromRGB(163, 162, 165) or peel.Color == Color3.fromRGB(13, 13, 13)) then
                                    currentPeel = peel
                                    break
                                end
                            end
                            if not currentPeel then task.wait(0.1) continue end
                            hitboxPart = currentBanana:FindFirstChild("HitboxPart")
                            SoundPart  = currentBanana:FindFirstChild("SoundPart")
                            bp         = SoundPart and SoundPart:FindFirstChild("BodyPosition")
                            if not bp and SoundPart then
                                bp          = Instance.new("BodyPosition")
                                bp.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
                                bp.Position = Vector3.new(0, 0, 9999)
                                bp.Parent   = SoundPart
                            end
                        end
                        local targets    = getAliveTargets(1)
                        local targetName = targets[1]
                        if not targetName then task.wait(0.1) continue end
                        local targetPlr  = getPlayer(targetName)
                        local targetChar = targetPlr and targetPlr.Character
                        local targetHRP  = targetChar and targetChar:FindFirstChild("HumanoidRootPart")
                        local targetHum  = targetChar and targetChar:FindFirstChild("Humanoid")
                        if not targetHRP or not targetHum or targetHum.Health == 0 then task.wait(0.1) continue end
                        if not currentPeel or not currentPeel.Parent then task.wait(0.1) continue end
                        local ragVal = targetHum:FindFirstChild("Ragdolled")
                        if ragVal and ragVal.Value == true then
                            if bp then
                                bp.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
                                bp.Position = Vector3.new(0, 0, 9999)
                            end
                            currentPeel.CFrame = CFrame.new(0, 0, 9999)
                            if hitboxPart and hitboxPart.Parent then hitboxPart.CFrame = CFrame.new(0, 0, 9999) end
                            task.wait(0.1) continue
                        end
                        if bp then bp.MaxForce = Vector3.new(0, 0, 0) end
                        local targetCF = targetHRP.CFrame * CFrame.new(0, 0, 0)
                        currentPeel.CFrame = targetCF
                        if currentPeel and currentPeel.Parent then currentPeel.CFrame = targetCF end
                        task.wait()
                    else
                        task.wait(0.1)
                    end
                end
            end)
        end
    end
})

