LT:AddToggle("CameraOff", {
    Text = "루프 컨트롤",
    Default = false,
    Callback = function(Value)
        if Value then
            if LoopControlC then LoopControlC:Disconnect() end

            pp.head.Transparency = 1
            pp.torso.Transparency = 1
            pp.rl.Transparency = 1
            pp.ll.Transparency = 1
            pp.ra.Transparency = 1
            pp.la.Transparency = 1
            for _, acc in ipairs(pp.char:GetDescendants()) do
                if acc:IsA("Accessory") and acc.Name ~= "TypingKeyboardMyWorld" then
                    local h = acc:FindFirstChildOfClass("Part")
                    if h then h.Transparency = 1 end
                end
            end

            LoopControlC = rs2.PreSimulation:Connect(function()
                if not pp.char or not pp.torso or not pp.hrp then return end
                local slots = math.min(#currentTargets, maxTargets.LoopKill)
                if slots == 0 then return end
                for i = 1, slots do
                    local targetName = currentTargets[i]
                    local Tplr = getPlayer(targetName)
                    local Tchar = Tplr and Tplr.Character
                    local Ttorso = Tchar and Tchar:FindFirstChild("Torso")
                    local Thrp = Tchar and Tchar:FindFirstChild("HumanoidRootPart")
                    local Thum = Tchar and Tchar:FindFirstChildOfClass("Humanoid")
                    if not Tplr or not Tchar or not Ttorso or not Thrp or not Thum or Thum.Health <= 0 then 
                        Fake(false)
                        continue 
                    end
                    if not isnetworkowner(Thrp) then
                        Fake(true)
                        ServerHrp = CFrame.new(Ttorso.Position + (Ttorso.Velocity * (plr:GetNetworkPing() + 0.22))) * CFrame.new(0, 0, 10)
                        rs.GrabEvents.SetNetworkOwner:FireServer(Ttorso, CFrame.lookAt(ServerHrp.Position, Ttorso.Position))
                    else
                        Fake(false)
                        local LIMBS = {"Head", "Left Arm", "Right Arm", "Left Leg", "Right Leg"}
                        for _, name in ipairs(LIMBS) do
                            local Tpart = Tchar:FindFirstChild(name)
                            local Ppart = pp.char:FindFirstChild(name)
                            if Tpart and Ppart then
                                local bsc = Tpart:FindFirstChild("BallSocketConstraint")
                                if bsc then
                                    bsc.LimitsEnabled = false
                                    bsc.MaxFrictionTorque = math.huge
                                end
                                if name ~= "Head" then
                                    local ragp = Tpart:FindFirstChild("RagdollLimbPart")
                                    if ragp then ragp.CanCollide = false end
                                end
                                Tpart.CFrame = Ppart.CFrame
                                Tpart.CanCollide = false
                                Tpart.CanQuery = false
                                Tpart.Transparency = 0.5
                                Tpart.AssemblyLinearVelocity = Vector3.zero
                                Tpart.AssemblyAngularVelocity = Vector3.zero
                            end
                        end
                        Ttorso.CFrame = pp.torso.CFrame
                        Ttorso.CanCollide = false
                        Ttorso.CanQuery = false
                        Ttorso.Transparency = 0.5
                        for _, acc in Tchar:GetDescendants() do
                            if acc:IsA("Accessory") and acc.Name ~= "TypingKeyboardMyWorld" then
                                local h = acc:FindFirstChildOfClass("Part")
                                if h then
                                    h.Transparency = 0.5
                                    h.CanCollide = false
                                    h.CanQuery = false
                                end
                            end
                        end
                    end
                end
            end)
        else
            if LoopControlC then
                LoopControlC:Disconnect()
                LoopControlC = nil
            end
            Fake(false)

            pp.head.Transparency = 0
            pp.torso.Transparency = 0
            pp.rl.Transparency = 0
            pp.ll.Transparency = 0
            pp.ra.Transparency = 0
            pp.la.Transparency = 0
            for _, acc in ipairs(pp.char:GetDescendants()) do
                if acc:IsA("Accessory") and acc.Name ~= "TypingKeyboardMyWorld" then
                    local h = acc:FindFirstChildOfClass("Part")
                    if h then h.Transparency = 0 end
                end
            end

            local slots = math.min(#currentTargets, maxTargets.LoopKill)
            for i = 1, slots do
                local targetName = currentTargets[i]
                local Tplr = getPlayer(targetName)
                local Tchar = Tplr and Tplr.Character
                if not Tchar then continue end
                local LIMBS = {"Head", "Torso", "Left Arm", "Right Arm", "Left Leg", "Right Leg"}
                for _, name in ipairs(LIMBS) do
                    local Tpart = Tchar:FindFirstChild(name)
                    if not Tpart then continue end
                    Tpart.CanCollide = true
                    Tpart.CanQuery = true
                    Tpart.Transparency = 0
                    local bsc = Tpart:FindFirstChild("BallSocketConstraint")
                    if bsc then
                        bsc.LimitsEnabled = true
                        bsc.MaxFrictionTorque = 0
                    end
                    if name ~= "Head" then
                        local ragp = Tpart:FindFirstChild("RagdollLimbPart")
                        if ragp then ragp.CanCollide = true end
                    end
                end
                for _, acc in Tchar:GetDescendants() do
                    if acc:IsA("Accessory") and acc.Name ~= "TypingKeyboardMyWorld" then
                        local h = acc:FindFirstChildOfClass("Part")
                        if h then
                            h.Transparency = 0
                            h.CanCollide = false
                            h.CanQuery = true
                        end
                    end
                end
            end
        end
    end
})

