-- 텔레포트  Desync/Original CFrame용 내부 변수 및 CFrame 캐싱
local isLoopGotoFaking = false
local loopGotoHbc = nil
local loopGotoOcf = nil
local loopGotoTargetCF = CFrame.identity

-- 드롭다운 및 인풋에 연동할 변수들
LoopGotoMode = "Original CFrame"
local LoopGotoXYZ = "0,6,0"
local LoopGotoROT = "0,0,0"

LT:AddDropdown("LoopGotoModeSelect", {
    Text = "루프 Goto 타입",
    Values = { "Original CFrame", "DeSync" },
    Default = "Original CFrame",
    Multi = false,
    Callback = function(Value)
        LoopGotoMode = Value
    end
})

LT:AddInput("LoopGotoXYZInput", {
    Text = "상대 X,Y,Z 오프셋",
    Default = "0,6,0",
    Callback = function(V)
        LoopGotoXYZ = V
    end
})

LT:AddInput("LoopGotoROTInput", {
    Text = "회전 각도 (rx,ry,rz)",
    Default = "0,0,0",
    Callback = function(V)
        LoopGotoROT = V
    end
})

-- Target Position Safety Validation (Prevents Void Fling Bug on target reset/snowplow/ragdoll)
local function isSafeTargetPosition(pos)
    if not pos then return false end
    -- Check for NaN (NaN ~= NaN)
    if pos.X ~= pos.X or pos.Y ~= pos.Y or pos.Z ~= pos.Z then return false end
    -- Check for void, fallen parts destroy height, or infinite positions
    if pos.Y < -200 or math.abs(pos.X) > 100000 or math.abs(pos.Z) > 100000 then return false end
    return true
end

-- 텔레포트 모드에 따른 처리 함수
local function applyLoopGotoState(part, state)
    if state == isLoopGotoFaking then return end
    isLoopGotoFaking = state
    if state then
        if LoopGotoMode == "Original CFrame" then
            if pp.hrp and isSafeTargetPosition(pp.hrp.Position) then loopGotoOcf = pp.hrp.CFrame end
            loopGotoHbc = rs2.Heartbeat:Connect(function()
                if pp.hrp and loopGotoTargetCF and isSafeTargetPosition(loopGotoTargetCF.Position) then
                    pp.hrp.CFrame = loopGotoTargetCF
                    sethiddenproperty(pp.hrp, "PhysicsRepRootPart", part)
                end
            end)
        elseif LoopGotoMode == "DeSync" then
            if pp.hrp and isSafeTargetPosition(pp.hrp.Position) then loopGotoOcf = pp.hrp.CFrame end
            rs2:BindToRenderStep("LoopGotoClientVision", Enum.RenderPriority.Camera.Value - 1, function()
                if pp.hrp and loopGotoOcf and isSafeTargetPosition(loopGotoOcf.Position) then
                    pp.hrp.CFrame = loopGotoOcf
                end
            end)
            loopGotoHbc = rs2.Heartbeat:Connect(function()
                if pp.hrp and pp.hum and loopGotoTargetCF and isSafeTargetPosition(loopGotoTargetCF.Position) then
                    loopGotoOcf = pp.hrp.CFrame
                    pp.hum:ChangeState(Enum.HumanoidStateType.PlatformStanding)
                    pp.hrp.CFrame = loopGotoTargetCF
                    sethiddenproperty(pp.hrp, "PhysicsRepRootPart", part)
                end
            end)
        end
    else
        pcall(function() rs2:UnbindFromRenderStep("LoopGotoClientVision") end)
        if loopGotoHbc then loopGotoHbc:Disconnect() loopGotoHbc = nil end
        if pp.hrp and loopGotoOcf and isSafeTargetPosition(loopGotoOcf.Position) then
            pp.hrp.CFrame = loopGotoOcf
        end
    end
end

LT:AddToggle("LoopGoto", {
    Text = "루프 Goto",
    Default = false,
    Callback = function(Value)
        if Value then
            if LoopGotoC then LoopGotoC:Disconnect() end
            
            LoopGotoC = rs2.PreSimulation:Connect(function()
                if not pp.char or not pp.torso or not pp.hrp then return end
                
                local targetName = currentTargets[1]
                if not targetName then
                    applyLoopGotoState(nil, false)
                    return
                end
                
                local Tplr = getPlayer(targetName)
                local Tchar = Tplr and Tplr.Character
                local Thrp = Tchar and Tchar:FindFirstChild("HumanoidRootPart")
                local Thum = Tchar and Tchar:FindFirstChildOfClass("Humanoid")
                
                -- Target Safety Check: If target is dead, resetting, in void, or NaN -> Disengage safely!
                if not Tplr or not Tchar or not Thrp or not Thum or Thum.Health <= 0 or not isSafeTargetPosition(Thrp.Position) then
                    applyLoopGotoState(nil, false)
                    if pp.hrp then
                        pp.hrp.AssemblyLinearVelocity = Vector3.zero
                        pp.hrp.AssemblyAngularVelocity = Vector3.zero
                    end
                    return
                end
                
                -- 상대 좌표(X,Y,Z) 및 회전각도(rx,ry,rz) 파싱
                local x, y, z = LoopGotoXYZ:match("([^,]+),([^,]+),([^,]+)")
                local rx, ry, rz = LoopGotoROT:match("([^,]+),([^,]+),([^ grand,]+)")
                
                x = tonumber(x) or 0
                y = tonumber(y) or 0
                z = tonumber(z) or 0
                rx = tonumber(rx) or 0
                ry = tonumber(ry) or 0
                rz = tonumber(rz) or 0
                
                local targetCF = Thrp.CFrame * CFrame.new(x, y, z) * CFrame.Angles(math.rad(rx), math.rad(ry), math.rad(rz))
                if isSafeTargetPosition(targetCF.Position) then
                    loopGotoTargetCF = targetCF
                    -- 물리적 속도 제어
                    pp.hrp.AssemblyLinearVelocity = Vector3.zero
                    pp.hrp.AssemblyAngularVelocity = Vector3.zero
                    -- 모드별 상태 전송
                    applyLoopGotoState(Thrp, true)
                else
                    applyLoopGotoState(nil, false)
                end
            end)
        else
            if LoopGotoC then
                LoopGotoC:Disconnect()
                LoopGotoC = nil
            end
            applyLoopGotoState(nil, false)
            if pp.hrp then
                pp.hrp.AssemblyLinearVelocity = Vector3.zero
                pp.hrp.AssemblyAngularVelocity = Vector3.zero
            end
        end
    end
})

RT:AddToggle("LoopBring", {
    Text = "루프 가져오기",
    Default = false,
    Callback = function(Value)
        LoopBringT = Value
        if not Value then
            -- 토글 해제 시 상태 청소 및 앵커 해제
            Fake(false)
            if pp.torso then
                pp.torso.Anchored = false
                pp.torso.AssemblyLinearVelocity = Vector3.zero
                pp.torso.AssemblyAngularVelocity = Vector3.zero
            end
            if pp.hum and not FreeCamC then
                cam.CameraType = Enum.CameraType.Custom
                cam.CameraSubject = pp.hum
            end
            return
        end

        local safeCF = pp.torso and pp.torso.CFrame
        if not safeCF then return end

        task.spawn(function()
            while LoopBringT do
                if not pp.char or not pp.torso then task.wait(0.1) continue end
                local targetName = currentTargets[1]
                if not targetName then task.wait(0.1) continue end

                local Tplr = getPlayer(targetName)
                local Tchar = Tplr and Tplr.Character
                local Ttorso = Tchar and Tchar:FindFirstChild("Torso")
                local Thrp = Tchar and Tchar:FindFirstChild("HumanoidRootPart")
                local Thum = Tchar and Tchar:FindFirstChildOfClass("Humanoid")

                if not Tplr or not Tchar or not Ttorso or not Thum or Thum.Health <= 0 then
                    Fake(false)
                    if pp.torso then pp.torso.Anchored = false end
                    task.wait(0.1)
                    continue
                end

                -- 상대방이 탈출했거나 아직 소유권이 없는지 확인
                local isNear = (Ttorso.Position - safeCF.Position).Magnitude <= 15
                local isOwned = Thrp and isnetworkowner(Thrp)

                if not isNear or not isOwned then
                    -- 대상을 데려오기 전까지 앵커 임시 해제
                    if pp.torso then pp.torso.Anchored = false end
                    if not LoopViewC and LoopCamera then cam.CameraType = Enum.CameraType.Scriptable end

                    -- 타겟 위치로 텔레포트하여 소유권 강탈
                    local fetchStart = tick()
                    repeat
                        Fake(true, Ttorso)
                        ServerHrp = CFrame.new(Ttorso.Position + (Ttorso.Velocity * (plr:GetNetworkPing() + 0.22))) * CFrame.new(0, 0, 10)
                        rs.GrabEvents.SetNetworkOwner:FireServer(Ttorso, CFrame.lookAt(ServerHrp.Position, Ttorso.Position))
                        task.wait()
                    until not LoopBringT or not Thrp or not Tchar or isnetworkowner(Thrp) or Thum.Health <= 0 or tick() - fetchStart > 3

                    -- 소유권 확보 후 시작 좌표로 귀환
                    Fake(false)
                    if pp.torso then
                        pp.torso.CFrame = safeCF
                        pp.torso.Anchored = true -- 가만히 있게 고정
                        pp.torso.AssemblyLinearVelocity = Vector3.zero
                        pp.torso.AssemblyAngularVelocity = Vector3.zero
                    end
                    if Tchar then
                        Tchar:PivotTo(safeCF * CFrame.new(0, 10, 0))
                    end
                    if pp.hum and not FreeCamC then
                        cam.CameraType = Enum.CameraType.Custom
                        cam.CameraSubject = pp.hum
                    end
                else
                    -- 타겟이 얌전히 쥐여져 있는 상태: 자신은 실행 지점에 고정
                    if pp.torso then
                        pp.torso.Anchored = true
                        pp.torso.CFrame = safeCF
                    end
                    
                    -- 상대방을 실행 지점 위에 강제 포지셔닝 및 속도 상쇄
                    Ttorso.CFrame = safeCF * CFrame.new(0, 10, 0)
                    Ttorso.AssemblyLinearVelocity = Vector3.zero
                    Ttorso.AssemblyAngularVelocity = Vector3.zero
                    
                    -- 네트워크 소유권 갱신 신호 계속 주입
                    rs.GrabEvents.SetNetworkOwner:FireServer(Ttorso, CFrame.lookAt(safeCF.Position, Ttorso.Position))
                    
                    task.wait()
                end
            end
        end)
    end
})

RT:AddButton({
    Text = "블랙홀",
    Callback = function()
        if not pp.char or not pp.torso then return end
        local slots = math.min(#currentTargets, maxTargets.LoopKill)
        if slots == 0 then return end
        local safeCF = pp.torso.CFrame
        for i = 1, slots do
            local targetName = currentTargets[i]
            local Tplr = getPlayer(targetName)
            local Tchar = Tplr and Tplr.Character
            local Ttorso = Tchar and Tchar:FindFirstChild("Torso")
            local Thum = Tchar and Tchar:FindFirstChildOfClass("Humanoid")
            if not (Tplr and Tchar and Ttorso and Thum and Thum.Health >= 0 and not pp.hum.SeatPart) then continue end
            for _ = 1, 10 do
                while not (toys and toys:FindFirstChild("NinjaKunai")) and not (inv and inv:FindFirstChild("NinjaKunai")) and task.wait() do
                    task.spawn(function() rs.MenuToys.SpawnToyRemoteFunction:InvokeServer("NinjaKunai", pp.torso.CFrame * CFrame.new(0,10,20), Vector3.zero) end)
                    local t = tick()
                    repeat rs2.PreSimulation:Wait() until (toys and toys:FindFirstChild("NinjaKunai")) or (inv and inv:FindFirstChild("NinjaKunai")) or tick() - t >= 0.3
                end
                local K = (toys and toys:FindFirstChild("NinjaKunai")) or (inv and inv:FindFirstChild("NinjaKunai"))
                local t = tick()
                repeat rs2.PreSimulation:Wait() until K:FindFirstChild("SoundPart") or tick() - t >= 0.3

                for _, part in ipairs(K:GetDescendants()) do
                    if part:IsA("BasePart") then
                        hiddenParts[part] = true
                    end
                end
                K.DescendantAdded:Connect(function(part)
                    if part:IsA("BasePart") then
                        hiddenParts[part] = true
                    end
                end)

                local sPart = K:FindFirstChild("SoundPart")
                local stPart = K:FindFirstChild("StickyPart")

                local t = tick()
                repeat rs2.PreSimulation:Wait() rs.GrabEvents.SetNetworkOwner:FireServer(sPart, CFrame.lookAt(pp.hrp.Position, getRealPosition(sPart))) until sPart:FindFirstChild("PartOwner") or tick() - t >= 0.3
                rs.PlayerEvents.StickyPartEvent:FireServer(stPart, Ttorso, CFrame.new(0,50,0))
                K.Name = "Done."
                repeat rs2.PreSimulation:Wait() until ctoy.Value or Thum.Health <= 0 or pp.hum.Health <= 0
            end
        end
    end
})

local RBox = Tab.Combat:AddRightGroupbox("SetOwner", "crown")

RBox:AddToggle("LoopKillSetOwner", {
    Text = "루프 킬(셋오너)",
    Default = false,
    Callback = function(Value)
        if Value then
            if LoopKillC then LoopKillC:Disconnect() end

            local killed = {}
            local lastTarget = {}
            local currentIndex = 1
            local safeCF = pp.torso and pp.torso.CFrame
            local isTeleported = false

            LoopKillC = rs2.PreSimulation:Connect(function()
                if not pp.char or not pp.torso then return end
                
                local slots = math.min(#currentTargets, maxTargets.LoopKill)
                if slots == 0 then
                    if isTeleported and safeCF then
                        pp.torso.CFrame = safeCF
                        isTeleported = false
                    end
                    return
                end
                
                if currentIndex > slots then currentIndex = 1 end

                if not isTeleported then
                    safeCF = pp.torso.CFrame
                end

                local targetName = currentTargets[currentIndex]
                local Tplr = getPlayer(targetName)
                local Tchar = Tplr and Tplr.Character
                local Ttorso = Tchar and Tchar:FindFirstChild("Torso")
                local Tneck = Tchar and Ttorso and Ttorso:FindFirstChild("Neck")
                local Thrp = Tchar and Tchar:FindFirstChild("HumanoidRootPart")
                local Thum = Tchar and Tchar:FindFirstChildOfClass("Humanoid")

                if not Tplr or not Tchar or not Ttorso or not Thum then
                    Fake(false)
                    if isTeleported and safeCF and pp.torso then
                        pp.torso.CFrame = safeCF
                        isTeleported = false
                    end
                    currentIndex = (currentIndex % slots) + 1
                    return
                end

                if lastTarget[targetName] ~= Tchar then
                    lastTarget[targetName] = Tchar
                    killed[targetName] = false
                end

                if Thum.Health > 0 then
                    isTeleported = true
                    if not LoopViewC and LoopCamera and LoopKillC then cam.CameraType = Enum.CameraType.Scriptable end
                    
                    Fake(true, Ttorso)
                    ServerHrp = CFrame.new(Ttorso.Position + (Ttorso.Velocity * (plr:GetNetworkPing() + 0.22))) * CFrame.new(0, 0, 10)
                    
                    -- 1. 서버 래그돌 리모트 전송 (서버 전체 래그돌 동기화)
                    if Thrp then pcall(function() rs.CharacterEvents.RagdollRemote:FireServer(Thrp, 99999) end) end

                    -- 2. 소유권 강탈 연속 주입 (서버 승인 확보)
                    for _ = 1, 3 do
                        rs.GrabEvents.SetNetworkOwner:FireServer(Ttorso, CFrame.lookAt(ServerHrp.Position, Ttorso.Position))
                        if Thrp then rs.GrabEvents.SetNetworkOwner:FireServer(Thrp, CFrame.lookAt(ServerHrp.Position, Thrp.Position)) end
                        task.wait(0.01)
                    end

                    -- 3. 서버 물리 낙사 킬 스트림 (관절 유지 + void CFrame 연속 전송)
                    local voidCF = CFrame.new(0, -99999, 0)
                    local voidVel = Vector3.new(0, -999999, 0)

                    for _ = 1, 6 do
                        Ttorso.CFrame = voidCF
                        Ttorso.AssemblyLinearVelocity = voidVel
                        if Thrp then
                            Thrp.CFrame = voidCF
                            Thrp.AssemblyLinearVelocity = voidVel
                        end
                        rs.GrabEvents.SetNetworkOwner:FireServer(Ttorso, CFrame.lookAt(voidCF.Position, voidCF.Position))
                        task.wait(0.02)
                    end

                    rs.GrabEvents.DestroyGrabLine:FireServer(Ttorso)
                else
                    Fake(false)
                    if pp.hum and not FreeCamC then cam.CameraType = Enum.CameraType.Custom end
                    if pp.torso and safeCF then
                        cam.CameraSubject = pp.hum
                        ServerHrp = safeCF
                        pp.torso.CFrame = safeCF
                        pp.torso.AssemblyLinearVelocity = Vector3.zero
                        pp.torso.AssemblyAngularVelocity = Vector3.zero
                    end
                    killed[targetName] = true
                    isTeleported = false
                    task.spawn(function()
                        task.wait()
                        currentIndex = (currentIndex % slots) + 1
                        killed[targetName] = false
                    end)
                end
            end)
        else
            Fake(false)
            if safeCF then ServerHrp = safeCF end
            if pp.hum and not FreeCamC then
                cam.CameraType = Enum.CameraType.Custom
                cam.CameraSubject = pp.hum
            end
            if LoopKillC then
                LoopKillC:Disconnect()
                LoopKillC = nil
            end
        end
    end
})

RBox:AddToggle("LoopKickSetOwner", {
    Text = "루프 킥(셋오너)",
    Default = false,
    Callback = function(Value)
        if Value then
            if LoopKickC then LoopKickC:Disconnect() end

            local kicked = {}
            local lastTarget = {}
            local currentIndex = 1
            local safeCF = pp.torso and pp.torso.CFrame
            local isTeleported = false

            LoopKickC = rs2.PreSimulation:Connect(function()
                if not pp.char or not pp.torso or not pp.hrp then return end
                
                local slots = math.min(#currentTargets, maxTargets.LoopKick)
                if slots == 0 then
                    if isTeleported and safeCF then
                        pp.torso.CFrame = safeCF
                        isTeleported = false
                    end
                    return
                end

                if currentIndex > slots then currentIndex = 1 end

                if not isTeleported then
                    safeCF = pp.torso.CFrame
                end

                local targetName = currentTargets[currentIndex]
                local Tplr = getPlayer(targetName)

                if not Tplr then
                    Fake(false)
                    if isTeleported and safeCF and pp.torso then
