RBox:AddToggle("JerkOff", {
    Text = "자위",
    Default = false,
    Callback = function(Value)
        enabled = Value

        if not enabled then
            running = false
            if animTrack then
                animTrack:Stop()
            end
        end
    end
}):AddKeyPicker("JerkOffTrigger", {
    Default = "Six",
    Text = "",
    Mode = "Toggle",
    Callback = function()
        if not enabled then return end

        local player = game:GetService('Players').LocalPlayer
        local char = player.Character or player.CharacterAdded:Wait()
        local humanoid = char:FindFirstChildOfClass('Humanoid')
        if not humanoid then return end

        if not animTrack then
            local anim = Instance.new('Animation')
            anim.AnimationId = 'rbxassetid://168268306'
            animTrack = (humanoid:FindFirstChildOfClass('Animator') or humanoid:WaitForChild('Animator')):LoadAnimation(anim)
        end

        running = not running

        if running then
            animTrack:Play()
            task.spawn(function()
                task.wait(0.3)
                while running and enabled and animTrack do
                    animTrack.TimePosition = 0.3
                    task.wait(0.1)
                end
            end)
        else
            if animTrack then
                animTrack:Stop()
            end
        end
    end
})

