				if creatureBlobman and creatureBlobman:IsA("Folder") then
					for _, child in ipairs(creatureBlobman:GetChildren()) do
						if child.Name == "LeftDetector" or child.Name == "RightDetector" then
							child:Destroy()
						end
					end
				end
			end
		end
	end)
end

