		return (arg * CFrame.new(n9, 1, 3) * cframe(math.rad(arg4 * n3 * n10), math.rad(arg3 * n3 * n10 + n4 * n10), math.rad(arg5 * n3 * n10)) * CFrame.new(0, n5 * arg2, 0)).Position
	end

