				local n12 = math.cos(n8) * gkaBlobRotateRadius
				local n13 = math.sin(n8) * gkaBlobRotateRadius
				local humanoidRootPart2 = v6:FindFirstChild("HumanoidRootPart") or v6:FindFirstChildWhichIsA("BasePart", true)

