								tbl19[arg] = arg.Rate
								arg.Rate = arg.Rate * n10
							end
						end

						applyRate(clone2)

						for _, descendant2 in ipairs(clone2:GetDescendants()) do
							applyRate(descendant2)
						end
					end
				end
			end

			clone:Destroy()
		end
	end

