	CheckForHome = function()
		for i = 1, 5 do
			local plots = workspace.Plots and workspace.Plots:FindFirstChild("Plot" .. i)

			if plots then
				local thisPlotsOwners = plots.PlotSign and plots.PlotSign:FindFirstChild("ThisPlotsOwners")

