		local obj3 = setmetatable({}, { __mode = "k" })

		registerModel = function(arg2)
			if typeof(arg2) ~= "Instance" then
				return
			end
			local parent

			if arg2:IsA("BasePart") then
				parent = arg2.Parent
			else
				parent = arg2
			end

			if parent and parent:IsA("Model") and parent ~= arg and parent.Parent then
				obj3[parent] = true
			end
