syncRecoveredProperties = function(arg, arg2)
	for k, v22 in next, arg2, nil do
		if arg[k] ~= v22 then
			local v23 = arg[k]

			if type(v23) ~= "number" then
				arg[k] = v22
			elseif type(v22) ~= "number" then
				arg[k] = v22
			elseif math.abs(v23 - v22) > 1e-05 then
				arg[k] = v22
			end
		end
	end
end

local NinjaShuriken = nil

