					local humanoid_ = character and character:FindFirstChild("Humanoid")

					if humanoid_ and humanoid_.Health <= 0 and not tbl25[k] then
						tbl25[k] = true

						if TargetTab_DeathNotif then
							if _NOTIFY then
								_NOTIFY("Target Dead: " .. k.Name, 3)
