										TweenService:Create(element, TweenInfo.new(0.3, Enum.EasingStyle.Exponential), {BackgroundTransparency = 1}):Play()
										TweenService:Create(element.UIStroke, TweenInfo.new(0.3, Enum.EasingStyle.Exponential), {Transparency = 1}):Play()
										TweenService:Create(element.Title, TweenInfo.new(0.3, Enum.EasingStyle.Exponential), {TextTransparency = 1}):Play()
									end
									for _, child in ipairs(element:GetChildren()) do
										if child.ClassName == "Frame" or child.ClassName == "TextLabel" or child.ClassName == "TextBox" or child.ClassName == "ImageButton" or child.ClassName == "ImageLabel" then
											child.Visible = false
										end
									end
								end
							end
						end
					end
				end

				TweenService:Create(Topbar.UIStroke, TweenInfo.new(0.5, Enum.EasingStyle.Exponential), {Transparency = 0}):Play()
				TweenService:Create(Main.Shadow.Image, TweenInfo.new(0.5, Enum.EasingStyle.Exponential), {ImageTransparency = 1}):Play()
				TweenService:Create(Topbar.CornerRepair, TweenInfo.new(0.5, Enum.EasingStyle.Exponential), {BackgroundTransparency = 1}):Play()
				TweenService:Create(Topbar.Divider, TweenInfo.new(0.5, Enum.EasingStyle.Exponential), {BackgroundTransparency = 1}):Play()
				TweenService:Create(Main, TweenInfo.new(0.5, Enum.EasingStyle.Exponential), {Size = UDim2.new(0, 495, 0, 45)}):Play()
				TweenService:Create(Topbar, TweenInfo.new(0.5, Enum.EasingStyle.Exponential), {Size = UDim2.new(0, 495, 0, 45)}):Play()

				task.wait(0.3)

				Elements.Visible = false
				TabList.Visible = false

				task.wait(0.2)
				Debounce = false
			end

			function RayfieldLibrary:CreateWindow(Settings)
				local Passthrough = false
				Topbar.Title.Text = Settings.Name
				Main.Size = UDim2.new(0, 450, 0, 260)
				Main.Visible = true
				Main.BackgroundTransparency = 1
				LoadingFrame.Title.TextTransparency = 1
				LoadingFrame.Subtitle.TextTransparency = 1
				Main.Shadow.Image.ImageTransparency = 1
				LoadingFrame.Version.TextTransparency = 1
				LoadingFrame.Title.Text = Settings.LoadingTitle or "Rayfield Interface Suite"
				LoadingFrame.Subtitle.Text = Settings.LoadingSubtitle or "by Sirius"
				if Settings.LoadingTitle ~= "Rayfield Interface Suite" then
					LoadingFrame.Version.Text = "Rayfield UI"
				end

				--print(Settings.Theme)
				Settings.Theme = "Default2"
				--print(Settings.Theme)

				if Settings.Theme then
					ChangeTheme(Settings.Theme)
					local success = pcall(ChangeTheme, Settings.Theme)
					if not success then
						warn('issue rendering theme. no theme file')
					end
				end
				
				Topbar.Visible = false
				Elements.Visible = false
				LoadingFrame.Visible = true

				pcall(function()
					if not Settings.ConfigurationSaving.FileName then
						Settings.ConfigurationSaving.FileName = tostring(game.PlaceId)
					end
					if not isfolder(RayfieldFolder.."/".."Configuration Folders") then

					end
					if Settings.ConfigurationSaving.Enabled == nil then
						Settings.ConfigurationSaving.Enabled = false
					end
					CFileName = Settings.ConfigurationSaving.FileName
					ConfigurationFolder = Settings.ConfigurationSaving.FolderName or ConfigurationFolder
					CEnabled = Settings.ConfigurationSaving.Enabled

					if Settings.ConfigurationSaving.Enabled then
						if not isfolder(ConfigurationFolder) then
							makefolder(ConfigurationFolder)
						end	
					end
				end)

				AddDraggingFunctionality(Topbar,Main)

				for _, TabButton in ipairs(TabList:GetChildren()) do
					if TabButton.ClassName == "Frame" and TabButton.Name ~= "Placeholder" then
						TabButton.BackgroundTransparency = 1
						TabButton.Title.TextTransparency = 1
						TabButton.Image.ImageTransparency = 1
						TabButton.UIStroke.Transparency = 1
					end
				end


				if Settings.Discord and Settings.Discord.Enabled and not useStudio then --REVAMP
					if not isfolder(RayfieldFolder.."/Discord Invites") then
						makefolder(RayfieldFolder.."/Discord Invites")
					end
					if not isfile(RayfieldFolder.."/Discord Invites".."/"..Settings.Discord.Invite..ConfigurationExtension) then
						if request then
							request({
								Url = 'http://127.0.0.1:6463/rpc?v=1',
								Method = 'POST',
								Headers = {
									['Content-Type'] = 'application/json',
									Origin = 'https://discord.com'
								},
								Body = HttpService:JSONEncode({
									cmd = 'INVITE_BROWSER',
									nonce = HttpService:GenerateGUID(false),
									args = {code = Settings.Discord.Invite}
								})
							})
						end

						if Settings.Discord.RememberJoins then -- We do logic this way so if the developer changes this setting, the user still won't be prompted, only new users
							writefile(RayfieldFolder.."/Discord Invites".."/"..Settings.Discord.Invite..ConfigurationExtension,"Rayfield RememberJoins is true for this invite, this invite will not ask you to join again")
						end
					end
				end

				if (Settings.KeySystem) then
					if not Settings.KeySettings then
						Passthrough = true
						return
					end

					if not isfolder(RayfieldFolder.."/Key System") then
						makefolder(RayfieldFolder.."/Key System")
					end

					if typeof(Settings.KeySettings.Key) == "string" then Settings.KeySettings.Key = {Settings.KeySettings.Key} end

					if Settings.KeySettings.GrabKeyFromSite then
						for i, Key in ipairs(Settings.KeySettings.Key) do
							local Success, Response = pcall(function()
								Settings.KeySettings.Key[i] = tostring(game:HttpGet(Key):gsub("[\n\r]", " "))
								Settings.KeySettings.Key[i] = string.gsub(Settings.KeySettings.Key[i], " ", "")
							end)
							if not Success then
								print("Rayfield | "..Key.." Error " ..tostring(Response))
								warn('Check docs.sirius.menu for help with Rayfield specific development.')
							end
						end
					end

					if not Settings.KeySettings.FileName then
						Settings.KeySettings.FileName = "No file name specified"
					end

					if isfile(RayfieldFolder.."/Key System".."/"..Settings.KeySettings.FileName..ConfigurationExtension) then
						for _, MKey in ipairs(Settings.KeySettings.Key) do
							if string.find(readfile(RayfieldFolder.."/Key System".."/"..Settings.KeySettings.FileName..ConfigurationExtension), MKey) then
								Passthrough = true
							end
						end
					end

					if not Passthrough then
						local AttemptsRemaining = math.random(2,6)
						Rayfield.Enabled = false
						local KeyUI = game:GetObjects("rbxassetid://11380036235")[1]

						if gethui then
							KeyUI.Parent = gethui()
						elseif syn.protect_gui then
							syn.protect_gui(Rayfield)
							KeyUI.Parent = CoreGui
						else
							KeyUI.Parent = CoreGui
						end

						if gethui then
							for _, Interface in ipairs(gethui():GetChildren()) do
								if Interface.Name == KeyUI.Name and Interface ~= KeyUI then
									Interface.Enabled = false
									Interface.Name = "KeyUI-Old"
								end
							end
						else
							for _, Interface in ipairs(CoreGui:GetChildren()) do
								if Interface.Name == KeyUI.Name and Interface ~= KeyUI then
									Interface.Enabled = false
									Interface.Name = "KeyUI-Old"
								end
							end
						end

						local KeyMain = KeyUI.Main
						KeyMain.Title.Text = Settings.KeySettings.Title or Settings.Name
						KeyMain.Subtitle.Text = Settings.KeySettings.Subtitle or "Key System"
						KeyMain.NoteMessage.Text = Settings.KeySettings.Note or "No instructions"

						KeyMain.Size = UDim2.new(0, 467, 0, 175)
						KeyMain.BackgroundTransparency = 1
						KeyMain.Shadow.Image.ImageTransparency = 1
						KeyMain.Title.TextTransparency = 1
						KeyMain.Subtitle.TextTransparency = 1
						KeyMain.KeyNote.TextTransparency = 1
						KeyMain.Input.BackgroundTransparency = 1
						KeyMain.Input.UIStroke.Transparency = 1
						KeyMain.Input.InputBox.TextTransparency = 1
						KeyMain.NoteTitle.TextTransparency = 1
						KeyMain.NoteMessage.TextTransparency = 1
						KeyMain.Hide.ImageTransparency = 1

						TweenService:Create(KeyMain, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {BackgroundTransparency = 0}):Play()
						TweenService:Create(KeyMain, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {Size = UDim2.new(0, 500, 0, 187)}):Play()
						TweenService:Create(KeyMain.Shadow.Image, TweenInfo.new(0.5, Enum.EasingStyle.Exponential), {ImageTransparency = 0.5}):Play()
						task.wait(0.05)
						TweenService:Create(KeyMain.Title, TweenInfo.new(0.4, Enum.EasingStyle.Exponential), {TextTransparency = 0}):Play()
						TweenService:Create(KeyMain.Subtitle, TweenInfo.new(0.5, Enum.EasingStyle.Exponential), {TextTransparency = 0}):Play()
						task.wait(0.05)
						TweenService:Create(KeyMain.KeyNote, TweenInfo.new(0.5, Enum.EasingStyle.Exponential), {TextTransparency = 0}):Play()
						TweenService:Create(KeyMain.Input, TweenInfo.new(0.5, Enum.EasingStyle.Exponential), {BackgroundTransparency = 0}):Play()
						TweenService:Create(KeyMain.Input.UIStroke, TweenInfo.new(0.5, Enum.EasingStyle.Exponential), {Transparency = 0}):Play()
						TweenService:Create(KeyMain.Input.InputBox, TweenInfo.new(0.5, Enum.EasingStyle.Exponential), {TextTransparency = 0}):Play()
						task.wait(0.05)
						TweenService:Create(KeyMain.NoteTitle, TweenInfo.new(0.4, Enum.EasingStyle.Exponential), {TextTransparency = 0}):Play()
						TweenService:Create(KeyMain.NoteMessage, TweenInfo.new(0.4, Enum.EasingStyle.Exponential), {TextTransparency = 0}):Play()
						task.wait(0.15)
						TweenService:Create(KeyMain.Hide, TweenInfo.new(0.4, Enum.EasingStyle.Exponential), {ImageTransparency = 0.3}):Play()


						KeyUI.Main.Input.InputBox.FocusLost:Connect(function()
							if #KeyUI.Main.Input.InputBox.Text == 0 then return end
							local KeyFound = false
							local FoundKey = ''
							for _, MKey in ipairs(Settings.KeySettings.Key) do
								if string.find(KeyMain.Input.InputBox.Text, MKey) then
									KeyFound = true
									FoundKey = MKey
								end
							end
							if KeyFound then 
								TweenService:Create(KeyMain, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {BackgroundTransparency = 1}):Play()
								TweenService:Create(KeyMain, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {Size = UDim2.new(0, 467, 0, 175)}):Play()
								TweenService:Create(KeyMain.Shadow.Image, TweenInfo.new(0.5, Enum.EasingStyle.Exponential), {ImageTransparency = 1}):Play()
								TweenService:Create(KeyMain.Title, TweenInfo.new(0.4, Enum.EasingStyle.Exponential), {TextTransparency = 1}):Play()
								TweenService:Create(KeyMain.Subtitle, TweenInfo.new(0.5, Enum.EasingStyle.Exponential), {TextTransparency = 1}):Play()
								TweenService:Create(KeyMain.KeyNote, TweenInfo.new(0.5, Enum.EasingStyle.Exponential), {TextTransparency = 1}):Play()
								TweenService:Create(KeyMain.Input, TweenInfo.new(0.5, Enum.EasingStyle.Exponential), {BackgroundTransparency = 1}):Play()
								TweenService:Create(KeyMain.Input.UIStroke, TweenInfo.new(0.5, Enum.EasingStyle.Exponential), {Transparency = 1}):Play()
								TweenService:Create(KeyMain.Input.InputBox, TweenInfo.new(0.5, Enum.EasingStyle.Exponential), {TextTransparency = 1}):Play()
								TweenService:Create(KeyMain.NoteTitle, TweenInfo.new(0.4, Enum.EasingStyle.Exponential), {TextTransparency = 1}):Play()
								TweenService:Create(KeyMain.NoteMessage, TweenInfo.new(0.4, Enum.EasingStyle.Exponential), {TextTransparency = 1}):Play()
								TweenService:Create(KeyMain.Hide, TweenInfo.new(0.4, Enum.EasingStyle.Exponential), {ImageTransparency = 1}):Play()
								task.wait(0.51)
								Passthrough = true
								if Settings.KeySettings.SaveKey then
									if writefile then
										writefile(RayfieldFolder.."/Key System".."/"..Settings.KeySettings.FileName..ConfigurationExtension, FoundKey)
									end
									RayfieldLibrary:Notify({Title = "Key System", Content = "The key for this script has been saved successfully."})
								end
							else
								if AttemptsRemaining == 0 then
									TweenService:Create(KeyMain, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {BackgroundTransparency = 1}):Play()
									TweenService:Create(KeyMain, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {Size = UDim2.new(0, 467, 0, 175)}):Play()
									TweenService:Create(KeyMain.Shadow.Image, TweenInfo.new(0.5, Enum.EasingStyle.Exponential), {ImageTransparency = 1}):Play()
									TweenService:Create(KeyMain.Title, TweenInfo.new(0.4, Enum.EasingStyle.Exponential), {TextTransparency = 1}):Play()
									TweenService:Create(KeyMain.Subtitle, TweenInfo.new(0.5, Enum.EasingStyle.Exponential), {TextTransparency = 1}):Play()
									TweenService:Create(KeyMain.KeyNote, TweenInfo.new(0.5, Enum.EasingStyle.Exponential), {TextTransparency = 1}):Play()
									TweenService:Create(KeyMain.Input, TweenInfo.new(0.5, Enum.EasingStyle.Exponential), {BackgroundTransparency = 1}):Play()
									TweenService:Create(KeyMain.Input.UIStroke, TweenInfo.new(0.5, Enum.EasingStyle.Exponential), {Transparency = 1}):Play()
									TweenService:Create(KeyMain.Input.InputBox, TweenInfo.new(0.5, Enum.EasingStyle.Exponential), {TextTransparency = 1}):Play()
									TweenService:Create(KeyMain.NoteTitle, TweenInfo.new(0.4, Enum.EasingStyle.Exponential), {TextTransparency = 1}):Play()
									TweenService:Create(KeyMain.NoteMessage, TweenInfo.new(0.4, Enum.EasingStyle.Exponential), {TextTransparency = 1}):Play()
									TweenService:Create(KeyMain.Hide, TweenInfo.new(0.4, Enum.EasingStyle.Exponential), {ImageTransparency = 1}):Play()
									task.wait(0.45)
									game.Players.LocalPlayer:Kick("No Attempts Remaining")
									game:Shutdown()
								end
								KeyMain.Input.InputBox.Text = ""
								AttemptsRemaining = AttemptsRemaining - 1
								TweenService:Create(KeyMain, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {Size = UDim2.new(0, 467, 0, 175)}):Play()
								TweenService:Create(KeyMain, TweenInfo.new(0.4, Enum.EasingStyle.Elastic), {Position = UDim2.new(0.495,0,0.5,0)}):Play()
								task.wait(0.1)
								TweenService:Create(KeyMain, TweenInfo.new(0.4, Enum.EasingStyle.Elastic), {Position = UDim2.new(0.505,0,0.5,0)}):Play()
								task.wait(0.1)
								TweenService:Create(KeyMain, TweenInfo.new(0.4, Enum.EasingStyle.Exponential), {Position = UDim2.new(0.5,0,0.5,0)}):Play()
								TweenService:Create(KeyMain, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {Size = UDim2.new(0, 500, 0, 187)}):Play()
							end
						end)

						KeyMain.Hide.MouseButton1Click:Connect(function()
							TweenService:Create(KeyMain, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {BackgroundTransparency = 1}):Play()
							TweenService:Create(KeyMain, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {Size = UDim2.new(0, 467, 0, 175)}):Play()
							TweenService:Create(KeyMain.Shadow.Image, TweenInfo.new(0.5, Enum.EasingStyle.Exponential), {ImageTransparency = 1}):Play()
							TweenService:Create(KeyMain.Title, TweenInfo.new(0.4, Enum.EasingStyle.Exponential), {TextTransparency = 1}):Play()
							TweenService:Create(KeyMain.Subtitle, TweenInfo.new(0.5, Enum.EasingStyle.Exponential), {TextTransparency = 1}):Play()
							TweenService:Create(KeyMain.KeyNote, TweenInfo.new(0.5, Enum.EasingStyle.Exponential), {TextTransparency = 1}):Play()
							TweenService:Create(KeyMain.Input, TweenInfo.new(0.5, Enum.EasingStyle.Exponential), {BackgroundTransparency = 1}):Play()
							TweenService:Create(KeyMain.Input.UIStroke, TweenInfo.new(0.5, Enum.EasingStyle.Exponential), {Transparency = 1}):Play()
							TweenService:Create(KeyMain.Input.InputBox, TweenInfo.new(0.5, Enum.EasingStyle.Exponential), {TextTransparency = 1}):Play()
							TweenService:Create(KeyMain.NoteTitle, TweenInfo.new(0.4, Enum.EasingStyle.Exponential), {TextTransparency = 1}):Play()
							TweenService:Create(KeyMain.NoteMessage, TweenInfo.new(0.4, Enum.EasingStyle.Exponential), {TextTransparency = 1}):Play()
							TweenService:Create(KeyMain.Hide, TweenInfo.new(0.4, Enum.EasingStyle.Exponential), {ImageTransparency = 1}):Play()
							task.wait(0.51)
							RayfieldLibrary:Destroy()
							KeyUI:Destroy()
						end)
					else
						Passthrough = true
					end
				end
				if Settings.KeySystem then
					repeat task.wait() until Passthrough
				end

				Notifications.Template.Visible = false
				Notifications.Visible = true
				Rayfield.Enabled = true
				task.wait(0.5)
				TweenService:Create(Main, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {BackgroundTransparency = 0}):Play()
				TweenService:Create(Main.Shadow.Image, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {ImageTransparency = 0.6}):Play()
				task.wait(0.1)
				TweenService:Create(LoadingFrame.Title, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {TextTransparency = 0}):Play()
				task.wait(0.05)
				TweenService:Create(LoadingFrame.Subtitle, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {TextTransparency = 0}):Play()
				task.wait(0.05)
				TweenService:Create(LoadingFrame.Version, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {TextTransparency = 0}):Play()

				Elements.Template.LayoutOrder = 100000
				Elements.Template.Visible = false

				Elements.UIPageLayout.FillDirection = Enum.FillDirection.Horizontal
				TabList.Template.Visible = false

				-- Tab
				local FirstTab = false
				local Window = {}
				function Window:CreateTab(Name,Image)
					local SDone = false
					local TabButton = TabList.Template:Clone()
					TabButton.Name = Name
					TabButton.Title.Text = Name
					TabButton.Parent = TabList
					TabButton.Title.TextWrapped = false
					TabButton.Size = UDim2.new(0, TabButton.Title.TextBounds.X + 30, 0, 30)

					if Image then
						TabButton.Title.AnchorPoint = Vector2.new(0, 0.5)
						TabButton.Title.Position = UDim2.new(0, 37, 0.5, 0)
						TabButton.Image.Image = "rbxassetid://"..Image
						TabButton.Image.Visible = true
						TabButton.Title.TextXAlignment = Enum.TextXAlignment.Left
						TabButton.Size = UDim2.new(0, TabButton.Title.TextBounds.X + 52, 0, 30)
					end

					TabButton.BackgroundTransparency = 1
					TabButton.Title.TextTransparency = 1
					TabButton.Image.ImageTransparency = 1
					TabButton.UIStroke.Transparency = 1

					TabButton.Visible = true

					-- Create Elements Page
					local TabPage = Elements.Template:Clone()
					TabPage.Name = Name
					TabPage.Visible = true

					TabPage.LayoutOrder = #Elements:GetChildren()

					for _, TemplateElement in ipairs(TabPage:GetChildren()) do
						if TemplateElement.ClassName == "Frame" and TemplateElement.Name ~= "Placeholder" then
							TemplateElement:Destroy()
						end
					end

					TabPage.Parent = Elements
					if not FirstTab then
						Elements.UIPageLayout.Animated = false
						Elements.UIPageLayout:JumpTo(TabPage)
						Elements.UIPageLayout.Animated = true
					end

					TabButton.UIStroke.Color = SelectedTheme.TabStroke
					-- Animate
					task.wait(0.1)
					if FirstTab then
						TabButton.BackgroundColor3 = SelectedTheme.TabBackground
						TabButton.Image.ImageColor3 = SelectedTheme.TabTextColor
						TabButton.Title.TextColor3 = SelectedTheme.TabTextColor
						TweenService:Create(TabButton, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {BackgroundTransparency = 0.7}):Play()
						TweenService:Create(TabButton.Title, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {TextTransparency = 0.2}):Play()
						TweenService:Create(TabButton.Image, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {ImageTransparency = 0.2}):Play()
						TweenService:Create(TabButton.UIStroke, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {Transparency = 0.5}):Play()

					else
						FirstTab = Name
						TabButton.BackgroundColor3 = SelectedTheme.TabBackgroundSelected
						TabButton.Image.ImageColor3 = SelectedTheme.SelectedTabTextColor
						TabButton.Title.TextColor3 = SelectedTheme.SelectedTabTextColor
						TweenService:Create(TabButton.Image, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {ImageTransparency = 0}):Play()
						TweenService:Create(TabButton, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {BackgroundTransparency = 0}):Play()
						TweenService:Create(TabButton.Title, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {TextTransparency = 0}):Play()
					end


					TabButton.Interact.MouseButton1Click:Connect(function()
						if Minimised then return end
						TweenService:Create(TabButton, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {BackgroundTransparency = 0}):Play()
						TweenService:Create(TabButton.UIStroke, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {Transparency = 1}):Play()
						TweenService:Create(TabButton.Title, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {TextTransparency = 0}):Play()
						TweenService:Create(TabButton.Image, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {ImageTransparency = 0}):Play()
						TweenService:Create(TabButton, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {BackgroundColor3 = SelectedTheme.TabBackgroundSelected}):Play()
						TweenService:Create(TabButton.Title, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {TextColor3 = SelectedTheme.SelectedTabTextColor}):Play()
						TweenService:Create(TabButton.Image, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {ImageColor3 = SelectedTheme.SelectedTabTextColor}):Play()

						for _, OtherTabButton in ipairs(TabList:GetChildren()) do
							if OtherTabButton.Name ~= "Template" and OtherTabButton.ClassName == "Frame" and OtherTabButton ~= TabButton and OtherTabButton.Name ~= "Placeholder" then
								TweenService:Create(OtherTabButton, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {BackgroundColor3 = SelectedTheme.TabBackground}):Play()
								TweenService:Create(OtherTabButton.Title, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {TextColor3 = SelectedTheme.TabTextColor}):Play()
								TweenService:Create(OtherTabButton.Image, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {ImageColor3 = SelectedTheme.TabTextColor}):Play()
								TweenService:Create(OtherTabButton, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {BackgroundTransparency = 0.7}):Play()
								TweenService:Create(OtherTabButton.Title, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {TextTransparency = 0.2}):Play()
								TweenService:Create(OtherTabButton.Image, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {ImageTransparency = 0.2}):Play()
								TweenService:Create(OtherTabButton.UIStroke, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {Transparency = 0.5}):Play()
							end
						end
						if Elements.UIPageLayout.CurrentPage ~= TabPage then
							Elements.UIPageLayout:JumpTo(TabPage)
						end

					end)

					local Tab = {}

					-- Button
					function Tab:CreateButton(ButtonSettings)
						local ButtonValue = {}

						local Button = Elements.Template.Button:Clone()
						Button.Name = ButtonSettings.Name
						Button.Title.Text = ButtonSettings.Name
						Button.Visible = true
						Button.Parent = TabPage

						Button.BackgroundTransparency = 1
						Button.UIStroke.Transparency = 1
						Button.Title.TextTransparency = 1

						TweenService:Create(Button, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {BackgroundTransparency = 0}):Play()
						TweenService:Create(Button.UIStroke, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {Transparency = 0}):Play()
						TweenService:Create(Button.Title, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {TextTransparency = 0}):Play()	


						Button.Interact.MouseButton1Click:Connect(function()
							local Success, Response = pcall(ButtonSettings.Callback)
							if not Success then
								TweenService:Create(Button, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {BackgroundColor3 = Color3.fromRGB(85, 0, 0)}):Play()
								TweenService:Create(Button.ElementIndicator, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {TextTransparency = 1}):Play()
								TweenService:Create(Button.UIStroke, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {Transparency = 1}):Play()
								Button.Title.Text = "Callback Error"
								print("Rayfield | "..ButtonSettings.Name.." Callback Error " ..tostring(Response))
								warn('Check docs.sirius.menu for help with Rayfield specific development.')
								task.wait(0.5)
								Button.Title.Text = ButtonSettings.Name
								TweenService:Create(Button, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {BackgroundColor3 = SelectedTheme.ElementBackground}):Play()
								TweenService:Create(Button.ElementIndicator, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {TextTransparency = 0.9}):Play()
								TweenService:Create(Button.UIStroke, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {Transparency = 0}):Play()
							else
								SaveConfiguration()
								TweenService:Create(Button, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {BackgroundColor3 = SelectedTheme.ElementBackgroundHover}):Play()
								TweenService:Create(Button.ElementIndicator, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {TextTransparency = 1}):Play()
								TweenService:Create(Button.UIStroke, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {Transparency = 1}):Play()
								task.wait(0.2)
								TweenService:Create(Button, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {BackgroundColor3 = SelectedTheme.ElementBackground}):Play()
								TweenService:Create(Button.ElementIndicator, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {TextTransparency = 0.9}):Play()
								TweenService:Create(Button.UIStroke, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {Transparency = 0}):Play()
							end
						end)

						Button.MouseEnter:Connect(function()
							TweenService:Create(Button, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {BackgroundColor3 = SelectedTheme.ElementBackgroundHover}):Play()
							TweenService:Create(Button.ElementIndicator, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {TextTransparency = 0.7}):Play()
						end)

						Button.MouseLeave:Connect(function()
							TweenService:Create(Button, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {BackgroundColor3 = SelectedTheme.ElementBackground}):Play()
							TweenService:Create(Button.ElementIndicator, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {TextTransparency = 0.9}):Play()
						end)

						function ButtonValue:Set(NewButton)
							Button.Title.Text = NewButton
							Button.Name = NewButton
						end

						return ButtonValue
					end

					-- ColorPicker
					function Tab:CreateColorPicker(ColorPickerSettings) -- by Throit
						ColorPickerSettings.Type = "ColorPicker"
						local ColorPicker = Elements.Template.ColorPicker:Clone()
						local Background = ColorPicker.CPBackground
						local Display = Background.Display
						local Main = Background.MainCP
						local Slider = ColorPicker.ColorSlider
						ColorPicker.ClipsDescendants = true
						ColorPicker.Name = ColorPickerSettings.Name
						ColorPicker.Title.Text = ColorPickerSettings.Name
						ColorPicker.Visible = true
						ColorPicker.Parent = TabPage
						ColorPicker.Size = UDim2.new(1, -10, 0, 45)
						Background.Size = UDim2.new(0, 39, 0, 22)
						Display.BackgroundTransparency = 0
						Main.MainPoint.ImageTransparency = 1
						ColorPicker.Interact.Size = UDim2.new(1, 0, 1, 0)
						ColorPicker.Interact.Position = UDim2.new(0.5, 0, 0.5, 0)
						ColorPicker.RGB.Position = UDim2.new(0, 17, 0, 70)
						ColorPicker.HexInput.Position = UDim2.new(0, 17, 0, 90)
						Main.ImageTransparency = 1
						Background.BackgroundTransparency = 1
						
						for _, rgbinput in ipairs(ColorPicker.RGB:GetChildren()) do
							if rgbinput:IsA("Frame") then
								rgbinput.BackgroundColor3 = SelectedTheme.InputBackground
								rgbinput.UIStroke.Color = SelectedTheme.InputStroke
							end
						end
						
						ColorPicker.HexInput.BackgroundColor3 = SelectedTheme.InputBackground
						ColorPicker.HexInput.UIStroke.Color = SelectedTheme.InputStroke
						


						local opened = false 
						local mouse = game.Players.LocalPlayer:GetMouse()
						Main.Image = "http://www.roblox.com/asset/?id=11415645739"
						local mainDragging = false 
						local sliderDragging = false 
						ColorPicker.Interact.MouseButton1Down:Connect(function()
							task.spawn(function()
								TweenService:Create(ColorPicker, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {BackgroundColor3 = SelectedTheme.ElementBackgroundHover}):Play()
								TweenService:Create(ColorPicker.UIStroke, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {Transparency = 1}):Play()
								task.wait(0.2)
								TweenService:Create(ColorPicker, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {BackgroundColor3 = SelectedTheme.ElementBackground}):Play()
								TweenService:Create(ColorPicker.UIStroke, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {Transparency = 0}):Play()
							end)

							if not opened then
								opened = true 
								TweenService:Create(Background, TweenInfo.new(0.45, Enum.EasingStyle.Exponential), {Size = UDim2.new(0, 18, 0, 15)}):Play()
								task.wait(0.1)
								TweenService:Create(ColorPicker, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {Size = UDim2.new(1, -10, 0, 120)}):Play()
								TweenService:Create(Background, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {Size = UDim2.new(0, 173, 0, 86)}):Play()
								TweenService:Create(Display, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {BackgroundTransparency = 1}):Play()
								TweenService:Create(ColorPicker.Interact, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {Position = UDim2.new(0.289, 0, 0.5, 0)}):Play()
								TweenService:Create(ColorPicker.RGB, TweenInfo.new(0.8, Enum.EasingStyle.Exponential), {Position = UDim2.new(0, 17, 0, 40)}):Play()
								TweenService:Create(ColorPicker.HexInput, TweenInfo.new(0.5, Enum.EasingStyle.Exponential), {Position = UDim2.new(0, 17, 0, 73)}):Play()
								TweenService:Create(ColorPicker.Interact, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {Size = UDim2.new(0.574, 0, 1, 0)}):Play()
								TweenService:Create(Main.MainPoint, TweenInfo.new(0.2, Enum.EasingStyle.Exponential), {ImageTransparency = 0}):Play()
								TweenService:Create(Main, TweenInfo.new(0.2, Enum.EasingStyle.Exponential), {ImageTransparency = SelectedTheme ~= RayfieldLibrary.Theme.Default and 0.25 or 0.1}):Play()
								TweenService:Create(Background, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {BackgroundTransparency = 0}):Play()
							else
								opened = false
								TweenService:Create(ColorPicker, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {Size = UDim2.new(1, -10, 0, 45)}):Play()
								TweenService:Create(Background, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {Size = UDim2.new(0, 39, 0, 22)}):Play()
								TweenService:Create(ColorPicker.Interact, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {Size = UDim2.new(1, 0, 1, 0)}):Play()
								TweenService:Create(ColorPicker.Interact, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {Position = UDim2.new(0.5, 0, 0.5, 0)}):Play()
								TweenService:Create(ColorPicker.RGB, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {Position = UDim2.new(0, 17, 0, 70)}):Play()
								TweenService:Create(ColorPicker.HexInput, TweenInfo.new(0.5, Enum.EasingStyle.Exponential), {Position = UDim2.new(0, 17, 0, 90)}):Play()
								TweenService:Create(Display, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {BackgroundTransparency = 0}):Play()
								TweenService:Create(Main.MainPoint, TweenInfo.new(0.2, Enum.EasingStyle.Exponential), {ImageTransparency = 1}):Play()
								TweenService:Create(Main, TweenInfo.new(0.2, Enum.EasingStyle.Exponential), {ImageTransparency = 1}):Play()
								TweenService:Create(Background, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {BackgroundTransparency = 1}):Play()
							end
							
						end)

						UserInputService.InputEnded:Connect(function(input, gameProcessed) if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then 
								mainDragging = false
								sliderDragging = false
							end end)
						Main.MouseButton1Down:Connect(function()
							if opened then
								mainDragging = true 
							end
						end)
						Main.MainPoint.MouseButton1Down:Connect(function()
							if opened then
								mainDragging = true 
							end
						end)
						Slider.MouseButton1Down:Connect(function()
							sliderDragging = true 
						end)
						Slider.SliderPoint.MouseButton1Down:Connect(function()
							sliderDragging = true 
						end)
						local h,s,v = ColorPickerSettings.Color:ToHSV()
						local color = Color3.fromHSV(h,s,v) 
						local hex = string.format("#%02X%02X%02X",color.R*0xFF,color.G*0xFF,color.B*0xFF)
						ColorPicker.HexInput.InputBox.Text = hex
						local function setDisplay()
							--Main
							Main.MainPoint.Position = UDim2.new(s,-Main.MainPoint.AbsoluteSize.X/2,1-v,-Main.MainPoint.AbsoluteSize.Y/2)
							Main.MainPoint.ImageColor3 = Color3.fromHSV(h,s,v)
							Background.BackgroundColor3 = Color3.fromHSV(h,1,1)
							Display.BackgroundColor3 = Color3.fromHSV(h,s,v)
							--Slider 
							local x = h * Slider.AbsoluteSize.X
							Slider.SliderPoint.Position = UDim2.new(0,x-Slider.SliderPoint.AbsoluteSize.X/2,0.5,0)
							Slider.SliderPoint.ImageColor3 = Color3.fromHSV(h,1,1)
							local color = Color3.fromHSV(h,s,v) 
							local r,g,b = math.floor((color.R*255)+0.5),math.floor((color.G*255)+0.5),math.floor((color.B*255)+0.5)
							ColorPicker.RGB.RInput.InputBox.Text = tostring(r)
							ColorPicker.RGB.GInput.InputBox.Text = tostring(g)
							ColorPicker.RGB.BInput.InputBox.Text = tostring(b)
							hex = string.format("#%02X%02X%02X",color.R*0xFF,color.G*0xFF,color.B*0xFF)
							ColorPicker.HexInput.InputBox.Text = hex
						end
						setDisplay()
						ColorPicker.HexInput.InputBox.FocusLost:Connect(function()
							if not pcall(function()
									local r, g, b = string.match(ColorPicker.HexInput.InputBox.Text, "^#?(%w%w)(%w%w)(%w%w)$")
									local rgbColor = Color3.fromRGB(tonumber(r, 16),tonumber(g, 16), tonumber(b, 16))
									h,s,v = rgbColor:ToHSV()
									hex = ColorPicker.HexInput.InputBox.Text
									setDisplay()
									ColorPickerSettings.Color = rgbColor
								end) 
							then 
								ColorPicker.HexInput.InputBox.Text = hex 
							end
							pcall(function()ColorPickerSettings.Callback(Color3.fromHSV(h,s,v))end)
							local r,g,b = math.floor((h*255)+0.5),math.floor((s*255)+0.5),math.floor((v*255)+0.5)
							ColorPickerSettings.Color = Color3.fromRGB(r,g,b)
							SaveConfiguration()
						end)
						--RGB
						local function rgbBoxes(box,toChange)
							local value = tonumber(box.Text) 
							local color = Color3.fromHSV(h,s,v) 
							local oldR,oldG,oldB = math.floor((color.R*255)+0.5),math.floor((color.G*255)+0.5),math.floor((color.B*255)+0.5)
							local save 
							if toChange == "R" then save = oldR;oldR = value elseif toChange == "G" then save = oldG;oldG = value else save = oldB;oldB = value end
							if value then 
								value = math.clamp(value,0,255)
								h,s,v = Color3.fromRGB(oldR,oldG,oldB):ToHSV()

								setDisplay()
							else 
								box.Text = tostring(save)
							end
							local r,g,b = math.floor((h*255)+0.5),math.floor((s*255)+0.5),math.floor((v*255)+0.5)
							ColorPickerSettings.Color = Color3.fromRGB(r,g,b)
							SaveConfiguration()
						end
						ColorPicker.RGB.RInput.InputBox.FocusLost:connect(function()
							rgbBoxes(ColorPicker.RGB.RInput.InputBox,"R")
							pcall(function()ColorPickerSettings.Callback(Color3.fromHSV(h,s,v))end)
						end)
						ColorPicker.RGB.GInput.InputBox.FocusLost:connect(function()
							rgbBoxes(ColorPicker.RGB.GInput.InputBox,"G")
							pcall(function()ColorPickerSettings.Callback(Color3.fromHSV(h,s,v))end)
						end)
						ColorPicker.RGB.BInput.InputBox.FocusLost:connect(function()
							rgbBoxes(ColorPicker.RGB.BInput.InputBox,"B")
							pcall(function()ColorPickerSettings.Callback(Color3.fromHSV(h,s,v))end)
						end)

						RunService.RenderStepped:connect(function()
							if mainDragging then 
								local localX = math.clamp(mouse.X-Main.AbsolutePosition.X,0,Main.AbsoluteSize.X)
								local localY = math.clamp(mouse.Y-Main.AbsolutePosition.Y,0,Main.AbsoluteSize.Y)
								Main.MainPoint.Position = UDim2.new(0,localX-Main.MainPoint.AbsoluteSize.X/2,0,localY-Main.MainPoint.AbsoluteSize.Y/2)
								s = localX / Main.AbsoluteSize.X
								v = 1 - (localY / Main.AbsoluteSize.Y)
								Display.BackgroundColor3 = Color3.fromHSV(h,s,v)
								Main.MainPoint.ImageColor3 = Color3.fromHSV(h,s,v)
								Background.BackgroundColor3 = Color3.fromHSV(h,1,1)
								local color = Color3.fromHSV(h,s,v) 
								local r,g,b = math.floor((color.R*255)+0.5),math.floor((color.G*255)+0.5),math.floor((color.B*255)+0.5)
								ColorPicker.RGB.RInput.InputBox.Text = tostring(r)
								ColorPicker.RGB.GInput.InputBox.Text = tostring(g)
								ColorPicker.RGB.BInput.InputBox.Text = tostring(b)
								ColorPicker.HexInput.InputBox.Text = string.format("#%02X%02X%02X",color.R*0xFF,color.G*0xFF,color.B*0xFF)
								pcall(function()ColorPickerSettings.Callback(Color3.fromHSV(h,s,v))end)
								ColorPickerSettings.Color = Color3.fromRGB(r,g,b)
								SaveConfiguration()
							end
							if sliderDragging then 
								local localX = math.clamp(mouse.X-Slider.AbsolutePosition.X,0,Slider.AbsoluteSize.X)
								h = localX / Slider.AbsoluteSize.X
								Display.BackgroundColor3 = Color3.fromHSV(h,s,v)
								Slider.SliderPoint.Position = UDim2.new(0,localX-Slider.SliderPoint.AbsoluteSize.X/2,0.5,0)
								Slider.SliderPoint.ImageColor3 = Color3.fromHSV(h,1,1)
								Background.BackgroundColor3 = Color3.fromHSV(h,1,1)
								Main.MainPoint.ImageColor3 = Color3.fromHSV(h,s,v)
								local color = Color3.fromHSV(h,s,v) 
								local r,g,b = math.floor((color.R*255)+0.5),math.floor((color.G*255)+0.5),math.floor((color.B*255)+0.5)
								ColorPicker.RGB.RInput.InputBox.Text = tostring(r)
								ColorPicker.RGB.GInput.InputBox.Text = tostring(g)
								ColorPicker.RGB.BInput.InputBox.Text = tostring(b)
								ColorPicker.HexInput.InputBox.Text = string.format("#%02X%02X%02X",color.R*0xFF,color.G*0xFF,color.B*0xFF)
								pcall(function()ColorPickerSettings.Callback(Color3.fromHSV(h,s,v))end)
								ColorPickerSettings.Color = Color3.fromRGB(r,g,b)
								SaveConfiguration()
							end
						end)

						if Settings.ConfigurationSaving then
							if Settings.ConfigurationSaving.Enabled and ColorPickerSettings.Flag then
								RayfieldLibrary.Flags[ColorPickerSettings.Flag] = ColorPickerSettings
							end
						end

						function ColorPickerSettings:Set(RGBColor)
							ColorPickerSettings.Color = RGBColor
							h,s,v = ColorPickerSettings.Color:ToHSV()
							color = Color3.fromHSV(h,s,v)
							setDisplay()
						end

						ColorPicker.MouseEnter:Connect(function()
							TweenService:Create(ColorPicker, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {BackgroundColor3 = SelectedTheme.ElementBackgroundHover}):Play()
						end)

						ColorPicker.MouseLeave:Connect(function()
							TweenService:Create(ColorPicker, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {BackgroundColor3 = SelectedTheme.ElementBackground}):Play()
						end)

						return ColorPickerSettings
					end

					-- Section
					function Tab:CreateSection(SectionName)

						local SectionValue = {}

						if SDone then
							local SectionSpace = Elements.Template.SectionSpacing:Clone()
							SectionSpace.Visible = true
							SectionSpace.Parent = TabPage
						end

						local Section = Elements.Template.SectionTitle:Clone()
						Section.Title.Text = SectionName
						Section.Visible = true
						Section.Parent = TabPage

						Section.Title.TextTransparency = 1
						TweenService:Create(Section.Title, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {TextTransparency = 0}):Play()

						function SectionValue:Set(NewSection)
							Section.Title.Text = NewSection
						end

						SDone = true

						return SectionValue
					end

					-- Label
					function Tab:CreateLabel(LabelText)
						local LabelValue = {}

						local Label = Elements.Template.Label:Clone()
						Label.Title.Text = LabelText
						Label.Visible = true
						Label.Parent = TabPage

						Label.BackgroundTransparency = 1
						Label.UIStroke.Transparency = 1
						Label.Title.TextTransparency = 1

						Label.BackgroundColor3 = SelectedTheme.SecondaryElementBackground
						Label.UIStroke.Color = SelectedTheme.SecondaryElementStroke

						TweenService:Create(Label, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {BackgroundTransparency = 0}):Play()
						TweenService:Create(Label.UIStroke, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {Transparency = 0}):Play()
						TweenService:Create(Label.Title, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {TextTransparency = 0}):Play()	

						function LabelValue:Set(NewLabel)
							Label.Title.Text = NewLabel
						end

						return LabelValue
					end

					-- Paragraph
					function Tab:CreateParagraph(ParagraphSettings)
						local ParagraphValue = {}

						local Paragraph = Elements.Template.Paragraph:Clone()
						Paragraph.Title.Text = ParagraphSettings.Title
						Paragraph.Content.Text = ParagraphSettings.Content
						Paragraph.Visible = true
						Paragraph.Parent = TabPage

						Paragraph.BackgroundTransparency = 1
						Paragraph.UIStroke.Transparency = 1
						Paragraph.Title.TextTransparency = 1
						Paragraph.Content.TextTransparency = 1

						Paragraph.BackgroundColor3 = SelectedTheme.SecondaryElementBackground
						Paragraph.UIStroke.Color = SelectedTheme.SecondaryElementStroke

						TweenService:Create(Paragraph, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {BackgroundTransparency = 0}):Play()
						TweenService:Create(Paragraph.UIStroke, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {Transparency = 0}):Play()
						TweenService:Create(Paragraph.Title, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {TextTransparency = 0}):Play()	
						TweenService:Create(Paragraph.Content, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {TextTransparency = 0}):Play()	

						function ParagraphValue:Set(NewParagraphSettings)
							Paragraph.Title.Text = NewParagraphSettings.Title
							Paragraph.Content.Text = NewParagraphSettings.Content
						end

						return ParagraphValue
					end

					-- Input
					function Tab:CreateInput(InputSettings)
						local Input = Elements.Template.Input:Clone()
						Input.Name = InputSettings.Name
						Input.Title.Text = InputSettings.Name
						Input.Visible = true
						Input.Parent = TabPage

						Input.BackgroundTransparency = 1
						Input.UIStroke.Transparency = 1
						Input.Title.TextTransparency = 1

						Input.InputFrame.BackgroundColor3 = SelectedTheme.InputBackground
						Input.InputFrame.UIStroke.Color = SelectedTheme.InputStroke

						TweenService:Create(Input, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {BackgroundTransparency = 0}):Play()
						TweenService:Create(Input.UIStroke, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {Transparency = 0}):Play()
						TweenService:Create(Input.Title, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {TextTransparency = 0}):Play()	

						Input.InputFrame.InputBox.PlaceholderText = InputSettings.PlaceholderText
						Input.InputFrame.Size = UDim2.new(0, Input.InputFrame.InputBox.TextBounds.X + 24, 0, 30)

						Input.InputFrame.InputBox.FocusLost:Connect(function()


							local Success, Response = pcall(function()
								InputSettings.Callback(Input.InputFrame.InputBox.Text)
							end)
							if not Success then
								TweenService:Create(Input, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {BackgroundColor3 = Color3.fromRGB(85, 0, 0)}):Play()
								TweenService:Create(Input.UIStroke, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {Transparency = 1}):Play()
								Input.Title.Text = "Callback Error"
								print("Rayfield | "..InputSettings.Name.." Callback Error " ..tostring(Response))
								warn('Check docs.sirius.menu for help with Rayfield specific development.')
								task.wait(0.5)
								Input.Title.Text = InputSettings.Name
								TweenService:Create(Input, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {BackgroundColor3 = SelectedTheme.ElementBackground}):Play()
								TweenService:Create(Input.UIStroke, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {Transparency = 0}):Play()
							end

							if InputSettings.RemoveTextAfterFocusLost then
								Input.InputFrame.InputBox.Text = ""
							end
							SaveConfiguration()
						end)

						Input.MouseEnter:Connect(function()
							TweenService:Create(Input, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {BackgroundColor3 = SelectedTheme.ElementBackgroundHover}):Play()
						end)

						Input.MouseLeave:Connect(function()
							TweenService:Create(Input, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {BackgroundColor3 = SelectedTheme.ElementBackground}):Play()
						end)

						Input.InputFrame.InputBox:GetPropertyChangedSignal("Text"):Connect(function()
							TweenService:Create(Input.InputFrame, TweenInfo.new(0.55, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out), {Size = UDim2.new(0, Input.InputFrame.InputBox.TextBounds.X + 24, 0, 30)}):Play()
						end)

						local InputSettings = {}
						function InputSettings:Set(text) --Doesnt fire the event
							Input.InputFrame.InputBox.Text = text
						end
						return InputSettings
					end

					-- Dropdown
					function Tab:CreateDropdown(DropdownSettings)
						local Dropdown = Elements.Template.Dropdown:Clone()
						if string.find(DropdownSettings.Name,"closed") then
							Dropdown.Name = "Dropdown"
						else
							Dropdown.Name = DropdownSettings.Name
						end
						Dropdown.Title.Text = DropdownSettings.Name
						Dropdown.Visible = true
						Dropdown.Parent = TabPage

						Dropdown.List.Visible = false
						if DropdownSettings.CurrentOption then
							if type(DropdownSettings.CurrentOption) == "string" then
								DropdownSettings.CurrentOption = {DropdownSettings.CurrentOption}
							end
							if not DropdownSettings.MultipleOptions and type(DropdownSettings.CurrentOption) == "table" then
								DropdownSettings.CurrentOption = {DropdownSettings.CurrentOption[1]}
							end
						else
							DropdownSettings.CurrentOption = {}
						end

						if DropdownSettings.MultipleOptions then
							if DropdownSettings.CurrentOption and type(DropdownSettings.CurrentOption) == "table" then
								if #DropdownSettings.CurrentOption == 1 then
									Dropdown.Selected.Text = DropdownSettings.CurrentOption[1]
								elseif #DropdownSettings.CurrentOption == 0 then
									Dropdown.Selected.Text = "None"
								else
									Dropdown.Selected.Text = "Various"
								end
							else
								DropdownSettings.CurrentOption = {}
								Dropdown.Selected.Text = "None"
							end
						else
							Dropdown.Selected.Text = DropdownSettings.CurrentOption[1] or "None"
						end


						Dropdown.BackgroundTransparency = 1
						Dropdown.UIStroke.Transparency = 1
						Dropdown.Title.TextTransparency = 1
						Dropdown.Toggle.ImageColor3 = SelectedTheme.TextColor

						Dropdown.Size = UDim2.new(1, -10, 0, 45)

						TweenService:Create(Dropdown, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {BackgroundTransparency = 0}):Play()
						TweenService:Create(Dropdown.UIStroke, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {Transparency = 0}):Play()
						TweenService:Create(Dropdown.Title, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {TextTransparency = 0}):Play()	

						for _, ununusedoption in ipairs(Dropdown.List:GetChildren()) do
							if ununusedoption.ClassName == "Frame" and ununusedoption.Name ~= "Placeholder" then
								ununusedoption:Destroy()
							end
						end

						Dropdown.Toggle.Rotation = 180

						Dropdown.Interact.MouseButton1Click:Connect(function()
							TweenService:Create(Dropdown, TweenInfo.new(0.4, Enum.EasingStyle.Exponential), {BackgroundColor3 = SelectedTheme.ElementBackgroundHover}):Play()
							TweenService:Create(Dropdown.UIStroke, TweenInfo.new(0.4, Enum.EasingStyle.Exponential), {Transparency = 1}):Play()
							task.wait(0.1)
							TweenService:Create(Dropdown, TweenInfo.new(0.4, Enum.EasingStyle.Exponential), {BackgroundColor3 = SelectedTheme.ElementBackground}):Play()
							TweenService:Create(Dropdown.UIStroke, TweenInfo.new(0.4, Enum.EasingStyle.Exponential), {Transparency = 0}):Play()
							if Debounce then return end
							if Dropdown.List.Visible then
								Debounce = true
								TweenService:Create(Dropdown, TweenInfo.new(0.5, Enum.EasingStyle.Exponential), {Size = UDim2.new(1, -10, 0, 45)}):Play()
								for _, DropdownOpt in ipairs(Dropdown.List:GetChildren()) do
									if DropdownOpt.ClassName == "Frame" and DropdownOpt.Name ~= "Placeholder" then
										TweenService:Create(DropdownOpt, TweenInfo.new(0.3, Enum.EasingStyle.Exponential), {BackgroundTransparency = 1}):Play()
										TweenService:Create(DropdownOpt.UIStroke, TweenInfo.new(0.3, Enum.EasingStyle.Exponential), {Transparency = 1}):Play()
										TweenService:Create(DropdownOpt.Title, TweenInfo.new(0.3, Enum.EasingStyle.Exponential), {TextTransparency = 1}):Play()
									end
								end
								TweenService:Create(Dropdown.List, TweenInfo.new(0.3, Enum.EasingStyle.Exponential), {ScrollBarImageTransparency = 1}):Play()
								TweenService:Create(Dropdown.Toggle, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {Rotation = 180}):Play()	
								task.wait(0.35)
								Dropdown.List.Visible = false
								Debounce = false
							else
								TweenService:Create(Dropdown, TweenInfo.new(0.5, Enum.EasingStyle.Exponential), {Size = UDim2.new(1, -10, 0, 180)}):Play()
								Dropdown.List.Visible = true
								TweenService:Create(Dropdown.List, TweenInfo.new(0.3, Enum.EasingStyle.Exponential), {ScrollBarImageTransparency = 0.7}):Play()
								TweenService:Create(Dropdown.Toggle, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {Rotation = 0}):Play()	
								for _, DropdownOpt in ipairs(Dropdown.List:GetChildren()) do
									if DropdownOpt.ClassName == "Frame" and DropdownOpt.Name ~= "Placeholder" then
										TweenService:Create(DropdownOpt, TweenInfo.new(0.3, Enum.EasingStyle.Exponential), {BackgroundTransparency = 0}):Play()
										TweenService:Create(DropdownOpt.UIStroke, TweenInfo.new(0.3, Enum.EasingStyle.Exponential), {Transparency = 0}):Play()
										TweenService:Create(DropdownOpt.Title, TweenInfo.new(0.3, Enum.EasingStyle.Exponential), {TextTransparency = 0}):Play()
									end
								end
							end
						end)

						Dropdown.MouseEnter:Connect(function()
							if not Dropdown.List.Visible then
								TweenService:Create(Dropdown, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {BackgroundColor3 = SelectedTheme.ElementBackgroundHover}):Play()
							end
						end)

						Dropdown.MouseLeave:Connect(function()
							TweenService:Create(Dropdown, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {BackgroundColor3 = SelectedTheme.ElementBackground}):Play()
						end)

						local function SetDropdownOptions()
							for _, Option in ipairs(DropdownSettings.Options) do
								local DropdownOption = Elements.Template.Dropdown.List.Template:Clone()
								DropdownOption.Name = Option
								DropdownOption.Title.Text = Option
								DropdownOption.Parent = Dropdown.List
								DropdownOption.Visible = true
								
								DropdownOption.UIStroke.Color = SelectedTheme.ElementStroke

								DropdownOption.BackgroundColor3 = DropdownSettings.CurrentOption == Option and SelectedTheme.DropdownSelected or SelectedTheme.DropdownUnselected

								DropdownOption.BackgroundTransparency = 1
								DropdownOption.UIStroke.Transparency = 1
								DropdownOption.Title.TextTransparency = 1

								--local Dropdown = Tab:CreateDropdown({
								--	Name = "Dropdown Example",
								--	Options = {"Option 1","Option 2"},
								--	CurrentOption = {"Option 1"},
								--  MultipleOptions = true,
								--	Flag = "Dropdown1",
								--	Callback = function(TableOfOptions)

								--	end,
								--})


								DropdownOption.Interact.ZIndex = 50
								DropdownOption.Interact.MouseButton1Click:Connect(function()
									if not DropdownSettings.MultipleOptions and table.find(DropdownSettings.CurrentOption, Option) then 
										return
									end

									if table.find(DropdownSettings.CurrentOption, Option) then
										table.remove(DropdownSettings.CurrentOption, table.find(DropdownSettings.CurrentOption, Option))
										if DropdownSettings.MultipleOptions then
											if #DropdownSettings.CurrentOption == 1 then
												Dropdown.Selected.Text = DropdownSettings.CurrentOption[1]
											elseif #DropdownSettings.CurrentOption == 0 then
												Dropdown.Selected.Text = "None"
											else
												Dropdown.Selected.Text = "Various"
											end
										else
											Dropdown.Selected.Text = DropdownSettings.CurrentOption[1]
										end
									else
										if not DropdownSettings.MultipleOptions then
											table.clear(DropdownSettings.CurrentOption)
										end
										table.insert(DropdownSettings.CurrentOption, Option)
										if DropdownSettings.MultipleOptions then
											if #DropdownSettings.CurrentOption == 1 then
												Dropdown.Selected.Text = DropdownSettings.CurrentOption[1]
											elseif #DropdownSettings.CurrentOption == 0 then
												Dropdown.Selected.Text = "None"
											else
												Dropdown.Selected.Text = "Various"
											end
										else
											Dropdown.Selected.Text = DropdownSettings.CurrentOption[1]
										end
										TweenService:Create(DropdownOption.UIStroke, TweenInfo.new(0.3, Enum.EasingStyle.Exponential), {Transparency = 1}):Play()
										TweenService:Create(DropdownOption, TweenInfo.new(0.3, Enum.EasingStyle.Exponential), {BackgroundColor3 = SelectedTheme.DropdownSelected}):Play()
										Debounce = true
										task.wait(0.2)
										TweenService:Create(DropdownOption.UIStroke, TweenInfo.new(0.3, Enum.EasingStyle.Exponential), {Transparency = 0}):Play()
									end


									local Success, Response = pcall(function()
										DropdownSettings.Callback(DropdownSettings.CurrentOption)
									end)

									if not Success then
										TweenService:Create(Dropdown, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {BackgroundColor3 = Color3.fromRGB(85, 0, 0)}):Play()
										TweenService:Create(Dropdown.UIStroke, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {Transparency = 1}):Play()
										Dropdown.Title.Text = "Callback Error"
										print("Rayfield | "..DropdownSettings.Name.." Callback Error " ..tostring(Response))
										warn('Check docs.sirius.menu for help with Rayfield specific development.')
										task.wait(0.5)
										Dropdown.Title.Text = DropdownSettings.Name
										TweenService:Create(Dropdown, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {BackgroundColor3 = SelectedTheme.ElementBackground}):Play()
										TweenService:Create(Dropdown.UIStroke, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {Transparency = 0}):Play()
									end

									for _, droption in ipairs(Dropdown.List:GetChildren()) do
										if droption.ClassName == "Frame" and droption.Name ~= "Placeholder" and not table.find(DropdownSettings.CurrentOption, droption.Name) then
											TweenService:Create(droption, TweenInfo.new(0.3, Enum.EasingStyle.Exponential), {BackgroundColor3 = SelectedTheme.DropdownUnselected}):Play()
										end
									end
									if not DropdownSettings.MultipleOptions then
										task.wait(0.1)
										TweenService:Create(Dropdown, TweenInfo.new(0.5, Enum.EasingStyle.Exponential), {Size = UDim2.new(1, -10, 0, 45)}):Play()
										for _, DropdownOpt in ipairs(Dropdown.List:GetChildren()) do
											if DropdownOpt.ClassName == "Frame" and DropdownOpt.Name ~= "Placeholder" then
												TweenService:Create(DropdownOpt, TweenInfo.new(0.3, Enum.EasingStyle.Exponential), {BackgroundTransparency = 1}):Play()
												TweenService:Create(DropdownOpt.UIStroke, TweenInfo.new(0.3, Enum.EasingStyle.Exponential), {Transparency = 1}):Play()
												TweenService:Create(DropdownOpt.Title, TweenInfo.new(0.3, Enum.EasingStyle.Exponential), {TextTransparency = 1}):Play()
											end
										end
										TweenService:Create(Dropdown.List, TweenInfo.new(0.3, Enum.EasingStyle.Exponential), {ScrollBarImageTransparency = 1}):Play()
										TweenService:Create(Dropdown.Toggle, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {Rotation = 180}):Play()	
										task.wait(0.35)
										Dropdown.List.Visible = false
									end
									Debounce = false
									SaveConfiguration()
								end)
							end
						end
						SetDropdownOptions()

						for _, droption in ipairs(Dropdown.List:GetChildren()) do
							if droption.ClassName == "Frame" and droption.Name ~= "Placeholder" then
								if not table.find(DropdownSettings.CurrentOption, droption.Name) then
									droption.BackgroundColor3 = SelectedTheme.DropdownUnselected
								else
									droption.BackgroundColor3 = SelectedTheme.DropdownSelected
								end
							end
						end

						function DropdownSettings:Set(NewOption)
							DropdownSettings.CurrentOption = NewOption

							if typeof(DropdownSettings.CurrentOption) == "string" then
								DropdownSettings.CurrentOption = {DropdownSettings.CurrentOption}
							end

							if not DropdownSettings.MultipleOptions then
								DropdownSettings.CurrentOption = {DropdownSettings.CurrentOption[1]}
							end

							if DropdownSettings.MultipleOptions then
								if #DropdownSettings.CurrentOption == 1 then
									Dropdown.Selected.Text = DropdownSettings.CurrentOption[1]
								elseif #DropdownSettings.CurrentOption == 0 then
									Dropdown.Selected.Text = "None"
								else
									Dropdown.Selected.Text = "Various"
								end
							else
								Dropdown.Selected.Text = DropdownSettings.CurrentOption[1]
							end


							local Success, Response = pcall(function()
								DropdownSettings.Callback(NewOption)
							end)
							if not Success then
								TweenService:Create(Dropdown, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {BackgroundColor3 = Color3.fromRGB(85, 0, 0)}):Play()
								TweenService:Create(Dropdown.UIStroke, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {Transparency = 1}):Play()
								Dropdown.Title.Text = "Callback Error"
								print("Rayfield | "..DropdownSettings.Name.." Callback Error " ..tostring(Response))
								warn('Check docs.sirius.menu for help with Rayfield specific development.')
								task.wait(0.5)
								Dropdown.Title.Text = DropdownSettings.Name
								TweenService:Create(Dropdown, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {BackgroundColor3 = SelectedTheme.ElementBackground}):Play()
								TweenService:Create(Dropdown.UIStroke, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {Transparency = 0}):Play()
							end

							for _, droption in ipairs(Dropdown.List:GetChildren()) do
								if droption.ClassName == "Frame" and droption.Name ~= "Placeholder" then
									if not table.find(DropdownSettings.CurrentOption, droption.Name) then
										droption.BackgroundColor3 = SelectedTheme.DropdownUnselected
									else
										droption.BackgroundColor3 = SelectedTheme.DropdownSelected
									end
								end
							end
							--SaveConfiguration()
						end

						function DropdownSettings:Refresh(optionsTable: table) -- updates a dropdown with new options from optionsTable
							DropdownSettings.Options = optionsTable
							for _, option in Dropdown.List:GetChildren() do
								if option.ClassName == "Frame" and option.Name ~= "Placeholder" then
									option:Destroy()
								end
							end
							SetDropdownOptions()
						end

						if Settings.ConfigurationSaving then
							if Settings.ConfigurationSaving.Enabled and DropdownSettings.Flag then
								RayfieldLibrary.Flags[DropdownSettings.Flag] = DropdownSettings
							end
						end

						return DropdownSettings
					end

					-- Keybind
					function Tab:CreateKeybind(KeybindSettings)
						local CheckingForKey = false
						local Keybind = Elements.Template.Keybind:Clone()
						Keybind.Name = KeybindSettings.Name
						Keybind.Title.Text = KeybindSettings.Name
						Keybind.Visible = true
						Keybind.Parent = TabPage

						Keybind.BackgroundTransparency = 1
						Keybind.UIStroke.Transparency = 1
						Keybind.Title.TextTransparency = 1

						Keybind.KeybindFrame.BackgroundColor3 = SelectedTheme.InputBackground
						Keybind.KeybindFrame.UIStroke.Color = SelectedTheme.InputStroke

						TweenService:Create(Keybind, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {BackgroundTransparency = 0}):Play()
						TweenService:Create(Keybind.UIStroke, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {Transparency = 0}):Play()
						TweenService:Create(Keybind.Title, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {TextTransparency = 0}):Play()	

						Keybind.KeybindFrame.KeybindBox.Text = KeybindSettings.CurrentKeybind
						Keybind.KeybindFrame.Size = UDim2.new(0, Keybind.KeybindFrame.KeybindBox.TextBounds.X + 24, 0, 30)

						Keybind.KeybindFrame.KeybindBox.Focused:Connect(function()
							CheckingForKey = true
							Keybind.KeybindFrame.KeybindBox.Text = ""
						end)
						Keybind.KeybindFrame.KeybindBox.FocusLost:Connect(function()
							CheckingForKey = false
							if Keybind.KeybindFrame.KeybindBox.Text == nil or "" then
								Keybind.KeybindFrame.KeybindBox.Text = KeybindSettings.CurrentKeybind
								SaveConfiguration()
							end
						end)

						Keybind.MouseEnter:Connect(function()
							TweenService:Create(Keybind, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {BackgroundColor3 = SelectedTheme.ElementBackgroundHover}):Play()
						end)

						Keybind.MouseLeave:Connect(function()
							TweenService:Create(Keybind, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {BackgroundColor3 = SelectedTheme.ElementBackground}):Play()
						end)

						UserInputService.InputBegan:Connect(function(input, processed)

							if CheckingForKey then
								if input.KeyCode ~= Enum.KeyCode.Unknown then
									if input.KeyCode == Enum.KeyCode.K then
										Keybind.KeybindFrame.KeybindBox.Text = ""
										KeybindSettings.CurrentKeybind = ""
									else
										local SplitMessage = string.split(tostring(input.KeyCode), ".")
										local NewKeyNoEnum = SplitMessage[3]
										Keybind.KeybindFrame.KeybindBox.Text = tostring(NewKeyNoEnum)
										KeybindSettings.CurrentKeybind = tostring(NewKeyNoEnum)
										Keybind.KeybindFrame.KeybindBox:ReleaseFocus()
										SaveConfiguration()
									end
								end
							elseif KeybindSettings.CurrentKeybind ~= "" and KeybindSettings.CurrentKeybind ~= nil then -- Test
								local current_keybind = ''
								local success, respone = pcall(function()
									current_keybind = Enum.KeyCode[KeybindSettings.CurrentKeybind]
								end)
								if not success then
									return
								end
								if (input.KeyCode ~= current_keybind or processed) then
									return
								end
								local Held = true
								local Connection
								Connection = input.Changed:Connect(function(prop)
									if prop == "UserInputState" then
										Connection:Disconnect()
										Held = false
									end
								end)

								if not KeybindSettings.HoldToInteract then
									local Success, Response = pcall(KeybindSettings.Callback)
									if not Success then
										TweenService:Create(Keybind, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {BackgroundColor3 = Color3.fromRGB(85, 0, 0)}):Play()
										TweenService:Create(Keybind.UIStroke, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {Transparency = 1}):Play()
										Keybind.Title.Text = "Callback Error"
										print("Rayfield | "..KeybindSettings.Name.." Callback Error " ..tostring(Response))
										warn('Check docs.sirius.menu for help with Rayfield specific development.')
										task.wait(0.5)
										Keybind.Title.Text = KeybindSettings.Name
										TweenService:Create(Keybind, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {BackgroundColor3 = SelectedTheme.ElementBackground}):Play()
										TweenService:Create(Keybind.UIStroke, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {Transparency = 0}):Play()
									end
								else
									task.wait(0.25)
									if Held then
										local Loop; Loop = RunService.Stepped:Connect(function()
											if not Held then
												KeybindSettings.Callback(false) -- maybe pcall this
												Loop:Disconnect()
											else
												KeybindSettings.Callback(true) -- maybe pcall this
											end
										end)
									end
								end
							end
						end)

						Keybind.KeybindFrame.KeybindBox:GetPropertyChangedSignal("Text"):Connect(function()
							TweenService:Create(Keybind.KeybindFrame, TweenInfo.new(0.55, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out), {Size = UDim2.new(0, Keybind.KeybindFrame.KeybindBox.TextBounds.X + 24, 0, 30)}):Play()
						end)

						function KeybindSettings:Set(NewKeybind)
							Keybind.KeybindFrame.KeybindBox.Text = tostring(NewKeybind)
							KeybindSettings.CurrentKeybind = tostring(NewKeybind)
							Keybind.KeybindFrame.KeybindBox:ReleaseFocus()
							SaveConfiguration()
						end
						if Settings.ConfigurationSaving then
							if Settings.ConfigurationSaving.Enabled and KeybindSettings.Flag then
								RayfieldLibrary.Flags[KeybindSettings.Flag] = KeybindSettings
							end
						end
						return KeybindSettings
					end

					-- Toggle
					function Tab:CreateToggle(ToggleSettings)
						local ToggleValue = {}

						local Toggle = Elements.Template.Toggle:Clone()
						Toggle.Name = ToggleSettings.Name
						Toggle.Title.Text = ToggleSettings.Name
						Toggle.Visible = true
						Toggle.Parent = TabPage

						Toggle.BackgroundTransparency = 1
						Toggle.UIStroke.Transparency = 1
						Toggle.Title.TextTransparency = 1
						Toggle.Switch.BackgroundColor3 = SelectedTheme.ToggleBackground

						if SelectedTheme ~= RayfieldLibrary.Theme.Default then
							Toggle.Switch.Shadow.Visible = false
						end

						TweenService:Create(Toggle, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {BackgroundTransparency = 0}):Play()
						TweenService:Create(Toggle.UIStroke, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {Transparency = 0}):Play()
						TweenService:Create(Toggle.Title, TweenInfo.new(0.7, Enum.EasingStyle.Exponential), {TextTransparency = 0}):Play()	

						if not ToggleSettings.CurrentValue then
							Toggle.Switch.Indicator.Position = UDim2.new(1, -40, 0.5, 0)
							Toggle.Switch.Indicator.UIStroke.Color = SelectedTheme.ToggleDisabledStroke
							Toggle.Switch.Indicator.BackgroundColor3 = SelectedTheme.ToggleDisabled
							Toggle.Switch.UIStroke.Color = SelectedTheme.ToggleDisabledOuterStroke
						else
							Toggle.Switch.Indicator.Position = UDim2.new(1, -20, 0.5, 0)
							Toggle.Switch.Indicator.UIStroke.Color = SelectedTheme.ToggleEnabledStroke
							Toggle.Switch.Indicator.BackgroundColor3 = SelectedTheme.ToggleEnabled
							Toggle.Switch.UIStroke.Color = SelectedTheme.ToggleEnabledOuterStroke
						end

						Toggle.MouseEnter:Connect(function()
							TweenService:Create(Toggle, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {BackgroundColor3 = SelectedTheme.ElementBackgroundHover}):Play()
						end)

						Toggle.MouseLeave:Connect(function()
							TweenService:Create(Toggle, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {BackgroundColor3 = SelectedTheme.ElementBackground}):Play()
						end)

						Toggle.Interact.MouseButton1Click:Connect(function()
							if ToggleSettings.CurrentValue then
								ToggleSettings.CurrentValue = false
								TweenService:Create(Toggle, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {BackgroundColor3 = SelectedTheme.ElementBackgroundHover}):Play()
								TweenService:Create(Toggle.UIStroke, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {Transparency = 1}):Play()
								TweenService:Create(Toggle.Switch.Indicator, TweenInfo.new(0.45, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {Position = UDim2.new(1, -40, 0.5, 0)}):Play()
								TweenService:Create(Toggle.Switch.Indicator, TweenInfo.new(0.4, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {Size = UDim2.new(0,12,0,12)}):Play()
								TweenService:Create(Toggle.Switch.Indicator.UIStroke, TweenInfo.new(0.55, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out), {Color = SelectedTheme.ToggleDisabledStroke}):Play()
								TweenService:Create(Toggle.Switch.Indicator, TweenInfo.new(0.8, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out), {BackgroundColor3 = SelectedTheme.ToggleDisabled}):Play()
								TweenService:Create(Toggle.Switch.UIStroke, TweenInfo.new(0.55, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out), {Color = SelectedTheme.ToggleDisabledOuterStroke}):Play()
								task.wait(0.05)
								TweenService:Create(Toggle.Switch.Indicator, TweenInfo.new(0.4, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {Size = UDim2.new(0,17,0,17)}):Play()
								task.wait(0.15)
								TweenService:Create(Toggle, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {BackgroundColor3 = SelectedTheme.ElementBackground}):Play()
								TweenService:Create(Toggle.UIStroke, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {Transparency = 0}):Play()	
							else
								ToggleSettings.CurrentValue = true
								TweenService:Create(Toggle, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {BackgroundColor3 = SelectedTheme.ElementBackgroundHover}):Play()
								TweenService:Create(Toggle.UIStroke, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {Transparency = 1}):Play()
								TweenService:Create(Toggle.Switch.Indicator, TweenInfo.new(0.5, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {Position = UDim2.new(1, -20, 0.5, 0)}):Play()
								TweenService:Create(Toggle.Switch.Indicator, TweenInfo.new(0.4, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {Size = UDim2.new(0,12,0,12)}):Play()
								TweenService:Create(Toggle.Switch.Indicator.UIStroke, TweenInfo.new(0.55, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out), {Color = SelectedTheme.ToggleEnabledStroke}):Play()
