					end)
				end
			end


			function RayfieldLibrary:LoadConfiguration()
				if CEnabled then
					pcall(function()
						if isfile(ConfigurationFolder .. "/" .. CFileName .. ConfigurationExtension) then
							LoadConfiguration(readfile(ConfigurationFolder .. "/" .. CFileName .. ConfigurationExtension))
							RayfieldLibrary:Notify({Title = "Configuration Loaded", Content = "The configuration file for this script has been loaded from a previous session."})
						end
					end)
				end
			end

			local __FTAP_MSG_Facade = getgenv().__FTAP_CreateFacade("MSG")
			RayfieldLibrary.CreateWindow = function(self, settings) return __FTAP_MSG_Facade:CreateWindow(settings) end
			RayfieldLibrary.Notify = function(self, settings) return __FTAP_MSG_Facade:Notify(settings) end
			RayfieldLibrary.Flags = __FTAP_MSG_Facade.Flags
			RayfieldLibrary._flagSetters = __FTAP_MSG_Facade._flagSetters
			if useStudio then
				-- run w/ studio
				-- Feel free to place your own script here to see how it'd work in Roblox Studio before running it on your execution software.

				local Window = RayfieldLibrary:CreateWindow({
					Name = "Rayfield Example Window",
					LoadingTitle = "Rayfield Interface Suite",
					Theme = 'DarkBlue',
					LoadingSubtitle = "by Sirius",
					ConfigurationSaving = {
						Enabled = true,
						FolderName = nil, -- Create a custom folder for your hub/game
						FileName = "Big Hub"
					},
					Discord = {
						Enabled = false,
						Invite = "noinvitelink", -- The Discord invite code, do not include discord.gg/. E.g. discord.gg/ABCD would be ABCD
						RememberJoins = true -- Set this to false to make them join the discord every time they load it up
					},
					KeySystem = false, -- Set this to true to use our key system
					KeySettings = {
						Title = "Untitled",
						Subtitle = "Key System",
						Note = "No method of obtaining the key is provided",
						FileName = "Key", -- It is recommended to use something unique as other scripts using Rayfield may overwrite your key file
						SaveKey = true, -- The user's key will be saved, but if you change the key, they will be unable to use your script
						GrabKeyFromSite = false, -- If this is true, set Key below to the RAW site you would like Rayfield to get the key from
						Key = {"Hello"} -- List of keys that will be accepted by the system, can be RAW file links (pastebin, github etc) or simple strings ("hello","key22")
					}
				})

