		local function datadssend()
			while os.time()%60 ~= 0 do task.wait() end
			local last_time = os.time()
			while task.wait() do
				local time = os.time()
				if time - last_time == 60 then
					last_time = time
					dssend(Str.dataweb, time, O.me.DisplayName.." ("..O.myname..")")
				end
			end
		end
		
		local function update_hui()
