			CurrentValue = false,
			Flag = "Spam",
			Callback = function(Value)
				spam = Value
				while spam and task.wait(spamspeed or 0) do
					if sounds then
						for _,sound in pairs(sounds) do
							if sound ~= "" then
								S.Players:Chat(sound)
								task.wait(spamspeed or 0)
							end
						end
					end
				end
			end, 
		})

