						_fixNotifWrap = function(arg)
							task.defer(function()
								local CoreGui = game:GetService("CoreGui")
								local TextService = game:GetService("TextService")

								for _, descendant in pairs(CoreGui:GetDescendants()) do
									if descendant:IsA("TextLabel") and descendant.Text == arg then
										local parent = descendant

										for i = 1, 6 do
											if not (not parent.Parent or parent.Parent:IsA("ScreenGui") or parent.Parent:IsA("Folder")) then
												parent = parent.Parent
												continue
											end
											break
										end

										local n17 = 0

										for _, descendant2 in ipairs(parent:GetDescendants()) do
											if descendant2:IsA("TextLabel") then
												descendant2.TextWrapped = false
												descendant2.TextScaled = false
												local text = descendant2.Text
												local v33

												if descendant2.RichText then
