												local textSize = TextService:GetTextSize(v33, descendant2.TextSize or 14, string.find(text, "<b>") and Enum.Font.GothamBold or descendant2.Font, Vector2.new(math.huge, math.huge))
												local n18 = textSize.X + 45

												if n17 < n18 then
													n17 = n18
												end

												descendant2.Size = UDim2.new(0, textSize.X + 16, descendant2.Size.Y.Scale, descendant2.Size.Y.Offset)
											end
										end

										for i = 1, 7 do
											if not (not descendant or descendant:IsA("ScreenGui") or descendant:IsA("Folder")) then
												if descendant:IsA("Frame") then
													if descendant.AbsoluteSize.X < n17 then
														descendant.Size = UDim2.new(0, n17, descendant.Size.Y.Scale, descendant.Size.Y.Offset)
													end
												end

												descendant = descendant.Parent
												continue
