																																																			local tbl39 = {}
																																																			local tbl40 = {}

																																																			for _, descendant in pairs(v77:GetDescendants()) do
																																																				if descendant:IsA("BasePart") then
																																																					tbl37[descendant] = descendant.Size
																																																					tbl38[descendant] = descendant.Transparency
																																																				elseif descendant:IsA("ParticleEmitter") then
																																																					table.insert(tbl39, descendant)

																																																					pcall(function()
																																																						descendant.Enabled = false
																																																					end)
																																																				elseif descendant:IsA("Beam") or descendant:IsA("Trail") then
																																																					table.insert(tbl40, descendant)

																																																					pcall(function()
																																																						descendant.Enabled = false
																																																					end)
																																																				elseif descendant:IsA("PointLight") or descendant:IsA("SpotLight") or descendant:IsA("SurfaceLight") then
																																																					table.insert(tbl40, descendant)

																																																					pcall(function()
																																																						descendant.Enabled = false
																																																					end)
																																																				end
																																																			end

																																																			local n33 = 1

																																																			task.spawn(function()
																																																				local now2 = tick()

																																																				while tick() - now2 < n33 do
																																																					if not (not v77 or not v77.Parent) then
																																																						local n34 = (tick() - now2) / n33
																																																						local n35 = 1 - (n34 < 0.5 and 2 * n34 * n34 or 1 - (-2 * n34 + 2) ^ 2 / 2)

																																																						for k, v78 in pairs(tbl37) do
																																																							if k and k.Parent then
																																																								pcall(function()
																																																									local cFrame = k.CFrame
																																																									k.Size = v78 * n35
																																																									k.CFrame = cFrame
																																																								end)
																																																							end
																																																						end

																																																						task.wait()
																																																						continue
																																																					end

																																																					break
																																																				end

																																																				if v77 and v77.Parent then
																																																					v77:Destroy()
																																																				end
																																																			end)
																																																		end

