																																																		fillRegion = function(arg, arg2, arg3, arg4)
																																																			local n38 = math.floor((arg - n37) / 4) * 4
																																																			local n39 = math.ceil((arg2 + n37) / 4) * 4
																																																			local n40 = math.floor((arg3 - n37) / 4) * 4
																																																			local n41 = n39 - n38
																																																			local n42 = math.ceil((arg4 + n37) / 4) * 4 - n40
																																																			local n43 = n35 - n36 / 2
																																																			local v75 = math.ceil(n41 / 2040)
																																																			local v76 = math.ceil(n42 / 2040)

																																																			for i = 0, v75 - 1 do
																																																				for i2 = 0, v76 - 1 do
																																																					local n44 = math.min(2040, n41 - i * 2040)
																																																					local n45 = math.min(2040, n42 - i2 * 2040)
																																																					local cframe2 = CFrame.new(n38 + i * 2040 + n44 / 2, n43, n40 + i2 * 2040 + n45 / 2)
																																																					local vector = Vector3.new(n44, 60, n45)

