																																																					end)

																																																					table.insert(tbl26, { cf = cframe2, size = vector })
																																																				end
																																																			end
																																																		end

																																																		for _, child in ipairs(children) do
																																																			local v75, v76, v77, v78 = getPartBounds(child)

																																																			if v75 then
																																																				fillRegion(v75, v76, v77, v78)
																																																			end
																																																		end

																																																		local folder2 = Instance.new("Folder")
																																																		folder2.Name = "_BeachHiddenOcean"
																																																		folder2.Parent = game:GetService("ReplicatedStorage")
																																																		v73 = folder2

																																																		for _, child in ipairs(children) do
																																																			pcall(function()
																																																				child.Parent = folder2
																																																			end)
																																																		end

																																																		pcall(function()
																																																			workspace.Terrain.WaterWaveSpeed = waterWaveSpeed2
																																																			workspace.Terrain.WaterWaveSize = waterWaveSize2
																																																			workspace.Terrain.WaterTransparency = waterTransparency2
																																																			workspace.Terrain.WaterReflectance = waterReflectance2
																																																		end)
