																																																															actionWheel.AddAction = function(arg, arg2)
																																																																if not arg2 or not arg2.Title then
																																																																	return
																																																																end
																																																																arg2.Id = arg2.Id or arg2.Title

																																																																for i, action in ipairs(arg.Actions) do
																																																																	if action.Id == arg2.Id then
																																																																		arg.Actions[i] = arg2
																																																																		arg:RebuildLayout()
																																																																		return
																																																																	end
																																																																end

																																																																table.insert(arg.Actions, arg2)
																																																																arg:RebuildLayout()
																																																															end

																																																															actionWheel.RemoveAction = function(arg, arg2)
																																																																for i, action in ipairs(arg.Actions) do
																																																																	if action.Id == arg2 then
																																																																		table.remove(arg.Actions, i)
																																																																		arg:RebuildLayout()
																																																																		return
																																																																	end
