																																																											local function fn58(arg, arg2, arg3)
																																																												if not arg or arg == "" then
																																																													return ""
																																																												end

																																																												if not arg2 or arg2 == "" then
																																																													return arg
																																																												end
																																																												local v85 = commandPanel.Normalize(arg)
																																																												local match = commandPanel.Normalize(arg2):lower():match("^%s*(.-)%s*$")
																																																												if not match or match == "" then
																																																													return v85
																																																												end
																																																												local str6 = v85:lower()
																																																												local str7 = arg3 and "#ffffff" or "#f0c96a"
																																																												local pos, v86 = str6:find(match, 1, true)
																																																												if pos and v86 <= #v85 then
																																																													return v85:sub(1, pos - 1) .. "<font color=\"" .. str7 .. "\"><b>" .. v85:sub(pos, v86) .. "</b></font>" .. v85:sub(v86 + 1)
																																																												end
																																																												local tbl45 = {}
																																																												local n37 = #match
																																																												local n38 = 1

																																																												for i = 1, #v85 do
																																																													local str8 = v85:sub(i, i)

																																																													if n38 <= n37 and str8:lower() == match:sub(n38, n38) then
																																																														table.insert(tbl45, "<font color=\"" .. str7 .. "\"><b>" .. str8 .. "</b></font>")
																																																														n38 += 1
																																																													else
																																																														table.insert(tbl45, str8)
																																																													end
																																																												end

																																																												return table.concat(tbl45)
																																																											end

