local Utility = {}

function Utility.isLocalAlive()
    if State.isRespawning then return false end
    local char = LocalPlayer.Character
    if not char or not char.Parent then return false end
    local inWs = false
    local ok = pcall(function() inWs = char:IsDescendantOf(Workspace) end)
    if not ok or not inWs then return false end
    local hum = char:FindFirstChildOfClass("Humanoid")
    if not hum or hum.Health <= 0 then return false end
    local dead = false
    pcall(function() dead = (hum:GetState() == Enum.HumanoidStateType.Dead) end)
    if dead then return false end
    local hrp = char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Torso")
    if not hrp or not hrp.Parent then return false end
    return true
end

function Utility.isAlive(plr)
    if not plr or plr == LocalPlayer then return Utility.isLocalAlive() end
    if not plr.Parent then return false end
    local char = plr.Character
    if not char or not char.Parent then return false end
    local inWs = false
    local ok = pcall(function() inWs = char:IsDescendantOf(Workspace) end)
    if not ok or not inWs then return false end
    local hum = char:FindFirstChildOfClass("Humanoid")
    if not hum or hum.Health <= 0 then return false end
    local dead = false
    pcall(function() dead = (hum:GetState() == Enum.HumanoidStateType.Dead) end)
    if dead then return false end
    local hrp = char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Torso")
    if not hrp or not hrp.Parent then return false end
    return true
end

function Utility.GetPlayerCharacter()
    if not Utility.isLocalAlive() then return nil end
    return LocalPlayer.Character
end

function Utility.GetPlayerRootPart()
    if not Utility.isLocalAlive() then return nil end
    local char = LocalPlayer.Character
    return char and (char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Torso"))
end

function Utility.GetPlayerCFrame()
    local root = Utility.GetPlayerRootPart()
    return root and root.CFrame
end

function Utility.getHum(char) return char and char:FindFirstChildOfClass("Humanoid") end
function Utility.getRoot(char) return char and (char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Torso")) end

do
    local function cleanupRespawnState()
        pcall(function()
            if State.connections.antiGrabChanged then State.connections.antiGrabChanged:Disconnect() State.connections.antiGrabChanged = nil end
            if State.connections.antiGrabCharAdded then State.connections.antiGrabCharAdded:Disconnect() State.connections.antiGrabCharAdded = nil end
        end)
    end
    local function markAlive()
        if State.isRespawning then
            State.isRespawning = false
            RemoteDispatcher:NewGeneration()
        end
    end
    local function onLocalDied(char)
        if State.isRespawning then return end
        State.isRespawning = true
        RemoteDispatcher:NewGeneration()
        pcall(function()
            Workspace.Gravity = 100
            if State.kickAllV2Conn then task.cancel(State.kickAllV2Conn) State.kickAllV2Conn = nil end
            Settings.BlobmanBeta.kickAllV2Active = false
            if BlobmanBetaFeature and BlobmanBetaFeature.stopKickAllV2 then pcall(BlobmanBetaFeature.stopKickAllV2) end
            if State.driftKickConn then task.cancel(State.driftKickConn) State.driftKickConn = nil end
            Settings.BlobmanBeta.driftKickActive = false
            if State.fightBackConn then pcall(function() task.cancel(State.fightBackConn) end) State.fightBackConn = nil end
            Settings.Anti.FightBack = false
            Settings.BlobmanBeta.kickActive = false
            Settings.BlobmanBeta.kickV2Active = false
            RemoteDispatcher:Flush()
            cleanupRespawnState()

            local c = char or LocalPlayer.Character
            if c then
                local hum = c:FindFirstChildOfClass("Humanoid")
                if hum then
                    hum.BreakJointsOnDeath = true
                end
                for _, p in ipairs(c:GetDescendants()) do
                    if p:IsA("BasePart") then
                        pcall(function()
                            p.Anchored = false
                            p.AssemblyLinearVelocity = Vector3.zero
                            p.AssemblyAngularVelocity = Vector3.zero
                        end)
                    elseif p:IsA("BodyGyro") or p:IsA("BodyPosition") or p:IsA("BodyVelocity") or p:IsA("BodyAngularVelocity") or p:IsA("BodyForce") then
                        pcall(function() p:Destroy() end)
                    end
                end
            end

            antiSetownLastSafePosition = nil
            antiSetownPositionHistory = {}
            antiSetownHeldSpamDetected = false
            antiSetownTeleportDetected = false

            if State.antiOwnershipConns and State.antiOwnershipConns["AntiOwn2Task"] then
                pcall(function() task.cancel(State.antiOwnershipConns["AntiOwn2Task"]) end)
                State.antiOwnershipConns["AntiOwn2Task"] = nil
            end

            -- Immediately delete Gucci Blobman upon death so old blobman never lingers
            pcall(function()
                local toyFolder = Workspace:FindFirstChild(LocalPlayer.Name .. "SpawnedInToys")
                if toyFolder then
                    for _, toy in ipairs(toyFolder:GetChildren()) do
                        if toy.Name == "CreatureBlobman" or toy.Name == "SantaSleigh" or toy.Name == "TractorGreen" or toy.Name == "Gucci" or toy:FindFirstChild("Gucci") then
                            pcall(function() DeleteToyRE:FireServer(toy) end)
                            pcall(function() toy:Destroy() end)
                        end
                    end
                end
            end)
        end)
    end
    local function setupDiedListener(char)
        if not char then return end
        local hum = char:FindFirstChildOfClass("Humanoid")
        if not hum then hum = char:WaitForChild("Humanoid", 5) end
        if not hum then return end
        hum.Died:Connect(function()
            onLocalDied(char)
        end)
        pcall(function()
            hum:GetPropertyChangedSignal("Health"):Connect(function()
                if hum.Health <= 0 then
                    onLocalDied(char)
                end
            end)
        end)
        pcall(function()
            char.AncestryChanged:Connect(function(_, parent)
                if parent == nil then
                    onLocalDied(char)
                end
            end)
        end)
    end
    LocalPlayer.CharacterAdded:Connect(function(char)
        State.isRespawning = true
        RemoteDispatcher:NewGeneration()
        task.spawn(function()
            local hum = char:WaitForChild("Humanoid", 10)
            local hrp = char:WaitForChild("HumanoidRootPart", 10)
            if not hum or not hrp then return end
            setupDiedListener(char)
            local waitStart = tick()
            while tick() - waitStart < 5 do
                if char:IsDescendantOf(Workspace) and hrp:IsDescendantOf(Workspace) and hum.Health > 0 and hrp.Position.Magnitude > 0.1 then
                    break
                end
                task.wait(0.05)
            end
            task.wait(0.6)
            if char and char.Parent and char:IsDescendantOf(Workspace) and hum and hum.Health > 0 then
                markAlive()
                antiSetownLastSafePosition = hrp.Position
                antiSetownPositionHistory = {hrp.Position}
                antiSetownHeldSpamDetected = false
                antiSetownTeleportDetected = false
            end
        end)
    end)
    LocalPlayer.CharacterRemoving:Connect(function(char)
        onLocalDied(char)
    end)
    if LocalPlayer.Character then
        setupDiedListener(LocalPlayer.Character)
    end
    task.spawn(function()
        while true do
            task.wait(0.25)
            if not State.isRespawning then
                local c = LocalPlayer.Character
                if not c or not c.Parent or not c:IsDescendantOf(Workspace) then
                    onLocalDied(c)
                else
                    local h = c:FindFirstChildOfClass("Humanoid")
                    if not h or h.Health <= 0 or h:GetState() == Enum.HumanoidStateType.Dead then
                        onLocalDied(c)
                    end
                end
            else
                local c = LocalPlayer.Character
                if c and c.Parent and c:IsDescendantOf(Workspace) then
                    local h = c:FindFirstChildOfClass("Humanoid")
                    local r = c:FindFirstChild("HumanoidRootPart")
                    if h and h.Health > 0 and r and r:IsDescendantOf(Workspace) then
                        task.wait(0.5)
                        if c and c.Parent and h and h.Health > 0 and State.isRespawning then
                            markAlive()
                        end
                    end
                end
            end
        end
    end)
    pcall(function()
        local oldNamecall
        oldNamecall = hookmetamethod(game, "__namecall", newcclosure(function(self, ...)
            local method = getnamecallmethod()
            if method ~= "FireServer" and method ~= "InvokeServer" then
                return oldNamecall(self, ...)
            end
            if State.packetBlockOutgoing then
                local args = {...}
                for i = 1, #args do
                    local a = args[i]
                    if typeof(a) == "string" and #a > 256 * 1024 then
                        return nil
                    end
                end
            end
            return oldNamecall(self, ...)
        end))
    end)
end
