local AntiFeature = {}
function AntiFeature.startStruggleLoop()
    local char = LocalPlayer.Character
    if not char or State.struggleTasks[char] then return end
    State.struggleTasks[char] = true
    task.spawn(function()
        while State.struggleTasks[char] do
            local head = char:FindFirstChild("Head")
            if head and head:FindFirstChild("PartOwner") and isHeldValue.Value then
                local grabberName = head.PartOwner.Value
                RemoteDispatcher:Fire(struggleEvent)
                local gce = ReplicatedStorage:FindFirstChild("GameCorrectionEvents")
                if gce then
                    local sav = gce:FindFirstChild("StopAllVelocity")
                    if sav then RemoteDispatcher:Fire(sav) end
                end
            else
                State.struggleTasks[char] = nil
                break
            end
            task.wait(0.1)
        end
    end)
end
function AntiFeature.setupAntiGrabV1()
    if State.connections.antiGrabChanged then
        State.connections.antiGrabChanged:Disconnect()
        State.connections.antiGrabChanged = nil
    end
    if State.connections.antiGrabCharAdded then
        State.connections.antiGrabCharAdded:Disconnect()
        State.connections.antiGrabCharAdded = nil
    end
    local lastHolder = nil
    local function updateHolder(char)
        if not char then return end
        local head = char:FindFirstChild("Head")
        if head then
            local po = head:FindFirstChild("PartOwner")
            if po then lastHolder = tostring(po.Value) end
        end
        char.DescendantAdded:Connect(function(desc)
            if desc.Name == "PartOwner" then
                lastHolder = tostring(desc.Value)
            end
        end)
    end
    local function tryStart(isBeingHeld)
        if not isBeingHeld then return end
        if not Settings.Anti.AntiGrab then return end
        if not Utility.isLocalAlive() then return end
        if lastHolder and isProtectedPlayer(lastHolder) then return end
        local char = LocalPlayer.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        if not hrp then return end
        if not isHeldValue.Value then return end
        local conn
        local trackedChar = char
        conn = RunService.Heartbeat:Connect(function()
            if not Utility.isLocalAlive() then
                pcall(function() if hrp and hrp.Parent then hrp.Anchored = false end end)
                if conn then conn:Disconnect() end
                return
            end
            if not hrp or not hrp.Parent or hrp:IsDescendantOf(Workspace) == false then
                pcall(function() if hrp and hrp.Parent then hrp.Anchored = false end end)
                if conn then conn:Disconnect() end
                return
            end
            if trackedChar ~= LocalPlayer.Character then
                pcall(function() if hrp and hrp.Parent then hrp.Anchored = false end end)
                if conn then conn:Disconnect() end
                return
            end
            if isHeldValue.Value then
                pcall(function()
                    hrp.Velocity = Vector3.new()
                    hrp.Anchored = true
                    RemoteDispatcher:Fire(struggleEvent, LocalPlayer)
                    RemoteDispatcher:Fire(ragdollRemoteEvent, hrp, 0)
                end)
            else
                pcall(function() if hrp and hrp.Parent then hrp.Anchored = false end end)
                if conn then conn:Disconnect() end
            end
        end)
    end
    State.connections.antiGrabChanged = isHeldValue.Changed:Connect(tryStart)
    local char = LocalPlayer.Character
    if char and Utility.isLocalAlive() then updateHolder(char) end
    State.connections.antiGrabCharAdded = LocalPlayer.CharacterAdded:Connect(function(newChar)
        task.wait(0.6)
        if Utility.isLocalAlive() then
            updateHolder(newChar)
        end
    end)
    if isHeldValue.Value then
        tryStart(true)
    end
end
function AntiFeature.disableAntiGrabV1()
    if State.connections.antiGrabChanged then
        State.connections.antiGrabChanged:Disconnect()
        State.connections.antiGrabChanged = nil
    end
    if State.connections.antiGrabCharAdded then
        State.connections.antiGrabCharAdded:Disconnect()
        State.connections.antiGrabCharAdded = nil
    end
end
do
    local seatlessGucciActive = false
    local seatlessGucciConn = nil
    local seatlessSpawnTick = nil
    function AntiFeature.startSeatlessGucci()
        seatlessGucciActive = true
        Settings.Anti.SeatlessGucciAntiGrab = true
        if not seatlessGucciConn then
            local ContextActionService = game:GetService("ContextActionService")
            seatlessGucciConn = RunService.RenderStepped:Connect(function()
                if not seatlessGucciActive then return end
                if not Utility.isLocalAlive() then return end
                local char = LocalPlayer.Character
                if not char then return end
                local hum = char:FindFirstChild("Humanoid")
                local root = char:FindFirstChild("HumanoidRootPart")
                local myToys = workspace:FindFirstChild(LocalPlayer.Name .. "SpawnedInToys")
                local ocarina = myToys and myToys:FindFirstChild("InstrumentWoodwindOcarina")
                if ocarina then
                    for _, prt in ipairs(char:GetChildren()) do
                        local owner = prt:FindFirstChild("PartOwner")
                        if owner and owner.Value ~= "" then
                            local holdPart = ocarina:FindFirstChild("HoldPart")
                            local holdFunc = holdPart and holdPart:FindFirstChild("HoldItemRemoteFunction")
                            if holdFunc then
                                task.spawn(function()
                                    pcall(function() holdFunc:InvokeServer(ocarina, char) end)
                                end)
                                local menuToys = ReplicatedStorage:FindFirstChild("MenuToys")
                                local destroyToy = menuToys and menuToys:FindFirstChild("DestroyToy")
                                if destroyToy then
                                    pcall(function() destroyToy:FireServer(ocarina) end)
                                end
                                if hum then
                                    hum:SetStateEnabled(Enum.HumanoidStateType.Jumping, true)
                                    hum.AutoRotate = true
                                    if hum.Sit then
                                        hum.Sit = false
                                    end
                                end
                                pcall(function()
                                    ContextActionService:UnbindAction("Escape")
                                    ContextActionService:UnbindAction("JumpRemover")
                                end)
                                owner.Value = ""
                            end
                        end
                    end
                else
                    local canSpawn = LocalPlayer:FindFirstChild("CanSpawnToy")
                    if canSpawn and canSpawn.Value and not seatlessSpawnTick then
                        seatlessSpawnTick = tick()
                        task.spawn(function()
                            pcall(function()
                                SpawnToyRF:InvokeServer("InstrumentWoodwindOcarina", CFrame.new(1e5, 1e5, 1e5), Vector3.zero)
                            end)
                        end)
                    elseif seatlessSpawnTick and tick() - seatlessSpawnTick > 1 and not (myToys and myToys:FindFirstChild("InstrumentWoodwindOcarina")) then
                        seatlessSpawnTick = nil
                    end
                    local grabbed = false
                    for _, prt in ipairs(char:GetChildren()) do
                        local owner = prt:FindFirstChild("PartOwner")
                        if owner and owner.Value ~= "" then
                            grabbed = true
                            break
                        end
                    end
                    if grabbed then
                        local charEvents = ReplicatedStorage:FindFirstChild("CharacterEvents")
                        if charEvents then
                            local struggle = charEvents:FindFirstChild("Struggle")
                            local ragdollRemote = charEvents:FindFirstChild("RagdollRemote")
                            if struggle then pcall(function() struggle:FireServer(LocalPlayer) end) end
                            if ragdollRemote and root then pcall(function() ragdollRemote:FireServer(root, 0) end) end
                        end
                    end
                end
            end)
        end
    end
    function AntiFeature.stopSeatlessGucci()
        seatlessGucciActive = false
        Settings.Anti.SeatlessGucciAntiGrab = false
        if seatlessGucciConn then
            seatlessGucciConn:Disconnect()
            seatlessGucciConn = nil
        end
    end
end
