function AntiFeature.checkOwnershipOnPlayer(plr)
    if typeof(plr) == "Instance" and plr:IsA("Player") and plr.Character then
        local head = plr.Character:FindFirstChild("Head")
        if head then
            local po = head:FindFirstChild("PartOwner")
            if po and po.Value == LocalPlayer.Name then return true end
        end
    end
    return false
end
function AntiFeature.createSkyVelocity(part)
    if part and part.Parent and not part:FindFirstChild("SkyVelocity") then
        local bv = Instance.new("BodyVelocity", part)
        bv.Name = "SkyVelocity"
        bv.Velocity = Vector3.new(0, 100000000000000, 0)
        bv.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
    end
end
function AntiFeature.snowshipPlayer(plr, fn)
    if not Utility.isLocalAlive() then return false end
    local char = LocalPlayer.Character
    local root = char and char:FindFirstChild("HumanoidRootPart")
    if not root then return false end
    if typeof(plr) ~= "Instance" or not plr:IsA("Player") or not plr.Character then return false end
    local hrp = plr.Character:FindFirstChild("HumanoidRootPart")
    if not hrp then return false end
    if AntiFeature.checkOwnershipOnPlayer(plr) then
        if type(fn) == "function" then fn() end
        return true
    end
    local dist = LocalPlayer:DistanceFromCharacter(hrp.Position)
    if dist <= 30 and dist > 0.1 then
        RemoteDispatcher:Fire(setNetworkOwnerEvent, hrp, CFrame.lookAt(root.Position, hrp.Position))
    end
    return false
end
function AntiFeature.setupAutoAttacker()
    if State.connections.autoAttacker then
        State.connections.autoAttacker:Disconnect()
        State.connections.autoAttacker = nil
    end
    local function watchChar(char)
        if not char then return end
        char.DescendantAdded:Connect(function(desc)
            if desc.Name ~= "PartOwner" then return end
            if not Settings.Anti.AutoAttacker then return end
            if not Utility.isLocalAlive() then return end
            local holderName = tostring(desc.Value)
            local holder = Players:FindFirstChild(holderName)
            if not holder or not holder.Character then return end
            local hum = holder.Character:FindFirstChildOfClass("Humanoid")
            local hrp = holder.Character:FindFirstChild("HumanoidRootPart")
            if not hum or not hrp or hum.Health <= 0 then return end
            if holder == LocalPlayer or isProtectedPlayer(holderName) then return end
            local mode = Settings.Anti.CounterMode or "Repulsion"
            local fn
            if mode == "Repulsion" then
                fn = function()
                    local myRoot = Utility.GetPlayerRootPart()
                    if not myRoot then return end
                    local diff = hrp.Position - myRoot.Position
                    local look = diff.Magnitude > 0.1 and diff.Unit or Vector3.new(0, 0, 1)
                    local bv = Instance.new("BodyVelocity", hrp)
                    bv.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
                    bv.Velocity = Vector3.new(look.X, 0.5, look.Z) * 100
                    task.wait()
                    bv:Destroy()
                    RemoteDispatcher:Fire(destroyGrabLineEvent, hrp)
                end
            elseif mode == "Freeze" then
                fn = function()
                    hum.WalkSpeed = 0
                    hum.Sit = false
                    hum.JumpPower = 0
                end
            elseif mode == "Death" then
                fn = function()
                    AntiFeature.createSkyVelocity(hrp)
                    for _ = 1, 20 do
                        hum.BreakJointsOnDeath = false
                        hum:ChangeState(Enum.HumanoidStateType.Dead)
                        hum.Jump = true
                        hum.Sit = true
                    end
                    task.wait()
                    RemoteDispatcher:Fire(destroyGrabLineEvent, hrp)
                end
            else
                fn = function()
                    AntiFeature.createSkyVelocity(hrp)
                    task.wait(1)
                    RemoteDispatcher:Fire(destroyGrabLineEvent, hrp)
                end
            end
            for _ = 1, 50 do
                if not Settings.Anti.AutoAttacker then break end
                if AntiFeature.snowshipPlayer(holder, fn) then break end
                task.wait()
            end
        end)
    end
    local char = LocalPlayer.Character
    if char and Utility.isLocalAlive() then watchChar(char) end
    State.connections.autoAttacker = LocalPlayer.CharacterAdded:Connect(function(newChar)
        task.wait(0.6)
        if Utility.isLocalAlive() then
            watchChar(newChar)
        end
    end)
end
function AntiFeature.disableAutoAttacker()
    if State.connections.autoAttacker then
        State.connections.autoAttacker:Disconnect()
        State.connections.autoAttacker = nil
    end
end
function AntiFeature.enableAntiGrabSolaris()
    if State.connections.antiGrab then State.connections.antiGrab:Disconnect() end
    local lastCheck = 0
    State.connections.antiGrab = RunService.Heartbeat:Connect(function()
        local now = tick()
        if now - lastCheck < 0.04 then return end
        lastCheck = now
        if State.isRespawning then return end
        local char = LocalPlayer.Character
        if char and char:FindFirstChild("Head") then
            local head = char.Head
            if head:FindFirstChild("PartOwner") and isHeldValue.Value then
                AntiFeature.startStruggleLoop()
            end
        end
    end)
end
function AntiFeature.disableAntiGrabSolaris()
    if State.connections.antiGrab then
        State.connections.antiGrab:Disconnect()
        State.connections.antiGrab = nil
    end
    for k in pairs(State.struggleTasks) do
        State.struggleTasks[k] = nil
    end
end
function AntiFeature.setupAntiExplosion(character)
    local humanoid = character:WaitForChild("Humanoid", 5)
    local hrp = character:WaitForChild("HumanoidRootPart", 5)
    if not humanoid or not hrp then return end
    if antiExplosionConnection then
        antiExplosionConnection:Disconnect()
    end
    antiExplosionConnection = Workspace.ChildAdded:Connect(function(model)
        if not Settings.Anti.AntiExplosion then return end
        if not Utility.isLocalAlive() then return end
        local char = LocalPlayer.Character
        local h = char and char:FindFirstChild("Humanoid")
        local r = char and char:FindFirstChild("HumanoidRootPart")
        if not h or not r or h.Health <= 0 then return end
        if model:IsA("BasePart") and (model.Position - r.Position).Magnitude <= 20 then
            if h.SeatPart ~= nil then
                r.Anchored = true
                task.wait(0.03)
                if not Utility.isLocalAlive() then return end
                r.AssemblyLinearVelocity = Vector3.zero
                r.AssemblyAngularVelocity = Vector3.zero
                r.Anchored = false
            else
                r.Anchored = true
                task.wait()
                if not Utility.isLocalAlive() then return end
                h:ChangeState(Enum.HumanoidStateType.Running)
                r.Anchored = false
                h.AutoRotate = true
                for _, limb in ipairs(char:GetDescendants()) do
                    if limb:IsA("BasePart") and limb.Name == "RagdollLimbPart" then
                        limb.CanCollide = false
                    end
                end
            end
        end
    end)
end
