function AntiFeature.setTouchQuery(state)
    local char = Workspace:FindFirstChild(LocalPlayer.Name)
    if not char then return end
    for _, v in ipairs(char:GetChildren()) do
        if v:IsA("Part") or v:IsA("BasePart") then
            v.CanTouch = state
            v.CanQuery = state
        end
    end
end
function AntiFeature.deleteAllPaintParts()
    for _, obj in ipairs(Workspace:GetDescendants()) do
        if obj:IsA("BasePart") and obj.Name == "PaintPlayerPart" then
            local clone = obj:Clone()
            clone.Archivable = true
            State.paintPartsBackup[obj:GetDebugId()] = { clone = clone, parent = obj.Parent }
            obj:Destroy()
        end
    end
end
function AntiFeature.restorePaintParts()
    for _, data in pairs(State.paintPartsBackup) do
        if data.clone and data.parent then
            data.clone.Parent = data.parent
        end
    end
    State.paintPartsBackup = {}
end
function AntiFeature.scanAndDeletePaintParts()
    local desc = Workspace:GetDescendants()
    for i = 1, #desc do
        local obj = desc[i]
        if obj:IsA("BasePart") and obj.Name == "PaintPlayerPart" then
            if not State.paintPartsBackup[obj:GetDebugId()] then
                local ok, clone = pcall(obj.Clone, obj)
                if ok then
                    clone.Archivable = true
                    State.paintPartsBackup[obj:GetDebugId()] = { clone = clone, parent = obj.Parent }
                end
            end
            pcall(function() obj:Destroy() end)
        end
    end
end
function AntiFeature.watchNewPaintParts()
    table.insert(State.paintConnections, Workspace.DescendantAdded:Connect(function(obj)
        if obj:IsA("BasePart") and obj.Name == "PaintPlayerPart" then
            task.defer(function()
                if obj and obj.Parent then
                    local clone = obj:Clone()
                    clone.Archivable = true
                    State.paintPartsBackup[obj:GetDebugId()] = { clone = clone, parent = obj.Parent }
                    obj:Destroy()
                end
            end)
        end
    end))
    table.insert(State.paintConnections, Workspace.DescendantRemoving:Connect(function(obj)
        if obj:IsA("BasePart") and obj.Name == "PaintPlayerPart" then
            State.paintPartsBackup[obj:GetDebugId()] = nil
        end
    end))
end
function AntiFeature.disconnectWatchers()
    for _, conn in ipairs(State.paintConnections) do
        if conn.Connected then conn:Disconnect() end
    end
    State.paintConnections = {}
    if State.paintScanThread then
        task.cancel(State.paintScanThread)
        State.paintScanThread = nil
    end
end
local function markGucciBlobman(model)
    if not model or model:FindFirstChild("Gucci") then return end
    local p = Instance.new("Part")
    p.Name = "Gucci"
    p.Size = Vector3.new(0.1, 0.1, 0.1)
    p.Transparency = 1
    p.CanCollide = false
    p.Anchored = true
    p.Parent = model
end
local function findGucciBlobman(folder)
    if not folder then return nil end
    for _, child in ipairs(folder:GetChildren()) do
        if child:IsA("Model") and child:FindFirstChild("Gucci") then
            return child
        end
    end
    return nil
end
local function isGucciBlobman(model)
    return model ~= nil and model:IsA("Model") and model:FindFirstChild("Gucci") ~= nil
end
local function spawnOrGetGucciBlobman(cframe, velocity)
    local inv = Workspace:FindFirstChild(LocalPlayer.Name .. "SpawnedInToys")
    local existing = findGucciBlobman(inv)
    if existing then return existing end
    local canSpawn = LocalPlayer:FindFirstChild("CanSpawnToy")
    if canSpawn then
        local wt = tick()
        while canSpawn and not canSpawn.Value and tick() - wt < 5 do task.wait(0.1) end
    end
    if not inv then
        local wt = tick()
        while not inv and tick() - wt < 3 do
            inv = Workspace:FindFirstChild(LocalPlayer.Name .. "SpawnedInToys")
            if inv then break end
            task.wait(0.1)
        end
    end
    local blob = nil
    for attempt = 1, 3 do
        blob = nil
        local conn
        inv = Workspace:FindFirstChild(LocalPlayer.Name .. "SpawnedInToys")
        if inv then
            conn = inv.ChildAdded:Connect(function(toy)
                if toy.Name == "CreatureBlobman" and toy:IsA("Model") then
                    markGucciBlobman(toy)
                    blob = toy
                    if conn then conn:Disconnect() end
                end
            end)
        end
        pcall(function() RemoteDispatcher:Invoke(SpawnToyRF, "CreatureBlobman", cframe, velocity) end)
        local startTick = tick()
        while not blob do
            if tick() - startTick > 2 then break end
            task.wait(0.01)
        end
        if conn then conn:Disconnect() end
        if blob then break end
        task.wait(0.3)
    end
    return blob
end
function AntiFeature.spawnBlobmanForGucci()
    local char = LocalPlayer.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    local pos = hrp and hrp.CFrame or CFrame.new(0, 50, 0)
    local inv = Workspace:FindFirstChild(LocalPlayer.Name .. "SpawnedInToys")
    local conn
    if inv then
        conn = inv.ChildAdded:Connect(function(toy)
            if toy.Name == "CreatureBlobman" and toy:IsA("Model") then
                markGucciBlobman(toy)
                if conn then conn:Disconnect() end
            end
        end)
        task.delay(3, function() if conn then conn:Disconnect() end end)
    end
    pcall(function()
        RemoteDispatcher:Invoke(SpawnToyRF, "CreatureBlobman", pos, Vector3.new(0, 0, 0))
    end)
end
function AntiFeature.startAntiGucci()
    if State.antiGucci.running then return end
    State.antiGucci.running = true
    local character = LocalPlayer.Character or LocalPlayer.CharacterAdded:Wait()
    local humanoid = character:WaitForChild("Humanoid")
    local rootPart = character:WaitForChild("HumanoidRootPart")
    State.antiGucci.safePosition = rootPart.CFrame
    local itm = nil
    local inexistance = {}
    local guccion = false
    local tickyticky = tick()
    local sp, sv
    local humconnection
    local GUTYPE = "CreatureBlobman"
    local GE = ReplicatedStorage:FindFirstChild("GrabEvents")
    local createGrab = GE and GE:FindFirstChild("CreateGrabLine")
    local setOwner = GE and GE:FindFirstChild("SetNetworkOwner")
    local destroyGrab = GE and GE:FindFirstChild("DestroyGrabLine")
    local function diddle()
        if itm then
            for _, prt in pairs(itm:GetChildren()) do
                if prt:IsA("BasePart") then prt.CanCollide = false end
            end
        end
        rootPart.CFrame = sp
        rootPart.AssemblyLinearVelocity = sv
        humanoid:GetPropertyChangedSignal("SeatPart"):Once(diddle)
    end
    State.antiGucci.blobLoop = task.spawn(function()
        while Settings.Anti.AntiGucciBlobman do
            character = LocalPlayer.Character
            if not character or not character:FindFirstChild("Humanoid") or not character:FindFirstChild("HumanoidRootPart") then
                task.wait(0.2)
                continue
            end
            humanoid = character:FindFirstChild("Humanoid")
            rootPart = character:FindFirstChild("HumanoidRootPart")
            local now = tick()
            local dt = now - tickyticky
            tickyticky = now
            local inv = Workspace:FindFirstChild(LocalPlayer.Name .. "SpawnedInToys")
            if itm and itm.Parent and itm:FindFirstChild("VehicleSeat") then
                local seat = itm.VehicleSeat
                local occupant = seat.Occupant
                if occupant and occupant ~= humanoid then
                    if itm.Name == "CreatureBlobman" then
                        guccion = false
                        local occSignal = seat:GetPropertyChangedSignal("Occupant")
                        while seat and seat.Parent and seat.Occupant and seat.Occupant ~= humanoid and Settings.Anti.AntiGucciBlobman do
                            occSignal:Wait()
                        end
                        if Settings.Anti.AntiGucciBlobman and humanoid and rootPart and seat and seat.Parent and (not seat.Occupant or seat.Occupant == humanoid) then
                            for _, prt in pairs(itm:GetChildren()) do
                                if prt:IsA("BasePart") then
                                    pcall(function() RemoteDispatcher:Fire(setNetworkOwnerEvent, prt, CFrame.lookAt(rootPart.CFrame.Position, prt.CFrame.Position)) end)
                                end
                            end
                            rootPart.CFrame = seat.CFrame + Vector3.new(0, 1.5, 0)
                            rootPart.AssemblyLinearVelocity = Vector3.zero
                            seat:Sit(humanoid)
                            pcall(function() RemoteDispatcher:Fire(ragdollRemoteEvent, rootPart, 1.6666666666666665E-2) end)
                            guccion = true
                        end
                    else
                        pcall(function() RemoteDispatcher:Fire(ReplicatedStorage.MenuToys.DestroyToy, itm) end)
                        itm = nil
                        guccion = false
                        inexistance = {}
                        task.wait(0.05)
                        if LocalPlayer:FindFirstChild("CanSpawnToy") and LocalPlayer.CanSpawnToy.Value then
                            pcall(function() RemoteDispatcher:Invoke(SpawnToyRF, GUTYPE, rootPart.CFrame * CFrame.new(0, 100000000, 10), Vector3.new(0, 0, 0)) end)
                        end
                    end
                    task.wait()
                    continue
                end
            end
            if itm and itm.Parent and not ((itm:FindFirstChild("HumanoidRootPart") or itm:FindFirstChild("SoundPart")) and itm:FindFirstChild("VehicleSeat") and (not itm.VehicleSeat.Occupant or itm.VehicleSeat.Occupant ~= humanoid) or (inexistance[itm] or 0) < 1) then
                pcall(function() RemoteDispatcher:Fire(ReplicatedStorage.MenuToys.DestroyToy, itm) end)
            else
                if inv then
                    itm = inv:FindFirstChild(GUTYPE)
                end
            end
            if not sp or not humanoid.SeatPart then
                sp = rootPart.CFrame
                sv = rootPart.AssemblyLinearVelocity
            end
            if humconnection ~= humanoid then
                humconnection = humanoid
                humanoid:GetPropertyChangedSignal("SeatPart"):Once(diddle)
            end
            local waitAfter = true
            if itm then
                inexistance[itm] = (inexistance[itm] or 0) + dt
                if (itm:FindFirstChild("HumanoidRootPart") or itm:FindFirstChild("SoundPart")) and itm:FindFirstChild("VehicleSeat") and (not itm.VehicleSeat.Occupant or itm.VehicleSeat.Occupant == humanoid) then
                    if not guccion then
                        pcall(function() (itm:FindFirstChild("HumanoidRootPart") or itm:FindFirstChild("SoundPart")).AssemblyLinearVelocity = Vector3.new(0, 0, 0) end)
                    end
                    local diddy = itm.VehicleSeat
                    diddy.Parent = nil
                    diddy.Parent = itm
                    local alreadyOwned = false
                    pcall(function()
                        for _, prt in pairs(itm:GetChildren()) do
                            if prt:FindFirstChild("PartOwner") and prt.PartOwner.Value == LocalPlayer.Name then
                                alreadyOwned = true
                            end
                        end
                    end)
                    local distPart = itm:FindFirstChild("HumanoidRootPart") or itm:FindFirstChild("SoundPart")
                    if not alreadyOwned and distPart and (rootPart.CFrame.Position - distPart.CFrame.Position).Magnitude < 28 then
                        pcall(function()
                            for _, prt in pairs(itm:GetChildren()) do
                                if prt:IsA("BasePart") and prt.CanQuery then
                                    RemoteDispatcher:Fire(setNetworkOwnerEvent, prt, CFrame.lookAt(rootPart.CFrame.Position, prt.CFrame.Position))
                                end
                            end
                        end)
                    end
                    if not humanoid.SeatPart then
                        humanoid.Sit = false
                    else
                        waitAfter = false
                        task.wait()
                    end
                    if rootPart and humanoid and itm:FindFirstChild("VehicleSeat") and (not itm.VehicleSeat.Occupant or itm.VehicleSeat.Occupant == humanoid) then
                        if humanoid.Ragdolled.Value or humanoid.Sit then
                            guccion = false
                        end
                        if itm.VehicleSeat.Occupant == humanoid then
                            guccion = true
                        elseif not guccion then
                            task.wait()
                            waitAfter = false
                            if itm:FindFirstChild("VehicleSeat") and (not itm.VehicleSeat.Occupant or itm.VehicleSeat.Occupant == humanoid) and not humanoid.Ragdolled.Value then
                                itm.VehicleSeat:Sit(humanoid)
                                RemoteDispatcher:Fire(ragdollRemoteEvent, rootPart, 1.6666666666666665E-2)
                            end
                        end
                        if guccion then
                            pcall(function() (itm:FindFirstChild("HumanoidRootPart") or itm:FindFirstChild("SoundPart")).AssemblyLinearVelocity = Vector3.new(0, 1e15, 0) end)
                        else
                            local ping = 0
                            pcall(function() ping = game:GetService("Stats").Network.ServerStatsItem["Data Ping"]:GetValue() end)
                            if (inexistance[itm] or 0) >= ping / 250 then
                                pcall(function() RemoteDispatcher:Fire(ReplicatedStorage.MenuToys.DestroyToy, itm) end)
                                humanoid.Sit = true
                            end
                        end
                    end
                else
                    if guccion then
                        humanoid.Sit = true
                    end
                    guccion = false
                    if (inexistance[itm] or 0) >= 1 then
                        pcall(function() RemoteDispatcher:Fire(ReplicatedStorage.MenuToys.DestroyToy, itm) end)
                        if LocalPlayer:FindFirstChild("CanSpawnToy") and LocalPlayer.CanSpawnToy.Value then
                            pcall(function() RemoteDispatcher:Invoke(SpawnToyRF, GUTYPE, rootPart.CFrame * CFrame.new(0, 100000000, 10), Vector3.new(0, 0, 0)) end)
                        end
                    end
                end
            else
                if guccion then
                    guccion = false
                    humanoid.Sit = true
                end
                if LocalPlayer:FindFirstChild("CanSpawnToy") and LocalPlayer.CanSpawnToy.Value then
                    pcall(function() RemoteDispatcher:Invoke(SpawnToyRF, GUTYPE, rootPart.CFrame * CFrame.new(0, 100000000, 10), Vector3.new(0, 0, 0)) end)
                end
            end
            if waitAfter then
                task.wait()
                humanoid.Sit = false
            else
                task.wait()
            end
        end
        State.antiGucci.running = false
    end)
end
function AntiFeature.stopAntiGucci()
    Settings.Anti.AntiGucciBlobman = false
    if State.antiGucci.blobLoop then
        task.cancel(State.antiGucci.blobLoop)
        State.antiGucci.blobLoop = nil
    end
    State.antiGucci.running = false
    local character = LocalPlayer.Character
    if character then
        local rootPart = character:FindFirstChild("HumanoidRootPart")
        local humanoid = character:FindFirstChildOfClass("Humanoid")
        if rootPart and State.antiGucci.safePosition then
            rootPart.CFrame = State.antiGucci.safePosition
            rootPart.AssemblyLinearVelocity = Vector3.zero
            rootPart.AssemblyAngularVelocity = Vector3.zero
        end
        if humanoid then humanoid.Sit = false end
    end
end
function AntiFeature.gucciSetupBlob(blob)
    if not blob then return end
    local character = LocalPlayer.Character
    if not character then return end
    local humanoid = character:WaitForChild("Humanoid")
    local rootPart = character:WaitForChild("HumanoidRootPart")
    local seat = blob:FindFirstChildWhichIsA("VehicleSeat", true)
    if not seat then return end
    local GE = ReplicatedStorage:FindFirstChild("GrabEvents")
    local createGrab = GE and GE:FindFirstChild("CreateGrabLine")
    local setOwner = GE and GE:FindFirstChild("SetNetworkOwner")
    local destroyGrab = GE and GE:FindFirstChild("DestroyGrabLine")
    rootPart.CFrame = seat.CFrame + Vector3.new(0, 2, 0)
    task.wait()
    seat:Sit(humanoid)
    task.wait(0.1)
    local gucciFrame = 0
    local setupStart = tick()
    while tick() - setupStart < 0.4 and Settings.Anti.AntiGucciBlobman do
        local parts = {}
        for _, part in ipairs(blob:GetDescendants()) do
            if part:IsA("BasePart") then
                table.insert(parts, part)
            end
        end
        local batchSize = math.min(#parts, 8)
        for i = 1, batchSize do
            local part = parts[i]
            if gucciFrame % 3 == 0 then
                RemoteDispatcher:Fire(setOwner, part, rootPart.CFrame)
            elseif gucciFrame % 3 == 1 then
                RemoteDispatcher:Fire(createGrab, part, Vector3.zero, part.Position, false)
            else
                RemoteDispatcher:Fire(destroyGrab, part)
            end
        end
        gucciFrame = gucciFrame + 1
        task.wait(0.08)
    end
    if humanoid then
        humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
        humanoid.Sit = false
    end
    task.wait(0.05)
end
function AntiFeature.startAntiGucciFast()
    local character = LocalPlayer.Character or LocalPlayer.CharacterAdded:Wait()
    local hum = character:WaitForChild("Humanoid")
    local hrp = character:WaitForChild("HumanoidRootPart")
    State.antiGucci.safePosition = hrp.CFrame
    hum.Sit = true
    task.wait(0.02)
    hum.Sit = false
    task.spawn(function()
        local t = tick()
        while tick() - t < 0.8 do
            for _, v in pairs(character:GetChildren()) do
                if v:IsA("BasePart") then v.Velocity = Vector3.new() end
            end
            task.wait(0.01)
        end
    end)
    local Blob = spawnOrGetGucciBlobman(hrp.CFrame, Vector3.new(0, -15.716, 0))
    if not Blob then return end
    local BHead = Blob:WaitForChild("Head", 3)
    local HitBox = Blob:WaitForChild("GrabbableHitbox", 3)
    local Seat = Blob:FindFirstChildWhichIsA("VehicleSeat", true)
    if not BHead or not HitBox or not Seat then return end
        task.spawn(function()
            while BHead and BHead.Parent do
                if HitBox and HitBox.Parent then
                    RemoteDispatcher:Fire(setNetworkOwnerEvent, HitBox, HitBox.CFrame)
                end
                if BHead:FindFirstChild("PartOwner") and BHead.PartOwner.Value == LocalPlayer.Name then
                    break
                end
                task.wait(0.06)
            end
        end)
    local settleT = tick()
    while tick() - settleT < 0.5 do
        if not Seat or not Seat.Parent then return end
        local prevPos = Seat.Position
        task.wait(0.03)
        if not Seat or not Seat.Parent then return end
        if (Seat.Position - prevPos).Magnitude < 0.05 then break end
    end
    hrp.CFrame = Seat.CFrame + Vector3.new(0, 1.5, 0)
    hrp.AssemblyLinearVelocity = Vector3.zero
    hrp.AssemblyAngularVelocity = Vector3.zero
    local autoGucci = true
    task.spawn(function()
        local startTime = tick()
        while autoGucci and tick() - startTime < 0.3 do
            if Blob and Blob.Parent and Seat and Seat.Occupant ~= hum then
                Seat:Sit(hum)
            end
            task.wait(0.01)
            if character and hum then hum:ChangeState(Enum.HumanoidStateType.Jumping) end
        end
        autoGucci = false
    end)
    task.spawn(function()
        while autoGucci do
            RemoteDispatcher:Fire(ragdollRemoteEvent, hrp, 0.05)
            task.wait(0.03)
        end
    end)
    task.wait(0.32)
    autoGucci = false
    hum.Sit = false
    for _, v in pairs(Blob:GetChildren()) do
        if v:IsA("BasePart") then
            v.CanCollide = false
            v.CanTouch = false
            v.CanQuery = false
        end
    end
    hrp.CFrame = State.antiGucci.safePosition
    hrp.AssemblyLinearVelocity = Vector3.zero
    hrp.AssemblyAngularVelocity = Vector3.zero
    local lastChar = character
    local lastOccupant = nil
    State.antiGucci.fastLoop = task.spawn(function()
        while Settings.Anti.AntiGucciBlobmanFast do
            local curChar = LocalPlayer.Character
            if not curChar or not curChar:FindFirstChild("Humanoid") or not curChar:FindFirstChild("HumanoidRootPart") then
                task.wait(0.2)
                continue
            end
            if curChar ~= lastChar then
                lastChar = curChar
                lastOccupant = nil
                local myHRP = nil
                local myHum = nil
                for _ = 1, 20 do
                    task.wait(0.05)
                    myHRP = curChar:FindFirstChild("HumanoidRootPart")
                    myHum = curChar:FindFirstChildOfClass("Humanoid")
                    if myHRP and myHum then break end
                end
                if not myHRP or not myHum then continue end
                if not Settings.Anti.AntiGucciBlobmanFast then continue end
                State.antiGucci.safePosition = myHRP.CFrame
                local oldBlob = Workspace:FindFirstChild(LocalPlayer.Name .. "SpawnedInToys")
                oldBlob = findGucciBlobman(oldBlob)
                local gucciBlob = nil
                local gucciHead = nil
                local gucciHitbox = nil
                local gucciSeat = nil
                if oldBlob then
                    gucciBlob = oldBlob
                    gucciHead = gucciBlob:FindFirstChild("Head")
                    gucciHitbox = gucciBlob:FindFirstChild("GrabbableHitbox")
                    gucciSeat = gucciBlob:FindFirstChildWhichIsA("VehicleSeat", true)
                end
                if not gucciBlob or not gucciHead or not gucciHitbox or not gucciSeat then
                    local newBlob = spawnOrGetGucciBlobman(myHRP.CFrame, Vector3.new(0, -15.716, 0))
                    if not newBlob then continue end
                    gucciBlob = newBlob
                    gucciHead = newBlob:WaitForChild("Head", 3)
                    gucciHitbox = newBlob:WaitForChild("GrabbableHitbox", 3)
                    gucciSeat = newBlob:FindFirstChildWhichIsA("VehicleSeat", true)
                    if not gucciHead or not gucciHitbox or not gucciSeat then continue end
                end
                task.spawn(function()
                    while gucciHead and gucciHead.Parent do
                        if gucciHitbox and gucciHitbox.Parent then
                            RemoteDispatcher:Fire(setNetworkOwnerEvent, gucciHitbox, gucciHitbox.CFrame)
                        end
                        if gucciHead:FindFirstChild("PartOwner") and gucciHead.PartOwner.Value == LocalPlayer.Name then
                            break
                        end
                        task.wait(0.06)
                    end
                end)
                for _, v in pairs(gucciBlob:GetChildren()) do
                    if v:IsA("BasePart") and v.Name ~= "GrabbableHitbox" and v.Name ~= "Head" then
                        pcall(function() RemoteDispatcher:Fire(setNetworkOwnerEvent, v, v.CFrame) end)
                    end
                end
                myHRP.CFrame = gucciSeat.CFrame + Vector3.new(0, 3, 0)
                myHRP.AssemblyLinearVelocity = Vector3.zero
                myHRP.AssemblyAngularVelocity = Vector3.zero
                task.wait(0.1)
                local reAutoGucci = true
                task.spawn(function()
                    local startTime = tick()
                    while reAutoGucci and tick() - startTime < 0.4 do
                        if gucciBlob and gucciBlob.Parent and gucciSeat and gucciSeat.Occupant ~= myHum then
                            gucciSeat:Sit(myHum)
                        end
                        task.wait(0.03)
                        if myHum then myHum:ChangeState(Enum.HumanoidStateType.Jumping) end
                    end
                    reAutoGucci = false
                end)
                task.spawn(function()
                    while reAutoGucci do
                        RemoteDispatcher:Fire(ragdollRemoteEvent, myHRP, 0.095)
                        task.wait(0.06)
                    end
                end)
                task.wait(0.5)
                reAutoGucci = false
                if myHum then myHum.Sit = false end
                for _, v in pairs(gucciBlob:GetChildren()) do
                    if v:IsA("BasePart") then
                        v.CanCollide = false
                        v.CanTouch = false
                        v.CanQuery = false
                    end
                end
                if not Settings.Anti.AntiGucciBlobmanFast then continue end
                myHRP.CFrame = State.antiGucci.safePosition
                myHRP.AssemblyLinearVelocity = Vector3.zero
                myHRP.AssemblyAngularVelocity = Vector3.zero
                continue
            end
            local b = Workspace:FindFirstChild(LocalPlayer.Name .. "SpawnedInToys")
            b = findGucciBlobman(b)
            if not b then
                State.antiGucci.safePosition = myHRP.CFrame
                local newBlob = spawnOrGetGucciBlobman(myHRP.CFrame, Vector3.new(0, -15.716, 0))
                if not newBlob then task.wait(0.3) continue end
                b = newBlob
                task.wait(0.1)
                continue
            end
            local s = b:FindFirstChildWhichIsA("VehicleSeat", true)
            local sOccupantChanged = s and s:GetPropertyChangedSignal("Occupant")
            local hitbox = b:FindFirstChild("GrabbableHitbox")
            local head = b:FindFirstChild("Head")
            if not s or not hitbox or not head then
                task.wait(0.1)
                continue
            end
            local myHum = curChar:FindFirstChildOfClass("Humanoid")
            local myHRP = curChar:FindFirstChild("HumanoidRootPart")
            if not myHum or not myHRP then
                task.wait(0.05)
                continue
            end
            local occupant = s.Occupant
            local isOccupiedByOther = occupant and occupant ~= myHum
            local partOwner = head:FindFirstChild("PartOwner")
            local isOwnedByMe = partOwner and partOwner.Value == LocalPlayer.Name
            local someoneLeft = lastOccupant and lastOccupant ~= myHum and (not occupant or occupant == myHum)
            lastOccupant = occupant
            local needsGucci = isOccupiedByOther or (not isOwnedByMe) or someoneLeft
            if needsGucci then
                -- Immediately wait for the seat to become free if someone is currently on it
                if s.Occupant and s.Occupant ~= myHum then
                    while s and s.Parent and s.Occupant and s.Occupant ~= myHum do
                        if not Settings.Anti.AntiGucciBlobmanFast then return end
                        sOccupantChanged:Wait()
                    end
                end
                if not Settings.Anti.AntiGucciBlobmanFast then return end
                if not s or not s.Parent then continue end

                -- Instant reclaim & network ownership claim
                task.spawn(function()
                    for _, prt in pairs(b:GetChildren()) do
                        if prt:IsA("BasePart") then
                            pcall(function() RemoteDispatcher:Fire(setNetworkOwnerEvent, prt, prt.CFrame) end)
                        end
                    end
                    while head and head.Parent do
                        if hitbox and hitbox.Parent then
                            RemoteDispatcher:Fire(setNetworkOwnerEvent, hitbox, hitbox.CFrame)
                        end
                        if head:FindFirstChild("PartOwner") and head.PartOwner.Value == LocalPlayer.Name then
                            break
                        end
                        task.wait(0.03)
                    end
                end)

                -- Instant teleport onto seat and sit immediately without delays
                myHRP.CFrame = s.CFrame + Vector3.new(0, 1.5, 0)
                myHRP.AssemblyLinearVelocity = Vector3.zero
                myHRP.AssemblyAngularVelocity = Vector3.zero
                s:Sit(myHum)
                pcall(function() RemoteDispatcher:Fire(ragdollRemoteEvent, myHRP, 0.05) end)

                local reAutoGucci = true
                task.spawn(function()
                    local startTime = tick()
                    while reAutoGucci and tick() - startTime < 0.25 do
                        if b and b.Parent and s and s.Parent and s.Occupant ~= myHum then
                            myHRP.CFrame = s.CFrame + Vector3.new(0, 1.5, 0)
                            s:Sit(myHum)
                        end
                        task.wait(0.01)
                        if myHum then myHum:ChangeState(Enum.HumanoidStateType.Jumping) end
                    end
                    reAutoGucci = false
                end)
                task.spawn(function()
                    while reAutoGucci do
                        RemoteDispatcher:Fire(ragdollRemoteEvent, myHRP, 0.05)
                        task.wait(0.03)
                    end
                end)
                task.wait(0.28)
                reAutoGucci = false
                if myHum then myHum.Sit = false end
                for _, v in pairs(b:GetChildren()) do
                    if v:IsA("BasePart") then
                        v.CanCollide = false
                        v.CanTouch = false
                        v.CanQuery = false
                    end
                end
                if not Settings.Anti.AntiGucciBlobmanFast then return end
                if myHRP and State.antiGucci.safePosition then
                    myHRP.CFrame = State.antiGucci.safePosition
                    myHRP.AssemblyLinearVelocity = Vector3.zero
                    myHRP.AssemblyAngularVelocity = Vector3.zero
                end
            end
            task.wait(0.05)
        end
    end)
end
function AntiFeature.stopAntiGucciFast()
    Settings.Anti.AntiGucciBlobmanFast = false
    if State.antiGucci.fastLoop then
        task.cancel(State.antiGucci.fastLoop)
        State.antiGucci.fastLoop = nil
    end
    local character = LocalPlayer.Character
    if character then
        local rootPart = character:FindFirstChild("HumanoidRootPart")
        local humanoid = character:FindFirstChildOfClass("Humanoid")
        if rootPart and State.antiGucci.safePosition then
            rootPart.CFrame = State.antiGucci.safePosition
            rootPart.AssemblyLinearVelocity = Vector3.zero
            rootPart.AssemblyAngularVelocity = Vector3.zero
        end
        if humanoid then humanoid.Sit = false end
    end
end
function AntiFeature.ragdoll()
