mainNotifySec:Toggle({
    Text = "Kick Notify",
    Flag = "KickNotify",
    Default = false,
    Callback = function(v)
        if State.kickNotifyConn then State.kickNotifyConn:Disconnect() State.kickNotifyConn = nil end
        if not State.kickNotifyCache then State.kickNotifyCache = {} end
        if not State.kickNotifyCd then State.kickNotifyCd = {} end
        if v then
            local function getClosestPlayer(pos)
                local best, bestDist = nil, math.huge
                for _, plr in ipairs(Players:GetPlayers()) do
                    if plr ~= LocalPlayer and plr.Character then
                        local part = plr.Character:FindFirstChild("HumanoidRootPart") or plr.Character:FindFirstChild("Head") or plr.Character:FindFirstChildWhichIsA("BasePart")
                        if part then
                            local d = (part.Position - pos).Magnitude
                            if d < bestDist then bestDist = d best = plr end
                        end
                    end
                end
                return best
            end
            local function playKickSound()
                local s = Instance.new("Sound")
                s.SoundId = "rbxassetid://86966498494980"
                s.Volume = 2.5 * 0.55
                s.PlayOnRemove = true
                s.Parent = game:GetService("SoundService")
                s:Destroy()
            end
            local function notifyKick(displayName, username)
                library:Notify({
                    Title = "EndorisFTAP Reborn",
                    Description = displayName .. " (" .. username .. ") has been kicked",
                    Time = 6,
                })
            end
            State.kickNotifyConn = Workspace.ChildAdded:Connect(function(obj)
                if obj.Name ~= "BlackHoleKick" and obj.Name ~= "BlackHoleDetected" then return end
                local pos
                pcall(function()
                    if obj:IsA("BasePart") then
                        pos = obj.Position
                    elseif obj:IsA("Model") then
                        local pp = obj.PrimaryPart
                        pos = pp and pp.Position or obj:GetPivot().Position
                    elseif obj:IsA("Attachment") then
                        pos = obj.WorldPosition
                    end
                end)
                if not pos then
                    task.wait(0.05)
                    pcall(function()
                        if obj:IsA("BasePart") then
                            pos = obj.Position
                        elseif obj:IsA("Model") then
                            local pp = obj.PrimaryPart
                            pos = pp and pp.Position or obj:GetPivot().Position
                        end
                    end)
                end
                if not pos then return end
                local closestPart, plr = GlobalPCLDTracker.findClosestPCLD(pos, 50)
                if not plr then
                    plr = getClosestPlayer(pos)
                end
                if not plr then return end
                if State.kickNotifyCd[plr.Name] and os.clock() - State.kickNotifyCd[plr.Name] < 10 then return end
                State.kickNotifyCd[plr.Name] = os.clock()
                playKickSound()
                notifyKick(plr.DisplayName, plr.Name)
            end)
        end
    end
})
