        if State.friendJoinConn then State.friendJoinConn:Disconnect() State.friendJoinConn = nil end
        State.friendJoinEnabled = v
        if not v then return end
        local function isFriend(plr)
            if not plr or not plr.UserId or plr.UserId <= 0 then return false end
            local ok, res = pcall(function() return LocalPlayer:IsFriendsWith(plr.UserId) end)
            if ok and res then return true end
            ok, res = pcall(function() return plr:IsFriendsWith(LocalPlayer.UserId) end)
            return ok and res or false
        end
        local function playFriendSound() end
        State.friendJoinConn = Players.PlayerAdded:Connect(function(plr)
            task.wait(1)
            if not State.friendJoinEnabled then return end
            if not isFriend(plr) then return end
            library:Notify({Title = "EndorisFTAP Reborn", Description = "Friend in server: " .. plr.DisplayName .. " (" .. plr.Name .. ")", Time = 4})
            playFriendSound()
        end)
    end
})
end)()
