local runningPlotAntiKick = false
local startPlotShuriken = nil
antiKickSec:Dropdown({
    Text = "Shuriken Mode",
    Flag = "ShurikenMode",
    List = {
        "Default",
        "Plot"
    },
    Default = "Default",
