antiKickSec:Toggle({Text = "Shuriken Anti Kick", Flag = "ShurikenAntiKick", Default = false, Callback = function(v)
    Settings.Anti.ShurikenAntiKick = v
    if Settings.Anti.ShurikenMode == "Plot" then
        Settings.Anti.NewPlotAntiKick = v
        if v then
            if startPlotShuriken then startPlotShuriken() end
        else
            runningPlotAntiKick = false
            State.currentPlotShuriken = nil
        end
        return
    end
    if v then
        task.spawn(function()
            local plr = LocalPlayer
            local RS = ReplicatedStorage
            local setOwner = RS:WaitForChild("GrabEvents"):WaitForChild("SetNetworkOwner")
            local createGL = RS:WaitForChild("GrabEvents"):WaitForChild("CreateGrabLine")
            local destroyGL = RS:WaitForChild("GrabEvents"):WaitForChild("DestroyGrabLine")
            local stickyEvent = RS:WaitForChild("PlayerEvents"):WaitForChild("StickyPartEvent")
            local spawnRemote = RS.MenuToys.SpawnToyRemoteFunction
            local destroyrem = RS:WaitForChild("MenuToys"):WaitForChild("DestroyToy")
            local canSpawn = plr:WaitForChild("CanSpawnToy")
            local function getHRP()
                if Utility.isLocalAlive() then
                    local char = LocalPlayer.Character
                    return char and char:FindFirstChild("HumanoidRootPart")
                end
                return nil
            end
            local function ClearKunai()
                local inv = Workspace:FindFirstChild(plr.Name.."SpawnedInToys")
                if inv and destroyrem then
                    for _, v in pairs(inv:GetChildren()) do
                        if v.Name == "AntiKick" or v.Name == "NinjaShuriken" then
                            pcall(function() RemoteDispatcher:Fire(destroyrem, v) end)
                        end
                    end
                end
            end
            local function CheckForHome()
                if not workspace.PlotItems.PlayersInPlots:FindFirstChild(plr.Name) then
                    return false
                end
                for _, v in pairs(workspace.Plots:GetChildren()) do
                    local sign = v:FindFirstChild("PlotSign")
                    local owners = sign and sign:FindFirstChild("ThisPlotsOwners")
                    if owners then
                        for _, b in pairs(owners:GetChildren()) do
                            if b.Value == plr.Name then
                                local folder = workspace.PlotItems:FindFirstChild(v.Name)
                                if folder then return true, folder end
                            end
                        end
                    end
                end
                return false
            end
            local function findExistingKunai()
                local inv = Workspace:FindFirstChild(plr.Name.."SpawnedInToys")
                local boolik, house = CheckForHome()
                local locs = {}
                if inv then locs[#locs+1] = inv end
                if boolik and house then locs[#locs+1] = house end
                for _, loc in ipairs(locs) do
                    local k = loc:FindFirstChild("AntiKick") or loc:FindFirstChild("NinjaShuriken")
                    if k then return k end
                    for _, child in ipairs(loc:GetChildren()) do
                        if child:IsA("Model") and child:FindFirstChild("StickyPart") then
                            child.Name = "AntiKick"
                            return child
                        end
                    end
                end
                return nil
            end
            local function StickKunai(kunai)
                if not kunai or not kunai:FindFirstChild("StickyPart") then return false end
                if not Utility.isLocalAlive() then return false end
                local currentHRP = getHRP()
                if not currentHRP then return false end
                if kunai:FindFirstChild("SoundPart") then
                    if not kunai.SoundPart:FindFirstChild("PartOwner") or kunai.SoundPart.PartOwner.Value ~= plr.Name then
                        pcall(function() RemoteDispatcher:Fire(setOwner, kunai.SoundPart, kunai.SoundPart.CFrame) end)
                    end
                end
                local sp = kunai.StickyPart
                if sp:FindFirstChild("StickyWeld") and sp.StickyWeld.Part1 then
                    return true
                end
                pcall(function() RemoteDispatcher:Fire(setOwner, sp, sp.CFrame) end)
                pcall(function() RemoteDispatcher:Fire(createGL, sp, Vector3.zero, sp.Position, false) end)
                pcall(function() RemoteDispatcher:Fire(destroyGL, sp) end)
                pcall(function() RemoteDispatcher:Fire(setOwner, sp, sp.CFrame) end)
                local firePart = currentHRP:FindFirstChild("FirePlayerPart") or currentHRP:WaitForChild("FirePlayerPart", 5)
                if firePart then
                    if Settings.Anti.UnsafeShuriken then
                        pcall(function() RemoteDispatcher:Fire(stickyEvent, sp, firePart, CFrame.new(0,0,0)) end)
                    else
                        pcall(function() RemoteDispatcher:Fire(stickyEvent, sp, firePart, CFrame.new(0,0,0) * CFrame.Angles(0, math.rad(90), math.rad(90))) end)
                    end
                    return true
                end
                return false
            end
            local function SpawnToy(name)
                local t = tick()
                while not canSpawn.Value do
                    if not Settings.Anti.ShurikenAntiKick or State.isRespawning or tick() - t > 5 then return nil end
                    task.wait(0.1)
                end
                local currentHRP = getHRP()
                if not currentHRP then return nil end
                local cf = currentHRP.CFrame * CFrame.new(Settings.Anti.UnsafeShuriken and 0 or 0, Settings.Anti.UnsafeShuriken and -0.5 or -1, Settings.Anti.UnsafeShuriken and 20 or 15)
                pcall(function() RemoteDispatcher:Invoke(spawnRemote, name, cf, Vector3.new(0,0,0)) end)
                local boolik, house = CheckForHome()
                local t2 = tick()
                while tick() - t2 < 4 do
                    if not Settings.Anti.ShurikenAntiKick or State.isRespawning then return nil end
                    local inv = Workspace:FindFirstChild(plr.Name.."SpawnedInToys")
                    local locs = {}
                    if inv then locs[#locs+1] = inv end
                    if boolik and house then locs[#locs+1] = house end
                    for _, loc in ipairs(locs) do
                        local k = loc:FindFirstChild("AntiKick") or loc:FindFirstChild(name) or loc:FindFirstChild("NinjaShuriken")
                        if k then
                            k.Name = "AntiKick"
                            return k
                        end
                    end
                    task.wait(0.1)
                end
                return nil
            end
            local lastSpawnT = 0
            local wasRespawning = false
            while Settings.Anti.ShurikenAntiKick do
                task.wait(0.05)
                if not Utility.isLocalAlive() then
                    wasRespawning = true
                    task.wait(0.2)
                    continue
                end
                if wasRespawning then
                    wasRespawning = false
                    lastSpawnT = 0
                    ClearKunai()
                end
                if not plr.Character or not plr.Character:FindFirstChild("Humanoid") or plr.Character.Humanoid.Health <= 0 then continue end
                local myHRP = getHRP()
                if not myHRP then continue end
                local kunai = findExistingKunai()
                local boolik, house = CheckForHome()
                if boolik and house and workspace.Plots:FindFirstChild(house.Name) then
                    local sign = workspace.Plots[house.Name]:FindFirstChild("PlotSign")
                    if sign and sign.ThisPlotsOwners.Value.TimeRemainingNum.Value > 89 and not kunai and tick() - lastSpawnT > 1 then
                        lastSpawnT = tick()
                        kunai = SpawnToy("NinjaShuriken")
                        if kunai == nil then continue end
                        kunai.Name = "AntiKick"
                        StickKunai(kunai)
                    end
                end
                if not kunai or not kunai.Parent then
                    if workspace.PlotItems.PlayersInPlots:FindFirstChild(plr.Name) then continue end
                    if tick() - lastSpawnT <= 0.8 then continue end
                    lastSpawnT = tick()
                    kunai = SpawnToy("NinjaShuriken")
                    if kunai == nil or not kunai.Parent then kunai = nil continue end
                    kunai.Name = "AntiKick"
                    StickKunai(kunai)
                    if not kunai or not kunai.Parent then kunai = nil continue end
                end
                local firePart = myHRP:FindFirstChild("FirePlayerPart") or myHRP:WaitForChild("FirePlayerPart", 5)
                if not firePart then continue end
                local sp = kunai and kunai.Parent and kunai:FindFirstChild("StickyPart")
                if not sp then ClearKunai() kunai = nil continue end
                local distToKunai = (myHRP.Position - sp.Position).Magnitude
                if distToKunai > 22 then
                    ClearKunai()
                    kunai = nil
                    continue
                end
                if Settings.Anti.UnsafeShuriken then
                    pcall(function() RemoteDispatcher:Fire(setOwner, sp, sp.CFrame) end)
                    pcall(function() RemoteDispatcher:Fire(stickyEvent, sp, firePart, CFrame.new(0,0,0)) end)
                else
                    local isStuck = sp:FindFirstChild("StickyWeld") and sp.StickyWeld.Part1 and true or false
                    if not isStuck then
                        local attemptStart = tick()
                        while tick() - attemptStart < 2.5 do
                            if not Settings.Anti.ShurikenAntiKick or State.isRespawning then break end
                            if not kunai or not kunai.Parent then kunai = nil break end
                            sp = kunai:FindFirstChild("StickyPart")
                            if not sp then kunai = nil break end
                            if sp:FindFirstChild("StickyWeld") and sp.StickyWeld.Part1 then isStuck = true break end
                            StickKunai(kunai)
                            task.wait(0.15)
                        end
                    end
                    if isStuck then
                        for _, obj in pairs(kunai:GetChildren()) do
                            if obj:IsA("BasePart") then
                                obj.CanTouch = false; obj.CanCollide = false; obj.CanQuery = false
                            end
                        end
                    end
                end
                if not kunai:FindFirstChild("Highlight") then
                    local high = Instance.new("Highlight", kunai)
                    high.FillColor = Color3.fromRGB(50, 50, 50)
                    high.OutlineColor = Color3.fromRGB(100, 100, 100)
                    high.Adornee = kunai
                end
                kunai.Name = "AntiKick"
            end
            ClearKunai()
        end)
    else
        local function ClearKunai()
            local plr = LocalPlayer
            local inv = Workspace:FindFirstChild(plr.Name.."SpawnedInToys")
            local destroyrem = ReplicatedStorage:WaitForChild("MenuToys"):WaitForChild("DestroyToy")
            if inv and destroyrem then
                for _, v in pairs(inv:GetChildren()) do
                    if v.Name == "AntiKick" or v.Name == "NinjaShuriken" then
                        pcall(function() RemoteDispatcher:Fire(destroyrem, v) end)
                    end
                end
            end
        end
        ClearKunai()
    end
end})
antiKickSec:Toggle({Text = "Unsafe Shuriken", Flag = "UnsafeShuriken", Default = false, Callback = function(v)
    if v and Settings.Anti.ShurikenMode ~= "Default" then return end
    Settings.Anti.UnsafeShuriken = v
