                local attachCFrame = CFrame.new(0.0490287527, 0.5, 0, 0, 0.00739139877, -0.999561906, -0.998452604, -0.0478846952, 0.0282763243, -0.0476547107, 0.99882561, 0)
                pcall(function() RemoteDispatcher:Fire(StickyPartEvent, sticky, leg, attachCFrame) end)
                task.wait(0.2)
                local weld2 = sticky:FindFirstChild("StickyWeld")
                if weld2 and weld2.Part1 == leg then
                    failCount = 0
