do
    local AntiKickItemActive = false
    local MyPCLD = nil
    local pcldConn = nil
    local pcldListConn = nil
    local pcldDescConn = nil
    local LoopSetOwnActive = false
    local loopSetOwnConn = nil
    local function deleteItem()
        pcall(function()
            local inv = workspace:FindFirstChild(LocalPlayer.Name.."SpawnedInToys")
            local destroyToy = DeleteToyRE
            if inv and destroyToy then
                for _, v in pairs(inv:GetChildren()) do
                    if v.Name == "AntiKickItem" then
                        destroyToy:FireServer(v)
                    end
                end
            end
        end)
    end
    local function setupLoopSetOwn()
        if loopSetOwnConn then return end
        loopSetOwnConn = RunService.Heartbeat:Connect(function()
            if not LoopSetOwnActive then return end
            if not Utility.isLocalAlive() then return end
            pcall(function()
                local char = LocalPlayer.Character
                local hrp = char and char:FindFirstChild("HumanoidRootPart")
                local inv = workspace:FindFirstChild(LocalPlayer.Name.."SpawnedInToys")
                if not hrp or not inv then return end
                local Item = inv:FindFirstChild("AntiKickItem")
                if not Item then return end
                local SoundPart = Item:FindFirstChild("Hitbox")
                if not SoundPart then return end
                if (SoundPart.Position - hrp.Position).Magnitude <= 22 then
                    sno(SoundPart)
                end
            end)
        end)
    end
    setupLoopSetOwn()
    local ToyList = {
        ["Japanese Lantern"] = "JapaneseLantern",
        ["Spray Can"]        = "SprayCanWD",
        ["Spooky Candle"]    = "SpookyCandle1",
    }
    local DropdownValues = {}
    for shortName, _ in pairs(ToyList) do
        table.insert(DropdownValues, shortName)
    end
    table.sort(DropdownValues)
    local SelectedToy = ToyList["Spooky Candle"] or ToyList[DropdownValues[1]]
    antiKickSec:Dropdown({Text = "anti kick item", Flag = "AntiKickItemType", Default = "Spooky Candle", List = DropdownValues, Callback = function(Value)
        SelectedToy = ToyList[Value]
    end})
    local function GetMagnitude(Part1, Part2)
        return (Part1.Position - Part2.Position).Magnitude
    end
    local function FWD(parent, part, timeOffset)
        return parent:FindFirstChild(part) or parent:WaitForChild(part, timeOffset or 1)
    end
    local function CheckNetworkOwnerOnPart(Part)
        local po = Part:FindFirstChild("PartOwner")
        return po and po.Value == LocalPlayer.Name
    end
    local function sno(part)
        pcall(function()
            setNetworkOwnerEvent:FireServer(part, part.CFrame)
        end)
    end
    local function CheckForHome()
        local plotItems = workspace:FindFirstChild("PlotItems")
        local plots = workspace:FindFirstChild("Plots")
        if plots and plotItems then
            for i = 1, 5 do
                local Plot = plots:FindFirstChild("Plot"..i)
                if Plot then
                    local sign = Plot:FindFirstChild("PlotSign")
                    local owners = sign and sign:FindFirstChild("ThisPlotsOwners")
                    if owners then
                        for _, v in pairs(owners:GetChildren()) do
                            if v.Value == LocalPlayer.Name then
                                return plotItems:FindFirstChild("Plot"..i)
                            end
                        end
                    end
                end
            end
        end
        return nil
    end
    local function SpawnToy(ToyName)
        local InPlot = LocalPlayer:FindFirstChild("InPlot")
        local InOwnedPlot = LocalPlayer:FindFirstChild("InOwnedPlot")
        local CanSpawnToy = LocalPlayer:FindFirstChild("CanSpawnToy")
        local inv = workspace:FindFirstChild(LocalPlayer.Name.."SpawnedInToys")
        if InPlot and InPlot.Value and InOwnedPlot and not InOwnedPlot.Value then
            InPlot:GetPropertyChangedSignal("Value"):Wait()
        end
        if CanSpawnToy and not CanSpawnToy.Value then
            CanSpawnToy:GetPropertyChangedSignal("Value"):Wait()
        end
        local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
        if not hrp then return nil end
        local SpawnCF = hrp.CFrame * CFrame.new(0, 14, 20)
        local Container = (InOwnedPlot and InOwnedPlot.Value) and CheckForHome() or inv
        if not Container then return nil end
        local spawnedObject = nil
        local connection
        connection = Container.ChildAdded:Connect(function(child)
            if child.Name == ToyName then
                spawnedObject = child
            end
        end)
        task.spawn(function()
            pcall(function()
                SpawnToyRF:InvokeServer(ToyName, SpawnCF, Vector3.zero)
            end)
        end)
        local start = tick()
        repeat task.wait() until spawnedObject or (tick() - start) > 2.5
        if connection then connection:Disconnect() end
        return spawnedObject
    end
    local function ensurePCLDTracker()
        if pcldConn then return end
        MyPCLD = nil
        local pcldSet = {}
        local myHistory = {}
        local RECORD_INTERVAL = 50 / 1000
        local MATCH_DISTANCE = 2.0
        local MATCH_ANGLE = 0.35
        local MIN_COUNT = 3
        local MAX_HISTORY = 600
        local lastRecordT = 0
        local nextCleanup = 20 + math.random() * 5
        local function rebuild()
            for k in pairs(pcldSet) do pcldSet[k] = nil end
            for _, v in pairs(workspace:GetDescendants()) do
                if v.Name == "PlayerCharacterLocationDetector" and v:IsA("BasePart") and v.Parent then
                    pcldSet[v] = 0
                end
            end
        end
        rebuild()
        pcldListConn = workspace.DescendantAdded:Connect(function(d)
            if d.Name == "PlayerCharacterLocationDetector" and d:IsA("BasePart") and not pcldSet[d] then
                pcldSet[d] = 0
            end
        end)
        pcldDescConn = workspace.DescendantRemoving:Connect(function(d)
            pcldSet[d] = nil
        end)
        local function clearHistory()
            for i = #myHistory, 1, -1 do
                myHistory[i] = nil
            end
        end
        pcldConn = RunService.Heartbeat:Connect(function()
            local char = LocalPlayer.Character
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            local now = tick()
            if hrp and hrp.Parent then
                if now - lastRecordT >= RECORD_INTERVAL then
                    lastRecordT = now
                    local last = myHistory[#myHistory]
                    local skip = false
                    if last then
                        local dPos = (hrp.Position - last.Position)
                        local dLook = (hrp.CFrame.LookVector - last.LookVector)
                        if dPos.Magnitude <= 0.5 and dLook.Magnitude <= 0.05 then
                            skip = true
                        end
                    end
                    if not skip then
                        myHistory[#myHistory + 1] = hrp.CFrame
                        if #myHistory > MAX_HISTORY then
                            table.remove(myHistory, 1)
                        end
                    end
                end
            end
            if now >= nextCleanup then
                nextCleanup = now + 20 + math.random() * 5
                clearHistory()
            end
            if #myHistory == 0 then return end
            local best, bestC = nil, 0
            for v, c in pairs(pcldSet) do
                if v.Parent and v:IsA("BasePart") then
                    local vcf = v.CFrame
                    local vpos = vcf.Position
                    local vlook = vcf.LookVector
                    local matched = false
                    for i = 1, #myHistory do
                        local hp = myHistory[i].Position
                        local dx = vpos.X - hp.X
                        local dy = vpos.Y - hp.Y
                        local dz = vpos.Z - hp.Z
                        if dx*dx + dy*dy + dz*dz <= MATCH_DISTANCE*MATCH_DISTANCE
                        and (vlook - myHistory[i].LookVector).Magnitude <= MATCH_ANGLE then
                            matched = true
                            break
                        end
                    end
                    if matched then
                        c = c + 1
                    else
                        c = c - 1
                    end
                    if c < 0 then c = 0 end
                    pcldSet[v] = c
                    if c > bestC then bestC = c best = v end
                else
                    pcldSet[v] = nil
                end
            end
            if best and bestC >= MIN_COUNT then
                MyPCLD = best
            end
        end)
    end
    ensurePCLDTracker()
