    do
        local pencilAntiKickActive = false
        local pencilAntiKickTask = nil
        local pencilRespawnConnection = nil
        local function spawnPencil()
            local spawnFolder = workspace:FindFirstChild(LocalPlayer.Name .. "SpawnedInToys")
            if not spawnFolder then return nil end
            local pencil = spawnFolder:FindFirstChild("ToolPencil")
            if pencil then return pencil end
            if LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart") then
                local hrp = LocalPlayer.Character.HumanoidRootPart
                local cf = hrp.CFrame * CFrame.new(0, -1, 10)
                pcall(function() RemoteDispatcher:Invoke(SpawnToyRF, "ToolPencil", cf, Vector3.new(0,0,0)) end)
                local t = tick()
                while tick() - t < 4 do
                    pencil = spawnFolder:FindFirstChild("ToolPencil")
                    if pencil then return pencil end
                    task.wait(0.1)
                end
            end
            return nil
        end
        local function fixPencil()
            if not Utility.isLocalAlive() then return end
            pcall(function()
                local spawnFolder = workspace:FindFirstChild(LocalPlayer.Name .. "SpawnedInToys")
                if not spawnFolder then return end
                local pencil = spawnFolder:FindFirstChild("ToolPencil")
                if not pencil then
                    pencil = spawnPencil()
                    if not pencil then return end
                end
                local char = LocalPlayer.Character
                if not char or not Utility.isLocalAlive() then return end
                local root = char:FindFirstChild("HumanoidRootPart")
                if not root then return end
                local stickyPart = pencil:FindFirstChild("StickyPart")
                local soundPart = pencil:FindFirstChild("SoundPart")
                if not stickyPart or not soundPart then return end
                if not soundPart:FindFirstChild("PartOwner") or soundPart.PartOwner.Value ~= LocalPlayer.Name then
                    pcall(function() RemoteDispatcher:Fire(setNetworkOwnerEvent, soundPart, soundPart.CFrame) end)
                end
                local firePart = root:FindFirstChild("FirePlayerPart") or root
                if not firePart then return end
                if stickyPart:FindFirstChild("StickyWeld") and stickyPart.StickyWeld.Part1 then
                    return
                end
                pcall(function() RemoteDispatcher:Fire(setNetworkOwnerEvent, stickyPart, stickyPart.CFrame) end)
                pcall(function() RemoteDispatcher:Fire(createGrabLineEvent, stickyPart, Vector3.zero, stickyPart.Position, false) end)
                pcall(function() RemoteDispatcher:Fire(destroyGrabLineEvent, stickyPart) end)
                pcall(function() RemoteDispatcher:Fire(setNetworkOwnerEvent, stickyPart, stickyPart.CFrame) end)
                pcall(function()
                    RemoteDispatcher:Fire(StickyPartEvent, stickyPart, firePart, CFrame.new(0, -0.85, 0) * CFrame.Angles(0, math.rad(180), 0))
                end)
                for _, prt in pairs(pencil:GetChildren()) do
                    if prt:IsA("BasePart") then
                        prt.CanQuery = false
                        prt.CanCollide = false
                        prt.CanTouch = false
                    end
                end
            end)
        end
        antiKickSec:Toggle({Text = "Anti Kick (Pencil)", Flag = "AntiKickPencil", Default = false, Callback = function(Value)
            Settings.Anti.AntiKickPencil = Value
            pencilAntiKickActive = Value
            if Value then
                if pencilRespawnConnection then pencilRespawnConnection:Disconnect() end
                pencilRespawnConnection = LocalPlayer.CharacterAdded:Connect(function()
                    task.wait(0.8)
                    if pencilAntiKickActive and Utility.isLocalAlive() then
                        fixPencil()
                    end
                end)
                pencilAntiKickTask = task.spawn(function()
                    while pencilAntiKickActive do
                        task.wait(0.05)
                        if Utility.isLocalAlive() then
                            fixPencil()
                        end
                    end
                end)
            else
                pencilAntiKickActive = false
                if pencilAntiKickTask then
                    task.cancel(pencilAntiKickTask)
                    pencilAntiKickTask = nil
                end
                if pencilRespawnConnection then
                    pencilRespawnConnection:Disconnect()
                    pencilRespawnConnection = nil
                end
                local spawnFolder = workspace:FindFirstChild(LocalPlayer.Name .. "SpawnedInToys")
                if spawnFolder then
                    local pencil = spawnFolder:FindFirstChild("ToolPencil")
                    if pencil then
                        pcall(function()
                            DeleteToyRE:FireServer(pencil)
                        end)
                    end
                end
            end
        end})
    end
end
local antiSetownKick = false
local antiSetownLastSafePosition = nil
local antiSetownTeleportDetected = false
local antiSetownPositionHistory = {}
local antiSetownMaxHistory = 10
local antiSetownHeldSpamDetected = false
local antiSetownHeldChangeTimes = {}
local antiSetownHeldSpamThreshold = 8
local antiSetownLastHeldValue = false
local antiSetownStruggling = false
local antiSetownLastStruggleTime = 0
local antiSetownStruggleCooldown = 0.5
    antiKickSec:Toggle({Text = "Anti Setown Kick", Flag = "AntiSetownKick", Default = false, Callback = function(Value)
    Settings.Anti.AntiSetownKick = Value
    antiSetownKick = Value
    if Value then
        task.spawn(function()
            local player = LocalPlayer
            local struggleRemote = ReplicatedStorage:WaitForChild("CharacterEvents"):WaitForChild("Struggle")
            local tpland = {
                Spawn = Vector3.new(0, -7.35, 0),
                SpawnCave = Vector3.new(-90, 14.6, -314.3),
                GreenHouse = Vector3.new(-538, -7, 74),
                PinkHouse = Vector3.new(-478, -7, -147),
                Barn = Vector3.new(-228, 82, -318),
                BlueHouse = Vector3.new(496, 83, -350),
                ChineseHouse = Vector3.new(542, 123, -93),
                PurpleHouse = Vector3.new(270, -7, 448),
                Factory = Vector3.new(134, 347, 352),
                OtherGreenHouse = Vector3.new(-359, 98, 357),
                BigCave = Vector3.new(-245, 80, 485),
                GoodPrison = Vector3.new(569.6, -7, 176.3),
                RuhubsDogAhhPrison = Vector3.new(564, 82.5, 210),
                ExtremelyGoodPrison = Vector3.new(525, 76, 56),
                TrainCave = Vector3.new(536.6, 87.5, -169.5),
                IslanCave = Vector3.new(75.8, 323, 368.5),
                ChineseRoof = Vector3.new(592, 153, -100),
                UfoCave = Vector3.new(29.6, 10.5, -225.8),
                Prison = Vector3.new(195, -7, -561),
                BlueHouseSlot = Vector3.new(562.2, 85.38, -212.56),
                SpawnSlot = Vector3.new(51.75, -5.3, -121.64),
                HauntedSlot = Vector3.new(164.57, -5.43, 530.97),
                RandomSlot = Vector3.new(-211.65, 85.7, 426.72),
                BeachSlot = Vector3.new(-546.97, -5.3, -41.09)
            }
            local SL = tpland["Spawn"]
            if player.Character and player.Character:FindFirstChild("HumanoidRootPart") then
                antiSetownLastSafePosition = player.Character.HumanoidRootPart.Position
                for i = 1, antiSetownMaxHistory do
                    table.insert(antiSetownPositionHistory, antiSetownLastSafePosition)
                end
            end
            if player:FindFirstChild("IsHeld") then
                antiSetownLastHeldValue = player.IsHeld.Value
            end
            while antiSetownKick and task.wait(0.05) do
                if not Utility.isLocalAlive() then
                    antiSetownLastSafePosition = nil
                    antiSetownPositionHistory = {}
                    antiSetownHeldSpamDetected = false
                    antiSetownTeleportDetected = false
                    continue
                end
                local char = player.Character
                if not char then
                    continue
                end
                local hrp = char:FindFirstChild("HumanoidRootPart")
                if not hrp then
                    continue
                end
                local currentPos = hrp.Position
                if not antiSetownLastSafePosition then
                    antiSetownLastSafePosition = currentPos
                    antiSetownPositionHistory = {currentPos}
                    continue
                end
                local currentTime = tick()
                local isHeld = false
                if player:FindFirstChild("IsHeld") then
                    isHeld = player.IsHeld.Value
                    if isHeld ~= antiSetownLastHeldValue then
                        table.insert(antiSetownHeldChangeTimes, currentTime)
                        antiSetownLastHeldValue = isHeld
                        for i = #antiSetownHeldChangeTimes, 1, -1 do
                            if currentTime - antiSetownHeldChangeTimes[i] > 2 then
                                table.remove(antiSetownHeldChangeTimes, i)
                            end
                        end
                        if #antiSetownHeldChangeTimes >= antiSetownHeldSpamThreshold then
                            antiSetownHeldSpamDetected = true
                        end
                    end
                end
                if isHeld and not antiSetownStruggling and (currentTime - antiSetownLastStruggleTime > antiSetownStruggleCooldown) then
                    antiSetownStruggling = true
                    antiSetownLastStruggleTime = currentTime
                    task.spawn(function()
                        for i = 1, 5 do
                            pcall(function()
                                RemoteDispatcher:Fire(struggleRemote, player)
                            end)
                            task.wait(0.05)
                        end
                        antiSetownStruggling = false
                    end)
                end
                table.insert(antiSetownPositionHistory, 1, currentPos)
                if #antiSetownPositionHistory > antiSetownMaxHistory then
                    table.remove(antiSetownPositionHistory, antiSetownMaxHistory + 1)
                end
                local avgDistance = 0
                if #antiSetownPositionHistory >= 2 then
                    for i = 2, #antiSetownPositionHistory do
                        avgDistance = avgDistance + (antiSetownPositionHistory[i - 1] - antiSetownPositionHistory[i]).Magnitude
                    end
                    avgDistance = avgDistance / (#antiSetownPositionHistory - 1)
                end
                local velocity = hrp.AssemblyLinearVelocity.Magnitude
                local movedDistance = (currentPos - antiSetownLastSafePosition).Magnitude
                local abnormalTeleport = false
                if antiSetownHeldSpamDetected then
                    abnormalTeleport = true
                elseif currentPos.Magnitude > 1000000 then
                    abnormalTeleport = true
                    antiSetownTeleportDetected = true
                elseif movedDistance > 100 and velocity < 50 and avgDistance < 10 then
                    abnormalTeleport = true
                    antiSetownTeleportDetected = true
                elseif currentPos.Y > 10000 or currentPos.Y < -1000 then
                    abnormalTeleport = true
                    antiSetownTeleportDetected = true
                elseif velocity > 500 then
                    abnormalTeleport = true
                    antiSetownTeleportDetected = true
                end
                if abnormalTeleport then
                    antiSetownHeldSpamDetected = false
                    antiSetownHeldChangeTimes = {}
                    hrp.AssemblyLinearVelocity = Vector3.zero
                    hrp.AssemblyAngularVelocity = Vector3.zero
                    for i = 1, 3 do
                        pcall(function()
                            RemoteDispatcher:Fire(struggleRemote, player)
                        end)
                        task.wait(0.05)
                    end
                    local teleported = false
                    if SL ~= 'off' and SL then
                        hrp.CFrame = CFrame.new(SL)
                        teleported = true
                    else
                        local plots = Workspace:FindFirstChild("Plots")
                        local foundSafe = false
                        if plots then
                            for i = 1, 5 do
                                local plot = plots:FindFirstChild("Plot" .. i)
                                if plot then
                                    local sign = plot:FindFirstChild("PlotSign")
                                    local ownersFolder = sign and sign:FindFirstChild("ThisPlotsOwners")
                                    local valueObj = ownersFolder and ownersFolder:FindFirstChild("Value")
                                    if valueObj and valueObj.Value == player.Name then
                                        local grabPart = plot:FindFirstChild("PlusGrabPart", true)
                                        if grabPart then
                                            hrp.CFrame = grabPart.CFrame
                                            foundSafe = true
                                            teleported = true
                                            break
                                        end
                                    end
                                end
                            end
                        end
                        if not foundSafe then
                            hrp.CFrame = CFrame.new(tpland["Spawn"])
                            teleported = true
                        end
                    end
                    if teleported then
                        hrp.AssemblyLinearVelocity = Vector3.zero
                        hrp.AssemblyAngularVelocity = Vector3.zero
                        if char:FindFirstChild("Humanoid") then
                            char.Humanoid.PlatformStand = false
                            char.Humanoid.Sit = false
                        end
                        task.wait(0.2)
                        antiSetownTeleportDetected = false
                        antiSetownLastSafePosition = hrp.Position
                        antiSetownPositionHistory = {}
                        for i = 1, antiSetownMaxHistory do
                            table.insert(antiSetownPositionHistory, antiSetownLastSafePosition)
                        end
                        task.spawn(function()
                            for i = 1, 5 do
                                pcall(function()
                                    RemoteDispatcher:Fire(struggleRemote, player)
                                end)
                                task.wait(0.1)
                            end
                        end)
                    end
                else
                    if not antiSetownTeleportDetected and movedDistance < 50 then
                        antiSetownLastSafePosition = currentPos
                    end
                end
                antiSetownLastStruggleTime = currentTime
            end
        end)
    else
        antiSetownKick = false
        antiSetownPositionHistory = {}
        antiSetownTeleportDetected = false
        antiSetownHeldSpamDetected = false
        antiSetownHeldChangeTimes = {}
    end
end})
