autoAntiLagEnabled = true
autoAntilagLagger = nil
autoAntilagActive = false
local AUTO_ANTILAG_ON = 200
local AUTO_ANTILAG_OFF = 150
local AUTO_ANTILAG_COOLDOWN = 20
local autoAntilagCurrentFPS = 60
local autoAntilagFpsFrames = 0
local autoAntilagFpsLast = tick()
local autoAntilagFpsHoldUntil = 0
local function refreshAntiLagScript()
    if not anticreatelinelocalscript then return end
    local antiLagActive = Settings.Anti.AntiLag == true
    local autoLagActive = autoAntiLagEnabled == true and autoAntilagActive == true
    anticreatelinelocalscript.Enabled = not (antiLagActive or autoLagActive)
end
RunService.RenderStepped:Connect(function()
    autoAntilagFpsFrames = autoAntilagFpsFrames + 1
    local now = tick()
    if now - autoAntilagFpsLast >= 0.5 then
        autoAntilagCurrentFPS = autoAntilagFpsFrames / (now - autoAntilagFpsLast)
        autoAntilagFpsFrames = 0
        autoAntilagFpsLast = now
    end
end)
local autoAntilagPlayerTimes = {}
local autoAntilagLastSpam = 0
local autoAntilagConns = {}
local autoAntilagLastCheck = 0
local function autoAntilagFindPlayer(obj)
    local cur = obj
    while typeof(cur) == "Instance" do
        if cur:IsA("Player") then return cur end
        cur = cur.Parent
    end
    return nil
end
local function autoAntilagRecord(plr)
    if not autoAntiLagEnabled then return end
    if not plr or plr == LocalPlayer then return end
    local name = plr.Name
    local list = autoAntilagPlayerTimes[name]
    if not list then
        list = {}
        autoAntilagPlayerTimes[name] = list
    end
    list[#list + 1] = tick()
end
local function autoAntilagHookRemote(remote)
    if not remote or not remote:IsA("RemoteEvent") then return end
    local conn = remote.OnClientEvent:Connect(function(...)
        local plr = nil
        for i = 1, math.min(select("#", ...), 4) do
            plr = autoAntilagFindPlayer(select(i, ...))
            if plr then break end
        end
        autoAntilagRecord(plr)
    end)
    table.insert(autoAntilagConns, conn)
end
autoAntilagHookRemote(createGrabLineEvent)
autoAntilagHookRemote(grabEventsFolder:FindFirstChild("ExtendGrabLine"))
autoAntilagHookRemote(destroyGrabLineEvent)
antiMiscSec:Toggle({Text = "Anti Lag", Flag = "AntiLag", Default = true, Callback = function(enabled)
    Settings.Anti.AntiLag = enabled
    autoAntilagActive = false
    refreshAntiLagScript()
    if not enabled then
        local grabParts = Workspace:FindFirstChild("GrabParts")
        if grabParts then
            for _, gp in ipairs(grabParts:GetChildren()) do
                local bp = gp:FindFirstChild("BeamPart")
                if bp then
                    for _, obj in ipairs(bp:GetChildren()) do
                        if obj:IsA("Beam") or obj:IsA("Trail") or obj:IsA("ParticleEmitter") or obj:IsA("PointLight") then
                            pcall(function() obj:Destroy() end)
                        end
                    end
                end
            end
        end
    end
end})
antiMiscSec:Dropdown({Text = "Auto Anti Lag Method", Flag = "AutoAntiLagMethod", List = {"Detect Spam", "Low FPS"}, Default = "Detect Spam", Callback = function(value)
    Settings.Anti.AutoAntiLagMethod = value
    if value ~= "Low FPS" then
        autoAntilagFpsHoldUntil = 0
    end
end})
antiMiscSec:Toggle({Text = "Auto Anti Lag", Flag = "AutoAntiLag", Default = true, Callback = function(v)
    autoAntiLagEnabled = v
    autoAntilagActive = false
    autoAntilagFpsHoldUntil = 0
    refreshAntiLagScript()
    if v then
        task.spawn(function()
            autoAntilagLastCheck = tick()
            while autoAntiLagEnabled and task.wait(0.25) do
                if Settings.Anti.AutoAntiLagMethod == "Low FPS" then
                    local fps = autoAntilagCurrentFPS
                    if fps < 15 then
                        if not autoAntilagActive then
                            autoAntilagActive = true
                            refreshAntiLagScript()
                            pcall(function()
                                library:Notify({
                                    Title = "EndorisFTAP Reborn",
                                    Description = "Your FPS is less than 15, Anti Lag Enabled",
                                    Time = 6.5,
                                })
                            end)
                        end
                        autoAntilagFpsHoldUntil = tick() + 30
                    elseif autoAntilagActive then
                        if autoAntilagFpsHoldUntil == 0 then
                            autoAntilagFpsHoldUntil = tick() + 30
                        elseif tick() >= autoAntilagFpsHoldUntil then
                            autoAntilagActive = false
                            autoAntilagFpsHoldUntil = 0
                            refreshAntiLagScript()
                        end
                    end
                else
                    local now = tick()
                    local dt = math.min(now - autoAntilagLastCheck, 3)
                    autoAntilagLastCheck = now
                    local window = math.max(dt, 1)
                    local worst, worstRate = nil, 0
                    for name, list in pairs(autoAntilagPlayerTimes) do
                        local i = 1
                        while i <= #list do
                            if now - list[i] > window then
                                table.remove(list, i)
                            else
                                i = i + 1
                            end
                        end
                        if #list == 0 then
                            autoAntilagPlayerTimes[name] = nil
                        elseif #list > worstRate then
                            worstRate = #list
                            worst = name
                        end
                    end
                    if autoAntilagActive then
                        if worstRate >= AUTO_ANTILAG_OFF then
                            autoAntilagLastSpam = now
                        elseif now - autoAntilagLastSpam >= AUTO_ANTILAG_COOLDOWN then
                            autoAntilagActive = false
                            autoAntilagLagger = nil
                            refreshAntiLagScript()
                        end
                    elseif worst and worstRate >= AUTO_ANTILAG_ON then
                        autoAntilagActive = true
                        autoAntilagLagger = Players:FindFirstChild(worst)
                        autoAntilagLastSpam = now
                        refreshAntiLagScript()
                        pcall(function()
                            library:Notify({
                                Title = "EndorisFTAP Reborn",
                                Description = ((autoAntilagLagger and autoAntilagLagger.DisplayName) or worst) .. " Lagged Server",
                                Time = 6.5,
                            })
                        end)
                    end
                end
            end
        end)
    else
        autoAntilagPlayerTimes = {}
        autoAntilagLastSpam = 0
        autoAntilagLagger = nil
        autoAntilagFpsHoldUntil = 0
        autoAntilagLastCheck = 0
        refreshAntiLagScript()
    end
end})
