do
    UserInputService.InputBegan:Connect(function(input, gpe)
        if input.UserInputType ~= Enum.UserInputType.Keyboard then return end
        local key = input.KeyCode
        local isL = key == Enum.KeyCode.L
        if not isL then
            local ok, char = pcall(function() return UserInputService:GetStringForKeyCode(key) end)
            if ok and char then isL = string.lower(char) == "Р В Р’В Р вЂ™Р’В Р В РЎС›Р Р†Р вЂљР’В" end
        end
        if not isL then return end
        if UserInputService:IsKeyDown(Enum.KeyCode.LeftAlt)
            and UserInputService:IsKeyDown(Enum.KeyCode.LeftControl)
            and UserInputService:IsKeyDown(Enum.KeyCode.LeftShift) then
            if not Settings.Anti.AntiLag then
                pcall(function()
                    local flag = library.Flags["AntiLag"]
                    if flag and flag.Callback then
                        flag.Callback(true)
                    end
                end)
            end
        end
    end)
end
antiMiscSec:Toggle({Text = "Anti Ragdoll", Flag = "AntiRagdoll", Default = false, Callback = function(v)
    Settings.Anti.AntiRagdoll = v
    if v then
        State.antiRagdollConns = {}
        local function applyProtection(char)
            if not Settings.Anti.AntiRagdoll then return end
            if not char then return end
            if State.antiRagdollConns then
                for _, c in ipairs(State.antiRagdollConns) do pcall(function() c:Disconnect() end) end
            end
            State.antiRagdollConns = {}
            local hum = char:FindFirstChildOfClass("Humanoid") or char:WaitForChild("Humanoid", 5)
            if not hum or hum.Health <= 0 then return end
            hum.BreakJointsOnDeath = false
            hum.AutoRotate = true
            if hum.PlatformStand and not Settings.Misc.fakeDeath and not Settings.Anti.LoopRagdoll then hum.PlatformStand = false end
            table.insert(State.antiRagdollConns, hum:GetPropertyChangedSignal("AutoRotate"):Connect(function()
                if Settings.Anti.AntiRagdoll and Utility.isLocalAlive() and hum.AutoRotate == false and not (type(getgenv) == "function" and getgenv().FTAP_SpinbotActive) then hum.AutoRotate = true end
            end))
            table.insert(State.antiRagdollConns, hum:GetPropertyChangedSignal("PlatformStand"):Connect(function()
                if Settings.Anti.AntiRagdoll and Utility.isLocalAlive() and not Settings.Misc.fakeDeath and not Settings.Anti.LoopRagdoll and hum.PlatformStand == true then hum.PlatformStand = false end
            end))
            table.insert(State.antiRagdollConns, RunService.RenderStepped:Connect(function()
                if Settings.Anti.AntiRagdoll and Utility.isLocalAlive() and hum.Sit and hum.SeatPart == nil then hum.Sit = false end
            end))
            table.insert(State.antiRagdollConns, hum.Died:Connect(function()
                hum.BreakJointsOnDeath = true
                if State.antiRagdollConns then
                    for _, c in ipairs(State.antiRagdollConns) do pcall(function() c:Disconnect() end) end
                    State.antiRagdollConns = {}
                end
            end))
