            if not toy then
                pcall(function()
                    RemoteDispatcher:Invoke(SpawnRemote, selectedToy, hrp.CFrame * CFrame.new(0, 5, 0), Vector3.zero)
                end)
                toggle = false
                return
            end
            for _, part in toy:GetDescendants() do
                if part:IsA("BasePart") then part.CanCollide = false end
            end
            local holdPart = toy:FindFirstChild("HoldPart")
            if not holdPart then return end
            local holdingPlayer = holdPart:FindFirstChild("HoldingPlayer")
            holdingPlayer = holdingPlayer and holdingPlayer.Value
            if holdingPlayer and holdingPlayer ~= plr then
                if selectedToy == "FoodHamburger" and getBurgerMarker(toy) ~= "AntiInputLagBurgerMarker" then
                    return
                end
                pcall(function()
                    RemoteDispatcher:Invoke(holdPart.DropItemRemoteFunction, toy, hrp.CFrame + Vector3.new(0, 10, 0), Vector3.zero)
                end)
                toy:Destroy()
                toggle = false
                return
            end
            local style = Settings.Anti.AntiInputLagStyle or "Up"
            toggle = not toggle
            if toggle then
                pcall(function()
                    RemoteDispatcher:Invoke(holdPart.HoldItemRemoteFunction, toy, char)
                end)
            else
                if style == "Circle" then
                    orbitAngle = orbitAngle + 20 * dt
                    local offsetX = math.cos(orbitAngle) * 2.5
                    local offsetZ = math.sin(orbitAngle) * 2.5
                    local dropCF = hrp.CFrame * CFrame.new(offsetX, 5, offsetZ)
                    pcall(function()
                        RemoteDispatcher:Invoke(holdPart.DropItemRemoteFunction, toy, dropCF, Vector3.new(0, 0, 0))
                    end)
                elseif style == "Hided" then
                    local rx = math.random(-999999, 999999)
                    local rz = math.random(-999999, 999999)
                    local ry = math.random(100, 500000)
                    pcall(function()
                        RemoteDispatcher:Invoke(holdPart.DropItemRemoteFunction, toy, CFrame.new(rx, ry, rz), Vector3.new(0, 0, 0))
                    end)
                else
                    pcall(function()
                    RemoteDispatcher:Invoke(holdPart.DropItemRemoteFunction, toy, hrp.CFrame + Vector3.new(0, 3, 0), Vector3.zero)
                    end)
                end
            end
        end)
    else
        if State.antiInputLagConn then State.antiInputLagConn:Disconnect() State.antiInputLagConn = nil end
    end
end})
antiMiscSec:Toggle({Text = "All Anti Input Here", Flag = "AllAntiInputDance", Default = false, Callback = function(v)
    Settings.Anti.AllAntiInputDance = v
    if not v then RemoteDispatcher:Flush() end
    if v then
        if State.allAntiInputDanceConn then State.allAntiInputDanceConn:Disconnect() State.allAntiInputDanceConn = nil end
        if State.allAntiInputDanceTask then task.cancel(State.allAntiInputDanceTask) State.allAntiInputDanceTask = nil end
        if State.allAntiInputDanceDesc then State.allAntiInputDanceDesc:Disconnect() State.allAntiInputDanceDesc = nil end
        if State.allAntiInputDanceRemoving then State.allAntiInputDanceRemoving:Disconnect() State.allAntiInputDanceRemoving = nil end
        local plr = LocalPlayer
        local cachedToys = {}
        local toyLookup = {}
        State.allAntiInputDanceToys = cachedToys
        local function isHoldable(obj)
            if obj:IsA("Model") and obj:FindFirstChild("HoldPart") then
                local hp = obj.HoldPart
                if hp:FindFirstChild("HoldItemRemoteFunction") and hp:FindFirstChild("DropItemRemoteFunction") then
                    return true
                end
            end
            return false
        end
        local function addToy(obj)
            if toyLookup[obj] then return end
            if not isHoldable(obj) then return end
            toyLookup[obj] = true
            table.insert(cachedToys, obj)
        end
        local function removeToy(obj)
            if not toyLookup[obj] then return end
            toyLookup[obj] = nil
            for i = #cachedToys, 1, -1 do
                if cachedToys[i] == obj then
                    table.remove(cachedToys, i)
                    break
                end
            end
        end
        for _, obj in pairs(Workspace:GetDescendants()) do
            addToy(obj)
        end
        if State.allAntiInputDanceDesc then State.allAntiInputDanceDesc:Disconnect() end
        if State.allAntiInputDanceRemoving then State.allAntiInputDanceRemoving:Disconnect() end
        State.allAntiInputDanceDesc = Workspace.DescendantAdded:Connect(addToy)
        State.allAntiInputDanceRemoving = Workspace.DescendantRemoving:Connect(removeToy)
        local MAX_HELD = 8
        State.allAntiInputDanceTask = task.spawn(function()
            local held = {}
            State.allAntiInputDanceHeld = held
            local function findNew()
                for _, obj in ipairs(cachedToys) do
                    if not obj or not obj.Parent then continue end
                    if not obj:FindFirstChild("HoldPart") then continue end
                    local already = false
                    for _, r in ipairs(held) do if r == obj then already = true break end end
                    if not already then return obj end
                end
                return nil
            end
            while Settings.Anti.AllAntiInputDance do
                local char = plr.Character
                if not char then task.wait(0.1) continue end
                local hrp = char:FindFirstChild("HumanoidRootPart")
                if not hrp then task.wait(0.1) continue end
                while #held < MAX_HELD and Settings.Anti.AllAntiInputDance do
                    local obj = findNew()
                    if not obj then break end
                    local holdPart = obj:FindFirstChild("HoldPart")
                    if not holdPart then continue end
                    pcall(function() RemoteDispatcher:Invoke(holdPart.HoldItemRemoteFunction, obj, char) end)
                    task.wait(0.003)
                    held[#held + 1] = obj
                end
                if #held >= MAX_HELD then
                    local obj = table.remove(held, 1)
                    if obj and obj.Parent then
                        local holdPart = obj:FindFirstChild("HoldPart")
                        if holdPart then
                            local cHRP = char and char:FindFirstChild("HumanoidRootPart")
                            if cHRP then
                                local visible = 0
                                for _, t in ipairs(cachedToys) do
                                    if t and t.Parent then visible = visible + 1 end
                                end
                                local y = 10 + visible
                                pcall(function() RemoteDispatcher:Invoke(holdPart.DropItemRemoteFunction, obj, cHRP.CFrame * CFrame.new(0, y, 0), Vector3.zero) end)
                            end
                        end
                    end
                    task.wait(0.003)
                    local newObj = findNew()
                    if newObj then
                        local holdPart = newObj:FindFirstChild("HoldPart")
                        if holdPart then
                            pcall(function() RemoteDispatcher:Invoke(holdPart.HoldItemRemoteFunction, newObj, char) end)
                            task.wait(0.003)
                            held[#held + 1] = newObj
                        end
                    end
                else
                    task.wait(0.05)
                end
            end
        end)
    else
        if State.allAntiInputDanceConn then State.allAntiInputDanceConn:Disconnect() State.allAntiInputDanceConn = nil end
        if State.allAntiInputDanceTask then task.cancel(State.allAntiInputDanceTask) State.allAntiInputDanceTask = nil end
        if State.allAntiInputDanceDesc then State.allAntiInputDanceDesc:Disconnect() State.allAntiInputDanceDesc = nil end
        if State.allAntiInputDanceRemoving then State.allAntiInputDanceRemoving:Disconnect() State.allAntiInputDanceRemoving = nil end
        task.wait(0.05)
        local heldNow = State.allAntiInputDanceHeld or {}
        local char = LocalPlayer.Character
        if char then
            local hrp = char:FindFirstChild("HumanoidRootPart")
            if hrp then
                local dropCF = hrp.CFrame * CFrame.new(0, 3, 0)
                for _, toy in ipairs(heldNow) do
                    if toy and toy.Parent then
                        local holdPart = toy:FindFirstChild("HoldPart")
                        if holdPart then
                            pcall(function()
                                RemoteDispatcher:Invoke(holdPart.DropItemRemoteFunction, toy, dropCF, Vector3.zero)
                            end)
                            task.wait(0.01)
                        end
                    end
                end
            end
        end
        State.allAntiInputDanceHeld = nil
        State.allAntiInputDanceToys = nil
    end
end})
Settings.Anti.removeAllAntiInput = false
local removeAllAntiInputConn = nil
antiMiscSec:Toggle({Text = "Anti All Anti Input", Flag = "RemoveAllAntiInput", Default = false, Callback = function(v)
    Settings.Anti.removeAllAntiInput = v
    if not v then RemoteDispatcher:Flush() end
    if v then
        local AllowedItems = {
            FoodHamburger = true, FoodCoconut = true, FoodPizzaCheese = true,
            FoodPizzaPepperoni = true, FoodHotdog = true, FoodMushroomPoison = true,
            FoodBread = true, FoodDippyEgg = true, FoodMayonnaise = true,
            FoodFrenchFries = true, FoodMeatStick = true, FoodDonut = true,
            FoodCakePink = true, InstrumentGuitarBanjo = true, InstrumentGuitarViolin = true,
            InstrumentGuitarUkulele = true, InstrumentWoodwindSaxophone = true,
            InstrumentWoodwindOcarina = true, InstrumentBrassVuvuzelaQwizik = true,
            InstrumentBrassTrumpet = true, InstrumentDrumBongos = true,
            InstrumentDrumSnare = true, InstrumentPianoMelodica = true,
            InstrumentVoiceMicrophone = true, CupMugWhite = true, CupMugBrown = true,
            PoopPile = true, PoopPileSparkle = true,
        }
        local plr = LocalPlayer
        local burgers = {}
        if State.removeAllAntiInputDesc then State.removeAllAntiInputDesc:Disconnect() State.removeAllAntiInputDesc = nil end
        State.removeAllAntiInputDesc = Workspace.DescendantAdded:Connect(function(obj)
            if AllowedItems[obj.Name] and obj:IsA("Model") then
                task.spawn(function()
                    local hp = obj:WaitForChild("HoldPart", 3)
                    if hp then table.insert(burgers, obj) end
                end)
            end
        end)
        for _, v in ipairs(Workspace:GetDescendants()) do
            if AllowedItems[v.Name] and v:IsA("Model") and v:FindFirstChild("HoldPart") then
                table.insert(burgers, v)
            end
        end
        removeAllAntiInputConn = RunService.Heartbeat:Connect(function()
            if not Settings.Anti.removeAllAntiInput then return end
            local now = os.clock()
            if (now - (State._lastRemoveAllInput or 0)) < 0.05 then return end
            State._lastRemoveAllInput = now
            local char = plr.Character
            if not char then return end
            local hrp = char:FindFirstChild("HumanoidRootPart")
            if not hrp then return end
            for i = #burgers, 1, -1 do
                local b = burgers[i]
                if not b or not b.Parent or not b:FindFirstChild("HoldPart") then
                    table.remove(burgers, i)
                else
                    local hp = b.HoldPart
                    pcall(function() RemoteDispatcher:Invoke(hp.HoldItemRemoteFunction, b, char) end)
                    pcall(function() RemoteDispatcher:Invoke(hp.DropItemRemoteFunction, b, hrp.CFrame + Vector3.new(0, -2000, 0), Vector3.zero) end)
                end
            end
        end)
    else
        if removeAllAntiInputConn then removeAllAntiInputConn:Disconnect() removeAllAntiInputConn = nil end
        if State.removeAllAntiInputDesc then State.removeAllAntiInputDesc:Disconnect() State.removeAllAntiInputDesc = nil end
    end
end})
antiMiscSec:Toggle({Text = "Anti Fire", Flag = "AntiFire", Default = false, Callback = function(enabled)
    Settings.Anti.AntiFire = enabled
    pcall(function()
        if enabled then
            if State.antiFireConn then State.antiFireConn:Disconnect() State.antiFireConn = nil end
            if State.antiFireTask then task.cancel(State.antiFireTask) State.antiFireTask = nil end
            local function stopAntiFire()
                if State.antiFireConn then State.antiFireConn:Disconnect() State.antiFireConn = nil end
                if State.antiFireTask then task.cancel(State.antiFireTask) State.antiFireTask = nil end
            end
            State.antiFireTask = task.spawn(function()
                local extinguishPart = findExtinguishPart()
                if not extinguishPart then
                    for _ = 1, 60 do
                        task.wait(0.1)
                        if not Settings.Anti.AntiFire then return end
                        extinguishPart = findExtinguishPart()
                        if extinguishPart then break end
                    end
                end
                if not extinguishPart then return end
                State.antiFireOriginalCF = extinguishPart.CFrame
                local lastFireUpdate = 0
                State.antiFireLastUpdate = 0
                State.antiFireConn = RunService.Heartbeat:Connect(function()
                    if not Settings.Anti.AntiFire then return end
                    if not extinguishPart.Parent then
                        local newEP = findExtinguishPart()
                        if newEP then extinguishPart = newEP end
                    end
                    local now = tick()
                    if now - lastFireUpdate < 0.05 then return end
                    lastFireUpdate = now
                    local char = LocalPlayer.Character
                    local root = char and char:FindFirstChild("HumanoidRootPart")
                    if not root then return end
                    if isPlayerBurning() then
                        local fp = char:FindFirstChild("FirePlayerPart") or root
                        extinguishPart.CFrame = fp.CFrame
                        if firetouchinterest then
                            pcall(function()
                                firetouchinterest(fp, extinguishPart, 0)
                                firetouchinterest(fp, extinguishPart, 1)
                            end)
                        end
                    elseif State.antiFireOriginalCF then
                        extinguishPart.CFrame = State.antiFireOriginalCF
                    end
                end)
            end)
            State.antiFireStop = stopAntiFire
        else
            if State.antiFireTask then task.cancel(State.antiFireTask) State.antiFireTask = nil end
            if State.antiFireConn then State.antiFireConn:Disconnect() State.antiFireConn = nil end
            if State.antiFireOriginalCF then
                local ep = findExtinguishPart()
                if ep then ep.CFrame = State.antiFireOriginalCF end
            end
        end
    end)
end})
