            while tick() - scanWait < 2 do
                local cand = Workspace:FindFirstChild("CreatureBlobman", true)
                if cand and cand:IsA("Model") then
                    local hd = cand:FindFirstChild("Head")
                    local isOurs = (not hd) or (not hd:FindFirstChild("PartOwner")) or hd.PartOwner.Value == LocalPlayer.Name
                    if isOurs then
                        Blob = cand
                        break
                    end
                end
                task.wait(0.1)
