antiBlobSec:Button({Text = "Break PCLD", Callback = function()
    task.spawn(function()
        local plr = LocalPlayer
        local serverPos = CFrame.new(-272.2197265625, -7.350403785705566, 475.0108947753906)
        workspace.FallenPartsDestroyHeight = -100000
        local storedJoints = {}
        local root
        local conn
        local active = false
        local function breakPCLD()
            local char = plr.Character
            if not char then return end
            root = char:WaitForChild("HumanoidRootPart")
            for _, v in ipairs(char:GetDescendants()) do
                if v:IsA("Motor6D") then
                    storedJoints[v] = v.Part0
                    v.Part0 = nil
                end
            end
            root.CFrame = serverPos
            conn = RunService.RenderStepped:Connect(function()
                if root and root.Parent then
                    root.AssemblyLinearVelocity = Vector3.zero
                    root.AssemblyAngularVelocity = Vector3.zero
                end
            end)
        end
        local function restore()
            if conn then
                conn:Disconnect()
                conn = nil
            end
            for m, p0 in pairs(storedJoints) do
                if m and m.Parent then
                    m.Part0 = p0
                end
            end
            storedJoints = {}
        end
        local function press6()
            active = not active
            if active then
                breakPCLD()
            else
                restore()
            end
        end
        press6()
        task.wait(0.12)
        press6()
        plr.CharacterAdded:Once(function()
            task.wait(0.25)
            press6()
            task.wait(0.12)
            press6()
        end)
    end)
end})
antiBlobSec:Toggle({Text = "Auto Break PCLD", Flag = "AutoBreakPCLD", Default = false, Callback = function(v)
    Settings.Anti.autoBreakPCLD = v
    if v then
        if State.autoBreakPCLDTask then task.cancel(State.autoBreakPCLDTask) end
        State.autoBreakPCLDTask = task.spawn(function()
            local plr = LocalPlayer
            local isFirstCycle = true
            while Settings.Anti.autoBreakPCLD do
                local char = plr.Character or plr.CharacterAdded:Wait()
                local hrp = char:WaitForChild("HumanoidRootPart", 5)
                local hum = char:WaitForChild("Humanoid", 5)
                if not hrp or not hum then
                    task.wait(0.5)
                    continue
                end
                if hum.Health <= 0 then
                    char = plr.CharacterAdded:Wait()
                    hrp = char:WaitForChild("HumanoidRootPart", 5)
                    hum = char:WaitForChild("Humanoid", 5)
                end
                if not hrp or not hum then continue end
                if isFirstCycle then
                    local savedCFrame = hrp.CFrame
                    hrp.CFrame = CFrame.new(hrp.Position.X, 50000, hrp.Position.Z)
                    task.wait(0.05)
                    hum.Health = 0
                    char = plr.CharacterAdded:Wait()
                    if not Settings.Anti.autoBreakPCLD then break end
                    hrp = char:WaitForChild("HumanoidRootPart", 5)
                    hum = char:WaitForChild("Humanoid", 5)
                    if hrp and hum then
                        task.wait(0.1)
                        hrp.CFrame = savedCFrame
                        task.wait(0.05)
                        hum.Health = 0
                    end
                    isFirstCycle = false
                else
                    task.wait(0.1)
                    if hum then
                        hum.Health = 0
                        pcall(function() char:BreakJoints() end)
                    end
                end
                char = plr.CharacterAdded:Wait()
                if not Settings.Anti.autoBreakPCLD then break end
                hum = char:WaitForChild("Humanoid", 5)
                if hum then
                    hum.Died:Wait()
                end
            end
        end)
    else
        if State.autoBreakPCLDTask then task.cancel(State.autoBreakPCLDTask) State.autoBreakPCLDTask = nil end
    end
end})
local gucciMode = "Blobman"
local gucciActive = false
local gucciTask = nil
local function gucciStop()
    gucciActive = false
    if gucciTask then
        task.cancel(gucciTask)
        gucciTask = nil
    end
end
local function gucciSitToggle(hum)
    if not hum then return end
    task.spawn(function()
        for _ = 1, 30 do
            hum.Sit = true
            task.wait()
            hum.Sit = false
        end
    end)
end
local function gucciTractorStart()
    local char = LocalPlayer.Character or LocalPlayer.CharacterAdded:Wait()
    local hum = char:WaitForChild("Humanoid", 5)
    local hrp = char:WaitForChild("HumanoidRootPart", 5)
    if not hum or not hrp then return end
    pcall(function()
        local pal
        local conn
        conn = LocalPlayer.PlayerGui.MenuGui.Menu.TabContents.ToyDestroy.Contents.ChildAdded:Connect(function(c)
            if c.Name == "TractorGreen" then
                pal = c
                task.wait()
                conn:Disconnect()
            end
        end)
        task.spawn(function()
            task.wait(1)
            if pal and pal:FindFirstChild("ViewItemButton") then
                local mess = pal.ViewItemButton.NewMessage:Clone()
                mess.Name = "Gucci2"
                mess.TextColor3 = Color3.fromRGB(255, 255, 255)
                mess.Text = "Anti Gucci"
                mess.Visible = true
                mess.Parent = pal.ViewItemButton
            end
        end)
    end)
    local inv = Workspace:FindFirstChild(LocalPlayer.Name .. "SpawnedInToys")
    if inv and inv:FindFirstChild("tractorgucci") then
        pcall(function() RemoteDispatcher:Fire(DeleteToyRE, inv.tractorgucci) end)
    end
    local blobb = nil
    local conn
    if inv then
        conn = inv.ChildAdded:Connect(function(child)
            if child.Name == "TractorGreen" and child:IsA("Model") then
                blobb = child
                if conn then conn:Disconnect() end
            end
        end)
    end
    task.spawn(function()
        pcall(function() RemoteDispatcher:Invoke(SpawnToyRF, "TractorGreen", hrp.CFrame * CFrame.new(0, -1, 13), Vector3.new(0, 0, 0)) end)
    end)
    local startTick = tick()
    while not blobb do
        if tick() - startTick > 5 then break end
        task.wait()
    end
    if conn then conn:Disconnect() end
    if not blobb then return end
    blobb.Name = "tractorgucci"
    local seat = blobb:WaitForChild("VehicleSeat", 3)
    if not seat then return end
    pcall(function() seat:Sit(hum) end)
    task.spawn(function()
        local endTime = tick() + 3
        while tick() < endTime do
            pcall(function() RemoteDispatcher:Fire(ragdollRemoteEvent, hrp, 0) end)
            task.wait()
        end
    end)
    task.wait()
    while seat.Occupant ~= hum do task.wait() end
    pcall(function() hum:ChangeState(Enum.HumanoidStateType.Jumping) end)
    local mainPart = blobb:FindFirstChild("Part") or blobb.PrimaryPart
    if mainPart then
        pcall(function() RemoteDispatcher:Fire(setNetworkOwnerEvent, mainPart, mainPart.CFrame) end)
    end
    task.wait(0.2)
    pcall(function() seat.CFrame = CFrame.new(0, -10000, 0) end)
    local function getTractorParts()
        local parts = {}
        local function collectParts(model)
            for _, child in pairs(model:GetChildren()) do
                if child:IsA("BasePart") then
                    pcall(function() child.CanCollide = false end)
                    table.insert(parts, child)
                end
                if child:IsA("Model") then
                    collectParts(child)
                end
            end
        end
        collectParts(blobb)
        return parts
    end
    while gucciActive do
        if not blobb or not blobb.Parent then
            local inv2 = Workspace:FindFirstChild(LocalPlayer.Name .. "SpawnedInToys")
            blobb = inv2 and (inv2:FindFirstChild("tractorgucci") or inv2:FindFirstChild("TractorGreen"))
            if not blobb then
                local curChar = LocalPlayer.Character
                local curRoot = curChar and curChar:FindFirstChild("HumanoidRootPart")
                local spawnCFrame = (curRoot and curRoot.CFrame or hrp.CFrame) * CFrame.new(0, -1, 13)
                local conn2
                if inv2 then
                    conn2 = inv2.ChildAdded:Connect(function(child)
                        if child.Name == "TractorGreen" and child:IsA("Model") then
                            blobb = child
                            if conn2 then conn2:Disconnect() end
                        end
                    end)
                end
                task.spawn(function()
                    pcall(function() RemoteDispatcher:Invoke(SpawnToyRF, "TractorGreen", spawnCFrame, Vector3.new(0, 0, 0)) end)
                end)
                local startTick2 = tick()
                while not blobb do
                    if tick() - startTick2 > 5 then break end
                    task.wait()
                end
                if conn2 then conn2:Disconnect() end
                if blobb then blobb.Name = "tractorgucci" end
            end
        end
        if blobb then
            local curChar = LocalPlayer.Character
            local curRoot = curChar and curChar:FindFirstChild("HumanoidRootPart")
            if curRoot then
                local myPos = curRoot.Position
                for _, prt in ipairs(getTractorParts()) do
                    if prt.Parent and (prt.Position - myPos).Magnitude <= 22 then
                        pcall(function() RemoteDispatcher:Fire(setNetworkOwnerEvent, prt, prt.CFrame) end)
                    end
                    pcall(function() prt.AssemblyLinearVelocity = Vector3.new(0, 1400, 0) end)
                end
            end
        end
        task.wait(0.02)
    end
end
