                gucciTractorStop()
            elseif gucciMode == "Train (Invisible)" then
                gucciTrainStop()
            elseif gucciMode == "Santa (Invisible)" then
                gucciSantaStop()
            else
                pcall(function() gucciBlobmanSet(false) end)
            end
        end
        gucciStop()
        gucciStart()
    else
