local TargetPCLDManager = {
    targetPCLDs = {},
    isBreaked = {},
    pcldStaticSince = {},
    lastPCLDPos = {},
    desyncStartTime = {},
    resetConnections = {},
}

function TargetPCLDManager.setupTarget(targetPlayer)
    if not targetPlayer or not targetPlayer.Parent then return end
    local name = targetPlayer.Name
    if TargetPCLDManager.resetConnections[name] then return end

    local conns = {}
    local function onTargetReset()
        TargetPCLDManager.isBreaked[name] = false
        TargetPCLDManager.pcldStaticSince[name] = nil
        TargetPCLDManager.lastPCLDPos[name] = nil
        TargetPCLDManager.desyncStartTime[name] = nil
        TargetPCLDManager.targetPCLDs[name] = nil
    end

    conns[#conns + 1] = targetPlayer.CharacterAdded:Connect(function(newChar)
        onTargetReset()
        task.spawn(function()
            local hum = newChar:WaitForChild("Humanoid", 5)
            if hum then
                conns[#conns + 1] = hum.Died:Connect(onTargetReset)
            end
        end)
    end)

    if targetPlayer.Character then
        local hum = targetPlayer.Character:FindFirstChildOfClass("Humanoid")
        if hum then
            conns[#conns + 1] = hum.Died:Connect(onTargetReset)
        end
    end

    TargetPCLDManager.resetConnections[name] = conns
end

function TargetPCLDManager.getPCLD(targetPlayer)
    if not targetPlayer or not targetPlayer.Parent then return nil end
    local name = targetPlayer.Name
    local cached = TargetPCLDManager.targetPCLDs[name]
    if cached and cached.Parent and cached:IsA("BasePart") then
        return cached
    end

    local pcld = GlobalPCLDTracker.getPCLDForPlayer(targetPlayer)
    if pcld and pcld.Parent and pcld:IsA("BasePart") then
        TargetPCLDManager.targetPCLDs[name] = pcld
        return pcld
    end

    return nil
end

function TargetPCLDManager.checkDesync(targetPlayer)
    if not targetPlayer or not targetPlayer.Parent then return false end
    local name = targetPlayer.Name
    TargetPCLDManager.setupTarget(targetPlayer)

    local tChar = targetPlayer.Character
    local tHRP = tChar and tChar:FindFirstChild("HumanoidRootPart")
    local tHum = tChar and tChar:FindFirstChildOfClass("Humanoid")
    if not tHRP or not tHum or tHum.Health <= 0 then
        TargetPCLDManager.desyncStartTime[name] = nil
        return false
    end

    local pcld = TargetPCLDManager.getPCLD(targetPlayer)
    if not pcld or not pcld.Parent then return false end

    local now = tick()
    local pcldPos = pcld.Position
    local dist = (pcldPos - tHRP.Position).Magnitude

    if dist > 30 then
        local lastPos = TargetPCLDManager.lastPCLDPos[name]
        if lastPos then
            local moveDelta = (pcldPos - lastPos).Magnitude
            if moveDelta < 0.5 then
                if not TargetPCLDManager.pcldStaticSince[name] then
                    TargetPCLDManager.pcldStaticSince[name] = now
                elseif now - TargetPCLDManager.pcldStaticSince[name] >= 20 then
                    TargetPCLDManager.isBreaked[name] = true
                end
            else
                TargetPCLDManager.pcldStaticSince[name] = nil
            end
        else
            TargetPCLDManager.pcldStaticSince[name] = now
        end
        TargetPCLDManager.lastPCLDPos[name] = pcldPos
    else
        TargetPCLDManager.pcldStaticSince[name] = nil
        TargetPCLDManager.desyncStartTime[name] = nil
        TargetPCLDManager.lastPCLDPos[name] = pcldPos
        return false
    end

    if TargetPCLDManager.isBreaked[name] then
        TargetPCLDManager.desyncStartTime[name] = nil
        return false
    end

    if not TargetPCLDManager.desyncStartTime[name] then
        TargetPCLDManager.desyncStartTime[name] = now
    elseif now - TargetPCLDManager.desyncStartTime[name] >= 15 then
        for _, v in pairs(tHRP:GetChildren()) do
            if v:IsA("BodyPosition") or v:IsA("BodyGyro") or v:IsA("BodyVelocity") or v:IsA("BodyForce") or v:IsA("BodyAngularVelocity") then
                pcall(function() v:Destroy() end)
            end
        end
        pcall(function()
            tHRP.AssemblyLinearVelocity = Vector3.zero
            tHRP.AssemblyAngularVelocity = Vector3.zero
        end)

        pcall(function()
            tHRP.CFrame = CFrame.new(pcld.Position + Vector3.new(0, 2, 0))
            tHRP.AssemblyLinearVelocity = Vector3.zero
            tHRP.AssemblyAngularVelocity = Vector3.zero
        end)

        TargetPCLDManager.desyncStartTime[name] = nil
        TargetPCLDManager.pcldStaticSince[name] = nil

        return true
    end

    return false
end

Players.PlayerRemoving:Connect(function(plr)
    local name = plr.Name
    if TargetPCLDManager.resetConnections[name] then
        for _, c in ipairs(TargetPCLDManager.resetConnections[name]) do
            pcall(function() c:Disconnect() end)
        end
        TargetPCLDManager.resetConnections[name] = nil
    end
    TargetPCLDManager.isBreaked[name] = nil
    TargetPCLDManager.pcldStaticSince[name] = nil
    TargetPCLDManager.lastPCLDPos[name] = nil
    TargetPCLDManager.desyncStartTime[name] = nil
    TargetPCLDManager.targetPCLDs[name] = nil
end)

local ownershipKick = {
    method = "Loop Kick",
    on = false,
    bring = true,
    ragdoll = true,
    posLocked = false,
    savedPos = nil,
    posLockedCFrame = nil,
}
local ownershipPosLockConn = nil
local function rememberOwnershipSavedPos(cframe)
    if cframe then ownershipKick.savedPos = cframe end
end
local function stopOwnershipPosLock()
    if ownershipPosLockConn then
        ownershipPosLockConn:Disconnect()
        ownershipPosLockConn = nil
    end
end
local function startOwnershipPosLock()
    local root = Utility.GetPlayerRootPart()
    local saved = ownershipKick.savedPos or (root and root.CFrame)
    if not saved then return false end
    ownershipKick.savedPos = saved
    ownershipKick.posLockedCFrame = saved
    if ownershipPosLockConn then return true end
    ownershipPosLockConn = RunService.RenderStepped:Connect(function()
        if not ownershipKick.on or not ownershipKick.posLocked then return end
        local currentRoot = Utility.GetPlayerRootPart()
        local lockCFrame = ownershipKick.posLockedCFrame
        if currentRoot and lockCFrame then
            local assembly = currentRoot.AssemblyRootPart or currentRoot
            assembly.AssemblyLinearVelocity = Vector3.zero
            assembly.AssemblyAngularVelocity = Vector3.zero
            local offset = assembly.CFrame:ToObjectSpace(currentRoot.CFrame)
            assembly.CFrame = lockCFrame * offset:Inverse()
        end
    end)
    return true
end
local function pauseOwnershipPosLock()
    stopOwnershipPosLock()
end
local function resumeOwnershipPosLock()
    if ownershipKick.on and ownershipKick.posLocked and ownershipKick.savedPos then
        startOwnershipPosLock()
    end
end
local function isAntiGucciActive()
    if Settings.Anti and (Settings.Anti.AntiGucciBlobman or Settings.Anti.AntiGucciBlobmanFast or Settings.Anti.GucciAntiGrab) then
        return true
    end
    if State.antiGucci and (State.antiGucci.running or State.antiGucci.blobLoop or State.antiGucci.fastLoop) then
        return true
    end
    return false
end

local function isMyCharacterPart(part)
    if not part then return false end
    local myChar = LocalPlayer.Character
    if not myChar then return false end
    if part == myChar then return true end
    local ok, res = pcall(function() return part:IsDescendantOf(myChar) end)
    return ok and res
end

local targetIndicatorGui = nil
local function destroyTargetIndicator()
    if targetIndicatorGui then
        pcall(function() targetIndicatorGui:Destroy() end)
        targetIndicatorGui = nil
    end
end
local function ensureTargetIndicator(target)
    if not target or not target.Character then return end
    local hrp = target.Character:FindFirstChild("HumanoidRootPart")
    if not hrp then return end
    if targetIndicatorGui and targetIndicatorGui.Parent and targetIndicatorGui.Adornee == hrp then
        return targetIndicatorGui
    end
    destroyTargetIndicator()
    local gui = Instance.new("BillboardGui")
    gui.Name = "OwnershipKickIndicator"
    gui.Adornee = hrp
    gui.AlwaysOnTop = true
    gui.LightInfluence = 0
    gui.MaxDistance = 0
    gui.Size = UDim2.fromOffset(26, 26)
    gui.StudsOffset = Vector3.new(0, 0, 0)
    local frame = Instance.new("Frame")
    frame.Name = "Dot"
    frame.Size = UDim2.fromScale(1, 1)
    frame.BackgroundColor3 = Color3.fromRGB(255, 0, 0)
    frame.BorderSizePixel = 0
    local corner = Instance.new("UICorner")
    corner.CornerRadius = UDim.new(1, 0)
    corner.Parent = frame
    frame.Parent = gui
    gui.Parent = hrp
    targetIndicatorGui = gui
    return gui
end
local function setTargetIndicator(isRagdolled)
    if not targetIndicatorGui or not targetIndicatorGui.Parent then return end
    local frame = targetIndicatorGui:FindFirstChild("Dot")
    if frame then
        frame.BackgroundColor3 = isRagdolled and Color3.fromRGB(0, 255, 0) or Color3.fromRGB(255, 0, 0)
    end
end
ownershipKickSec:Dropdown({Text = "Kick Method", Flag = "OwnershipKickMethod", List = {"Loop Kick", "Loop Kick V2", "Loop Kick V3", "Loop Kick V4", "Loop Kick V5", "Loop Kick V6", "Loop Kick V7", "Loop Lock (Can Kick Target)"}, Callback = function(value)
