local targetHighlightInstance = nil
local targetHighlightCharConn = nil
local targetHighlightPlayerAddedConn = nil
local targetHighlightPlayerRemovingConn = nil
local targetHighlightHeartbeatConn = nil
local targetHighlightEnabled = false

local function destroyTargetHighlight()
    if targetHighlightInstance then
        pcall(function() targetHighlightInstance:Destroy() end)
        targetHighlightInstance = nil
    end
    if targetHighlightCharConn then
        pcall(function() targetHighlightCharConn:Disconnect() end)
        targetHighlightCharConn = nil
    end
end

updateTargetHighlight = function()
    if not targetHighlightEnabled or not ownershipKickTarget then
        destroyTargetHighlight()
        return
    end
    local targetPlr = Players:FindFirstChild(ownershipKickTarget)
    if not targetPlr then
        destroyTargetHighlight()
        return
    end
    local char = targetPlr.Character
    if not char or not char.Parent then
        destroyTargetHighlight()
        return
    end
    if targetHighlightInstance and targetHighlightInstance.Parent == char and targetHighlightInstance.Adornee == char then
        return
    end
    destroyTargetHighlight()
    pcall(function()
        local hl = Instance.new("Highlight")
        hl.Name = "OwnershipTargetHighlight"
        hl.FillColor = Color3.fromRGB(120, 120, 120)
        hl.FillTransparency = 0.5
        hl.OutlineColor = Color3.fromRGB(160, 160, 160)
        hl.OutlineTransparency = 0
        hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
        hl.Adornee = char
        hl.Parent = char
        targetHighlightInstance = hl
    end)

    if not targetHighlightCharConn then
        targetHighlightCharConn = targetPlr.CharacterAdded:Connect(function(newChar)
            task.wait(0.1)
            if targetHighlightEnabled and ownershipKickTarget == targetPlr.Name then
                updateTargetHighlight()
            end
        end)
    end
end

ownershipKickSec:Toggle({Text = "Highlight Target", Flag = "OwnershipHighlightTarget", Default = false, Callback = function(v)
    targetHighlightEnabled = v
    if v then
        updateTargetHighlight()
        if not targetHighlightHeartbeatConn then
            local timer = 0
            targetHighlightHeartbeatConn = RunService.Heartbeat:Connect(function(dt)
                if not targetHighlightEnabled then return end
                timer = timer + dt
                if timer < 0.5 then return end
                timer = 0
                pcall(updateTargetHighlight)
            end)
        end
        if not targetHighlightPlayerAddedConn then
            targetHighlightPlayerAddedConn = Players.PlayerAdded:Connect(function(plr)
                if targetHighlightEnabled and ownershipKickTarget and plr.Name == ownershipKickTarget then
                    task.wait(0.2)
                    pcall(updateTargetHighlight)
                end
            end)
        end
        if not targetHighlightPlayerRemovingConn then
            targetHighlightPlayerRemovingConn = Players.PlayerRemoving:Connect(function(plr)
                if ownershipKickTarget and plr.Name == ownershipKickTarget then
                    destroyTargetHighlight()
                end
            end)
        end
    else
        if targetHighlightHeartbeatConn then
            pcall(function() targetHighlightHeartbeatConn:Disconnect() end)
            targetHighlightHeartbeatConn = nil
        end
        if targetHighlightPlayerAddedConn then
            pcall(function() targetHighlightPlayerAddedConn:Disconnect() end)
            targetHighlightPlayerAddedConn = nil
        end
        if targetHighlightPlayerRemovingConn then
            pcall(function() targetHighlightPlayerRemovingConn:Disconnect() end)
            targetHighlightPlayerRemovingConn = nil
        end
        destroyTargetHighlight()
    end
end})
local function executeBring(tRoot, customSavedPos)
    if not ownershipKick.bring then return false end
    if not tRoot or not tRoot.Parent then return false end
    if not Utility.isLocalAlive() then return false end
    local myChar = LocalPlayer.Character
    local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
    if not myRoot then return false end

    local now = tick()
    if now - (ownershipKick.lastBringTime or 0) < 0.8 then
        return false
    end

    if (tRoot.Position - myRoot.Position).Magnitude <= 29 then
        return false
    end

    for _, v in pairs(tRoot:GetChildren()) do
        if v:IsA("BodyPosition") or v:IsA("BodyGyro") or v:IsA("BodyVelocity") or v:IsA("BodyForce") then
            pcall(function() v:Destroy() end)
        end
    end

    pauseOwnershipPosLock()
    local curSaved = customSavedPos or ownershipKick.savedPos or myRoot.CFrame

    local GE = ReplicatedStorage:FindFirstChild("GrabEvents")
    local setNE = GE and GE:FindFirstChild("SetNetworkOwner")
    local destroyGL = GE and GE:FindFirstChild("DestroyGrabLine")

    local tHum = tRoot.Parent and tRoot.Parent:FindFirstChildOfClass("Humanoid")
    if tHum then
        pcall(function()
            tHum.PlatformStand = true
            tHum.Sit = false
        end)
    end

    local bringStart = tick()
    while tick() - bringStart < 0.5 do
        if not Utility.isLocalAlive() or not tRoot.Parent then
            break
        end
        if not isAntiGucciActive() then
            myRoot.CFrame = tRoot.CFrame * CFrame.new(0, -15, 0)
            myRoot.AssemblyLinearVelocity = Vector3.zero
            myRoot.AssemblyAngularVelocity = Vector3.zero
        end
        if setNE then
            pcall(function() RemoteDispatcher:Fire(setNE, tRoot, tRoot.CFrame) end)
        end
        if destroyGL and (tick() - bringStart) > 0.05 then
            pcall(function() RemoteDispatcher:Fire(destroyGL, tRoot) end)
        end
        RunService.Heartbeat:Wait()
    end

    if myRoot and myRoot.Parent and curSaved and Utility.isLocalAlive() and not isAntiGucciActive() then
        myRoot.CFrame = curSaved
        myRoot.AssemblyLinearVelocity = Vector3.zero
        myRoot.AssemblyAngularVelocity = Vector3.zero
    end

    if tRoot and tRoot.Parent then
        local bringDest = (curSaved or myRoot.CFrame).Position + (curSaved or myRoot.CFrame):VectorToWorldSpace(Vector3.new(0, 15, 0))
        local bp = tRoot:FindFirstChild("KickBodyPos")
        if not bp then
            bp = Instance.new("BodyPosition")
            bp.Name = "KickBodyPos"
            bp.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
            bp.D = 5000
            bp.P = 1500000
            bp.Parent = tRoot
        end
        bp.Position = bringDest

        local bg = tRoot:FindFirstChild("KickBodyGyro")
        if not bg then
            bg = Instance.new("BodyGyro")
            bg.Name = "KickBodyGyro"
            bg.MaxTorque = Vector3.new(math.huge, math.huge, math.huge)
            bg.D = 500
            bg.P = 50000
            bg.Parent = tRoot
        end
        bg.CFrame = (curSaved or myRoot.CFrame)

        if setNE then
            pcall(function() RemoteDispatcher:Fire(setNE, tRoot, tRoot.CFrame) end)
        end
        if destroyGL then
            pcall(function() RemoteDispatcher:Fire(destroyGL, tRoot) end)
        end
    end

    ownershipKick.lastBringTime = tick()
    resumeOwnershipPosLock()
    return true
end

local ownershipKickTask = nil
local ownershipKickFloatConn = nil
local function cleanupOwnershipKickTarget()
    local target = Players:FindFirstChild(ownershipKickTarget)
    if not target or not target.Character then return end
    local dgl
    local GE = ReplicatedStorage:FindFirstChild("GrabEvents")
    if GE then dgl = GE:FindFirstChild("DestroyGrabLine") end
    local hum = target.Character:FindFirstChildOfClass("Humanoid")
    for _, part in pairs(target.Character:GetDescendants()) do
        if part:IsA("BasePart") then
            pcall(function()
                part.AssemblyLinearVelocity = Vector3.zero
                part.AssemblyAngularVelocity = Vector3.zero
            end)
        elseif part:IsA("BodyPosition") or part:IsA("BodyGyro") or part:IsA("BodyVelocity")
            or part:IsA("AlignPosition") or part:IsA("AlignOrientation")
            or part:IsA("VectorForce") or part:IsA("LinearVelocity") or part:IsA("AngularVelocity")
            or part:IsA("Torque") or part:IsA("RocketPropulsion") then
            pcall(function() part:Destroy() end)
        elseif part:IsA("Attachment") and (part.Name == "KickAtt0" or part.Name == "KickAtt1") then
            pcall(function() part:Destroy() end)
        end
    end
    local terrain = Workspace:FindFirstChildOfClass("Terrain")
    if terrain then
        for _, a in pairs(terrain:GetChildren()) do
            if a:IsA("Attachment") and a.Name == "KickAtt1" then
                pcall(function() a:Destroy() end)
            end
        end
    end
    if dgl then
        pcall(function() RemoteDispatcher:Fire(dgl, target.Character:FindFirstChild("HumanoidRootPart")) end)
    end
    if hum then
        pcall(function() hum.PlatformStand = false end)
        pcall(function() hum.Sit = false end)
    end
end
ownershipKick["Loop Kick"] = function(v)
    Settings.Loop.ownershipKickActive = v
    if not v then
        destroyTargetIndicator()
        RemoteDispatcher:NewGeneration()
        if ownershipKickTask then task.cancel(ownershipKickTask) ownershipKickTask = nil end
        if ownershipKickFloatConn then ownershipKickFloatConn:Disconnect() ownershipKickFloatConn = nil end
        if ownershipKickV2ZeroVelConn then pcall(function() ownershipKickV2ZeroVelConn:Disconnect() end) ownershipKickV2ZeroVelConn = nil end
        task.spawn(cleanupOwnershipKickTarget)
        return
    end
    if not ownershipKickTarget then warn("[OK] Select target") Settings.Loop.ownershipKickActive = false return end
    ownershipKickTask = task.spawn(function()
        local destroyGrabLineEvent = grabEventsFolder:WaitForChild("DestroyGrabLine")
        local createGrabLineEvent = grabEventsFolder:WaitForChild("CreateGrabLine")
        local setNetworkOwnerEvent = grabEventsFolder:WaitForChild("SetNetworkOwner")
        local function startFloating()
            if ownershipKickFloatConn then return end
            ownershipKickFloatConn = RunService.Stepped:Connect(function()
                if not Utility.isLocalAlive() then return end
                local ch = LocalPlayer.Character
                if ch then
                    for _, p in pairs(ch:GetChildren()) do
                        if p:IsA("BasePart") and p.CanCollide then p.CanCollide = false end
                    end
                end
            end)
        end
        local function stopFloating()
            if ownershipKickFloatConn then ownershipKickFloatConn:Disconnect() ownershipKickFloatConn = nil end
        end
        local function SNOWship(targetHRP)
            if not targetHRP then return end
            local root = Utility.GetPlayerRootPart()
            if not root then return end
            local dist = LocalPlayer:DistanceFromCharacter(targetHRP.Position)
            if dist <= 30 and dist > 0.1 then
                RemoteDispatcher:Fire(setNetworkOwnerEvent, targetHRP, CFrame.lookAt(root.Position, targetHRP.Position))
            end
        end
        local function checkAlive(target)
            if not target or target == LocalPlayer then return false end
            if isProtectedPlayer(target.Name) then return false end
            if not target.Character then return false end
            local hrp = target.Character:FindFirstChild("HumanoidRootPart")
            local hum = target.Character:FindFirstChildOfClass("Humanoid")
            if not hrp or not hum or hum.Health <= 0 then return false end
            return true
        end
        local function hasOwnership(target)
            local head = target.Character and target.Character:FindFirstChild("Head")
            return head and head:FindFirstChild("PartOwner") and head.PartOwner.Value == LocalPlayer.Name
        end
        while Settings.Loop.ownershipKickActive do
            if not Utility.isLocalAlive() then task.wait(0.25) continue end
            local playerCFrame = Utility.GetPlayerCFrame()
            rememberOwnershipSavedPos(playerCFrame)
            if ownershipKickTarget ~= "" then
                local target = Players:FindFirstChild(ownershipKickTarget)
                if not target then task.wait(0.1) continue end
                if not checkAlive(target) then task.wait(0.1) continue end
                local pips = Workspace:FindFirstChild("PlotItems") and Workspace.PlotItems:FindFirstChild("PlayersInPlots")
                if pips then
                    local inSafe = false
                    for _, child in pairs(pips:GetChildren()) do
                        if child.Name == ownershipKickTarget then inSafe = true break end
                        if child:IsA("ObjectValue") and child.Value and child.Value.Name == ownershipKickTarget then inSafe = true break end
                        if child:IsA("StringValue") and child.Value == ownershipKickTarget then inSafe = true break end
                    end
                    if inSafe then
                        while Settings.Loop.ownershipKickActive do
                            task.wait(0.5)
                            if not Utility.isLocalAlive() then break end
                            local stillInSafe = false
                            pips = Workspace:FindFirstChild("PlotItems") and Workspace.PlotItems:FindFirstChild("PlayersInPlots")
                            if pips then
                                for _, child in pairs(pips:GetChildren()) do
                                    if child.Name == ownershipKickTarget then stillInSafe = true break end
                                    if child:IsA("ObjectValue") and child.Value and child.Value.Name == ownershipKickTarget then stillInSafe = true break end
                                    if child:IsA("StringValue") and child.Value == ownershipKickTarget then stillInSafe = true break end
                                end
                            end
                            if not stillInSafe then break end
                        end
                    end
                end
                local targetHRP = target.Character:FindFirstChild("HumanoidRootPart")
                local targetHum = target.Character:FindFirstChildOfClass("Humanoid")
                if targetHRP and targetHum then
                    if targetHum.SeatPart ~= nil then
                        while Settings.Loop.ownershipKickActive and target and checkAlive(target) do
                            local tHum = target.Character and target.Character:FindFirstChildOfClass("Humanoid")
                            local tHRP = target.Character and target.Character:FindFirstChild("HumanoidRootPart")
                            if not tHum or not tHRP or tHum.SeatPart == nil then break end
                            if not Utility.isLocalAlive() then break end
                            local bv = tHRP:FindFirstChild("SkyVelocity")
                            if bv then pcall(function() bv:Destroy() end) end
                            for _, v in pairs(tHRP:GetChildren()) do
                                if v:IsA("BodyPosition") or v:IsA("BodyGyro") or v:IsA("BodyVelocity") then
                                    pcall(function() v:Destroy() end)
                                end
                            end
                            local myRoot = Utility.GetPlayerRootPart()
                            if ownershipKick.bring and not isAntiGucciActive() and myRoot and Utility.isLocalAlive() then
                                myRoot.CFrame = tHRP.CFrame * CFrame.new(0, 0, 3)
                                myRoot.AssemblyLinearVelocity = Vector3.zero
                                myRoot.AssemblyAngularVelocity = Vector3.zero
                            end
                            for _ = 1, 3 do
                                RemoteDispatcher:Fire(setNetworkOwnerEvent, tHRP, tHRP.CFrame)
                            end
                            task.wait(0.05)
                        end
                    end
                end
                if TargetPCLDManager.checkDesync(target) then
                    task.wait(0.1)
                    continue
                end
                if targetHRP then
                local myRootInit = Utility.GetPlayerRootPart()
                if not ownershipKick.bring and myRootInit and (targetHRP.Position - myRootInit.Position).Magnitude > 29 then
                    task.wait(0.1)
                    continue
                end
            if not ownershipKickV2ZeroVelConn then
                ownershipKickV2ZeroVelConn = RunService.RenderStepped:Connect(function()
                    local t = Players:FindFirstChild(ownershipKickTarget)
                    if t and t.Character and Utility.isLocalAlive() then
                        for _, part in pairs(t.Character:GetDescendants()) do
                            if part:IsA("BasePart") then
                                part.AssemblyLinearVelocity = Vector3.zero
                                part.AssemblyAngularVelocity = Vector3.zero
                            end
                        end
                    end
                end)
            end
            for _ = 0, 50 do
                        if not Utility.isLocalAlive() then break end
                        startFloating()
                        SNOWship(targetHRP)
                        ensureTargetIndicator(target)
                        local targetHum = target.Character and target.Character:FindFirstChildOfClass("Humanoid")
                        if targetHum and targetHum.SeatPart ~= nil then break end
                        if TargetPCLDManager.checkDesync(target) then break end
                        local tRag = targetHum and targetHum:FindFirstChild("Ragdolled")
                        setTargetIndicator(tRag and tRag.Value == true)
                        if not checkAlive(target) or not Settings.Loop.ownershipKickActive or hasOwnership(target) or targetHRP.AssemblyLinearVelocity.Magnitude > 500 then
                            RemoteDispatcher:Fire(destroyGrabLineEvent, targetHRP)
                            task.wait()
                            local bv = targetHRP:FindFirstChild("SkyVelocity")
                            if not bv then
                                bv = Instance.new("BodyVelocity")
                                bv.Name = "SkyVelocity"
                                bv.Velocity = Vector3.new(0, 100000000000000, 0)
                                bv.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
                                bv.Parent = targetHRP
                            end
                            break
                        end
                        task.wait()
                        if not Utility.isLocalAlive() then break end
                        local myRoot = Utility.GetPlayerRootPart()
                        if myRoot and targetHRP and targetHRP.Parent and Utility.isLocalAlive() then
                            if (targetHRP.Position - myRoot.Position).Magnitude > 29 then
                                if ownershipKick.bring then
                                    executeBring(targetHRP, playerCFrame)
                                else
                                    task.wait(0.1)
                                end
                            end
                        end
                    end
                end
            end
            if Utility.isLocalAlive() then
                local myRoot2 = Utility.GetPlayerRootPart()
                if myRoot2 and playerCFrame then
                    myRoot2.CFrame = playerCFrame
                    myRoot2.AssemblyLinearVelocity = Vector3.zero
                    myRoot2.AssemblyAngularVelocity = Vector3.zero
                end
                resumeOwnershipPosLock()
            end
            task.wait(0.1)
        end
        stopFloating()
        local myRoot3 = Utility.GetPlayerRootPart()
        if myRoot3 then
            local pc = Utility.GetPlayerCFrame()
            if pc then myRoot3.CFrame = pc end
        end
    end)
end
local function startOwnershipPalletHammer(isOn, palletName)
    if not ownershipKick.ragdoll then return end
    local function realParent(obj)
        if not obj then return false end
        local ok, res = pcall(function() return obj.Parent ~= nil end)
        return ok and res
    end
    while not Utility.isLocalAlive() do
        if not isOn() or not ownershipKick.ragdoll then return end
        task.wait(0.1)
    end
    if not ownershipKick.ragdoll then return end
    local root = BlobmanBetaFeature.getLocalRoot()
    if not root then return end
    local palletModel = nil
    do
        local inv = BlobmanBetaFeature.getInv()
        if not inv then return end
        local conn
        conn = inv.ChildAdded:Connect(function(toy)
            if toy.Name == "PalletLightBrown" and realParent(toy) then
                palletModel = toy
                conn:Disconnect()
            end
        end)
        task.spawn(function()
            local didSpawn = false
            for _ = 1, 30 do
                if not ownershipKick.ragdoll or not isOn() then break end
                if State.isRespawning then task.wait(0.05) continue end
                if not didSpawn then
                    didSpawn = true
                    pcall(function() SpawnToyRF:InvokeServer("PalletLightBrown", root.CFrame * CFrame.new(0, 5, 0), Vector3.zero) end)
                end
                task.wait(0.05)
            end
        end)
        local t = tick()
        while not palletModel do
            if not ownershipKick.ragdoll or not isOn() then pcall(function() conn:Disconnect() end) break end
            if tick() - t > 5 then pcall(function() conn:Disconnect() end) break end
            task.wait(0.01)
        end
    end
    if not palletModel or not realParent(palletModel) or not ownershipKick.ragdoll then
        if palletModel and realParent(palletModel) then
            pcall(function() DeleteToyRE:FireServer(palletModel) end)
        end
        return
    end
    pcall(function() palletModel:WaitForChild("SoundPart", 5) end)
    local palletPart = pcall(function() return palletModel:FindFirstChild("SoundPart") end) and palletModel:FindFirstChild("SoundPart")
    if not palletPart then return end
    pcall(function() palletModel.Name = palletName end)
    pcall(function() setNetworkOwnerEvent:FireServer(palletPart, palletPart.CFrame) end)
    local SEGMENTS = 8
    local IMPACT_POWER = 10
    local hammerGoingDown = true
    local segmentIndex = 0
    local lastOwnerTime = tick()
    while isOn() and ownershipKick.ragdoll and realParent(palletModel) do
        RunService.Heartbeat:Wait()
        if not Utility.isLocalAlive() then task.wait(0.1) continue end
        if not realParent(palletPart) then break end
        local target = Players:FindFirstChild(ownershipKickTarget)
        local targetChar = target and target.Character
        local targetHrp = targetChar and targetChar:FindFirstChild("HumanoidRootPart")
        if targetHrp then
            if tick() - lastOwnerTime > 1.0 then
                pcall(function() setNetworkOwnerEvent:FireServer(palletPart, palletPart.CFrame) end)
                lastOwnerTime = tick()
            end
            local startPos = targetHrp.Position + Vector3.new(0, 500, 0)
            local endPos = targetHrp.Position
            if hammerGoingDown then
                segmentIndex = segmentIndex + 1
                local alpha = segmentIndex / SEGMENTS
                local nextPos = startPos:Lerp(endPos, alpha)
                pcall(function()
                    palletPart.CFrame = CFrame.new(nextPos)
                    palletPart.AssemblyLinearVelocity = Vector3.new(0, -1500, 0)
                    palletPart.AssemblyAngularVelocity = Vector3.zero
                end)
                for _, part in pairs(palletModel:GetChildren()) do
                    if part:IsA("BasePart") then
                        pcall(function()
                            part.Transparency = 1
                            part.CanCollide = false
                            part.CanQuery = false
                        end)
                    end
                end
                if segmentIndex >= SEGMENTS then
                    pcall(function() palletPart.AssemblyLinearVelocity = Vector3.new(0, -IMPACT_POWER, 0) end)
                    hammerGoingDown = false
                end
            else
                pcall(function()
                    palletPart.CFrame = CFrame.new(startPos)
                    palletPart.AssemblyLinearVelocity = Vector3.zero
                end)
                segmentIndex = 0
                hammerGoingDown = true
            end
        else
            local myChar = LocalPlayer.Character
            local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
            if myRoot then
                pcall(function()
                    palletPart.CFrame = myRoot.CFrame * CFrame.new(0, 10, 0)
                    palletPart.AssemblyLinearVelocity = Vector3.zero
                end)
            end
        end
    end
    if palletModel and realParent(palletModel) then
        pcall(function() DeleteToyRE:FireServer(palletModel) end)
    end
end
local ownershipKickV2Task = nil
local ownershipKickV2FloatConn = nil
local ownershipKickV2ZeroVelConn = nil
local palletRagdollTask = nil
ownershipKick["Loop Kick V2"] = function(v)
