        if ownershipKickV2Task then task.cancel(ownershipKickV2Task) ownershipKickV2Task = nil end
        if ownershipKickV2FloatConn then ownershipKickV2FloatConn:Disconnect() ownershipKickV2FloatConn = nil end
        if ownershipKickV2ZeroVelConn then ownershipKickV2ZeroVelConn:Disconnect() ownershipKickV2ZeroVelConn = nil end
        Settings.Loop.palletRagdollActive = false
        if palletRagdollTask then task.cancel(palletRagdollTask) palletRagdollTask = nil end
        task.spawn(function()
            local inv = BlobmanBetaFeature.getInv()
            if inv then
                local pallet = inv:FindFirstChild("PalletForRagdoll")
                if pallet then pcall(function() RemoteDispatcher:Fire(DeleteToyRE, pallet) end) end
            end
            cleanupOwnershipKickTarget()
        end)
        return
    end
    if not ownershipKickTarget then warn("[OK] Select target") Settings.Loop.ownershipKickV2Active = false return end
    ownershipKickV2Task = task.spawn(function()
        local GE = ReplicatedStorage:WaitForChild("GrabEvents")
        local setNE = GE:WaitForChild("SetNetworkOwner")
        local destroyGL = GE:WaitForChild("DestroyGrabLine")
        local createGL = GE:WaitForChild("CreateGrabLine")
        local function destroyKickConstraints(tRoot)
            if not tRoot then return end
            local bp = tRoot:FindFirstChild("KickBodyPos")
            if bp then pcall(function() bp:Destroy() end) end
            local bg = tRoot:FindFirstChild("KickBodyGyro")
            if bg then pcall(function() bg:Destroy() end) end
        end
        local function createKickConstraints(tRoot)
            if not tRoot or not tRoot.Parent then return end
            for _, v in pairs(tRoot:GetChildren()) do
                if v:IsA("BodyPosition") or v:IsA("BodyGyro") then pcall(function() v:Destroy() end) end
            end
            local bodyPos = Instance.new("BodyPosition")
            bodyPos.Name = "KickBodyPos"
            bodyPos.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
            bodyPos.D = 5000
            bodyPos.P = 1500000
            bodyPos.Position = tRoot.Position
            bodyPos.Parent = tRoot
            local bodyGyro = Instance.new("BodyGyro")
            bodyGyro.Name = "KickBodyGyro"
            bodyGyro.MaxTorque = Vector3.new(math.huge, math.huge, math.huge)
            bodyGyro.D = 500
            bodyGyro.P = 50000
            bodyGyro.CFrame = tRoot.CFrame
            bodyGyro.Parent = tRoot
        end
        local function startFloating()
            if ownershipKickV2FloatConn then return end
            ownershipKickV2FloatConn = RunService.Stepped:Connect(function()
                if not Utility.isLocalAlive() then return end
                local ch = LocalPlayer.Character
                if ch then
                    for _, p in pairs(ch:GetChildren()) do
                        if p:IsA("BasePart") and p.CanCollide then p.CanCollide = false end
                    end
                end
            end)
        end
        local function stopFloating()
            if ownershipKickV2FloatConn then ownershipKickV2FloatConn:Disconnect() ownershipKickV2FloatConn = nil end
        end
        local function checkAlive(t)
            if not t or t == LocalPlayer then return false end
            if isProtectedPlayer(t.Name) then return false end
            if not t.Character then return false end
            local hrp = t.Character:FindFirstChild("HumanoidRootPart")
            local hum = t.Character:FindFirstChildOfClass("Humanoid")
            if not hrp or not hum or hum.Health <= 0 then return false end
            return true
        end



        local gotOwnership = false
        while Settings.Loop.ownershipKickV2Active do
            if not Utility.isLocalAlive() then task.wait(0.2) continue end
            local target = Players:FindFirstChild(ownershipKickTarget)
            if not target or not target.Character then RunService.RenderStepped:Wait() continue end
            local myChar = LocalPlayer.Character
            local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
            if not myRoot or not Utility.isLocalAlive() then RunService.RenderStepped:Wait() continue end
            local savedPos = myRoot.CFrame
            rememberOwnershipSavedPos(savedPos)
            local tChar = target.Character
            local tRoot = tChar and tChar:FindFirstChild("HumanoidRootPart")
            local tHum = tChar and tChar:FindFirstChildOfClass("Humanoid")
            if not tRoot or not tHum or tHum.Health <= 0 then RunService.RenderStepped:Wait() continue end

            local pips = Workspace:FindFirstChild("PlotItems") and Workspace.PlotItems:FindFirstChild("PlayersInPlots")
            if pips then
                local inSafe = false
                for _, child in pairs(pips:GetChildren()) do
                    if child.Name == ownershipKickTarget then inSafe = true break end
                    if child:IsA("ObjectValue") and child.Value and child.Value.Name == ownershipKickTarget then inSafe = true break end
                    if child:IsA("StringValue") and child.Value == ownershipKickTarget then inSafe = true break end
                end
                if inSafe then
                    while Settings.Loop.ownershipKickV2Active do
                        RunService.RenderStepped:Wait()
                        local stillInSafe = false
                        pips = Workspace:FindFirstChild("PlotItems") and Workspace.PlotItems:FindFirstChild("PlayersInPlots")
                        if pips then
                            for _, child in pairs(pips:GetChildren()) do
                                if child.Name == ownershipKickTarget then stillInSafe = true break end
                                if child:IsA("ObjectValue") and child.Value and child.Value.Name == ownershipKickTarget then stillInSafe = true break end
                                if child:IsA("StringValue") and child.Value == ownershipKickTarget then stillInSafe = true break end
                            end
                        end
                        if not stillInSafe then break end
                    end
                end
            end

            -- Initial bring if target is > 29 studs away and bring is enabled
            if (tRoot.Position - myRoot.Position).Magnitude > 29 then
                if ownershipKick.bring then
                    executeBring(tRoot, savedPos)
                    task.wait(0.05)
                else
                    task.wait(0.1)
                    continue
                end
            end

            gotOwnership = false
            for i = 1, 200 do
                if not Settings.Loop.ownershipKickV2Active then break end
                target = Players:FindFirstChild(ownershipKickTarget)
                if not target or not target.Character then break end
                myChar = LocalPlayer.Character
                myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
                if not myRoot then break end
                tChar = target.Character
                tRoot = tChar and tChar:FindFirstChild("HumanoidRootPart")
                tHum = tChar and tChar:FindFirstChildOfClass("Humanoid")
                if not tRoot or not tHum or tHum.Health <= 0 then break end

                if tHum.SeatPart ~= nil then
                    destroyKickConstraints(tRoot)
                    for _, v in pairs(tRoot:GetChildren()) do
                        if v:IsA("BodyPosition") or v:IsA("BodyGyro") or v:IsA("BodyVelocity") then
                            pcall(function() v:Destroy() end)
                        end
                    end
                    if ownershipKick.bring and not isAntiGucciActive() and myRoot and myRoot.Parent then
                        myRoot.CFrame = tRoot.CFrame * CFrame.new(0, 0, 3)
                        myRoot.AssemblyLinearVelocity = Vector3.zero
                        myRoot.AssemblyAngularVelocity = Vector3.zero
                    end
                    for _ = 1, 3 do
                        pcall(function() RemoteDispatcher:Fire(setNE, tRoot, tRoot.CFrame) end)
                    end
                    RunService.Heartbeat:Wait()
                    continue
                end

                if TargetPCLDManager.checkDesync(target) then
                    destroyKickConstraints(tRoot)
                    task.wait(0.1)
                    break
                end

                local head = tChar:FindFirstChild("Head")
                if not head then break end
                local partOwner = head:FindFirstChild("PartOwner")
                if partOwner and partOwner.Value == LocalPlayer.Name then
                    gotOwnership = true
                    break
                end

                if (tRoot.Position - myRoot.Position).Magnitude > 29 then
                    if ownershipKick.bring then
                        executeBring(tRoot, savedPos)
                        task.wait(0.05)
                    else
                        task.wait(0.1)
                        continue
                    end
                end

                pcall(function() RemoteDispatcher:Fire(setNE, tRoot, tRoot.CFrame) end)
                RunService.RenderStepped:Wait()
            end

            if not gotOwnership or not Settings.Loop.ownershipKickV2Active then continue end

            target = Players:FindFirstChild(ownershipKickTarget)
            if not target or not target.Character then continue end
            myChar = LocalPlayer.Character
            myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
            if not myRoot then continue end
            tChar = target.Character
            tRoot = tChar and tChar:FindFirstChild("HumanoidRootPart")
            tHum = tChar and tChar:FindFirstChildOfClass("Humanoid")
            if not tRoot or not tHum or tHum.Health <= 0 then continue end

            for _, v in pairs(tRoot:GetChildren()) do
                if v:IsA("BodyPosition") or v:IsA("BodyGyro") or v:IsA("BodyVelocity") then
                    pcall(function() v:Destroy() end)
                end
            end

            myRoot.CFrame = savedPos
            myRoot.AssemblyLinearVelocity = Vector3.zero
            myRoot.AssemblyAngularVelocity = Vector3.zero
            pcall(function() RemoteDispatcher:Fire(setNE, tRoot, tRoot.CFrame) end)
            pcall(function() RemoteDispatcher:Fire(destroyGL, tRoot) end)

            local ragdollFrame = 0
            local ragdollDestroyInterval = 6 + math.random(7)
            local wasRagdolled = false
            local notRagdolledSince = nil
            local burstFrame = 0

            while Settings.Loop.ownershipKickV2Active do
                if not Utility.isLocalAlive() then
                    task.wait(0.2)
                    break
                end
                target = Players:FindFirstChild(ownershipKickTarget)
                if not target or not target.Character then task.wait(0.1) break end
                myChar = LocalPlayer.Character
                myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
                if not myRoot or not Utility.isLocalAlive() then task.wait(0.1) break end
                tChar = target.Character
                tRoot = tChar and tChar:FindFirstChild("HumanoidRootPart")
                tHum = tChar and tChar:FindFirstChildOfClass("Humanoid")
                if not tRoot or not tHum or tHum.Health <= 0 then task.wait(0.1) break end

                if tHum.SeatPart ~= nil then
                    destroyKickConstraints(tRoot)
                    for _, v in pairs(tRoot:GetChildren()) do
                        if v:IsA("BodyPosition") or v:IsA("BodyGyro") or v:IsA("BodyVelocity") then
                            pcall(function() v:Destroy() end)
                        end
                    end
                    if ownershipKick.bring and not isAntiGucciActive() and myRoot and myRoot.Parent then
                        myRoot.CFrame = tRoot.CFrame * CFrame.new(0, 0, 3)
                        myRoot.AssemblyLinearVelocity = Vector3.zero
                        myRoot.AssemblyAngularVelocity = Vector3.zero
                    end
                    for _ = 1, 3 do
                        pcall(function() RemoteDispatcher:Fire(setNE, tRoot, tRoot.CFrame) end)
                    end
                    RunService.Heartbeat:Wait()
                    continue
                end

                if TargetPCLDManager.checkDesync(target) then
                    destroyKickConstraints(tRoot)
                    for _, v in pairs(tRoot:GetChildren()) do
                        if v:IsA("BodyPosition") or v:IsA("BodyGyro") or v:IsA("BodyVelocity") then
                            pcall(function() v:Destroy() end)
                        end
                    end
                    RunService.Heartbeat:Wait()
                    break
                end

                local myHead = myChar:FindFirstChild("Head")
                local dist = (tRoot.Position - myRoot.Position).Magnitude
                if dist > 29 then
                    if not ownershipKick.bring then
                        task.wait(0.1)
                        continue
                    end
                    notRagdolledSince = nil
                    wasRagdolled = false
                    ragdollFrame = 0
                    executeBring(tRoot, savedPos)
                    task.wait(0.05)
                end

                tHum.Sit = true
                tHum.AutoRotate = false
                pcall(function() tHum:ChangeState(Enum.HumanoidStateType.Physics) end)
                local ragdolled = tHum:FindFirstChild("Ragdolled")
                local isRagdolled = ragdolled and ragdolled.Value == true
                ensureTargetIndicator(target)
                setTargetIndicator(isRagdolled)
                createKickConstraints(tRoot)
                local bp = tRoot:FindFirstChild("KickBodyPos")
                if bp then
                    bp.Position = (myHead and myHead.Position or myRoot.Position) + myRoot.CFrame:VectorToWorldSpace(Vector3.new(0, 15, 0))
                end
                local bg = tRoot:FindFirstChild("KickBodyGyro")
                if bg then bg.CFrame = CFrame.Angles(0, 0, 0) end

                pcall(function() RemoteDispatcher:Fire(setNE, tRoot, tRoot.CFrame) end)
                burstFrame = burstFrame + 1
                if burstFrame >= 2 then
                    burstFrame = 0
                    for _ = 1, 2 do
                        pcall(function() RemoteDispatcher:Fire(setNE, tRoot, tRoot.CFrame) end)
                        pcall(function() RemoteDispatcher:Fire(destroyGL, tRoot) end)
                    end
                end

                if isRagdolled then
                    ragdollFrame = ragdollFrame + 1
                    if ragdollFrame >= ragdollDestroyInterval then
                        ragdollFrame = 0
                        ragdollDestroyInterval = 6 + math.random(7)
                        pcall(function() RemoteDispatcher:Fire(setNE, tRoot, tRoot.CFrame) end)
                        pcall(function() RemoteDispatcher:Fire(destroyGL, tRoot) end)
                    end
                elseif wasRagdolled then
                    pcall(function() RemoteDispatcher:Fire(setNE, tRoot, tRoot.CFrame) end)
                    pcall(function() RemoteDispatcher:Fire(createGL, tRoot, Vector3.zero, tRoot.Position, false) end)
                    pcall(function() RemoteDispatcher:Fire(destroyGL, tRoot) end)
                end
                wasRagdolled = isRagdolled
                RunService.Heartbeat:Wait()
            end

            stopFloating()
            if ownershipKickV2ZeroVelConn then ownershipKickV2ZeroVelConn:Disconnect() ownershipKickV2ZeroVelConn = nil end
            destroyKickConstraints(tRoot)
        end
        local cleanupTarget = Players:FindFirstChild(ownershipKickTarget)
        local cleanupRoot = cleanupTarget and cleanupTarget.Character and cleanupTarget.Character:FindFirstChild("HumanoidRootPart")
        destroyKickConstraints(cleanupRoot)
        stopFloating()
        if ownershipKickV2ZeroVelConn then ownershipKickV2ZeroVelConn:Disconnect() ownershipKickV2ZeroVelConn = nil end
        local myRoot3 = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
        if myRoot3 then
            myRoot3.AssemblyLinearVelocity = Vector3.zero
            myRoot3.AssemblyAngularVelocity = Vector3.zero
        end
        local target = Players:FindFirstChild(ownershipKickTarget)
        local tChar2 = target and target.Character
        local tRoot2 = tChar2 and tChar2:FindFirstChild("HumanoidRootPart")
        local tHum2 = tChar2 and tChar2:FindFirstChildOfClass("Humanoid")
        if tRoot2 then pcall(function() tRoot2.AssemblyLinearVelocity = Vector3.zero end) end
        if tHum2 then pcall(function() tHum2.PlatformStand = false; tHum2.Sit = false end) end
    end)
    if not palletRagdollTask then
        Settings.Loop.palletRagdollActive = true
        palletRagdollTask = task.spawn(function()
            local function isOn()
                return Settings.Loop.palletRagdollActive and Settings.Loop.ownershipKickV2Active
            end
            while isOn() do
                if State.isRespawning then task.wait(0.3) continue end
                startOwnershipPalletHammer(isOn, "PalletForRagdoll")
                if not isOn() then break end
                task.wait(0.1)
            end
        end)
    end
end
local destroyTargetGucciTask = nil
local seatLastSitter = {}
local trackedSeats = {}
local seatTrackerConns = {}

local function addTrackedSeat(seat)
    if not (seat and (seat:IsA("VehicleSeat") or seat:IsA("Seat"))) then return end
    if trackedSeats[seat] then return end
    trackedSeats[seat] = true

    local function checkOccupant()
        local occ = seat.Occupant
        if occ and occ.Parent then
            local occHum = occ.Parent:FindFirstChildOfClass("Humanoid")
            local occChar = occHum and occHum.Parent
            if occChar then
                for _, plr in ipairs(Players:GetPlayers()) do
                    if plr.Character == occChar then
                        seatLastSitter[seat] = plr
                        return
                    end
                end
            end
        end
    end

    local occConn = seat:GetPropertyChangedSignal("Occupant"):Connect(checkOccupant)
    table.insert(seatTrackerConns, occConn)
    checkOccupant()
end

local function hookPlayerSeat(plr)
    if not plr then return end
    local function hookChar(char)
        if not char then return end
        local hum = char:FindFirstChildOfClass("Humanoid")
        if hum then
            local s = hum.SeatPart
            if s and (s:IsA("VehicleSeat") or s:IsA("Seat")) then
                addTrackedSeat(s)
                seatLastSitter[s] = plr
            end
            local conn = hum:GetPropertyChangedSignal("SeatPart"):Connect(function()
                local curSeat = hum.SeatPart
                if curSeat and (curSeat:IsA("VehicleSeat") or curSeat:IsA("Seat")) then
                    addTrackedSeat(curSeat)
                    seatLastSitter[curSeat] = plr
                end
            end)
            table.insert(seatTrackerConns, conn)
        end
    end
    if plr.Character then hookChar(plr.Character) end
    local conn = plr.CharacterAdded:Connect(function(c)
        task.wait(0.1)
        hookChar(c)
    end)
    table.insert(seatTrackerConns, conn)
end

local function startSeatTracker()
    if #seatTrackerConns > 0 then return end
    for _, seat in ipairs(workspace:GetDescendants()) do
        if seat:IsA("VehicleSeat") or seat:IsA("Seat") then
            addTrackedSeat(seat)
        end
    end
    local addedConn = workspace.DescendantAdded:Connect(function(d)
        if d:IsA("VehicleSeat") or d:IsA("Seat") then
            addTrackedSeat(d)
        end
    end)
    table.insert(seatTrackerConns, addedConn)
    local remConn = workspace.DescendantRemoving:Connect(function(d)
        if trackedSeats[d] then
            trackedSeats[d] = nil
            seatLastSitter[d] = nil
        end
    end)
    table.insert(seatTrackerConns, remConn)

    for _, plr in ipairs(Players:GetPlayers()) do
        hookPlayerSeat(plr)
    end
    local plrConn = Players.PlayerAdded:Connect(hookPlayerSeat)
    table.insert(seatTrackerConns, plrConn)

    local lastBackupScan = 0
    local scanConn = RunService.Heartbeat:Connect(function()
        local now = tick()
        if now - lastBackupScan < 0.5 then return end
        lastBackupScan = now
        for seat in pairs(trackedSeats) do
            if not (seat and seat.Parent) then
                trackedSeats[seat] = nil
                seatLastSitter[seat] = nil
            else
                local occ = seat.Occupant
                if occ and occ.Parent then
                    local occHum = occ.Parent:FindFirstChildOfClass("Humanoid")
                    local occChar = occHum and occHum.Parent
                    if occChar then
                        for _, plr in ipairs(Players:GetPlayers()) do
                            if plr.Character == occChar then
                                seatLastSitter[seat] = plr
                                break
                            end
                        end
                    end
                end
            end
        end
    end)
    table.insert(seatTrackerConns, scanConn)
end

local function stopSeatTracker()
    for _, c in ipairs(seatTrackerConns) do
        pcall(function() c:Disconnect() end)
    end
    seatTrackerConns = {}
    trackedSeats = {}
end
local destroyGucciMethod = "Standard"
local function destroyGucciStop()
    if destroyTargetGucciTask then task.cancel(destroyTargetGucciTask) destroyTargetGucciTask = nil end
    stopSeatTracker()
    local myChar = LocalPlayer.Character
    local myHum = myChar and myChar:FindFirstChildOfClass("Humanoid")
    if myHum and myHum.Sit then myHum.Sit = false end
end
local function destroyGucciStart()
    local targetName = ownershipKickTarget
    if not targetName then return end
    local targetPlayer = Players:FindFirstChild(targetName)
    if not targetPlayer or targetPlayer == LocalPlayer then return end
    if destroyGucciMethod == "Input Lag" then
        destroyTargetGucciTask = task.spawn(function()
            local function spawnBlob()
                local myChar = LocalPlayer.Character
                local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
                if not myRoot then return nil end
                local inv = BlobmanBetaFeature.getInv()
                local SpawnedToy = nil
                if inv then
                    local conn
                    conn = inv.ChildAdded:Connect(function(toy)
                        if toy.Name == "CreatureBlobman" and toy:IsA("Model") then
                            SpawnedToy = toy
                            conn:Disconnect()
                        end
                    end)
                    task.spawn(function()
                        pcall(function()
                            RemoteDispatcher:Invoke(SpawnToyRF, "CreatureBlobman", myRoot.CFrame * CFrame.new(0, -1, 8), Vector3.zero)
                        end)
                    end)
                    local t = tick()
                    while not SpawnedToy do
                        if tick() - t > 4 then conn:Disconnect() break end
                        task.wait(0.01)
                    end
                end
                if SpawnedToy then
                    if not SpawnedToy:FindFirstChild("VehicleSeat") then
                        SpawnedToy:WaitForChild("VehicleSeat", 2)
                    end
                    return SpawnedToy
                end
                return nil
            end
            local function sitBlob(blob)
                if not blob then return nil end
                local seat = blob:FindFirstChild("VehicleSeat") or blob:FindFirstChildWhichIsA("VehicleSeat")
                local char = LocalPlayer.Character
                local hum = char and char:FindFirstChild("Humanoid")
                local root = char and char:FindFirstChild("HumanoidRootPart")
                if not seat or not hum or not root then return nil end
                if seat.Occupant ~= hum then
                    root.CFrame = seat.CFrame + Vector3.new(0, 2, 0)
                    task.wait(0.2)
                    pcall(function() seat:Sit(hum) end)
                end
                return seat
            end
            local lastTargetSeat = nil
            local targetLeftSeat = false
            local myBlob = nil
            local seatConn = nil
            local seatConnChar = nil
            local function observeTargetSeat(char)
                if not char then return end
                if seatConnChar == char and seatConn then return end
                if seatConn then pcall(function() seatConn:Disconnect() end) seatConn = nil end
                seatConnChar = char
                local tHum = char:FindFirstChildOfClass("Humanoid")
                if not tHum then return end
                local function update()
                    local s = tHum.SeatPart
                    if s and s:IsA("VehicleSeat") and s.Parent then
                        lastTargetSeat = s
                        targetLeftSeat = false
                    elseif lastTargetSeat then
                        targetLeftSeat = true
                    end
                end
                update()
                seatConn = tHum:GetPropertyChangedSignal("SeatPart"):Connect(update)
            end
            while true do
                if not Utility.isLocalAlive() then
                    lastTargetSeat = nil
                    targetLeftSeat = false
                    task.wait(0.3)
                    continue
                end
                local target = Players:FindFirstChild(targetName)
                local tChar = target and target.Character
                local tHum = tChar and tChar:FindFirstChildOfClass("Humanoid")
                local tRoot = tChar and tChar:FindFirstChild("HumanoidRootPart")
                if not target or not tChar or not tHum or tHum.Health <= 0 then
                    lastTargetSeat = nil
                    targetLeftSeat = false
                    task.wait(0.3)
                    continue
                end
                observeTargetSeat(tChar)
                if targetLeftSeat and lastTargetSeat and lastTargetSeat.Parent and tRoot then
                    if not myBlob or not myBlob.Parent then
                        myBlob = BlobmanBetaFeature.getBlobman()
                            or BlobmanBetaFeature.findAnyBlobman()
                            or spawnBlob()
                        if not myBlob then
                            spawnBlob()
                            task.wait(0.5)
                            myBlob = BlobmanBetaFeature.getBlobman() or spawnBlob()
                        end
                    end
                    if myBlob then
                        sitBlob(myBlob)
                        local scriptObj = myBlob:FindFirstChild("BlobmanSeatAndOwnerScript")
                        if scriptObj then
                            local CG = scriptObj:FindFirstChild("CreatureGrab")
                            local CD = scriptObj:FindFirstChild("CreatureRelease") or scriptObj:FindFirstChild("CreatureDrop")
                            local L_Det = myBlob:FindFirstChild("LeftDetector")
                            local L_Weld = L_Det and L_Det:FindFirstChild("LeftWeld")
                            local R_Det = myBlob:FindFirstChild("RightDetector")
                            local R_Weld = R_Det and R_Det:FindFirstChild("RightWeld")
                            if CG and CD and R_Det and R_Weld then
                                local char = LocalPlayer.Character
                                local root = char and char:FindFirstChild("HumanoidRootPart")
                                local savedPos = root and root.CFrame
                                local bRoot = myBlob:FindFirstChild("HumanoidRootPart")
                                if bRoot then
                                    bRoot.CFrame = tRoot.CFrame
                                    task.wait(0.15)
                                end
                                pcall(function() RemoteDispatcher:Fire(CG, nil, tRoot, R_Weld) end)
                                task.wait(0.02)
                                pcall(function() RemoteDispatcher:Fire(CD, R_Weld) end)
                                task.wait(0.02)
                                pcall(function() RemoteDispatcher:Fire(CG, R_Det, tRoot, L_Weld) end)
                                task.wait(0.02)
                                pcall(function() RemoteDispatcher:Fire(CD, L_Weld) end)
                                task.wait(0.06)
                                local hum = char and char:FindFirstChild("Humanoid")
                                if hum then hum.Sit = false end
                                if root then root.Velocity = Vector3.new(0, 20, 0) end
                                task.wait(0.1)
                                if root and savedPos then
                                    root.CFrame = savedPos
                                    root.Velocity = Vector3.zero
                                end
                            end
                        end
                    end
                end
                task.wait(0.3)
            end
        end)
        return
    end
    destroyTargetGucciTask = task.spawn(function()
        startSeatTracker()
        while true do
            if not Utility.isLocalAlive() then
                task.wait(0.2)
                continue
            end
            local target = Players:FindFirstChild(targetName)
            local tChar = target and target.Character
            local tHum = tChar and tChar:FindFirstChildOfClass("Humanoid")
            local tRoot = tChar and (tChar:FindFirstChild("HumanoidRootPart") or tChar:FindFirstChild("Torso"))
            local myChar = LocalPlayer.Character
            local myHum = myChar and myChar:FindFirstChildOfClass("Humanoid")
            local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")

            if myHum and myRoot and Utility.isLocalAlive() then
                local seatsToDestroy = {}
                local added = {}

                local function considerSeat(seat)
                    if not seat or not seat:IsA("VehicleSeat") and not seat:IsA("Seat") then return end
                    if not seat.Parent or not seat:IsDescendantOf(Workspace) then return end
                    if added[seat] then return end
                    if seatLastSitter[seat] == LocalPlayer then return end
                    added[seat] = true
                    table.insert(seatsToDestroy, seat)
                end

                -- 1. Currently sitting seat
                if tHum and tHum.SeatPart then
                    considerSeat(tHum.SeatPart)
                end

                -- 2. Recorded last sitter seat from tracker
                for seat, plr in pairs(seatLastSitter) do
                    if plr == target then
                        considerSeat(seat)
                    end
                end

                -- 3. Target spawned toys folders (NameSpawnedInToys and variations)
                for _, fName in ipairs({targetName .. "SpawnedInToys", targetName .. "Toys"}) do
                    local toysFolder = Workspace:FindFirstChild(fName)
                    if toysFolder then
                        for _, desc in ipairs(toysFolder:GetDescendants()) do
                            if desc:IsA("VehicleSeat") or desc:IsA("Seat") then
                                considerSeat(desc)
                            end
                        end
                    end
                end

                -- 4. Check tracked seats whose parent model is owned by target
                for seat in pairs(trackedSeats) do
                    if seat and seat.Parent and not added[seat] then
                        local model = seat:FindFirstAncestorOfClass("Model")
                        if model and model ~= Workspace then
                            local hasTargetTag = false
                            for _, tag in ipairs({"PartOwner", "Owner", "OwnerName", "Creator"}) do
                                local v = model:FindFirstChild(tag)
                                if v and tostring(v.Value) == targetName then
                                    hasTargetTag = true
                                    break
                                end
                            end
                            if hasTargetTag then
                                considerSeat(seat)
                            end
                        end
                    end
                end

                -- 5. Proximity fallback: if target is standing right on/near a seat within 15 studs
                if tRoot then
                    for seat in pairs(trackedSeats) do
                        if seat and seat.Parent and seat:IsDescendantOf(Workspace) and not added[seat] then
                            if (seat.Position - tRoot.Position).Magnitude <= 15 then
                                considerSeat(seat)
                            end
                        end
                    end
                end

                -- Process destroying seats
                for _, seat in ipairs(seatsToDestroy) do
                    if not Utility.isLocalAlive() then break end
                    if seat and seat.Parent and seat:IsDescendantOf(Workspace) then
                        local safeSpot = myRoot.CFrame
                        myRoot.CFrame = seat.CFrame + Vector3.new(0, 1.5, 0)
                        myRoot.Velocity = Vector3.zero
                        myRoot.AssemblyLinearVelocity = Vector3.zero

                        -- Sit on the seat
                        pcall(function() seat:Sit(myHum) end)
                        local sitWait = tick()
                        while tick() - sitWait < 0.35 do
                            if not Utility.isLocalAlive() or not seat.Parent then break end
                            if myHum.SeatPart == seat then break end
                            pcall(function() seat:Sit(myHum) end)
                            task.wait(0.05)
                        end

                        if not Utility.isLocalAlive() then break end
                        seatLastSitter[seat] = LocalPlayer
                        myHum.Sit = false

                        task.wait(0.05)
                        if Utility.isLocalAlive() and myRoot and myRoot.Parent then
                            myRoot.CFrame = safeSpot
                            myRoot.Velocity = Vector3.zero
                            myRoot.AssemblyLinearVelocity = Vector3.zero
                        end
                        task.wait(0.05)
                    end
                end
            end
            task.wait(0.2)
        end
    end)
end
ownershipKickSec:Dropdown({Text = "Destroy Gucci Method", Flag = "OwnershipDestroyGucciMethod", List = {"Standard", "Input Lag"}, Default = "Standard", Callback = function(value)
    destroyGucciMethod = value
    if destroyTargetGucciTask then
        destroyGucciStop()
        destroyGucciStart()
    end
end})
ownershipKickSec:Toggle({Text = "Destroy Gucci", Flag = "DestroyTargetGucci", Default = false, Callback = function(v)
