            end
            pcall(function()
                tRoot.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                tRoot.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
            end)
        end
        if tChar then
            local tHum = tChar:FindFirstChild("Humanoid")
            if tHum then
