                            pcall(function() v:Destroy() end)
                        end
                    end
                    local bodyPos = Instance.new("BodyPosition")
                    bodyPos.Name = "KickBodyPos"
                    bodyPos.MaxForce = Vector3.new(1000000, 1000000, 1000000)
                    bodyPos.D = 500
                    bodyPos.P = 50000
                    bodyPos.Position = tRoot.Position
                    bodyPos.Parent = tRoot
                    local bodyGyro = Instance.new("BodyGyro")
                    bodyGyro.Name = "KickBodyGyro"
                    bodyGyro.MaxTorque = Vector3.new(1000000, 1000000, 1000000)
                    bodyGyro.D = 500
                    bodyGyro.P = 50000
                    bodyGyro.CFrame = tRoot.CFrame
                    bodyGyro.Parent = tRoot
                    attachments.bodyPos = bodyPos
                    attachments.bodyGyro = bodyGyro
                end
            else
                pcall(function()
                    tHum.Sit = true
                    tHum.AutoRotate = false
                end)
                pcall(function() tHum:ChangeState(Enum.HumanoidStateType.Physics) end)
                pcall(function() ensureTargetIndicator(target) end)
                pcall(function()
                    local v3Rag = tHum:FindFirstChild("Ragdolled")
                    setTargetIndicator(v3Rag and v3Rag.Value == true)
                end)
                if not pausedRespawn() then
                    pcall(function() RemoteDispatcher:Fire(setNetworkOwnerEvent, tRoot, tRoot.CFrame) end)
                    local now = tick()
                    if now - lastGL >= GRAB_INTERVAL then
                        lastGL = now
                        pcall(function() RemoteDispatcher:Fire(grabEventsFolder.CreateGrabLine, tRoot, Vector3.zero, tRoot.Position, false) end)
                        pcall(function() RemoteDispatcher:Fire(destroyGrabLineEvent, tRoot) end)
                    end
                end
                if pausedRespawn() or not localCharValid() then
                    cleanupPhysicsObjects()
                    isGrabbing = false
                    startTime = nil
                    checkStartTime = nil
                    task.wait(0.15)
                    return
                end
                if attachments.bodyPos then
                    pcall(function()
                        attachments.bodyPos.Position = (lastMyRoot.CFrame * CFrame.new(5, 16, 2)).Position
                        if tRoot and tRoot.Parent then tRoot.AssemblyLinearVelocity = ZERO_VECTOR end
                    end)
                end
                if attachments.bodyGyro then
                    pcall(function()
                        v3SpinAngle = v3SpinAngle + V3_SPIN_SPEED
                        attachments.bodyGyro.CFrame = CFrame.Angles(0, v3SpinAngle, 0)
                    end)
                end
                if not checkStartTime then checkStartTime = tick() + 0.25 end
                if checkStartTime and tick() >= checkStartTime then
                    local tRootOk, tRootAlive = pcall(function() return tRoot.Parent ~= nil end)
                    if not tRoot or not tRootOk or not tRootAlive then cleanupPhysicsObjects() isGrabbing = false startTime = nil checkStartTime = nil return end
                    local dist = (lastMyRoot.Position - tRoot.Position).Magnitude
                    if dist > MAX_DISTANCE then
                        if pausedRespawn() then
                            cleanupPhysicsObjects()
                            isGrabbing = false
                            startTime = nil
                            checkStartTime = nil
                            task.wait(0.15)
                            return
                        end
                        if not ownershipKick.bring then
                            task.wait(0.1)
                            return
                        end
                        cleanupPhysicsObjects()
                        isGrabbing = false
                        startTime = tick()
                        checkStartTime = nil
                        executeBring(tRoot, savedPos)
                        return
                    end
                end
            end
            end)
        end
        cleanupPhysicsObjects()
        destroyTargetIndicator()
        pcall(function()
            if lastMyRoot and lastMyRoot.Parent then
                if savedPos then lastMyRoot.CFrame = savedPos end
                lastMyRoot.AssemblyLinearVelocity = Vector3.zero
                lastMyRoot.AssemblyAngularVelocity = Vector3.zero
            end
        end)
    end)
