            return r and true or false
        end
        local function pausedRespawn()
            return not Utility.isLocalAlive()
        end
        while Settings.Loop.ownershipKickV6Active do
            pcall(function()
            RunService.Stepped:Wait()
            if pausedRespawn() then
                cleanupPhysicsObjects()
                isGrabbing = false
                startTime = nil
                checkStartTime = nil
                savedPos = nil
                lastMyRoot = nil
                task.wait(0.2)
                return
            end
            if not isTargetAlive() then
                cleanupPhysicsObjects()
                task.wait(0.5)
                return
            end
            local pips = Workspace:FindFirstChild("PlotItems") and Workspace.PlotItems:FindFirstChild("PlayersInPlots")
            if pips then
                local inSafe = false
                for _, child in pairs(pips:GetChildren()) do
                    if child.Name == ownershipKickTarget then inSafe = true break end
                    if child:IsA("ObjectValue") and child.Value and child.Value.Name == ownershipKickTarget then inSafe = true break end
                    if child:IsA("StringValue") and child.Value == ownershipKickTarget then inSafe = true break end
                end
                if inSafe then
                    while Settings.Loop.ownershipKickV6Active do
                        task.wait(0.5)
                        local stillInSafe = false
                        pips = Workspace:FindFirstChild("PlotItems") and Workspace.PlotItems:FindFirstChild("PlayersInPlots")
                        if pips then
                            for _, child in pairs(pips:GetChildren()) do
                                if child.Name == ownershipKickTarget then stillInSafe = true break end
                                if child:IsA("ObjectValue") and child.Value and child.Value.Name == ownershipKickTarget then stillInSafe = true break end
                                if child:IsA("StringValue") and child.Value == ownershipKickTarget then stillInSafe = true break end
                            end
                        end
                        if not stillInSafe then break end
                    end
                end
            end
            myChar = LocalPlayer.Character
            myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
            if not myRoot then return end
            if myRoot ~= lastMyRoot then
                lastMyRoot = myRoot
                isGrabbing = false
                startTime = nil
                checkStartTime = nil
                cleanupPhysicsObjects()
                if myRoot:IsDescendantOf(Workspace) then
                    savedPos = myRoot.CFrame
                end
            end
            local tChar = target.Character
            local tHum = tChar and tChar:FindFirstChild("Humanoid")
            local tRoot = currentTargetRoot
            if not tChar or not tHum or not tRoot or tHum.Health <= 0 then task.wait(0.1) return end
            if tHum.SeatPart ~= nil then
                cleanupPhysicsObjects()
                isGrabbing = false
                startTime = nil
                checkStartTime = nil
                if ownershipKick.bring and not isAntiGucciActive() and myRoot and myRoot.Parent then
                    myRoot.CFrame = tRoot.CFrame * CFrame.new(0, 0, 3)
                    myRoot.AssemblyLinearVelocity = ZERO_VECTOR
                    myRoot.AssemblyAngularVelocity = ZERO_VECTOR
                end
                for _ = 1, 3 do
                    pcall(function() RemoteDispatcher:Fire(setNetworkOwnerEvent, tRoot, tRoot.CFrame) end)
                end
                task.wait(0.05)
                return
            end
            if TargetPCLDManager.checkDesync(target) then
                cleanupPhysicsObjects()
                isGrabbing = false
                startTime = nil
                checkStartTime = nil
                task.wait(0.1)
                return
            end
            if not isGrabbing then
                if not ownershipKick.bring and (tRoot.Position - myRoot.Position).Magnitude > 29 then
                    task.wait(0.05)
                    return
                end
                if not startTime then startTime = tick() end
                if tick() - startTime > GRAB_TIMEOUT then
                    isGrabbing = true
                    startTime = nil
                    myRoot.CFrame = savedPos
                    myRoot.AssemblyLinearVelocity = ZERO_VECTOR
                    for _, v in pairs(tRoot:GetChildren()) do
                        if v:IsA("BodyPosition") or v:IsA("BodyGyro") or v:IsA("BodyVelocity") then
                            pcall(function() v:Destroy() end)
                        end
                    end
                    local bodyPos = Instance.new("BodyPosition")
                    bodyPos.Name = "KickBodyPos"
                    bodyPos.MaxForce = Vector3.new(1000000, 1000000, 1000000)
                    bodyPos.D = 500
                    bodyPos.P = 50000
                    bodyPos.Position = tRoot.Position
                    bodyPos.Parent = tRoot
                    local bodyGyro = Instance.new("BodyGyro")
                    bodyGyro.Name = "KickBodyGyro"
                    bodyGyro.MaxTorque = Vector3.new(1000000, 1000000, 1000000)
                    bodyGyro.D = 500
                    bodyGyro.P = 50000
                    bodyGyro.CFrame = tRoot.CFrame
                    bodyGyro.Parent = tRoot
                    attachments.bodyPos = bodyPos
                    attachments.bodyGyro = bodyGyro
                end
            else
                tHum.Sit = true
                tHum.AutoRotate = false
                pcall(function() tHum:ChangeState(Enum.HumanoidStateType.Physics) end)
                ensureTargetIndicator(target)
                local v6Rag = tHum:FindFirstChild("Ragdolled")
                setTargetIndicator(v6Rag and v6Rag.Value == true)
                if not pausedRespawn() then
                    pcall(function() RemoteDispatcher:Fire(setNetworkOwnerEvent, tRoot, tRoot.CFrame) end)
                    loopKickV6FrameCount = loopKickV6FrameCount + 1
                    if loopKickV6FrameCount >= 5 then
                        loopKickV6FrameCount = 0
                        pcall(function() RemoteDispatcher:Fire(destroyGrabLineEvent, tRoot) end)
                    end
                end
                myChar = LocalPlayer.Character
                if pausedRespawn() or not myChar then
                    cleanupPhysicsObjects()
                    isGrabbing = false
                    startTime = nil
                    checkStartTime = nil
                    task.wait(0.15)
                    return
                end
                myRoot = myChar:FindFirstChild("HumanoidRootPart")
                if not myRoot then return end
                if attachments.bodyPos and myRoot then
                    attachments.bodyPos.Position = (myRoot.CFrame * CFrame.new(5, 16, 2)).Position
                    if tRoot and tRoot.Parent then tRoot.AssemblyLinearVelocity = ZERO_VECTOR end
                end
                if attachments.bodyGyro then
                    attachments.bodyGyro.CFrame = myRoot.CFrame
                end
                if not checkStartTime then checkStartTime = tick() + 0.25 end
                if checkStartTime and tick() >= checkStartTime then
                    if not tRoot or not tRoot.Parent then cleanupPhysicsObjects() isGrabbing = false startTime = nil checkStartTime = nil return end
                    local dist = (myRoot.Position - tRoot.Position).Magnitude
                    if dist > MAX_DISTANCE then
                        if pausedRespawn() then
                            cleanupPhysicsObjects()
                            isGrabbing = false
                            startTime = nil
                            checkStartTime = nil
                            task.wait(0.15)
                            return
                        end
                        if not ownershipKick.bring then
                            task.wait(0.1)
                            return
                        end
                        cleanupPhysicsObjects()
                        isGrabbing = false
                        startTime = tick()
                        checkStartTime = nil
                        loopKickV6FrameCount = 0
                        executeBring(tRoot, savedPos)
                        return
                    end
                end
            end
            end)
        end
        cleanupPhysicsObjects()
        destroyTargetIndicator()
        if myRoot and myRoot.Parent and savedPos then
            pcall(function() myRoot.CFrame = savedPos myRoot.AssemblyLinearVelocity = Vector3.zero end)
        end
        resumeOwnershipPosLock()
    end)
end
local loopKickV7Task = nil
local loopKickV7FpsConn = nil
local function cleanupOwnershipKickV7Target()
    local target = ownershipKickTarget and Players:FindFirstChild(ownershipKickTarget)
    if not target or not target.Character then return end
    local targetRoot = target.Character:FindFirstChild("HumanoidRootPart")
    if not targetRoot then return end
    for _, child in pairs(targetRoot:GetChildren()) do
        if child:IsA("BodyPosition") or child:IsA("BodyGyro") then
            pcall(function() child:Destroy() end)
        end
    end
    pcall(function()
        targetRoot.AssemblyLinearVelocity = Vector3.zero
        targetRoot.AssemblyAngularVelocity = Vector3.zero
    end)
end
ownershipKick["Loop Kick V7"] = function(v)
    Settings.Loop.ownershipKickV7Active = v
    if not v then
        Settings.Loop.ownershipKickV7Active = false
        if loopKickV7Task then
            task.cancel(loopKickV7Task)
            loopKickV7Task = nil
        end
        if loopKickV7FpsConn then
            loopKickV7FpsConn:Disconnect()
            loopKickV7FpsConn = nil
        end
        cleanupOwnershipKickV7Target()
        return
    end
    if not ownershipKickTarget then
        Settings.Loop.ownershipKickV7Active = false
        pcall(function()
            library:Notify({Title = "Ownership Kick", Description = "Please select a target first!", Time = 3})
        end)
        ownershipKick.on = false
        pcall(function()
            if library._flagSetters and library._flagSetters["OwnershipKick"] then
                library._flagSetters["OwnershipKick"](false)
            end
        end)
        return
    end
    loopKickV7Task = task.spawn(function()
        local GE = ReplicatedStorage:FindFirstChild("GrabEvents")
        if not GE then
            Settings.Loop.ownershipKickV7Active = false
            return
        end
        local myChar = LocalPlayer.Character
        local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
        if not myRoot then
            Settings.Loop.ownershipKickV7Active = false
            return
        end
        local savedPos = myRoot.CFrame
        rememberOwnershipSavedPos(savedPos)
        local dragging = false
        local grabStartTime = 0
        local checkStartTime = 0
        local currentFPS = 60
        local bodyPos = nil
        local bodyGyro = nil
        loopKickV7FpsConn = RunService.RenderStepped:Connect(function(dt)
            currentFPS = 1 / dt
        end)
        local function cleanupBodies()
            pcall(function()
                if bodyPos then bodyPos:Destroy() bodyPos = nil end
                if bodyGyro then bodyGyro:Destroy() bodyGyro = nil end
            end)
        end
        local function createBodies(targetRoot, pos)
            cleanupBodies()
            for _, child in pairs(targetRoot:GetChildren()) do
                if child:IsA("BodyPosition") or child:IsA("BodyGyro") then
                    pcall(function() child:Destroy() end)
                end
            end
            bodyPos = Instance.new("BodyPosition")
            bodyPos.MaxForce = Vector3.new(9e9, 9e9, 9e9)
            bodyPos.D = 100
            bodyPos.Position = pos
            bodyPos.Parent = targetRoot
            bodyGyro = Instance.new("BodyGyro")
            bodyGyro.MaxTorque = Vector3.new(9e9, 9e9, 9e9)
            bodyGyro.D = 100
            bodyGyro.CFrame = CFrame.new(pos)
            bodyGyro.Parent = targetRoot
        end
        while Settings.Loop.ownershipKickV7Active do
            local target = Players:FindFirstChild(ownershipKickTarget)
            if not target or not target.Parent then
                cleanupBodies()
                break
            end
            myChar = LocalPlayer.Character
            myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
            local targetChar = target.Character
            local targetRoot = targetChar and targetChar:FindFirstChild("HumanoidRootPart")
            local targetHum = targetChar and targetChar:FindFirstChild("Humanoid")
            if targetRoot and targetHum and targetHum.Health > 0 and myRoot then
                if not dragging then
                    if (targetRoot.Position - myRoot.Position).Magnitude > 29 then
                        if ownershipKick.bring then
                            executeBring(targetRoot, savedPos)
                        else
                            task.wait(0.1)
                            continue
                        end
                    end
                    pauseOwnershipPosLock()
                    cleanupBodies()
                    checkStartTime = 0
                    if not isMyCharacterPart(targetRoot) then
                        pcall(function()
                            targetHum.PlatformStand = true
                            targetHum.Sit = true
                            if GE.SetNetworkOwner then GE.SetNetworkOwner:FireServer(targetRoot, targetRoot.CFrame) end
                            if GE.SetNetworkOwner then GE.SetNetworkOwner:FireServer(targetRoot, targetRoot.CFrame) end
                            if GE.DestroyGrabLine then GE.DestroyGrabLine:FireServer(targetRoot) end
                        end)
                    end
                    myRoot.AssemblyLinearVelocity = Vector3.zero
                    myRoot.AssemblyAngularVelocity = Vector3.zero
                    if grabStartTime == 0 then grabStartTime = tick() end
                    if tick() - grabStartTime > 0.35 then
                        dragging = true
                        grabStartTime = 0
                        checkStartTime = tick()
                        local lockPos = savedPos * CFrame.new(5, 20, 4)
                        createBodies(targetRoot, lockPos.Position)
                    end
                else
                    if ownershipKick.posLocked then
                        myRoot.CFrame = savedPos
                        myRoot.AssemblyLinearVelocity = Vector3.zero
                        myRoot.AssemblyAngularVelocity = Vector3.zero
                    end
                    resumeOwnershipPosLock()
                    local lockPos = savedPos * CFrame.new(5, 20, 4)
                    if bodyPos and bodyPos.Parent then
                        bodyPos.Position = lockPos.Position
                        if bodyGyro then bodyGyro.CFrame = lockPos end
                    else
                        createBodies(targetRoot, lockPos.Position)
                    end
                    targetHum.PlatformStand = true
                    if not isMyCharacterPart(targetRoot) then
                    pcall(function()
                        if GE.SetNetworkOwner and GE.DestroyGrabLine then
                            if currentFPS > 200 then
                                GE.SetNetworkOwner:FireServer(targetRoot, lockPos)
                                GE.SetNetworkOwner:FireServer(targetRoot, lockPos)
                                GE.DestroyGrabLine:FireServer(targetRoot)
                            elseif currentFPS >= 155 and currentFPS <= 200 then
                                GE.SetNetworkOwner:FireServer(targetRoot, lockPos)
                                GE.SetNetworkOwner:FireServer(targetRoot, lockPos)
                                GE.SetNetworkOwner:FireServer(targetRoot, lockPos)
                                GE.DestroyGrabLine:FireServer(targetRoot)
                            else
                                GE.SetNetworkOwner:FireServer(targetRoot, lockPos)
                                GE.SetNetworkOwner:FireServer(targetRoot, lockPos)
                                GE.SetNetworkOwner:FireServer(targetRoot, lockPos)
                                GE.SetNetworkOwner:FireServer(targetRoot, lockPos)
                                GE.DestroyGrabLine:FireServer(targetRoot)
                            end
                        end
                    end)
                    end
                    if checkStartTime > 0 and tick() - checkStartTime > 0.30 then
                        local currentDist = (targetRoot.Position - lockPos.Position).Magnitude
                        if currentDist > 10 then
                            dragging = false
                            grabStartTime = 0
                            checkStartTime = 0
                            cleanupBodies()
                            if ownershipKick.bring then
                                executeBring(targetRoot, savedPos)
                            end
                        else
                            checkStartTime = tick()
                        end
                    end
                end
            else
                dragging = false
                grabStartTime = 0
                checkStartTime = 0
                cleanupBodies()
            end
            RunService.Heartbeat:Wait()
        end
        if loopKickV7FpsConn then
            loopKickV7FpsConn:Disconnect()
            loopKickV7FpsConn = nil
        end
        cleanupBodies()
        if ownershipKick.posLocked and myRoot and myRoot.Parent then myRoot.CFrame = savedPos end
        resumeOwnershipPosLock()
        loopKickV7Task = nil
    end)
end
local loopLockTask = nil
ownershipKick["Loop Lock (Can Kick Target)"] = function(v)
    Settings.Loop.ownershipKickLoopLockActive = v
    if not v then
        destroyTargetIndicator()
        if loopLockTask then task.cancel(loopLockTask) loopLockTask = nil end
        task.spawn(cleanupOwnershipKickTarget)
        return
    end
    if not ownershipKickTarget then warn("[Loop Lock] Select target") Settings.Loop.ownershipKickLoopLockActive = false return end
