                dragging = false
                grabStartTime = 0
                checkStartTime = 0
                savedPos = nil
                lastMyRoot = nil
                if bringDistConn then pcall(function() task.cancel(bringDistConn) end) bringDistConn = nil end
                bringMonitorStarted = false
                bringNeedReBring = false
                task.wait(0.2)
                continue
            end
            local target = Players:FindFirstChild(ownershipKickTarget)
            if not target or not target.Character or not target.Parent then
                cleanupBodies()
                dragging = false
                grabStartTime = 0
                checkStartTime = 0
                repeat
                    RunService.Heartbeat:Wait()
                    target = Players:FindFirstChild(ownershipKickTarget)
                until not isOn() or (target and target.Character and target.Parent)
                if not isOn() then break end
            end
            local pips = Workspace:FindFirstChild("PlotItems") and Workspace.PlotItems:FindFirstChild("PlayersInPlots")
            if pips then
                local inSafe = false
                for _, child in pairs(pips:GetChildren()) do
                    if child.Name == ownershipKickTarget then inSafe = true break end
                    if child:IsA("ObjectValue") and child.Value and child.Value.Name == ownershipKickTarget then inSafe = true break end
                    if child:IsA("StringValue") and child.Value == ownershipKickTarget then inSafe = true break end
                end
                if inSafe then
                    while isOn() do
                        task.wait(0.5)
                        local stillInSafe = false
                        pips = Workspace:FindFirstChild("PlotItems") and Workspace.PlotItems:FindFirstChild("PlayersInPlots")
                        if pips then
                            for _, child in pairs(pips:GetChildren()) do
                                if child.Name == ownershipKickTarget then stillInSafe = true break end
                                if child:IsA("ObjectValue") and child.Value and child.Value.Name == ownershipKickTarget then stillInSafe = true break end
                                if child:IsA("StringValue") and child.Value == ownershipKickTarget then stillInSafe = true break end
                            end
                        end
                        if not stillInSafe then break end
                    end
                end
            end
            myChar = LocalPlayer.Character
            myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
            if myRoot and myRoot ~= lastMyRoot then
                lastMyRoot = myRoot
                savedPos = myRoot.CFrame
                dragging = false
                grabStartTime = 0
                checkStartTime = 0
                cleanupBodies()
                if bringDistConn then task.cancel(bringDistConn) bringDistConn = nil end
                bringMonitorStarted = false
                bringNeedReBring = false
            end
            local tChar = target.Character
            local tRoot = tChar and tChar:FindFirstChild("HumanoidRootPart")
            local tHum = tChar and tChar:FindFirstChildOfClass("Humanoid")
            if tRoot and tHum and tHum.Health > 0 and myRoot then
                if tHum.SeatPart ~= nil and not isMyCharacterPart(tRoot) then
                    cleanupBodies()
                    dragging = false
                    grabStartTime = 0
                    checkStartTime = 0
                    if bringDistConn then pcall(function() task.cancel(bringDistConn) end) bringDistConn = nil end
                    bringMonitorStarted = false
                    bringNeedReBring = false
                    if ownershipKick.bring and not isAntiGucciActive() and myRoot and myRoot.Parent then
                        myRoot.CFrame = tRoot.CFrame * CFrame.new(0, 0, 3)
                        myRoot.AssemblyLinearVelocity = Vector3.zero
                        myRoot.AssemblyAngularVelocity = Vector3.zero
                    end
                    for _ = 1, 3 do
                        pcall(function() RemoteDispatcher:Fire(setNetworkOwnerEvent, tRoot, tRoot.CFrame) end)
                    end
                    task.wait(0.05)
                    continue
                end
                if TargetPCLDManager.checkDesync(target) then
                    cleanupBodies()
                    dragging = false
                    grabStartTime = 0
                    checkStartTime = 0
                    if bringDistConn then pcall(function() task.cancel(bringDistConn) end) bringDistConn = nil end
                    bringMonitorStarted = false
                    bringNeedReBring = false
                    task.wait(0.1)
                    continue
                end
                if not dragging then
                    if (tRoot.Position - myRoot.Position).Magnitude > 29 and not ownershipKick.bring then
                        RunService.Heartbeat:Wait()
                        continue
                    end
                    cleanupBodies()
                    checkStartTime = 0
                    pcall(function()
                        tHum.PlatformStand = true
                        tHum.Sit = false
                        RemoteDispatcher:Fire(setNetworkOwnerEvent, tRoot, tRoot.CFrame)
                    end)
                    if grabStartTime == 0 then grabStartTime = tick() end
                    if tick() - grabStartTime > 0.2 then
                        dragging = true
                        grabStartTime = 0
                        checkStartTime = tick()
                        if ownershipKick.bring and not isAntiGucciActive() and myRoot and myRoot.Parent and savedPos then
                            myRoot.CFrame = savedPos
                            myRoot.AssemblyLinearVelocity = Vector3.zero
                            myRoot.AssemblyAngularVelocity = Vector3.zero
                        end
                        resumeOwnershipPosLock()
                        local lockPos = (savedPos or myRoot.CFrame) * CFrame.new(5, 16, 2)
                        createBodies(tRoot, lockPos.Position)
                    end
                else
                    if State.isRespawning then
                        cleanupBodies()
                        dragging = false
                        grabStartTime = 0
                        checkStartTime = 0
                        if bringDistConn then pcall(function() task.cancel(bringDistConn) end) bringDistConn = nil end
                        bringMonitorStarted = false
                        bringNeedReBring = false
                        task.wait(0.2)
                        continue
                    end
                    myChar = LocalPlayer.Character
                    myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
                    if not myRoot then continue end
                    if ownershipKick.bring and not bringMonitorStarted then
                        bringMonitorStarted = true
                        bringChecking = true
                        task.defer(function()
                            if not ownershipKick.bring then return end
                            if bringDistConn then task.cancel(bringDistConn) end
                            bringDistConn = task.spawn(function()
                                while ownershipKick.bring and Settings.Loop.ownershipKickLoopLockActive and Utility.isLocalAlive() do
                                    if bringChecking then
                                        local myC = LocalPlayer.Character
                                        local myR = myC and myC:FindFirstChild("HumanoidRootPart")
                                        local tP = Players:FindFirstChild(ownershipKickTarget)
                                        local tC = tP and tP.Character
                                        local tR = tC and tC:FindFirstChild("HumanoidRootPart")
                                        if myR and tR and (tR.Position - myR.Position).Magnitude > 29 then
                                            bringNeedReBring = true
                                        end
                                    end
                                    RunService.RenderStepped:Wait()
                                end
                            end)
                        end)
                    end
                    if ownershipKick.bring and bringNeedReBring then
                        bringNeedReBring = false
                        bringChecking = false
                        executeBring(tRoot, savedPos)
                        if bodyPos and bodyPos.Parent then
                            bodyPos.Position = (myRoot.CFrame * CFrame.new(5, 16, 2)).Position
                        end
                        bringChecking = true
                    end
                    local lockPos = myRoot.CFrame * CFrame.new(5, 16, 2)
                    if bodyPos and bodyPos.Parent then
                        bodyPos.Position = lockPos.Position
                        if bodyGyro then
                            bodyGyro.CFrame = lockPos
                        end
                    else
                        createBodies(tRoot, lockPos.Position)
                    end
                    pcall(function()
                        tHum.PlatformStand = true
                        tHum.Sit = false
                    end)
                    local ragdolledVal = Workspace[target.Name] and Workspace[target.Name].Humanoid and Workspace[target.Name].Humanoid.Ragdolled
                    local isRagdolled = ragdolledVal and ragdolledVal.Value == true
                    ensureTargetIndicator(target)
                    setTargetIndicator(isRagdolled)
                    pcall(function() RemoteDispatcher:Fire(setNetworkOwnerEvent, tRoot, lockPos) end)
                    if not isRagdolled and tick() - lastFullCycle >= 0.040 then
                        lastFullCycle = tick()
                        pcall(function() RemoteDispatcher:Fire(destroyGrabLineEvent, tRoot) end)
                    end
                    if checkStartTime > 0 and tick() - checkStartTime > 0.2 then
                        local currentDist = (tRoot.Position - myRoot.Position).Magnitude
                        if currentDist > 29 then
                            dragging = false
                            grabStartTime = 0
                            checkStartTime = 0
                            cleanupBodies()
                            if ownershipKick.bring then
                                executeBring(tRoot, savedPos)
                            end
                        else
                            checkStartTime = tick()
                        end
                    end
                end
            else
                dragging = false
                grabStartTime = 0
                checkStartTime = 0
                cleanupBodies()
            end
            RunService.Heartbeat:Wait()
        end
        if bringDistConn then task.cancel(bringDistConn) bringDistConn = nil end
        cleanupBodies()
        resumeOwnershipPosLock()
        destroyTargetIndicator()
        Settings.Loop.ownershipKickLoopLockActive = false
        ownershipKick.on = false
        pcall(function()
            if library._flagSetters and library._flagSetters["OwnershipKick"] then
                library._flagSetters["OwnershipKick"](false)
            end
        end)
    end)
end
