                end
                MyBlob = myhum.SeatPart.Parent
                local ct = Players:FindFirstChild(target.Name)
                if not (ct and ct.Character) then continue end
                local tHum = ct.Character:FindFirstChildOfClass("Humanoid")
                local tHRP = ct.Character:FindFirstChild("HumanoidRootPart")
                if not (tHum and tHRP and tHum.Health ~= 0) then continue end
                local blobRoot = MyBlob:FindFirstChild("HumanoidRootPart")
                local scr = MyBlob:FindFirstChild("BlobmanSeatAndOwnerScript")
                local CG = scr and scr:FindFirstChild("CreatureGrab")
                local CD = scr and scr:FindFirstChild("CreatureRelease")
                local rd = MyBlob:FindFirstChild("RightDetector")
                local rw = rd and rd:FindFirstChild("RightWeld")
                if not (blobRoot and CG and CD and rw) then continue end
                local pos = myHRP.CFrame
                blobRoot.CFrame = tHRP.CFrame
                task.wait(0.05)
                repeat task.wait()
                    for _ = 1, 2 do
                        RemoteDispatcher:Fire(CG, nil, tHRP, rw)
                        RemoteDispatcher:Fire(CD, rw)
                    end
                until not Settings.BlobmanBeta.loopKillActive or isnetworkowner(tHRP)
                if not Settings.BlobmanBeta.loopKillActive then break end
                task.wait()
                if tHum and tHum.Health ~= 0 then tHum:ChangeState("Dead") end
                pcall(function()
                    myHRP.AssemblyLinearVelocity = Vector3.zero
                    myHRP.AssemblyAngularVelocity = Vector3.zero
                end)
                pcall(function()
                    blobRoot.AssemblyLinearVelocity = Vector3.zero
                    blobRoot.AssemblyAngularVelocity = Vector3.zero
                end)
                blobRoot.CFrame = pos
            end
        end
    end)
end})
