blobSec:Button({Text = "Touch", Callback = function()
    task.spawn(function()
        local target = BlobmanBetaFeature.checkTarget()
        if not target then return end
        local character = target.Character
        if not character then return end
        local root = character:FindFirstChild("HumanoidRootPart")
        if not root then return end
        local function snapBlobTo(blob2, targetCFrame)
            local hrp = blob2:FindFirstChild("HumanoidRootPart")
            if not hrp then return end
            hrp.CFrame = targetCFrame
            local att0 = hrp:FindFirstChild("BlobAttachment") or Instance.new("Attachment", hrp)
            att0.Name = "BlobAttachment"
            local targetPart = Workspace:FindFirstChild("BlobTarget") or Instance.new("Part")
            targetPart.Anchored = true
            targetPart.CanCollide = false
            targetPart.Size = Vector3.new(1, 1, 1)
            targetPart.Transparency = 1
            targetPart.CFrame = targetCFrame
            targetPart.Name = "BlobTarget"
            targetPart.Parent = Workspace
            local att1 = targetPart:FindFirstChild("BlobTargetAttachment") or Instance.new("Attachment", targetPart)
            att1.Name = "BlobTargetAttachment"
            local ap = hrp:FindFirstChild("BlobAlignPos") or Instance.new("AlignPosition", hrp)
            ap.Name = "BlobAlignPos"
            ap.Attachment0 = att0
            ap.Attachment1 = att1
            ap.RigidityEnabled = true
            ap.Responsiveness = 300
            ap.MaxForce = math.huge
            local ao = hrp:FindFirstChild("BlobAlignOri") or Instance.new("AlignOrientation", hrp)
            ao.Name = "BlobAlignOri"
            ao.Attachment0 = att0
            ao.Attachment1 = att1
            ao.Responsiveness = 300
            ao.MaxTorque = math.huge
            ao.RigidityEnabled = true
        end
        local function releaseBlobAlign(blob2)
            local hrp = blob2 and blob2:FindFirstChild("HumanoidRootPart")
            if not hrp then return end
            if hrp:FindFirstChild("BlobAlignPos") then hrp.BlobAlignPos:Destroy() end
            if hrp:FindFirstChild("BlobAlignOri") then hrp.BlobAlignOri:Destroy() end
            if hrp:FindFirstChild("BlobAttachment") then hrp.BlobAttachment:Destroy() end
            local targetPart = Workspace:FindFirstChild("BlobTarget")
            if targetPart then targetPart:Destroy() end
        end
        local blob = BlobmanBetaFeature.getBlobman()
            or BlobmanBetaFeature.findAnyBlobman()
            or BlobmanBetaFeature.spawnBlobman()
        if not blob or not blob:FindFirstChild("VehicleSeat") then
            library:Notify({Title = "Touch", Description = "Blobman not found!", Time = 3})
            return
        end
        local myChar = LocalPlayer.Character
        local myHRP = myChar and myChar:FindFirstChild("HumanoidRootPart")
        local myHum = myChar and myChar:FindFirstChildOfClass("Humanoid")
        if not myHRP or not myHum then return end
        local playerStartPos = myHRP.Position
        local vehicleSeat = blob.VehicleSeat
        if not myHum.Sit or myHum.SeatPart ~= vehicleSeat then
            if vehicleSeat.Occupant and vehicleSeat.Occupant ~= myHum then
                pcall(function() vehicleSeat.Occupant.Jump = true end)
                task.wait(0.03)
            end
            local sitStart = tick()
            while tick() - sitStart < 0.3 do
                if not blob or not blob.Parent then break end
                myHRP.CFrame = vehicleSeat.CFrame + Vector3.new(0, 2, 0)
                pcall(function() vehicleSeat:Sit(myHum) end)
                if myHum.Sit and myHum.SeatPart == vehicleSeat then break end
                task.wait(0.03)
            end
        end
        if not (myHum.Sit and myHum.SeatPart == vehicleSeat) then
            library:Notify({Title = "Touch", Description = "Failed to sit on blobman!", Time = 3})
            return
        end
        task.wait(0.03)
        for _ = 1, 20 do
            if myHum.Sit and myHum.SeatPart and myHum.SeatPart.Parent and myHum.SeatPart.Parent.Name == "CreatureBlobman" and not isGucciBlobman(myHum.SeatPart.Parent) then break end
            BlobmanBetaFeature.forceSitBlobman()
            task.wait(0.05)
        end
        if not (myHum.Sit and myHum.SeatPart and myHum.SeatPart.Parent and myHum.SeatPart.Parent.Name == "CreatureBlobman" and not isGucciBlobman(myHum.SeatPart.Parent)) then
            library:Notify({Title = "Touch", Description = "Failed to sit on blobman!", Time = 3})
            return
        end
        blob = myHum.SeatPart.Parent
        local seatScript = blob:FindFirstChild("BlobmanSeatAndOwnerScript") or blob:FindFirstChild("BlobmanSeatAndOwnerScript[old]")
        if not seatScript then
            library:Notify({Title = "Touch", Description = "Blobman script not found!", Time = 3})
            return
        end
        local grab = seatScript:FindFirstChild("CreatureGrab")
        local release = seatScript:FindFirstChild("CreatureRelease")
        local drop = seatScript:FindFirstChild("CreatureDrop")
        if not grab or not drop then
            library:Notify({Title = "Touch", Description = "Blobman grab remote not found!", Time = 3})
            return
        end
        local set = setNetworkOwnerEvent
        local del = destroyGrabLineEvent
        local function ensureSetNE(part, duration)
            local start = tick()
            while tick() - start < (duration or 1.5) do
                if not part or not part.Parent then return false end
                pcall(function() RemoteDispatcher:Fire(set, part, part.CFrame) end)
                local ok, owner = pcall(function() return part:GetNetworkOwner() end)
                if ok and owner == LocalPlayer then return true end
                task.wait(0.05)
            end
            return false
        end
        local detector = blob:FindFirstChild("LeftDetector")
        local weld = detector and detector:FindFirstChild("LeftWeld")
        local localHrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
        if not localHrp then return end
        ensureSetNE(root, 0.5)
        snapBlobTo(blob, root.CFrame)
        local arriveStart = tick()
        while tick() - arriveStart < 0.8 and root.Parent do
            local bhrp = blob:FindFirstChild("HumanoidRootPart")
            if bhrp and (bhrp.Position - root.Position).Magnitude < 10 then break end
            snapBlobTo(blob, root.CFrame)
            task.wait(0.03)
        end
        task.wait(0.05)
        for _ = 1, 5 do
            pcall(function() RemoteDispatcher:Fire(grab, blob.RightDetector, root, blob.RightDetector.RightWeld) end)
            task.wait(0.03)
        end
        ensureSetNE(root, 0.5)
        snapBlobTo(blob, CFrame.new(Vector3.new(0, 100, 0)))
        task.wait(0.1)
        pcall(function() RemoteDispatcher:Fire(release, blob.RightDetector.RightWeld) end)
        task.wait(0.03)
        snapBlobTo(blob, CFrame.new(Vector3.new(0, 100, 0)))
        task.wait(0.03)
        local blobHrp = blob:FindFirstChild("HumanoidRootPart")
        if blobHrp and root.Parent then
            ensureSetNE(root, 0.5)
            local up = CFrame.new(blobHrp.Position.X, blobHrp.Position.Y + 20, blobHrp.Position.Z)
            for _ = 1, 8 do
                if not root.Parent then break end
                pcall(function() RemoteDispatcher:Fire(set, root, up) end)
                pcall(function() RemoteDispatcher:Fire(del, root) end)
                root.CFrame = up
                if (root.Position - up.Position).Magnitude < 12 then break end
                task.wait(0.03)
            end
            task.wait(0.03)
            pcall(function() RemoteDispatcher:Fire(grab, detector, localHrp, weld) end)
            task.wait(0.03)
            pcall(function() RemoteDispatcher:Fire(grab, detector, root, weld) end)
            pcall(function() RemoteDispatcher:Fire(drop, weld, root.RootAttachment) end)
        end
        task.wait(0.3)
        releaseBlobAlign(blob)
        BlobmanBetaFeature.ungrab(root)
        local backChar = LocalPlayer.Character
        local backRoot = backChar and backChar:FindFirstChild("HumanoidRootPart")
        if backRoot and playerStartPos and (backRoot.Position - playerStartPos).Magnitude > 50 then
            backRoot.CFrame = CFrame.new(playerStartPos)
            pcall(function() backRoot.AssemblyLinearVelocity = Vector3.zero end)
            pcall(function() backRoot.AssemblyAngularVelocity = Vector3.zero end)
        end
    end)
end})
