    local name = value:match("@(.+)$")
    if name then Settings.BlobmanBeta.bananaRagdollTarget = name end
end})
blobBananaRagdollSec:Toggle({Text = "Loop Banana Ragdoll", Flag = "BananaRagdoll", Default = false, Callback = function(v)
    Settings.BlobmanBeta.bananaRagdollActive = v
    if not v then
        RemoteDispatcher:NewGeneration()
        task.spawn(function()
            pcall(function()
                local inv = Workspace:FindFirstChild(LocalPlayer.Name .. "SpawnedInToys")
                local banana = inv and inv:FindFirstChild("FoodBanana")
                if banana then
                    local SoundPart = banana:FindFirstChild("SoundPart")
                    local AlignPos = SoundPart and SoundPart:FindFirstChild("AlignPosition")
                    if AlignPos then AlignPos:Destroy() end
                    RemoteDispatcher:Fire(DeleteToyRE, banana)
                end
            end)
        end)
        return
    end
    task.spawn(function()
        local targetName = Settings.BlobmanBeta.bananaRagdollTarget
        if not targetName then
            Settings.BlobmanBeta.bananaRagdollActive = false
            return
        end
        local targetPLR = Players:FindFirstChild(targetName)
        if not targetPLR then
            Settings.BlobmanBeta.bananaRagdollActive = false
            return
        end
        local myChar = LocalPlayer.Character
        local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
        if not myRoot then Settings.BlobmanBeta.bananaRagdollActive = false return end
        local GE = ReplicatedStorage:WaitForChild("GrabEvents")
        local setNE = GE:WaitForChild("SetNetworkOwner")
        local destroyGL = GE:WaitForChild("DestroyGrabLine")
        local holdEvents = ReplicatedStorage:FindFirstChild("HoldEvents") or ReplicatedStorage:WaitForChild("HoldEvents")
        local function FWD(parent, part, time)
            return parent:FindFirstChild(part) or parent:WaitForChild(part, time or 5)
        end
        local function CFP(parent, part)
            return parent:FindFirstChild(part) ~= nil
        end
        local function sno(part)
            pcall(function() RemoteDispatcher:Fire(setNE, part, part.CFrame) end)
        end
        local function unsno(part)
            pcall(function() RemoteDispatcher:Fire(destroyGL, part) end)
        end
        local function CheckNetworkOwnerOnPart(part)
            return CFP(part, "PartOwner") and part.PartOwner.Value == LocalPlayer.Name
        end
        local function SpawnToy(ToyName)
            local canSpawn = LocalPlayer:FindFirstChild("CanSpawnToy")
            if canSpawn and not canSpawn.Value then
                canSpawn:GetPropertyChangedSignal("Value"):Wait()
            end
            local container = Workspace:FindFirstChild(LocalPlayer.Name .. "SpawnedInToys")
            if not container then return nil end
            local spawned
            local conn = container.ChildAdded:Connect(function(toy)
                if toy.Name == ToyName then
                    spawned = toy
                end
            end)
            pcall(function() RemoteDispatcher:Invoke(SpawnToyRF, ToyName, CFrame.new(0, 999999, 0), Vector3.zero) end)
            local start = tick()
            while not spawned do
                if tick() - start > 2.5 then break end
                task.wait(0.01)
            end
            conn:Disconnect()
            return spawned
        end
        local banana, SoundPart
        local AlignPos
        local orbitAtt
        local lastSnoT = 0
        local snoCount = 0
        local setupDone = false
        local lastTargetPos = nil
        local bananaTarget = Instance.new("Part")
        bananaTarget.Name = "BananaTarget"
        bananaTarget.Anchored = true
        bananaTarget.CanCollide = false
        bananaTarget.Size = Vector3.new(1, 1, 1)
        bananaTarget.Transparency = 1
        bananaTarget.Parent = Workspace
        while Settings.BlobmanBeta.bananaRagdollActive and task.wait() do
            local inv = Workspace:FindFirstChild(LocalPlayer.Name .. "SpawnedInToys")
            if not inv then continue end
            banana = inv:FindFirstChild("FoodBanana")
            SoundPart = banana and banana:FindFirstChild("SoundPart")
            if not banana then
                setupDone = false
                banana = SpawnToy("FoodBanana")
                if not banana then continue end
                SoundPart = nil
            end
            if not setupDone then
                for _, v in pairs(inv:GetChildren()) do
                    if v.Name == "FoodBanana" and v ~= banana then
                        pcall(function() RemoteDispatcher:Fire(DeleteToyRE, v) end)
                    end
                end
                SoundPart = SoundPart or FWD(banana, "SoundPart", 5)
                if not SoundPart then
                    pcall(function() RemoteDispatcher:Fire(DeleteToyRE, banana) end)
                    continue
                end
                local holdPart = FWD(banana, "HoldPart", 5)
                if holdPart then
                    local holdRemote = FWD(holdPart, "HoldItemRemoteFunction", 5)
                    if holdRemote then
                        pcall(function() RemoteDispatcher:Invoke(holdRemote, banana, myChar) end)
                    end
                end
                pcall(function() RemoteDispatcher:Fire(holdEvents.Use, banana) end)
                while CFP(banana, "EdiblePart") and Settings.BlobmanBeta.bananaRagdollActive do task.wait() end
                pcall(function() RemoteDispatcher:Fire(holdEvents.Use, banana) end)
                if holdPart then
                    local dropRemote = FWD(holdPart, "DropItemRemoteFunction", 5)
                    if dropRemote then
                        pcall(function() RemoteDispatcher:Invoke(dropRemote, banana, myChar:GetPivot() * CFrame.new(0, 15, -10), Vector3.zero) end)
                    end
                end
                repeat
                    task.wait(0.01)
                    SoundPart = banana and banana:FindFirstChild("SoundPart")
                    if not SoundPart then break end
                    sno(SoundPart)
                until not SoundPart or CFP(SoundPart, "PartOwner") or not Settings.BlobmanBeta.bananaRagdollActive
                if not SoundPart then continue end
                unsno(SoundPart)
                sno(SoundPart)
                SoundPart.CanCollide = true
                local Atach = Instance.new("Attachment")
                Atach.Parent = SoundPart
                AlignPos = Instance.new("AlignPosition")
                AlignPos.Responsiveness = 200
                AlignPos.MaxForce = math.huge
                AlignPos.MaxVelocity = math.huge
                AlignPos.Parent = SoundPart
                AlignPos.Attachment0 = Atach
                setupDone = true
            end
            if banana then
                for _, v in pairs(banana:GetChildren()) do
                    if CFP(v, "PartOwner") and not CheckNetworkOwnerOnPart(v) then
                        pcall(function() RemoteDispatcher:Fire(DeleteToyRE, banana) end)
                        banana = nil
                        break
                    end
                end
            end
            if not banana then continue end
            AlignPos = SoundPart and SoundPart:FindFirstChild("AlignPosition")
            if not AlignPos then
                pcall(function() RemoteDispatcher:Fire(DeleteToyRE, banana) end)
                banana = nil
                continue
            end
            local tChar = targetPLR and targetPLR.Character
            local tHRP = tChar and tChar:FindFirstChild("HumanoidRootPart")
            if tHRP then lastTargetPos = tHRP.Position end
            local nowSno = os.clock()
            if snoCount < 2 and nowSno - lastSnoT > 0.5 then
                lastSnoT = nowSno
                snoCount = snoCount + 1
                unsno(SoundPart)
                sno(SoundPart)
                unsno(SoundPart)
            end
            if orbitAtt then orbitAtt:Destroy() end
            orbitAtt = Instance.new("Attachment", bananaTarget)
            orbitAtt.Name = "BananaOrbitAtt"
            local targetPos
            if tHRP then
                local roll = math.random()
                if roll < 0.15 then
                    local leftLeg = tChar:FindFirstChild("Left Leg")
                    local foot = leftLeg and leftLeg:FindFirstChild("LeftFootAttachment")
                    if foot then
                        targetPos = foot.WorldPosition
                    else
                        targetPos = tHRP.Position
                    end
                elseif roll < 0.4 then
                    local parts = {"HumanoidRootPart", "Head", "Torso", "Left Leg", "Right Leg"}
                    local bp = tChar:FindFirstChild(parts[math.random(1, #parts)]) or tHRP
                    targetPos = bp.Position
                else
                    local from = SoundPart.Position
                    local toT = tHRP.Position - from
                    local dir = toT.Magnitude > 0.01 and toT.Unit or Vector3.new(1, 0, 0)
                    local perp = dir:Cross(Vector3.new(0, 1, 0))
                    if perp.Magnitude < 0.1 then perp = Vector3.new(1, 0, 0) end
                    perp = perp.Unit
                    local up = dir:Cross(perp).Unit
                    local spread = dir + perp * ((math.random() - 0.5) * 2.4) + up * ((math.random() - 0.5) * 2)
                    if spread.Magnitude < 0.01 then spread = dir end
                    spread = spread.Unit
                    targetPos = tHRP.Position + spread * (6 + math.random() * 14)
                end
            else
                targetPos = lastTargetPos
            end
            if not targetPos then continue end
            if not Settings.Anti.AntiVoid and targetPos.Y < -24 then
                targetPos = Vector3.new(targetPos.X, -24, targetPos.Z)
            end
            orbitAtt.WorldPosition = targetPos
            AlignPos.Attachment1 = orbitAtt
        end
        if orbitAtt then orbitAtt:Destroy() end
        if bananaTarget then bananaTarget:Destroy() end
    end)
end})
