blobSelfFlingSec:Toggle({Text = "Self Fling", Flag = "SelfFling", Default = false, Callback = function(v)
    Settings.BlobmanBeta.selfFlingActive = v
    if not v then
        RemoteDispatcher:NewGeneration()
        if Settings.BlobmanBeta.selfFlingConn then
            task.cancel(Settings.BlobmanBeta.selfFlingConn)
            Settings.BlobmanBeta.selfFlingConn = nil
        end
        if Settings.BlobmanBeta.selfFlingCleanup then
            Settings.BlobmanBeta.selfFlingCleanup()
            Settings.BlobmanBeta.selfFlingCleanup = nil
        end
        return
    end
    task.spawn(function()
        local targetName = Settings.BlobmanBeta.selfFlingTarget
        if not targetName then
            Settings.BlobmanBeta.selfFlingActive = false
            return
        end
        local myChar = LocalPlayer.Character
        local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
        local myHum = myChar and myChar:FindFirstChildOfClass("Humanoid")
        if not myRoot or not myHum then
            Settings.BlobmanBeta.selfFlingActive = false
            return
        end
        local savedCF = myRoot.CFrame
        local FPDH = workspace.FallenPartsDestroyHeight
        local function fullReset()
            pcall(function()
                workspace.FallenPartsDestroyHeight = FPDH
                workspace.CurrentCamera.CameraSubject = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
                local ch = LocalPlayer.Character
                if not ch then return end
                local r = ch:FindFirstChild("HumanoidRootPart")
                local h = ch:FindFirstChildOfClass("Humanoid")
                if r then
                    r.CFrame = savedCF
                    r.Velocity = Vector3.zero
                    r.RotVelocity = Vector3.zero
                end
                for _, part in pairs(ch:GetChildren()) do
                    if part:IsA("BasePart") then
                        part.Velocity = Vector3.zero
                        part.RotVelocity = Vector3.zero
                    end
                end
                for _, obj in pairs(ch:GetDescendants()) do
                    if obj:IsA("BodyVelocity") or obj:IsA("BodyAngularVelocity") then
                        obj:Destroy()
                    end
                end
                if h then h:ChangeState(Enum.HumanoidStateType.GettingUp) end
            end)
        end
        Settings.BlobmanBeta.selfFlingCleanup = fullReset
        workspace.FallenPartsDestroyHeight = -100000
        local BV = Instance.new("BodyVelocity")
        BV.Name = "_SelfFlingAnchor"
        BV.Velocity = Vector3.zero
        BV.MaxForce = Vector3.new(9e9, 9e9, 9e9)
        BV.Parent = myRoot
        myHum:SetStateEnabled(Enum.HumanoidStateType.Seated, false)
        local function fpos(basePart, pos, ang)
            myRoot.CFrame = CFrame.new(basePart.Position) * pos * ang
            myChar:SetPrimaryPartCFrame(CFrame.new(basePart.Position) * pos * ang)
            myRoot.Velocity = Vector3.new(9e7, 9e7 * 10, 9e7)
            myRoot.RotVelocity = Vector3.new(9e8, 9e8, 9e8)
        end
        Settings.BlobmanBeta.selfFlingConn = task.spawn(function()
            while Settings.BlobmanBeta.selfFlingActive do
                myChar = LocalPlayer.Character
                myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
                myHum = myChar and myChar:FindFirstChildOfClass("Humanoid")
                if not myRoot or not myHum then
                    task.wait(0.2)
                    continue
                end
                local ct = Players:FindFirstChild(targetName)
                local ctChar = ct and ct.Character
                local ctHRP = ctChar and ctChar:FindFirstChild("HumanoidRootPart")
                local ctHum = ctChar and ctChar:FindFirstChildOfClass("Humanoid")
                if not ctHRP or not ctHum then
                    task.wait(0.3)
                    continue
                end
                workspace.CurrentCamera.CameraSubject = ctChar:FindFirstChild("Head") or ctHRP
                local targetPart = ctHRP
                local angle = 0
                local flingStart = tick()
                repeat
                    if not Settings.BlobmanBeta.selfFlingActive then break end
                    myRoot = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
                    if not myRoot then break end
                    targetPart = ctChar and ctChar:FindFirstChild("HumanoidRootPart")
                    if not targetPart then break end
                    ctHum = ctChar:FindFirstChildOfClass("Humanoid")
                    if not ctHum then break end
                    if targetPart.Velocity.Magnitude < 50 then
                        angle = angle + 100
                        fpos(targetPart, CFrame.new(0, 1.5, 0) + ctHum.MoveDirection * targetPart.Velocity.Magnitude / 1.25, CFrame.Angles(math.rad(angle), 0, 0))
                        task.wait()
                        fpos(targetPart, CFrame.new(0, -1.5, 0) + ctHum.MoveDirection * targetPart.Velocity.Magnitude / 1.25, CFrame.Angles(math.rad(angle), 0, 0))
                        task.wait()
                        fpos(targetPart, CFrame.new(0, 1.5, 0) + ctHum.MoveDirection * targetPart.Velocity.Magnitude / 1.25, CFrame.Angles(math.rad(angle), 0, 0))
                        task.wait()
                        fpos(targetPart, CFrame.new(0, -1.5, 0) + ctHum.MoveDirection * targetPart.Velocity.Magnitude / 1.25, CFrame.Angles(math.rad(angle), 0, 0))
                        task.wait()
                        fpos(targetPart, CFrame.new(0, 1.5, 0) + ctHum.MoveDirection, CFrame.Angles(math.rad(angle), 0, 0))
                        task.wait()
                        fpos(targetPart, CFrame.new(0, -1.5, 0) + ctHum.MoveDirection, CFrame.Angles(math.rad(angle), 0, 0))
                        task.wait()
                    else
                        fpos(targetPart, CFrame.new(0, 1.5, ctHum.WalkSpeed), CFrame.Angles(math.rad(90), 0, 0))
                        task.wait()
                        fpos(targetPart, CFrame.new(0, -1.5, -ctHum.WalkSpeed), CFrame.Angles(0, 0, 0))
                        task.wait()
                        fpos(targetPart, CFrame.new(0, 1.5, ctHum.WalkSpeed), CFrame.Angles(math.rad(90), 0, 0))
                        task.wait()
                        fpos(targetPart, CFrame.new(0, -1.5, 0), CFrame.Angles(math.rad(90), 0, 0))
                        task.wait()
                        fpos(targetPart, CFrame.new(0, -1.5, 0), CFrame.Angles(0, 0, 0))
                        task.wait()
                        fpos(targetPart, CFrame.new(0, -1.5, 0), CFrame.Angles(math.rad(90), 0, 0))
                        task.wait()
                        fpos(targetPart, CFrame.new(0, -1.5, 0), CFrame.Angles(0, 0, 0))
                        task.wait()
                    end
                until tick() - flingStart > 2 or not Settings.BlobmanBeta.selfFlingActive
                if not Settings.BlobmanBeta.selfFlingActive then break end
                workspace.CurrentCamera.CameraSubject = myHum
                repeat
                    myRoot = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
                    if not myRoot then break end
                    myRoot.CFrame = savedCF
                    myRoot.Velocity = Vector3.zero
                    myRoot.RotVelocity = Vector3.zero
                    myChar = LocalPlayer.Character
                    if myChar then
                        for _, part in pairs(myChar:GetChildren()) do
                            if part:IsA("BasePart") then
                                part.Velocity = Vector3.zero
                                part.RotVelocity = Vector3.zero
                            end
                        end
                        local h = myChar:FindFirstChildOfClass("Humanoid")
                        if h then h:ChangeState(Enum.HumanoidStateType.GettingUp) end
                    end
                    task.wait()
                until (myRoot.Position - savedCF.p).Magnitude < 5 or not Settings.BlobmanBeta.selfFlingActive
                task.wait(0.3)
            end
            fullReset()
        end)
    end)
end})
end)()
;(function()
local holeTargetSec = BlobmanTab:Section({Text = "Hole Target"})
local holeTargetCombo
local holeTargetTask = nil
local function holeTargetCleanup()
    local inv = Workspace:FindFirstChild(LocalPlayer.Name .. "SpawnedInToys")
    if inv then
        for _, child in ipairs(inv:GetChildren()) do
            if child.Name == "NinjaShuriken" then
                pcall(function() RemoteDispatcher:Fire(DeleteToyRE, child) end)
            end
        end
    end
end
local function holeTargetLoop()
    while Settings.BlobmanBeta.holeTargetActive do
        local target = Players:FindFirstChild(Settings.BlobmanBeta.holeTarget)
        if not target or not target.Character then
            Settings.BlobmanBeta.holeTargetActive = false
            return
        end
        local tRoot = target.Character:FindFirstChild("HumanoidRootPart")
        if not tRoot then
            task.wait(0.5)
            continue
        end
        local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
        if not hrp then
            task.wait(0.5)
            continue
        end
        local BackPack = Workspace:FindFirstChild(LocalPlayer.Name .. "SpawnedInToys")
        if not BackPack then
            task.wait(0.5)
            continue
        end
        for _, child in ipairs(BackPack:GetChildren()) do
            local sp = child:FindFirstChild("StickyPart")
            if sp and not sp:FindFirstChild("StickyWeld") and (child.Name == "NinjaShuriken" or tonumber(child.Name)) then
                pcall(function() RemoteDispatcher:Fire(DeleteToyRE, child) end)
            end
        end
        task.wait(0.2)
        local canSpawn = LocalPlayer:FindFirstChild("CanSpawnToy")
        local stuckCount = 0
        for i = 1, 10 do
            if not Settings.BlobmanBeta.holeTargetActive then break end
            if not hrp or not hrp.Parent then break end
            if not target or not target.Character or not target.Character:FindFirstChild("HumanoidRootPart") then break end
            local attached = false
            for attempt = 1, 3 do
                if attached then break end
                if not Settings.BlobmanBeta.holeTargetActive then break end
                if not hrp or not hrp.Parent then break end
                if canSpawn and not canSpawn.Value then
                    local deadline = tick() + 5
                    while not canSpawn.Value and tick() < deadline and Settings.BlobmanBeta.holeTargetActive and hrp and hrp.Parent do
                        task.wait()
                    end
                end
                local shur = nil
                local conn = BackPack.ChildAdded:Connect(function(child)
                    if child.Name == "NinjaShuriken" and not shur then
                        shur = child
                    end
                end)
                task.spawn(function()
                    pcall(function()
                        RemoteDispatcher:Invoke(SpawnToyRF, "NinjaShuriken", tRoot.Position + Vector3.new(0, 0, 18), Vector3.zero)
                    end)
                end)
                local startTime = tick()
                while not shur and tick() - startTime < 1 and hrp and hrp.Parent do
                    task.wait()
                end
                if conn then conn:Disconnect() end
                if not hrp or not hrp.Parent then break end
                if not shur then
                    shur = BackPack:FindFirstChild("NinjaShuriken")
                end
                if shur then
                    local detectTime = tick()
                    shur.Name = tostring(i)
                    local stickyPart = shur:FindFirstChild("StickyPart")
                    local spStart = tick()
                    while not stickyPart and tick() - spStart < 1 and hrp and hrp.Parent do
                        stickyPart = shur:FindFirstChild("StickyPart")
                        task.wait()
                    end
                    if stickyPart then
                        local soundPart = shur:FindFirstChild("SoundPart") or stickyPart
                        pcall(function() RemoteDispatcher:Fire(setNetworkOwnerEvent, soundPart, soundPart.CFrame) end)
                        pcall(function()
                            RemoteDispatcher:Fire(StickyPartEvent, stickyPart, tRoot, CFrame.Angles(0, 0, 0))
                        end)
                    end
                    local waitUntil = detectTime + 0.5
                    while tick() < waitUntil and hrp and hrp.Parent do task.wait() end
                    if stickyPart and stickyPart:FindFirstChild("StickyWeld") and stickyPart.StickyWeld.Part1 then
                        attached = true
                        stuckCount = stuckCount + 1
                    end
                end
                task.wait(0.1)
            end
        end
        if stuckCount >= 10 then
            while Settings.BlobmanBeta.holeTargetActive do
                task.wait(0.5)
            end
        else
            task.wait(0.5)
        end
    end
    holeTargetCleanup()
end
