miscBringCombo = miscBringSec:Dropdown({Text = "Select Target", Flag = "MiscBringDropdown", List = BlobmanBetaFeature.GetPlayerList(), Callback = function(value)
    local name = value:match("@(.+)$")
    if name then miscBringTarget = name end
