local barrierNoclipConn = nil
local barrierNoclipLoop = nil
State.barrierNoclipSaved = nil
local function barrierNoclipApply(part)
    if not part:IsA("BasePart") then return end
    if not State.barrierNoclipSaved then State.barrierNoclipSaved = {} end
    if not State.barrierNoclipSaved[part] then
        State.barrierNoclipSaved[part] = {
            CanCollide = part.CanCollide,
            CanQuery = part.CanQuery,
            CanTouch = part.CanTouch,
        }
    end
    part.CanCollide = false
    part.CanQuery = false
    part.CanTouch = false
end
local function barrierNoclipApplyRecursive(obj)
    barrierNoclipApply(obj)
    for _, child in ipairs(obj:GetChildren()) do
        barrierNoclipApplyRecursive(child)
    end
end
local function setBarrierNoclip()
    if not State.barrierNoclip then return end
    local Plots = Workspace:FindFirstChild("Plots")
    local root = Plots or Workspace
    for _, obj in ipairs(root:GetDescendants()) do
        if obj.Name == "PlotBarrier" or obj.Name == "PlotArea" then
            barrierNoclipApplyRecursive(obj)
        end
    end
end
local function restoreBarrierNoclip()
    if State.barrierNoclipSaved then
        for part, props in pairs(State.barrierNoclipSaved) do
            if part and part.Parent then
                part.CanCollide = props.CanCollide
                part.CanQuery = props.CanQuery
                part.CanTouch = props.CanTouch
            end
        end
        State.barrierNoclipSaved = nil
    end
end
miscUtilSec:Toggle({Text = "Barrier Noclip", Flag = "BarrierNoclip", Default = false, Callback = function(v)
    State.barrierNoclip = v
    if v then
        setBarrierNoclip()
        barrierNoclipConn = Workspace.DescendantAdded:Connect(function(obj)
            if not State.barrierNoclip then return end
            if obj.Name == "PlotBarrier" or obj.Name == "PlotArea" then
                task.wait(0.1)
                barrierNoclipApplyRecursive(obj)
            end
        end)
        barrierNoclipLoop = RunService.Heartbeat:Connect(function(dt)
            if not State.barrierNoclip then return end
            State.barrierNoclipTimer = (State.barrierNoclipTimer or 0) + dt
            if State.barrierNoclipTimer < 0.5 then return end
            State.barrierNoclipTimer = 0
            setBarrierNoclip()
        end)
    else
        if barrierNoclipConn then barrierNoclipConn:Disconnect() barrierNoclipConn = nil end
        if barrierNoclipLoop then barrierNoclipLoop:Disconnect() barrierNoclipLoop = nil end
        restoreBarrierNoclip()
    end
end})
