        pcall(function() RemoteDispatcher:Invoke(SpawnToyRF, "YouDecoy", myRoot.CFrame, Vector3.zero) end)
        task.wait(0.15)
        inv = Workspace:FindFirstChild(LocalPlayer.Name .. "SpawnedInToys")
