miscFunSec:Toggle({Text = "Fake Death", Flag = "FakeDeath", Default = false, Callback = function(on)
    Settings.Misc.fakeDeath = on
    local char = LocalPlayer.Character
    if not char then return end
    local hum = char:FindFirstChildOfClass("Humanoid")
    if not hum then return end
    local hrp = char:FindFirstChild("HumanoidRootPart")
    if on then
        State.fakeDeathAnimConn = nil
        State.fakeDeathRagdollLoop = nil
        local savedWalkSpeed = hum.WalkSpeed
        local savedJumpPower = hum.JumpPower
        local savedJumpHeight = hum.JumpHeight
        State.fakeDeathSavedSpeed = savedWalkSpeed
        State.fakeDeathSavedJumpPower = savedJumpPower
        State.fakeDeathSavedJumpHeight = savedJumpHeight
        hum.WalkSpeed = 0
        hum.JumpPower = 0
        hum.JumpHeight = 0
        local animator = hum:FindFirstChildOfClass("Animator")
        if animator then
            for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
                track:Stop(0)
            end
            State.fakeDeathAnimConn = animator.AnimationPlayed:Connect(function(track)
                if Settings.Misc.fakeDeath then task.defer(function() track:Stop(0) end) end
            end)
        end
        hum.BreakJointsOnDeath = false
        RemoteDispatcher:Fire(ragdollRemoteEvent, hrp, 2)
        hum.PlatformStand = true
        State.fakeDeathRagdollLoop = task.spawn(function()
            while Settings.Misc.fakeDeath do
                task.wait(0.05)
                local c = LocalPlayer.Character
                local h = c and c:FindFirstChildOfClass("Humanoid")
                local r = c and c:FindFirstChild("HumanoidRootPart")
                if h and r and h.Health > 0 then
                    RemoteDispatcher:Fire(ragdollRemoteEvent, r, 0.5)
                    h.PlatformStand = true
                end
            end
        end)
        if State.fakeDeathCharAdded then State.fakeDeathCharAdded:Disconnect() end
        State.fakeDeathCharAdded = LocalPlayer.CharacterAdded:Connect(function(newChar)
            Settings.Misc.fakeDeath = false
            if State.fakeDeathAnimConn then State.fakeDeathAnimConn:Disconnect() State.fakeDeathAnimConn = nil end
            State.fakeDeathRagdollLoop = nil
            if State.fakeDeathCharAdded then State.fakeDeathCharAdded:Disconnect() State.fakeDeathCharAdded = nil end
        end)
    else
        Settings.Misc.fakeDeath = false
        task.wait(0.5)
        if State.fakeDeathAnimConn then State.fakeDeathAnimConn:Disconnect() State.fakeDeathAnimConn = nil end
        State.fakeDeathRagdollLoop = nil
        if State.fakeDeathCharAdded then State.fakeDeathCharAdded:Disconnect() State.fakeDeathCharAdded = nil end
        hum.WalkSpeed = State.fakeDeathSavedSpeed or 16
        hum.JumpPower = State.fakeDeathSavedJumpPower or 50
        hum.JumpHeight = State.fakeDeathSavedJumpHeight or 7.2
        State.fakeDeathSavedSpeed = nil
        State.fakeDeathSavedJumpPower = nil
        State.fakeDeathSavedJumpHeight = nil
        RemoteDispatcher:Fire(ragdollRemoteEvent, hrp, 0)
        hum.PlatformStand = false
        hum:ChangeState(Enum.HumanoidStateType.GettingUp)
        if hrp then
            hrp.AssemblyLinearVelocity = Vector3.zero
            hrp.AssemblyAngularVelocity = Vector3.zero
        end
    end
end})
miscFunSec:Toggle({Text = "Coconut Dick", Flag = "CoconutDick", Default = false, Callback = function(v)
    Settings.Misc.coconutDick = v
    if not v then
        if State.coconutDickTask then task.cancel(State.coconutDickTask) State.coconutDickTask = nil end
        return
    end
    State.coconutDickTask = task.spawn(function()
        local Me = LocalPlayer
        local SetNetworkOwner = setNetworkOwnerEvent
        local SpawnToy = SpawnToyRF
        local DestroyToy = DeleteToyRE
        local Offsets = {
            [1] = CFrame.new(-0.45, -1.2, -0.7),
            [2] = CFrame.new(0.45, -1.2, -0.7),
            [3] = CFrame.new(0, -1, 0.8),
        }
        local Coconuts = {}
        while Settings.Misc.coconutDick do
            local Character = Me.Character
            local Root = Character and Character:FindFirstChild("HumanoidRootPart")
            if not Root then
                task.wait(0.1)
                continue
            end
            local Folder = Workspace:FindFirstChild(Me.Name .. "SpawnedInToys")
            if not Folder then
                task.wait(0.1)
                continue
            end
            local Length = 8
            local Damping = 100
            table.clear(Coconuts)
            for _, Toy in ipairs(Folder:GetChildren()) do
                if Toy.Name == "FoodCoconut" then
                    table.insert(Coconuts, Toy)
                end
            end
            if #Coconuts < (Length + 2) then
                task.spawn(function()
                    RemoteDispatcher:Invoke(SpawnToy, "FoodCoconut", Root.CFrame * CFrame.new(-5, 0, 10), Vector3.zero)
                end)
            end
            for i, Coconut in ipairs(Coconuts) do
                local Part = Coconut:FindFirstChild("SoundPart")
                local HoldPart = Coconut:FindFirstChild("HoldPart")
                local Rigid = HoldPart and HoldPart:FindFirstChild("RigidConstraint")
                local PartOwner = Part and Part:FindFirstChild("PartOwner")
                if Part and HoldPart and Rigid then
                    if PartOwner and PartOwner.Value == Me.Name then
                        if i <= 2 then
                            Part.CFrame = Root.CFrame * Offsets[i] * CFrame.new(Root.Velocity / Damping)
                        else
                            Part.CFrame = Root.CFrame * Offsets[3] * CFrame.new(Root.Velocity / Damping) * CFrame.new(0, 0, Offsets[3].Z - (i + 0.2))
                        end
                        Part.Velocity = Vector3.zero
                    else
                        RemoteDispatcher:Fire(SetNetworkOwner, Part, Part.CFrame)
                    end
                    if Rigid.Attachment1 then
                        RemoteDispatcher:Fire(DestroyToy, Coconut)
                    end
                    for _, PartObj in ipairs(Coconut:GetChildren()) do
                        if PartObj:IsA("BasePart") then
                            PartObj.CanCollide = false
                            PartObj.CanQuery = false
                            if PartObj.Transparency ~= 1 then
                                PartObj.Transparency = 0
                            end
                        end
                    end
                end
            end
            task.wait(0.01)
        end
    end)
end})
