    miscLagSec:Toggle({Text = "Instant Lag Server", Flag = "OatLagInstant", Default = false, Callback = function(value)
        oatLagEnabled = value
        if value then
            if oatLagTask then task.cancel(oatLagTask) oatLagTask = nil end
            oatLagTask = task.spawn(function()
