miscLagSec:Toggle({Text = "Lag Server", Flag = "LagServer", Default = false, Callback = function(v)
    lagServerEnabled = v
    if v then
        if lagServerTask then task.cancel(lagServerTask) lagServerTask = nil end
        lagServerTask = task.spawn(function()
            local acc = 0
            local lastSend = tick()
            while lagServerEnabled do
                task.wait()
                local now = tick()
                local dt = now - lastSend
                lastSend = now
                if dt > 0.1 then dt = 0.1 end
                local rate = Settings.Misc.lagServerIntensity or 100
                acc = acc + rate * dt
                local n = math.floor(acc)
                acc = acc - n
                local createLine = getLagCreateLine()
                local spawnLocation = getLagSpawnLocation()
                for _ = 1, n do
                    fireLagCreateLine(createLine, spawnLocation, spawnLocation and spawnLocation.CFrame)
                end
            end
        end)
    else
        if lagServerTask then task.cancel(lagServerTask) lagServerTask = nil end
    end
end})
