local function setupKeybindList()
    local keybindListGui = nil
    local keybindListMain = nil
    local keybindListContainer = nil
    local keybindDragConns = {}
    local itemLabels = {}
    local pendingUpdate = false

    local function updateKeybindDisplay()
        if not keybindListContainer or not keybindListMain then return end
        pendingUpdate = false

        local entries = {}
        local seen = {}

        if library and library._keybindEntries then
            for _, entry in ipairs(library._keybindEntries) do
                local name = entry.name or ""
                local key = entry.key or ""
                local mode = entry.mode or "Toggle"
                local state = entry.state == true
                if name ~= "Menu Toggle" and key ~= "" and key ~= "Unknown" and not seen[name] then
                    seen[name] = true
                    entries[#entries + 1] = {
                        id = name,
                        name = name,
                        key = key,
                        mode = mode,
                        state = state
                    }
                end
            end
        end

        if library and library.Flags then
            for flag, data in pairs(library.Flags) do
                if type(data) == "table" and data.Key and data.Key ~= "" and data.Key ~= "Unknown" then
                    local name = tostring(flag)
                    if not seen[name] and not seen[flag] then
                        seen[name] = true
                        entries[#entries + 1] = {
                            id = name,
                            name = name,
                            key = data.Key,
                            mode = data.Mode or "Toggle",
                            state = false
                        }
                    end
                end
            end
        end

        local activeIds = {}
        for i, entry in ipairs(entries) do
            activeIds[entry.id] = true
            local lbl = itemLabels[entry.id]
            if not lbl or not lbl.Parent then
                lbl = Instance.new("TextLabel")
                lbl.Name = "KBEntry_" .. entry.id
                lbl.Size = UDim2.new(1, 0, 0, 18)
                lbl.BackgroundTransparency = 1
                lbl.TextColor3 = Color3.fromRGB(200, 200, 200)
                lbl.Font = Enum.Font.Code
                lbl.TextSize = 13
                lbl.TextXAlignment = Enum.TextXAlignment.Left
                lbl.Parent = keybindListContainer
                itemLabels[entry.id] = lbl
            end
            lbl.LayoutOrder = i
            local status = entry.state and "On" or "Off"
            lbl.Text = entry.name .. ": " .. entry.key .. " | " .. entry.mode .. " | " .. status
            if entry.state then
                lbl.TextColor3 = Color3.fromRGB(120, 220, 120)
            else
                lbl.TextColor3 = Color3.fromRGB(200, 200, 200)
            end
        end

        for id, lbl in pairs(itemLabels) do
            if not activeIds[id] then
                pcall(function() lbl:Destroy() end)
                itemLabels[id] = nil
            end
        end

        local count = #entries
        local h = math.max(56, 32 + count * 20)
        keybindListMain.Size = UDim2.new(0, 260, 0, h)
    end

    local function requestUpdate()
        if not keybindListGui or not keybindListGui.Parent then return end
        if pendingUpdate then return end
        pendingUpdate = true
        task.defer(updateKeybindDisplay)
    end

    miscConfigSec:Toggle({Text = "Keybind List", Flag = "KeybindListToggle", Default = false, Callback = function(v)
        if v then
            keybindListGui = Instance.new("ScreenGui")
            keybindListGui.Name = "KeybindListGui"
            keybindListGui.ResetOnSpawn = false
            keybindListGui.DisplayOrder = 999
            keybindListGui.Parent = PlayerGui

            local main = Instance.new("Frame")
            main.Name = "KeybindListMain"
            main.Size = UDim2.new(0, 260, 0, 60)
            main.Position = UDim2.new(0.5, -130, 0, 100)
            main.BackgroundColor3 = Color3.fromRGB(18, 18, 20)
            main.BackgroundTransparency = 0.1
            main.BorderSizePixel = 0
            main.Active = true
            main.Parent = keybindListGui

            Instance.new("UICorner", main).CornerRadius = UDim.new(0, 6)
            keybindListMain = main

            local title = Instance.new("TextLabel")
            title.Name = "Title"
            title.Size = UDim2.new(1, 0, 0, 22)
            title.Position = UDim2.new(0, 0, 0, 0)
            title.BackgroundTransparency = 1
            title.Text = "Keybinds"
            title.TextColor3 = Color3.fromRGB(255, 255, 255)
            title.Font = Enum.Font.GothamBold
            title.TextSize = 14
            title.TextXAlignment = Enum.TextXAlignment.Center
            title.Parent = main

            local sep = Instance.new("Frame")
            sep.Name = "Separator"
            sep.Size = UDim2.new(0.9, 0, 0, 1)
            sep.Position = UDim2.new(0.05, 0, 0, 22)
            sep.BackgroundColor3 = Color3.fromRGB(60, 60, 60)
            sep.BorderSizePixel = 0
            sep.Parent = main

            local container = Instance.new("Frame")
            container.Name = "ListContainer"
            container.Size = UDim2.new(1, -16, 1, -30)
            container.Position = UDim2.new(0, 8, 0, 28)
            container.BackgroundTransparency = 1
            container.Parent = main
            keybindListContainer = container

            local layout = Instance.new("UIListLayout")
            layout.Padding = UDim.new(0, 2)
            layout.SortOrder = Enum.SortOrder.LayoutOrder
            layout.Parent = container

            local dragging, dragStart, startPos = false, nil, nil
            table.insert(keybindDragConns, main.InputBegan:Connect(function(input)
                if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                    dragging = true
                    dragStart = input.Position
                    startPos = main.Position
                end
            end))
            table.insert(keybindDragConns, main.InputEnded:Connect(function(input)
                if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                    dragging = false
                end
            end))
            table.insert(keybindDragConns, UserInputService.InputChanged:Connect(function(input)
                if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
                    local delta = input.Position - dragStart
                    main.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
                end
            end))

            itemLabels = {}
            library.OnKeybindChanged = function()
                requestUpdate()
            end

            updateKeybindDisplay()
        else
            library.OnKeybindChanged = nil
            for _, c in ipairs(keybindDragConns) do if c.Connected then c:Disconnect() end end
            keybindDragConns = {}
            if keybindListGui then keybindListGui:Destroy() keybindListGui = nil end
            keybindListMain = nil
            keybindListContainer = nil
            itemLabels = {}
            pendingUpdate = false
        end
    end})
end
setupKeybindList()
local b64chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local function base64Encode(str)
    local bits = str:gsub(".", function(c)
        local v = c:byte()
        local b = ""
        for i = 7, 0, -1 do
            local r = v % (2 ^ (i + 1))
            b = b .. (r >= 2 ^ i and "1" or "0")
            v = v - (r >= 2 ^ i and 2 ^ i or 0)
        end
        return b
    end)
    bits = bits .. "0000"
    local out = ""
    for i = 1, #bits, 7 do
        local chunk = bits:sub(i, i + 6)
        if #chunk < 7 then break end
        local c = 0
        for j = 1, 7 do
            if chunk:sub(j, j) == "1" then c = c + 2 ^ (7 - j) end
        end
        c = math.floor(c / 2)
        out = out .. b64chars:sub(c + 1, c + 1)
    end
    local pad = 4 - (#out % 4)
    if pad == 4 then pad = 0 end
    return out .. ("="):rep(pad)
end
local function base64Decode(b64)
    b64 = b64:gsub("[^A-Za-z0-9+/=]", "")
    local out = ""
    for i = 1, #b64, 4 do
        local chunk = b64:sub(i, i + 3)
        local bits = ""
        for j = 1, #chunk do
            local ch = chunk:sub(j, j)
            if ch == "=" then break end
            local pos = b64chars:find(ch, 1, true) - 1
            for k = 5, 0, -1 do
                bits = bits .. (pos % (2 ^ (k + 1)) >= 2 ^ k and "1" or "0")
            end
        end
        for j = 1, #bits - 7, 8 do
            local byte = 0
            for k = 1, 8 do
                if bits:sub(j + k - 1, j + k - 1) == "1" then
                    byte = byte + 2 ^ (8 - k)
                end
            end
            out = out .. string.char(byte)
        end
    end
    return out
end
local CONFIG_FILENAME = "config.txt"
local function dedupe(list)
    local seen = {}
    local out = {}
    for _, p in ipairs(list) do
        if p and p ~= "" and not seen[p] then
            seen[p] = true
            out[#out + 1] = p
        end
    end
    return out
end
local function getRealProfiles()
    local profiles = {}
    local seen = {}
    local function add(p)
        p = tostring(p):gsub("/", "\\")
        if p ~= "" and not seen[p] then
            seen[p] = true
            table.insert(profiles, p)
        end
    end
    local okEnv, envFn = pcall(function() return os.getenv end)
    if okEnv and type(envFn) == "function" then
        local ok1, v1 = pcall(function() return envFn("USERPROFILE") end)
        local ok2, v2 = pcall(function() return envFn("HOME") end)
        local ok3, v3 = pcall(function() return envFn("HOMEDRIVE") end)
        local ok4, v4 = pcall(function() return envFn("HOMEPATH") end)
        if ok1 and type(v1) == "string" and v1 ~= "" then
            add(v1)
        elseif ok2 and type(v2) == "string" and v2 ~= "" then
            add(v2)
        elseif ok3 and ok4 and type(v3) == "string" and type(v4) == "string" and v3 ~= "" and v4 ~= "" then
            add(v3 .. v4)
        end
    end
    local userFolders
    local okL = pcall(function() userFolders = listfiles("C:\\Users") end)
    if not (okL and type(userFolders) == "table") then
        okL = pcall(function() userFolders = listfiles("C:/Users") end)
    end
    if okL and type(userFolders) == "table" then
        warn("[CFG] listfiles C:\\Users count=" .. tostring(#userFolders))
        for _, f in ipairs(userFolders) do
            local seg = tostring(f):gsub("\\", "/"):match("([^/]+)/?$")
            if seg and seg ~= "" and seg ~= "Public" and seg ~= "Default" and seg ~= "All Users" and seg ~= "desktop.ini" then
                add("C:\\Users\\" .. seg)
            end
        end
    else
        warn("[CFG] listfiles C:\\Users failed or empty")
    end
    return profiles
end
local function getDocumentsCandidates()
    local list = {}
    local temp
    local okEnv, envFn = pcall(function() return os.getenv end)
    if okEnv and type(envFn) == "function" then
        local ok5, v5 = pcall(function() return envFn("TEMP") end)
        local ok6, v6 = pcall(function() return envFn("TMP") end)
        if ok5 and type(v5) == "string" and v5 ~= "" then
            temp = v5
        elseif ok6 and type(v6) == "string" and v6 ~= "" then
            temp = v6
        end
    end
    local profiles = getRealProfiles()
    warn("[CFG] getenv type=" .. tostring(okEnv and type(envFn)) .. " profiles: " .. table.concat(profiles, " | "))
    for _, prof in ipairs(profiles) do
        list[#list + 1] = prof .. "\\Documents\\" .. CONFIG_FILENAME
        list[#list + 1] = prof .. "\\OneDrive\\Documents\\" .. CONFIG_FILENAME
        list[#list + 1] = prof .. "\\AppData\\Local\\Temp\\" .. CONFIG_FILENAME
    end
    if temp then
        list[#list + 1] = tostring(temp):gsub("/", "\\") .. "\\" .. CONFIG_FILENAME
    end
    return dedupe(list)
end
local function saveConfigToFile(json)
    local candidates = getDocumentsCandidates()
    warn("[CFG] candidates: " .. table.concat(candidates, " | "))
    for _, path in ipairs(candidates) do
        local ok, err = pcall(function() writefile(path, json) end)
        if ok then
            return path
        end
        warn("[CFG] write failed: " .. tostring(path) .. " :: " .. tostring(err))
    end
    local okF = pcall(function() writefile(CONFIG_FILENAME, json) end)
    if okF then
        return CONFIG_FILENAME
    end
    return nil
end
local function loadConfigFromFile()
    local candidates = getDocumentsCandidates()
    candidates[#candidates + 1] = CONFIG_FILENAME
    for _, path in ipairs(candidates) do
        local ok, raw = pcall(function() return readfile(path) end)
        if ok and raw and raw ~= "" then
            return raw, path
        end
    end
    return nil, nil
end
miscConfigSec:Button({Text = "Save Config", Callback = function()
    warn("[CFG] Export start")
    local export = {}
    local count = 0
    for flag, val in pairs(library.Flags) do
        if typeof(val) == "Color3" then
            export[flag] = { R = val.R, G = val.G, B = val.B }
            count = count + 1
        elseif type(val) == "table" then
            local keys = {}
            for k, v in pairs(val) do
                if typeof(v) == "Color3" then
                    keys[k] = { R = v.R, G = v.G, B = v.B }
                elseif type(v) ~= "function" and type(v) ~= "userdata" and type(v) ~= "table" then
                    keys[k] = v
                end
            end
            if next(keys) then
                export[flag] = keys
                count = count + 1
            end
        elseif type(val) ~= "function" and type(val) ~= "userdata" then
            export[flag] = val
            count = count + 1
        end
    end
    for section, values in pairs(Settings) do
        if type(values) == "table" then
            for k, v in pairs(values) do
                if type(v) ~= "function" and type(v) ~= "userdata" and type(v) ~= "table" then
                    export[section .. "." .. k] = v
                    count = count + 1
                end
            end
        end
    end
    do
        local kbMap = {ZoomBind="Zoom",PalletGodKey="Part Object Grab",PvpSafe="PVP SAFE",PushKey="Push Key",SpamDanceKey="Spam Dance",LegitAimKey="Legit Aim Key",PlayerFlyKey="Fly Key",PlayerClickTPKey="TP Key"}
        local kd = {}
        local gui = library.ScreenGui
        if gui then
            for fl, dn in pairs(kbMap) do
                for _, d in ipairs(gui:GetDescendants()) do
                    if d.Name=="KeybindText" and d:IsA("TextLabel") and d.Text==dn then
                        local p = d.Parent
                        if p and p.Name=="Keybind" then
                            local f = p:FindFirstChild("KeybindFrame")
                            if f then
                                local ft = f:FindFirstChild("KeybindFrameText")
                                if ft and ft.Text ~= "" then kd[fl] = ft.Text end
                            end
                        end
                        break
                    end
                end
            end
        end
        if next(kd) then export["__keybinds__"] = kd count = count + 1 end
    end
    warn("[CFG] Export count: " .. count)
    local json = HttpService:JSONEncode(export)
    warn("[CFG] JSON length: " .. #json)
    local savedPath = saveConfigToFile(json)
    warn("[CFG] save result: " .. tostring(savedPath))
    if savedPath then
        configLabel:Set({Text = "Saved to " .. savedPath .. " (" .. #json .. " chars)"})
    else
        configLabel:Set({Text = "Failed to save config"})
    end
end})
miscConfigSec:Button({Text = "Load Config", Callback = function()
    warn("[CFG] Import start")
    local raw, loadPath = loadConfigFromFile()
    warn("[CFG] load path: " .. tostring(loadPath) .. " len=" .. tostring(raw and #raw or "nil"))
    if not raw or raw == "" then warn("[CFG] file empty") configLabel:Set({Text = "No config file found"}) return end
    warn("[CFG] file start: " .. raw:sub(1, 100))
    local ok, data = pcall(function() return HttpService:JSONDecode(raw) end)
    warn("[CFG] JSONDecode: " .. tostring(ok))
    if not ok or type(data) ~= "table" then warn("[CFG] decode err: " .. tostring(data)) return end
    local setterCount = 0
    local flagCount = 0
    for flag, val in pairs(data) do
        if flag ~= "__keybinds__" then
            if library._flagSetters and library._flagSetters[flag] then
                if type(val) == "table" then
                    if type(val.R) == "number" and type(val.G) == "number" and type(val.B) == "number" then
                        local col = Color3.new(val.R, val.G, val.B)
                        local sOk, sErr = pcall(function() library._flagSetters[flag](col) end)
                        warn("[CFG] color setter " .. flag .. " ok=" .. tostring(sOk) .. " " .. tostring(sErr))
                        setterCount = setterCount + 1
                    else
                        local current = library.Flags[flag]
                        local target
                        if type(current) == "table" then
                            target = current
                        else
                            target = {}
                            library.Flags[flag] = target
                        end
                        for k, v in pairs(val) do
                            if type(v) == "table" and type(v.R) == "number" and type(v.G) == "number" and type(v.B) == "number" then
                                target[k] = Color3.new(v.R, v.G, v.B)
                            else
                                target[k] = v
                            end
                        end
                        pcall(function() library._flagSetters[flag](library.Flags[flag]) end)
                        warn("[CFG] setter " .. flag .. "=table ok")
                        setterCount = setterCount + 1
                    end
                else
                    local current = library.Flags[flag]
                    if current ~= val then
                        local sOk, sErr = pcall(function() library._flagSetters[flag](val) end)
                        warn("[CFG] setter " .. flag .. "=" .. tostring(val) .. " ok=" .. tostring(sOk) .. " " .. tostring(sErr))
                        setterCount = setterCount + 1
                    end
                end
            elseif string.find(flag, "%.") then
                local section, key = flag:match("^(.-)%.(.+)$")
                if section and key and Settings[section] and Settings[section][key] ~= val then
                    Settings[section][key] = val
                end
            else
                if library.Flags[flag] ~= val then
                    library.Flags[flag] = val
                    flagCount = flagCount + 1
                end
            end
        end
    end
    if data["__keybinds__"] then
        do
            local kbMap = {ZoomBind="Zoom",PalletGodKey="Part Object Grab",PvpSafe="PVP SAFE",PushKey="Push Key",SpamDanceKey="Spam Dance",LegitAimKey="Legit Aim Key",PlayerFlyKey="Fly Key",PlayerClickTPKey="TP Key"}
            for fl, kn in pairs(data["__keybinds__"]) do
                if library._flagSetters and library._flagSetters[fl] then
                    local current = library.Flags[fl]
                    local mode = "Toggle"
                    if type(current) == "table" then
                        mode = current.Mode or "Toggle"
                    end
                    pcall(function() library._flagSetters[fl]({Key = kn, Mode = mode}) end)
                end
            end
        end
        warn("[CFG] keybinds loaded")
    end
    warn("[CFG] Done. Setters: " .. setterCount .. " Flags: " .. flagCount)
    configLabel:Set({Text = "Loaded " .. setterCount .. " settings"})
end})
local function updatePvPCharacter(NewCharacter)
    if not (NewCharacter and NewCharacter:IsDescendantOf(workspace)) then return end
    State.Root = NewCharacter:WaitForChild("HumanoidRootPart", 3)
    if not State.Root then return end
    State.HRPs[State.Root] = nil
end
if LocalPlayer.Character then updatePvPCharacter(LocalPlayer.Character) end
LocalPlayer.CharacterAdded:Connect(updatePvPCharacter)
workspace.DescendantAdded:Connect(function(Descendant)
    if Descendant:IsA("BasePart") and Descendant.Name == "HumanoidRootPart" then
        if Descendant ~= State.Root then State.HRPs[Descendant] = true end
    end
end)
workspace.DescendantRemoving:Connect(function(Descendant)
    if State.HRPs[Descendant] then
        State.HRPs[Descendant] = nil
        if State.LastGrabbedTarget == Descendant then State.LastGrabbedTarget = nil end
    end
end)
for _, Descendant in workspace:GetDescendants() do
    if Descendant:IsA("BasePart") and Descendant.Name == "HumanoidRootPart" then
        if Descendant ~= State.Root then State.HRPs[Descendant] = true end
    end
end
do
    local savedRotCF = nil
    local isLocking = false
    local function isRotateVisible()
        local ok, result = pcall(function()
            local pg = LocalPlayer:FindFirstChild("PlayerGui")
            if not pg then return false end
            local cg = pg:FindFirstChild("ControlsGui")
            if not cg then return false end
            local pf = cg:FindFirstChild("PCFrame")
            if not pf then return false end
            local r = pf:FindFirstChild("Rotate")
            if not r then return false end
            return r.Visible
        end)
        return ok and result or false
