    local tbAlreadyFiring = false
    RunService.RenderStepped:Connect(function(dt)
        local ok, err = pcall(function()
            if not Settings.PvP.TriggerbotEnabled then
                tbAlreadyFiring = false
                return
            end
            if Settings.PvP.TriggerKeybindMode and not Settings.PvP.TriggerKeybindHeld then
                tbAlreadyFiring = false
                return
            end
            if workspace:FindFirstChild("GrabParts") then
                tbAlreadyFiring = false
                return
            end
            local myChar = LocalPlayer.Character
            local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
            if not myRoot then tbAlreadyFiring = false return end
            local cam = State.CameraClone or workspace.CurrentCamera
            if not cam then tbAlreadyFiring = false return end
            local camCF = cam.CFrame
            local origin = camCF.Position
            local vpSize = cam.ViewportSize
            local centerX, centerY = vpSize.X / 2, vpSize.Y / 2
            tbRayParams.FilterDescendantsInstances = { myChar, workspace.Terrain }
            local now = tick()
            local bestTarget = nil
            local bestDist = tbFOV
            for _, plr in ipairs(Players:GetPlayers()) do
                if plr ~= LocalPlayer then
                    local plrChar = plr.Character
                    if plrChar then
                        local plrRoot = plrChar:FindFirstChild("HumanoidRootPart")
                        local plrHum = plrChar:FindFirstChildOfClass("Humanoid")
                        if plrRoot and plrHum and plrHum.Health > 0 then
                            local dist = (myRoot.Position - plrRoot.Position).Magnitude
                            local hasGamepass = LocalPlayer:FindFirstChild("FartherReach") ~= nil
                            if dist <= (hasGamepass and 30 or 20) then
                                local velocity = plrRoot.Velocity
                                local predictedPos = plrRoot.Position + velocity * dt * 2
                                local parts = {"Head", "Torso", "HumanoidRootPart", "Right Arm", "Left Arm", "Right Leg", "Left Leg", "Right Hand", "Left Hand"}
                                for _, partName in ipairs(parts) do
                                    local part = plrChar:FindFirstChild(partName)
                                    if part then
                                        local worldPos = part.Position
                                        local screenPos, onScreen = cam:WorldToScreenPoint(worldPos)
                                        if onScreen then
                                            local dx = screenPos.X - centerX
                                            local dy = screenPos.Y - centerY
                                            local screenDist = math.sqrt(dx * dx + dy * dy)
                                            local predScreenPos = cam:WorldToScreenPoint(predictedPos)
                                            local pdx = predScreenPos.X - centerX
                                            local pdy = predScreenPos.Y - centerY
                                            local predScreenDist = math.sqrt(pdx * pdx + pdy * pdy)
                                            local effectiveDist = math.min(screenDist, predScreenDist)
                                            if effectiveDist < bestDist then
                                                local rayDir = (worldPos - origin)
                                                local rayResult = workspace:Raycast(origin, rayDir, tbRayParams)
                                                if rayResult then
                                                    local hitModel = rayResult.Instance:FindFirstAncestorOfClass("Model")
                                                    if hitModel and hitModel == plrChar then
                                                        bestDist = effectiveDist
                                                        bestTarget = part
                                                    end
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end
            if bestTarget then
                if not tbAlreadyFiring then
                    tbAlreadyFiring = true
                    tbLastFire = now
                    pcall(function() mouse1press() end)
                    pcall(function() mouse1release() end)
                end
            else
                tbAlreadyFiring = false
            end
        end)
    end)
end
