local runningSpinAura = false
local spinAuraTask = nil
auraAtkSec:Toggle({Text = "Spin Aura", Flag = "SpinAura", Default = false, Callback = function(enabled)
    runningSpinAura = enabled
    if enabled then
        spinAuraTask = task.spawn(function()
            local spinAngle = 0
            while runningSpinAura do
                pcall(function()
                    local root = auraGetRoot()
                    if not root then return end
                    local spinRadius = Settings.Aura.auraRadius * 0.8
                    spinAngle = spinAngle + 0.05
                    if spinAngle >= 6.28 then spinAngle = 0 end
                    local inRange = {}
                    for _, player in pairs(Players:GetPlayers()) do
                        if player ~= LocalPlayer and not auraIsFriend(player) and not isProtectedPlayer(player.Name) and player.Character then
                            local targetChar = player.Character
                            local humanoid = targetChar:FindFirstChildOfClass("Humanoid")
                            local torso = targetChar:FindFirstChild("Torso") or targetChar:FindFirstChild("UpperTorso") or targetChar:FindFirstChild("HumanoidRootPart")
                            if torso and humanoid and humanoid.Health > 0 then
                                local dist = (Vector3.new(torso.Position.X, 0, torso.Position.Z) - Vector3.new(root.Position.X, 0, root.Position.Z)).Magnitude
                                if dist <= spinRadius then
                                    table.insert(inRange, {player = player, torso = torso, humanoid = humanoid})
                                else
                                    local t = targetChar:FindFirstChild("Torso") or targetChar:FindFirstChild("UpperTorso") or targetChar:FindFirstChild("HumanoidRootPart")
                                    if t then
                                        local bv = t:FindFirstChild("SpinAuraBV")
                                        local bg = t:FindFirstChild("SpinAuraBG")
                                        if bv then bv:Destroy() end
                                        if bg then bg:Destroy() end
                                    end
                                    humanoid.PlatformStand = false
                                end
                            end
                        end
                    end
                    local count = #inRange
                    if count > 0 then
                        local circleRadius = 10
                        local GE = ReplicatedStorage.GrabEvents
                        for i, data in ipairs(inRange) do
                            local angle = spinAngle + (i - 1) * (2 * math.pi / count)
                            local targetPosition = root.Position + Vector3.new(math.cos(angle) * circleRadius, 5, math.sin(angle) * circleRadius)
                            pcall(function()
                                RemoteDispatcher:Fire(GE.SetNetworkOwner, data.torso, root.CFrame)
                            end)
                            task.wait(0.035)
                            pcall(function()
                                RemoteDispatcher:Fire(GE.CreateGrabLine, data.torso, Vector3.zero, data.torso.Position, false)
                            end)
                            task.wait(0.035)
                            pcall(function()
                                RemoteDispatcher:Fire(GE.DestroyGrabLine, data.torso)
                            end)
                            local bv = data.torso:FindFirstChild("SpinAuraBV") or Instance.new("BodyVelocity")
                            bv.Name = "SpinAuraBV"
                            local diff = targetPosition - data.torso.Position
                            local vel = diff * 25
                            bv.Velocity = vel
                            bv.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
                            bv.P = 10000
                            bv.Parent = data.torso
                            local bg = data.torso:FindFirstChild("SpinAuraBG") or Instance.new("BodyGyro")
                            bg.Name = "SpinAuraBG"
                            bg.MaxTorque = Vector3.new(math.huge, math.huge, math.huge)
                            bg.P = 10000
                            bg.D = 500
                            bg.CFrame = CFrame.new(data.torso.Position, Vector3.new(root.Position.X, data.torso.Position.Y, root.Position.Z))
                            bg.Parent = data.torso
                            data.humanoid.PlatformStand = true
                        end
                    end
                end)
                task.wait(0.02)
            end
        end)
    else
        if spinAuraTask then task.cancel(spinAuraTask) spinAuraTask = nil end
        for _, player in pairs(Players:GetPlayers()) do
            if player ~= LocalPlayer and player.Character then
                local humanoid = player.Character:FindFirstChildOfClass("Humanoid")
                local torso = player.Character:FindFirstChild("Torso") or player.Character:FindFirstChild("UpperTorso") or player.Character:FindFirstChild("HumanoidRootPart")
                if humanoid then humanoid.PlatformStand = false end
                if torso then
                    local bv = torso:FindFirstChild("SpinAuraBV")
                    local bg = torso:FindFirstChild("SpinAuraBG")
                    if bv then bv:Destroy() end
                    if bg then bg:Destroy() end
                end
            end
        end
    end
end})
local traxAuraEnabled = false
local traxAuraTask = nil
auraAtkSec:Toggle({Text = "Trax Aura", Flag = "TraxAura", Default = false, Callback = function(v)
    traxAuraEnabled = v
    if v then
        traxAuraTask = task.spawn(function()
            local oscillation = 0
            while traxAuraEnabled do
                pcall(function()
                    local root = auraGetRoot()
                    if not root then return end
                    oscillation = oscillation + 0.3
                    local moveOffset = math.sin(oscillation) * 2
                    for _, player in pairs(Players:GetPlayers()) do
                        if player ~= LocalPlayer and not auraIsFriend(player) and not isProtectedPlayer(player.Name) and player.Character then
                            local torso = player.Character:FindFirstChild("Torso") or player.Character:FindFirstChild("UpperTorso") or player.Character:FindFirstChild("HumanoidRootPart")
                            local humanoid = player.Character:FindFirstChildOfClass("Humanoid")
                            if torso and humanoid and (torso.Position - root.Position).Magnitude <= Settings.Aura.auraRadius then
                                local lookVector = root.CFrame.LookVector
                                local lowerFrontPos = root.Position + (lookVector * 3) + Vector3.new(0, -1.4, 0)
                                local currentDistance = 2 + moveOffset / 1.4
                                local targetPosition = lowerFrontPos + (lookVector * currentDistance)
                                RemoteDispatcher:Fire(ReplicatedStorage.GrabEvents.SetNetworkOwner, torso, CFrame.new(targetPosition))
                                local bv = torso:FindFirstChild("TraxAuraBV") or Instance.new("BodyVelocity")
                                bv.Name = "TraxAuraBV"
                                local diff = targetPosition - torso.Position
                                local vel = diff * 25
                                bv.Velocity = vel
                                bv.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
                                bv.P = 10000
                                bv.Parent = torso
                                local bg = torso:FindFirstChild("TraxAuraBG") or Instance.new("BodyGyro")
                                bg.Name = "TraxAuraBG"
                                bg.MaxTorque = Vector3.new(math.huge, math.huge, math.huge)
                                bg.P = 10000
                                bg.D = 500
                                bg.CFrame = CFrame.new(torso.Position, lowerFrontPos) * CFrame.Angles(math.rad(90), math.pi, 0)
                                bg.Parent = torso
                                humanoid.PlatformStand = true
                            else
                                local bv = torso:FindFirstChild("TraxAuraBV")
                                local bg = torso:FindFirstChild("TraxAuraBG")
                                if bv then bv:Destroy() end
                                if bg then bg:Destroy() end
                            end
                        end
                    end
                end)
                task.wait(0.03)
            end
        end)
    else
        if traxAuraTask then task.cancel(traxAuraTask) traxAuraTask = nil end
        for _, player in pairs(Players:GetPlayers()) do
            if player ~= LocalPlayer and player.Character then
                local humanoid = player.Character:FindFirstChildOfClass("Humanoid")
                local torso = player.Character:FindFirstChild("Torso") or player.Character:FindFirstChild("UpperTorso")
                if humanoid then humanoid.PlatformStand = false end
                if torso then
                    local bv = torso:FindFirstChild("TraxAuraBV")
                    local bg = torso:FindFirstChild("TraxAuraBG")
                    if bv then bv:Destroy() end
                    if bg then bg:Destroy() end
                end
            end
        end
    end
end})
