local runningDestroyAntiKickAura = false
local destroyAuraCancelId = 0
auraAtkSec:Toggle({Text = "Anti Anti Kick Aura", Flag = "DestroyAntiKickAura", Default = false, Callback = function(enabled)
    if not enabled then
        runningDestroyAntiKickAura = false
        destroyAuraCancelId = destroyAuraCancelId + 1
        if State.antiKickAuraTask then task.cancel(State.antiKickAuraTask) State.antiKickAuraTask = nil end
        return
    end
    runningDestroyAntiKickAura = true
    local myCancelId = destroyAuraCancelId
    State.antiKickAuraTask = task.spawn(function()
        local processedParents = {}
        while runningDestroyAntiKickAura and destroyAuraCancelId == myCancelId do
            local root = auraGetRoot()
            if not root then task.wait(0.2) continue end
            local myPos = root.Position
            local auraRadius = Settings.Aura.auraRadius
            local myChar = LocalPlayer.Character
            table.clear(processedParents)
            for _, obj in ipairs(Workspace:GetPartBoundsInRadius(myPos, auraRadius)) do
                if not runningDestroyAntiKickAura or destroyAuraCancelId ~= myCancelId then return end
                if not obj:IsA("BasePart") then continue end
                if obj.Name ~= "StickyPart" then continue end
                if myChar and myChar:IsAncestorOf(obj) then continue end
                local parent = obj.Parent
                if not parent or processedParents[parent] then continue end
                if isMySpawnedToy(obj) then continue end
                processedParents[parent] = true
                -- Claim network ownership with 3 SetNetworkOwner calls before pushing
                pcall(function()
                    for _ = 1, 3 do
                        RemoteDispatcher:Fire(setNetworkOwnerEvent, obj, obj.CFrame)
                    end
                    RemoteDispatcher:Fire(createGrabLineEvent, obj, Vector3.zero, obj.Position, false)
                    RemoteDispatcher:Fire(destroyGrabLineEvent, obj)
                end)
                for _, part in ipairs(parent:GetChildren()) do
                    if not runningDestroyAntiKickAura or destroyAuraCancelId ~= myCancelId then return end
                    if not part:IsA("BasePart") then continue end
                    local direction = (part.Position - myPos)
                    direction = Vector3.new(direction.X, 0, direction.Z)
                    local dist = direction.Magnitude
                    if dist < 0.5 then continue end
                    pcall(function()
                        -- 3 SetNetworkOwner calls before setting velocity
                        for _ = 1, 3 do
                            RemoteDispatcher:Fire(setNetworkOwnerEvent, part, part.CFrame)
                        end
                        local pushDir = direction.Unit
                        local force = math.clamp(200 / dist, 50, 300) * 1000
                        part.AssemblyLinearVelocity = pushDir * force
                        part.AssemblyAngularVelocity = Vector3.new(
                            math.random(-8, 8),
                            math.random(-8, 8),
                            math.random(-8, 8)
                        )
                        -- Immediately 2 SetNetworkOwner calls right after velocity
                        for _ = 1, 2 do
                            RemoteDispatcher:Fire(setNetworkOwnerEvent, part, part.CFrame)
                        end
                    end)
                end
            end
            task.wait(0.08)
        end
    end)
end})
auraAtkSec:Toggle({Text = "Anti Blobman Aura", Flag = "AntiBlobmanAura", Default = false, Callback = function(v)
