local runningAntiBananaAura = false
local antiBananaAuraCancelId = 0
auraAtkSec:Toggle({Text = "Anti Banana Aura", Flag = "AntiBananaAura", Default = false, Callback = function(enabled)
    if not enabled then
        runningAntiBananaAura = false
        antiBananaAuraCancelId = antiBananaAuraCancelId + 1
        return
    end
    runningAntiBananaAura = true
    local myCancelId = antiBananaAuraCancelId
    task.spawn(function()
        local GE = ReplicatedStorage:WaitForChild("GrabEvents")
        local setNE = GE:WaitForChild("SetNetworkOwner")
        local createGL = GE:WaitForChild("CreateGrabLine")
        local destroyGL = GE:WaitForChild("DestroyGrabLine")
        local auraFrame = 0
        while runningAntiBananaAura and antiBananaAuraCancelId == myCancelId do
            local root = auraGetRoot()
            if not root then task.wait(0.2) continue end
            local myPos = root.Position
            local auraRadius = Settings.Aura.auraRadius
            local myChar = LocalPlayer.Character
            for _, obj in ipairs(Workspace:GetPartBoundsInRadius(myPos, auraRadius)) do
                if not runningAntiBananaAura or antiBananaAuraCancelId ~= myCancelId then return end
                if not obj:IsA("BasePart") then continue end
                if obj.Name ~= "HitboxPart" then continue end
                if myChar and myChar:IsAncestorOf(obj) then continue end
                if isMySpawnedToy(obj) then continue end
                if auraFrame % 3 == 0 then
                    RemoteDispatcher:Fire(setNE, obj, obj.CFrame)
                elseif auraFrame % 3 == 1 then
                    RemoteDispatcher:Fire(createGL, obj, Vector3.zero, obj.Position, false)
                else
                    RemoteDispatcher:Fire(destroyGL, obj)
                end
                pcall(function()
                    local direction = (obj.Position - myPos).Unit
                    local bv = Instance.new("BodyVelocity")
                    bv.Velocity = direction * 5000 + Vector3.new(0, 2000, 0)
                    bv.MaxForce = Vector3.one * math.huge
                    bv.Parent = obj
                    Debris:AddItem(bv, 0.3)
                end)
            end
            auraFrame = auraFrame + 1
            task.wait()
        end
    end)
end})
local runningShieldAura = false
local shieldAuraCancelId = 0
auraAtkSec:Toggle({Text = "Toys Shield Aura", Flag = "ShieldAura", Default = false, Callback = function(enabled)
    if not enabled then
        runningShieldAura = false
        shieldAuraCancelId = shieldAuraCancelId + 1
        return
    end
    runningShieldAura = true
    local myCancelId = shieldAuraCancelId
    task.spawn(function()
        local setNetworkOwner = grabEventsFolder:FindFirstChild("SetNetworkOwner")
        if not setNetworkOwner then return end

        local scanInterval = 0.12
        local maxObjectsPerPass = 8
        local nextScan = 0
        local nextCandidateIndex = 1
        local candidates = {}
        local activeParts = {}

        local function isPlayerPart(part, playerCharacters)
            local node = part
            while node and node ~= Workspace do
                if playerCharacters[node] then return true end
                node = node.Parent
            end
            return false
        end

        local function clearPart(part)
            if not part then return end
            pcall(function()
                part.AssemblyLinearVelocity = Vector3.zero
                part.AssemblyAngularVelocity = Vector3.zero
            end)
        end

        local function refreshCandidates(position, radius)
            local playerCharacters = {}
            for _, player in ipairs(Players:GetPlayers()) do
                if player.Character then
                    playerCharacters[player.Character] = true
                end
            end

            local found = {}
            local foundParts = {}
            local ok, nearbyParts = pcall(function()
                return Workspace:GetPartBoundsInRadius(position, radius)
            end)
            if not ok or not nearbyParts then
                nearbyParts = {}
            end

            for _, obj in ipairs(nearbyParts) do
                if obj:IsA("BasePart") and not obj.Anchored
                    and not isPlayerPart(obj, playerCharacters)
                    and not isMySpawnedToy(obj) then
                    local assemblyPart = obj.AssemblyRootPart or obj
                    if assemblyPart and assemblyPart.Parent and not assemblyPart.Anchored
                        and not foundParts[assemblyPart] then
                        foundParts[assemblyPart] = true
                        found[#found + 1] = {part = assemblyPart, sample = obj}
                    end
                end
            end

            -- GetPartBoundsInRadius can return many parts from one toy. Keep one
            -- assembly root per toy and process the list in a stable order so a
            -- large pile cannot starve objects at the end of the query result.
            table.sort(found, function(a, b)
                local aName = a.part:GetFullName()
                local bName = b.part:GetFullName()
                return aName < bName
            end)

            local oldParts = activeParts
            activeParts = {}
            for _, candidate in ipairs(found) do
                activeParts[candidate.part] = true
            end
            for part in pairs(oldParts) do
                if not activeParts[part] then
                    clearPart(part)
                end
            end
            candidates = found
            if nextCandidateIndex > #candidates then
                nextCandidateIndex = 1
            end
        end

        local function processCandidate(candidate, position, radius)
            local part = candidate.part
            local sample = candidate.sample
            if not part or not part.Parent or part.Anchored then return end
            if not sample or not sample.Parent then return end
            if (sample.Position - position).Magnitude > radius + 1 then return end
            local direction = part.Position - position
            direction = Vector3.new(direction.X, 0, direction.Z)
            local distance = direction.Magnitude
            if distance < 0.5 then return end
            pcall(function()
                local hasSticky = (part.Name == "StickyPart")
                if not hasSticky and part.Parent then
                    hasSticky = (part.Parent:FindFirstChild("StickyPart") ~= nil)
                end

                if hasSticky then
                    -- 3 SetNetworkOwner calls before setting velocity
                    for _ = 1, 3 do
                        RemoteDispatcher:Fire(setNetworkOwner, part, part.CFrame)
                    end
                    local pushDir = direction.Unit
                    local force = math.clamp(200 / distance, 50, 300) * 1000
                    part.AssemblyLinearVelocity = pushDir * force
                    part.AssemblyAngularVelocity = Vector3.new(
                        math.random(-8, 8),
                        math.random(-8, 8),
                        math.random(-8, 8)
                    )
                    -- Immediately 2 SetNetworkOwner calls right after setting velocity
                    for _ = 1, 2 do
                        RemoteDispatcher:Fire(setNetworkOwner, part, part.CFrame)
                    end
                else
                    RemoteDispatcher:Fire(setNetworkOwner, part, part.CFrame)
                    local pushDir = direction.Unit
                    local force = math.clamp(200 / distance, 50, 300) * 1000
                    part.AssemblyLinearVelocity = pushDir * force
                    part.AssemblyAngularVelocity = Vector3.new(
                        math.random(-8, 8),
                        math.random(-8, 8),
                        math.random(-8, 8)
                    )
                end
            end)
        end

        while runningShieldAura and shieldAuraCancelId == myCancelId do
            local root = auraGetRoot()
            if not root then
                task.wait(0.2)
                continue
            end
            local position = root.Position
            local radius = Settings.Aura.auraRadius
            if tick() >= nextScan then
                nextScan = tick() + scanInterval
                refreshCandidates(position, radius)
            end

            local count = #candidates
            if count > 0 then
                if nextCandidateIndex > count then nextCandidateIndex = 1 end
                local processed = math.min(maxObjectsPerPass, count)
                for _ = 1, processed do
                    if not runningShieldAura or shieldAuraCancelId ~= myCancelId then break end
                    local candidate = candidates[nextCandidateIndex]
                    nextCandidateIndex = (nextCandidateIndex % count) + 1
                    processCandidate(candidate, position, radius)
                    task.wait()
                end
            else
                task.wait(scanInterval)
            end
        end

        for part in pairs(activeParts) do
            clearPart(part)
        end
    end)
end})
local repelAuraEnabled = false
