                            if auraFrame % 3 == 0 then
                                RemoteDispatcher:Fire(SetNetworkOwner, part, root.CFrame)
                            elseif auraFrame % 3 == 1 then
                                RemoteDispatcher:Fire(CreateGrabLine, part, Vector3.zero, part.Position, false)
                            else
                                RemoteDispatcher:Fire(DestroyGrabLine, part)
                            end
                            pcall(function() part.AssemblyLinearVelocity = dir * Settings.Aura.repelAuraForce + Vector3.new(0, 50, 0) end)
                        end
                    end
                end
            end
            auraFrame = auraFrame + 1
            task.wait(0.1)
        end
    end) end
end})
