        playerConnections.NC = RunService.Stepped:Connect(function()
            local char = playerGetChar()
            if char then
                for _, p in pairs(char:GetDescendants()) do
                    if p:IsA("BasePart") then p.CanCollide = false end
                end
            end
        end)
