                    if prop == "CFrame" then
                        local camLookRef = Workspace.CurrentCamera.CFrame.LookVector
                        targetHum.CameraOffset = -Vector3.new(camLookRef.X, 5, camLookRef.Z) * 1.7
                    end
                end))
            end

            -- Noclip and continuous teleport 25 studs below creature
            table.insert(controlState.conns, RunService.Stepped:Connect(function()
                if not controlState.active or controlState.mode ~= "creature" then return end
                local c = LocalPlayer.Character
