                    local hrpPart = c:FindFirstChild("HumanoidRootPart")
                    local refPart = targetHRP or targetHead
                    if hrpPart and refPart and refPart.Parent then
                        local underPos = Vector3.new(refPart.Position.X, refPart.Position.Y + charOffset, refPart.Position.Z)
                        hrpPart.CFrame = CFrame.new(underPos)
                        hrpPart.AssemblyLinearVelocity = Vector3.zero
                        hrpPart.AssemblyAngularVelocity = Vector3.zero
                    end
