    lineSec:Toggle({Text = "Model", Flag = "LineModelEnabled", Default = true, Callback = function(v)
        lineModelEnabled = v
        applyLineSettings()
    end})
    lineSec:Toggle({Text = "Colors", Flag = "EnableBeamColor", Default = false, Callback = function(v)
        beamColorEnabled = v
        applyLineSettings()
    end})
    lineSec:ColorPicker({Text = "Start", Flag = "BeamColor0", Default = Color3.fromRGB(255, 255, 255), Callback = function(c)
        beamColor0 = c
        applyLineSettings()
    end})
    lineSec:ColorPicker({Text = "End", Flag = "BeamColor1", Default = Color3.fromRGB(255, 255, 255), Callback = function(c)
        beamColor1 = c
        applyLineSettings()
    end})
    lineSec:Toggle({Text = "Rainbow", Flag = "Rainbow", Default = false, Callback = function(v)
        setRainbowBeam(v)
    end})
