do
    local grabSoundEnabled = false
    local grabSoundChoice = "OOF"
    local grabSoundIdByChoice = {
        ["OOF"] = "rbxassetid://11184290847",
        ["1234567"] = "rbxassetid://1234567",
    }
    local grabLastSoundTime = 0
    local function playGrabSound()
        local now = tick()
        if now - grabLastSoundTime < 0.3 then return end
        grabLastSoundTime = now
        local sid = grabSoundIdByChoice[grabSoundChoice]
        if not sid then return end
        pcall(function()
            local snd = Instance.new("Sound")
            snd.Name = "GrabSound"
            snd.SoundId = sid
            snd.Volume = 1
            snd.PlayOnRemove = true
            snd.Parent = game:GetService("SoundService")
            snd:Destroy()
        end)
    end
    Workspace.DescendantAdded:Connect(function(obj)
        if not grabSoundEnabled then return end
        if obj.Name == "GrabParts" and obj:IsA("Model") then
            playGrabSound()
        end
    end)
    local grabSoundSec = VisualsTab:Section({Text = "Grab Sound"})
    grabSoundSec:Toggle({Text = "Grab Sound", Flag = "GrabSound", Default = false, Callback = function(v)
        grabSoundEnabled = v
    end})
    grabSoundSec:Dropdown({
        Text = "Grab Sound",
        Flag = "GrabSoundSelect",
        List = {"OOF", "1234567"},
        Default = "OOF",
        Callback = function(value)
            grabSoundChoice = value
        end,
    })
end
do
    local Visuals = {}
    Visuals.ForceFieldEnabled = false
    Visuals.ForceFieldColor = Color3.fromRGB(128, 128, 128)
    Visuals.OriginalColors = {}
    Visuals.AuraEnabled = false
    Visuals.AuraType = "Godly"
    Visuals.CustomAuraID = ""
    Visuals.CurrentAuraModel = nil
    Visuals.AuraEffects = {}
    Visuals.AuraModels = {
        Godly = "rbxassetid://16699750981",
        ["Super Sayien"] = "rbxassetid://116109508364297",
        ["North Star"] = "rbxassetid://83945069652732",
        ["Blue Lord"] = "rbxassetid://10974316799",
        ["Pink Aura"] = "rbxassetid://115980859615239",
        ["Angel Wing"] = "rbxassetid://90022969696073",
        ["Sweet Heart"] = "rbxassetid://91724768175470",
        ["Ethereal Aura"] = "rbxassetid://97041568674250",
        Hearts = "hearts_particle",
    }
    local function saveOriginalColors(c)
        Visuals.OriginalColors[c] = {}
        for _, p in ipairs(c:GetDescendants()) do
            if p:IsA("BasePart") and p.Name ~= "Hat" then
                Visuals.OriginalColors[c][p] = {Color = p.Color, Material = p.Material}
            end
        end
    end
    function Visuals.applyForceField(c)
        saveOriginalColors(c)
        for _, p in ipairs(c:GetDescendants()) do
            if p:IsA("BasePart") and p.Name ~= "Hat" then
                p.Color = Visuals.ForceFieldColor
                p.Material = Enum.Material.ForceField
            end
        end
    end
    function Visuals.removeForceField(c)
        local orig = Visuals.OriginalColors[c]
        if not orig then return end
        for p, d in pairs(orig) do
            if p and p.Parent and p:IsA("BasePart") then
                p.Color = d.Color
                p.Material = d.Material
            end
        end
        Visuals.OriginalColors[c] = nil
    end
    function Visuals.updateForceField()
        local c = LocalPlayer.Character
        if not (c and Visuals.ForceFieldEnabled) then return end
        for _, p in ipairs(c:GetDescendants()) do
            if p:IsA("BasePart") and p.Name ~= "Hat" and p.Material == Enum.Material.ForceField then
                p.Color = Visuals.ForceFieldColor
            end
        end
    end
    function Visuals.disableAura()
        for _, o in ipairs(Visuals.AuraEffects) do
            if o and o.Parent then o:Destroy() end
        end
        table.clear(Visuals.AuraEffects)
    end
    function Visuals.enableAura(c)
        Visuals.disableAura()
        if Visuals.AuraType == "Hearts" then
            local head = c:FindFirstChild("Head") or c:FindFirstChildWhichIsA("BasePart")
            if head then
                local holder = Instance.new("Folder")
                holder.Name = "EndorisHeartAura"
                holder.Parent = head
                table.insert(Visuals.AuraEffects, holder)
                local palette = {
                    Color3.fromRGB(255, 60, 60),
                    Color3.fromRGB(255, 110, 140),
                    Color3.fromRGB(255, 40, 90),
                    Color3.fromRGB(220, 70, 120),
                }
                task.spawn(function()
                    while holder and holder.Parent do
                        local size = 0.7 + math.random() * 0.4
                        local heart = Instance.new("Part")
                        heart.Name = "Heart"
                        heart.Size = Vector3.new(size, size, 0.05)
                        heart.Anchored = true
                        heart.CanCollide = false
                        heart.CanQuery = false
                        heart.CanTouch = false
                        heart.CastShadow = false
                        heart.Material = Enum.Material.Neon
                        heart.Transparency = 1
                        heart.Color = palette[math.random(#palette)]
                        heart.CFrame = head.CFrame * CFrame.new(
                            (math.random() * 2 - 1) * 1.5,
                            0.4 + math.random() * 0.6,
                            (math.random() * 2 - 1) * 1.5
                        ) * CFrame.Angles(0, math.rad(math.random(-60, 60)), 0)
                        local gui = Instance.new("BillboardGui")
                        gui.Name = "HeartGui"
                        gui.Size = UDim2.new(1.15, 0, 1.15, 0)
                        gui.AlwaysOnTop = false
                        gui.MaxDistance = 300
                        gui.Adornee = heart
                        local lbl = Instance.new("TextLabel")
                        lbl.Name = "HeartLabel"
                        lbl.Size = UDim2.new(1, 0, 1, 0)
                        lbl.BackgroundTransparency = 1
                        lbl.BorderSizePixel = 0
                        lbl.Text = "РІв„ўТђ"
                        lbl.Font = Enum.Font.GothamBlack
                        lbl.TextScaled = true
                        lbl.TextColor3 = heart.Color
                        lbl.TextStrokeColor3 = Color3.new(
                            math.min(heart.Color.R * 1.4, 1),
                            math.min(heart.Color.G * 1.4, 1),
                            math.min(heart.Color.B * 1.4, 1)
                        )
                        lbl.TextStrokeTransparency = 0
                        lbl.Parent = gui
                        gui.Parent = heart
                        heart.Parent = holder
                        table.insert(Visuals.AuraEffects, heart)
                        task.spawn(function()
                            local t0 = os.clock()
                            local life = 1.3 + math.random() * 0.7
                            local start = heart.CFrame
                            local riseSpeed = 1.2 + math.random() * 0.6
                            while heart and heart.Parent do
                                local dt = (os.clock() - t0) / life
                                if dt >= 1 then break end
                                heart.CFrame = start * CFrame.new(0, dt * riseSpeed, 0)
                                heart.Size = Vector3.new(size * (1 + dt * 0.7), size * (1 + dt * 0.7), 0.05)
                                lbl.TextTransparency = dt * dt
                                lbl.TextStrokeTransparency = dt * dt
                                task.wait()
                            end
                            if heart and heart.Parent then heart:Destroy() end
                        end)
                        task.wait(0.13)
                    end
                end)
            end
            return
        end
        if not Visuals.CurrentAuraModel then return end
        local tmp = Visuals.CurrentAuraModel:Clone()
        for _, o in ipairs(tmp:GetDescendants()) do
            if not o:IsA("BasePart") then
                local cl = o:Clone()
                local pn = o.Parent and o.Parent.Name
                local tgt = pn and c:FindFirstChild(pn) or c:FindFirstChildWhichIsA("BasePart")
                if tgt and not tgt:FindFirstChild(cl.Name) then
                    cl.Parent = tgt
                    table.insert(Visuals.AuraEffects, cl)
                end
            end
        end
        tmp:Destroy()
    end
    function Visuals.updateAuraLogic()
        if Visuals.AuraType == "Hearts" then
            Visuals.CurrentAuraModel = nil
            if Visuals.AuraEnabled and LocalPlayer.Character then Visuals.enableAura(LocalPlayer.Character) end
            return
        end
        local id = Visuals.CustomAuraID ~= "" and ("rbxassetid://" .. Visuals.CustomAuraID:gsub("%D", "")) or Visuals.AuraModels[Visuals.AuraType]
        if not id then return end
        local ok, m = pcall(function() return game:GetObjects(id)[1] end)
        if ok and m then
            Visuals.CurrentAuraModel = m
            if Visuals.AuraEnabled and LocalPlayer.Character then Visuals.enableAura(LocalPlayer.Character) end
        end
    end
    local function vReapply(c)
        task.wait(1)
        if Visuals.ForceFieldEnabled then Visuals.applyForceField(c) end
        if Visuals.AuraEnabled then Visuals.enableAura(c) end
    end
    LocalPlayer.CharacterAdded:Connect(vReapply)
    if LocalPlayer.Character then task.defer(function() vReapply(LocalPlayer.Character) end) end
    RunService.Heartbeat:Connect(function()
        if Visuals.ForceFieldEnabled then Visuals.updateForceField() end
    end)
    visualsSkinAuraSec:Toggle({Text = "Animated Skin", Flag = "VisualFF", Default = false, Callback = function(v)
        Visuals.ForceFieldEnabled = v
        local c = LocalPlayer.Character
        if c then
            if v then Visuals.applyForceField(c) else Visuals.removeForceField(c) end
        end
    end})
    visualsSkinAuraSec:Toggle({Text = "Player Aura", Flag = "VisualAura", Default = false, Callback = function(v)
        Visuals.AuraEnabled = v
        if v then
            if not Visuals.CurrentAuraModel then Visuals.updateAuraLogic() end
            local c = LocalPlayer.Character
            if c then Visuals.enableAura(c) end
        else
            Visuals.disableAura()
        end
    end})
    do
        local ai = {}
        for k in pairs(Visuals.AuraModels) do table.insert(ai, k) end
        table.sort(ai)
        visualsSkinAuraSec:Dropdown({Text = "Aura Type", Flag = "VisualAuraType", Default = "Godly", List = ai, Callback = function(v)
            Visuals.AuraType = v
            Visuals.CustomAuraID = ""
            if Visuals.AuraEnabled then Visuals.updateAuraLogic() end
    end})
end
end
do
    local Angel = {}
    Angel.Enabled = false
    Angel.Task = nil
    Angel.Model = nil
    Angel.LeftWeld = nil
    Angel.RightWeld = nil
    Angel.BaseColor = Color3.fromRGB(214, 214, 214)
    Angel.AccentColor = Color3.fromRGB(255, 255, 255)
    Angel.OffsetX = 1.4
    Angel.OffsetY = 0.5
    Angel.OffsetZ = 0.7
    local function clearAngelWings()
        if Angel.Task then
            task.cancel(Angel.Task)
            Angel.Task = nil
        end
        Angel.LeftWeld = nil
        Angel.RightWeld = nil
        if Angel.Model and Angel.Model.Parent then Angel.Model:Destroy() end
        Angel.Model = nil
    end
    local function createWing(parent, name, right)
        local root = Instance.new("Part")
        root.Name = name
        root.CanCollide = false
        root.CanTouch = false
        root.CanQuery = false
        root.Massless = true
        root.Transparency = 1
        root.Size = Vector3.new(0.25, 0.25, 0.25)
        root.Parent = parent
        local side = right and 1 or -1
        local spine = Instance.new("Part")
        spine.Name = name .. "Spine"
        spine.CanCollide = false
        spine.CanTouch = false
        spine.CanQuery = false
        spine.Massless = true
        spine.Material = Enum.Material.Neon
        spine.Color = Angel.BaseColor:Lerp(Angel.AccentColor, 0.35)
        spine.Transparency = 0.22
        spine.Size = Vector3.new(0.22, 0.6, 1.55)
        spine.Parent = parent
        local spineCF = CFrame.new(side * 0.48, 0.11, 0.74) * CFrame.Angles(math.rad(4), math.rad(side * 12), 0)
        spine.CFrame = root.CFrame * spineCF
        local spineWeld = Instance.new("Weld")
        spineWeld.Part0 = root
        spineWeld.Part1 = spine
        spineWeld.C0 = spineCF
        spineWeld.Parent = spine
        for i = 1, 10 do
            for layer = 1, 2 do
                local feather = Instance.new("Part")
                feather.Name = name .. "Feather" .. tostring(i) .. "_" .. tostring(layer)
                feather.CanCollide = false
                feather.CanTouch = false
                feather.CanQuery = false
                feather.Massless = true
                feather.Material = Enum.Material.Neon
                local t = math.clamp((0.08 + (i / 10) * 0.55) + ((layer == 2 and 0.08 or 0)), 0, 0.95)
                feather.Color = Angel.BaseColor:Lerp(Angel.AccentColor, t)
                feather.Transparency = math.clamp((0.06 + i * 0.018) + ((layer == 2 and 0.08 or 0)), 0.05, 0.55)
                feather.Size = Vector3.new(0.24 + i * 0.022, 0.16 + i * 0.028, 0.95 + i * 0.24)
                feather.Parent = parent
                feather:SetAttribute("WingIndex", i)
                feather:SetAttribute("WingLayer", layer)
                local mesh = Instance.new("SpecialMesh")
                mesh.MeshType = Enum.MeshType.Wedge
                mesh.Scale = Vector3.new(1, 1 + i * 0.03, 1.2 + i * 0.08)
                mesh.Parent = feather
                local zOff = layer == 1 and 0.12 or -0.12
                local yOff = layer == 1 and 0.03 or -0.03
                local ang = layer == 1 and -2 or 4
                local fCF = CFrame.new(side * (0.22 + i * 0.135), (0.28 - i * 0.03) + yOff, (0.02 + i * 0.14) + zOff)
                    * CFrame.Angles(math.rad(4 + i * 0.9), math.rad(side * (11 + i * 5.5)), math.rad(side * (9 + i * 3.5 + ang)))
                feather.CFrame = root.CFrame * fCF
                local weld = Instance.new("Weld")
                weld.Part0 = root
                weld.Part1 = feather
                weld.C0 = fCF
                weld.Parent = feather
            end
        end
        return root
    end
    local function refreshPalette()
        if not Angel.Model or not Angel.Model.Parent then return end
        for _, part in ipairs(Angel.Model:GetDescendants()) do
            if part:IsA("BasePart") then
                local lower = string.lower(part.Name)
                if string.find(lower, "feather", 1, true) then
                    local idx = tonumber(part:GetAttribute("WingIndex")) or 1
                    local layer = tonumber(part:GetAttribute("WingLayer")) or 1
                    local t = math.clamp((0.08 + (idx / 10) * 0.55) + ((layer == 2 and 0.08 or 0)), 0, 0.95)
                    part.Color = Angel.BaseColor:Lerp(Angel.AccentColor, t)
                elseif string.find(lower, "spine", 1, true) then
                    part.Color = Angel.BaseColor:Lerp(Angel.AccentColor, 0.35)
                end
            elseif part:IsA("ParticleEmitter") and part.Name == "EndorisAngelDust" then
                part.Color = ColorSequence.new(Angel.BaseColor:Lerp(Angel.AccentColor, 0.3), Angel.AccentColor)
            end
        end
    end
    local function ensureWingModel()
        local char = LocalPlayer.Character
        local anchor = char and (char:FindFirstChild("UpperTorso") or char:FindFirstChild("Torso") or char:FindFirstChild("HumanoidRootPart"))
        if not char or not anchor then return nil end
        if Angel.Model and Angel.Model.Parent == char and Angel.LeftWeld and Angel.RightWeld then return anchor end
        if Angel.Model and Angel.Model.Parent then Angel.Model:Destroy() end
        Angel.Model = Instance.new("Model")
        Angel.Model.Name = "EndorisAngelWings"
        Angel.Model.Parent = char
        local left = createWing(Angel.Model, "LeftWing", false)
        local right = createWing(Angel.Model, "RightWing", true)
        Angel.LeftWeld = Instance.new("Weld")
        Angel.LeftWeld.Part0 = anchor
        Angel.LeftWeld.Part1 = left
        Angel.LeftWeld.C0 = CFrame.new(-Angel.OffsetX, Angel.OffsetY, Angel.OffsetZ) * CFrame.Angles(0, math.rad(-28), math.rad(-18))
        Angel.LeftWeld.Parent = left
        Angel.RightWeld = Instance.new("Weld")
        Angel.RightWeld.Part0 = anchor
        Angel.RightWeld.Part1 = right
        Angel.RightWeld.C0 = CFrame.new(Angel.OffsetX, Angel.OffsetY, Angel.OffsetZ) * CFrame.Angles(0, math.rad(28), math.rad(18))
        Angel.RightWeld.Parent = right
        local dust = Instance.new("ParticleEmitter")
        dust.Name = "EndorisAngelDust"
        dust.Texture = "rbxassetid://243098098"
        dust.Lifetime = NumberRange.new(0.45, 0.9)
        dust.Speed = NumberRange.new(1, 4)
        dust.Rate = 22
        dust.Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.25), NumberSequenceKeypoint.new(1, 0) })
        dust.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.2), NumberSequenceKeypoint.new(1, 1) })
        dust.Color = ColorSequence.new(Angel.BaseColor:Lerp(Angel.AccentColor, 0.3), Angel.AccentColor)
        dust.Parent = anchor
        refreshPalette()
        return anchor
    end
    local function startWingLoop()
        clearAngelWings()
        Angel.Enabled = true
        Angel.Task = task.spawn(function()
            local t = 0
            local lastTransparency = 0
            while Angel.Enabled do
                local anchor = ensureWingModel()
                if anchor and Angel.LeftWeld and Angel.RightWeld then
                    t = t + 0.2
                    local flap = math.sin(t) * 24
                    local pitch = math.rad(2 + math.cos(t * 0.5) * 2)
                    Angel.LeftWeld.C0 = CFrame.new(-Angel.OffsetX, Angel.OffsetY, Angel.OffsetZ) * CFrame.Angles(pitch, math.rad(-28 - flap), math.rad(-18))
                    Angel.RightWeld.C0 = CFrame.new(Angel.OffsetX, Angel.OffsetY, Angel.OffsetZ) * CFrame.Angles(pitch, math.rad(28 + flap), math.rad(18))
                end
                if Angel.Model and Angel.Model.Parent and tick() - lastTransparency >= 0.1 then
                    lastTransparency = tick()
                    for _, part in ipairs(Angel.Model:GetDescendants()) do
                        if part:IsA("BasePart") then
                            local lower = string.lower(part.Name)
                            if string.find(lower, "feather", 1, true) or string.find(lower, "spine", 1, true) then
                                part.Transparency = 0
                            end
                        end
                    end
                end
                task.wait(0.03)
            end
            clearAngelWings()
        end)
    end
    local function setWingEnabled(v)
        Angel.Enabled = v
        if v then
            startWingLoop()
        else
            clearAngelWings()
        end
    end
    LocalPlayer.CharacterAdded:Connect(function()
        if Angel.Enabled then
            task.wait(0.5)
            ensureWingModel()
        end
    end)
    visualsSkinAuraSec:Toggle({ Text = "Angel Wings", Flag = "AngelWings", Default = false, Callback = setWingEnabled })
end
visualsWorldSec:Dropdown({Text = "PCLD Style", Flag = "PCLDStyle", List = {"Default", "Default V2"}, Default = "Default", Callback = function(v)
    Settings.Misc.pcldStyle = v
end})
visualsWorldSec:Toggle({Text = "PCLD Visual", Flag = "PCLDVisual", Default = false, Callback = function(value)
    Settings.Misc.pcldVisual = value
    if value then
        local function buildPCLDOutline(part)
            local model = Instance.new("Model")
            model.Name = "PCLDOutline"
            local size = part.Size
            local hx, hy, hz = size.X / 2, size.Y / 2, size.Z / 2
            local t = math.clamp(math.min(hx, hy, hz) * 0.08, 0.05, 0.6)
            local corners = {
                Vector3.new(-hx, -hy, -hz), Vector3.new(hx, -hy, -hz),
                Vector3.new(hx, hy, -hz), Vector3.new(-hx, hy, -hz),
                Vector3.new(-hx, -hy, hz), Vector3.new(hx, -hy, hz),
                Vector3.new(hx, hy, hz), Vector3.new(-hx, hy, hz),
            }
            local edges = {{1,2},{2,3},{3,4},{4,1},{5,6},{6,7},{7,8},{8,5},{1,5},{2,6},{3,7},{4,8}}
            local bars = {}
            for _, e in ipairs(edges) do
                local c1, c2 = corners[e[1]], corners[e[2]]
                local mid = (c1 + c2) / 2
                local len = (c2 - c1).Magnitude
                local bar = Instance.new("Part")
                bar.Name = "PCLDEdge"
                bar.Size = Vector3.new(t, t, len)
                bar.Anchored = true
                bar.CanCollide = false
                bar.CanQuery = false
                bar.CanTouch = false
                bar.Massless = true
                bar.Material = Enum.Material.Air
                bar.Color = Settings.Misc.pcldColor or Color3.fromRGB(106, 104, 104)
                bar.Transparency = Settings.Misc.pcldAlpha or 0.5
                bar.CFrame = CFrame.lookAt(mid, c2)
                bar.Parent = model
                table.insert(bars, {bar, bar.CFrame})
            end
            model.Parent = workspace
            return {model = model, bars = bars}
        end
        local function placeOutline(entry, cf)
            for _, b in ipairs(entry.bars) do
                b[1].CFrame = cf * b[2]
            end
        end
        State.pcldParts = {}
        for _, part in ipairs(workspace:GetDescendants()) do
            if part:IsA("BasePart") and part.Name == "PlayerCharacterLocationDetector" then
                table.insert(State.pcldParts, part)
            end
        end
        State.pcldDescConn = workspace.DescendantAdded:Connect(function(part)
            if Settings.Misc.pcldVisual and part:IsA("BasePart") and part.Name == "PlayerCharacterLocationDetector" then
                table.insert(State.pcldParts, part)
            end
        end)
        State.pcldConn = RunService.Heartbeat:Connect(function(dt)
            if not Settings.Misc.pcldVisual then return end
            local style = Settings.Misc.pcldStyle or "Default"
            for i = #State.pcldParts, 1, -1 do
                local part = State.pcldParts[i]
                if not part.Parent then
                    table.remove(State.pcldParts, i)
                    if State.pcldProxies then local proxy = State.pcldProxies[part]; if proxy then pcall(function() proxy:Destroy() end) State.pcldProxies[part] = nil end end
                    if State.pcldOutlines then local o = State.pcldOutlines[part]; if o then pcall(function() o.model:Destroy() end) State.pcldOutlines[part] = nil end end
                    if State.pcldOutlineCFrames then State.pcldOutlineCFrames[part] = nil end
                elseif style == "Default V2" then
                    local entry = State.pcldOutlines and State.pcldOutlines[part]
                    if not (entry and entry.model and entry.model.Parent) then
                        entry = buildPCLDOutline(part)
                        if not State.pcldOutlines then State.pcldOutlines = {} end
                        State.pcldOutlines[part] = entry
                        if not State.pcldOutlineCFrames then State.pcldOutlineCFrames = {} end
                        State.pcldOutlineCFrames[part] = part.CFrame
                    end
                    local hidden = (part.Position.X == 0 and part.Position.Y == 0 and part.Position.Z == 0)
                    for _, b in ipairs(entry.bars) do
                        b[1].Transparency = hidden and 1 or (Settings.Misc.pcldAlpha or 0.5)
                    end
                    part.Transparency = 1
                    if not Settings.Misc.smoothPCLD then
                        placeOutline(entry, part.CFrame)
                    end
                    if State.pcldProxies and State.pcldProxies[part] then pcall(function() State.pcldProxies[part]:Destroy() end) State.pcldProxies[part] = nil end
                else
                    if Settings.Misc.smoothPCLD then
                        local proxy = State.pcldProxies and State.pcldProxies[part]
                        if not (proxy and proxy.Parent) then
                            proxy = Instance.new("Part")
                            proxy.Name = "SmoothPCLD"
                            proxy.Size = part.Size
