        State.pcldNameGuis = {}
        local function ensureGui(part)
            local gui = State.pcldNameGuis[part]
            if not (gui and gui.Parent) then
                gui = Instance.new("BillboardGui")
                gui.Name = "PCLDNameTag"
                gui.Size = UDim2.fromOffset(240, 36)
                gui.AlwaysOnTop = true
                gui.ClipsDescendants = true
                local label = Instance.new("TextLabel")
                label.Name = "Label"
                label.Size = UDim2.new(1, 0, 1, 0)
                label.BackgroundTransparency = 1
                label.BorderSizePixel = 0
                label.TextColor3 = Color3.fromRGB(255, 255, 255)
                label.TextStrokeTransparency = 0.3
                label.Font = Enum.Font.GothamBold
                label.TextSize = 14
                label.TextXAlignment = Enum.TextXAlignment.Center
                label.TextYAlignment = Enum.TextYAlignment.Center
                label.Text = ""
                label.Parent = gui
                gui.Parent = part
                State.pcldNameGuis[part] = gui
            end
            gui.Adornee = part
            if gui.Parent ~= part then gui.Parent = part end
            gui.StudsOffset = Vector3.zero
            gui.ExtentsOffset = Vector3.zero
            gui.MaxDistance = 0
            return gui
        end

        local nameCursor = 1
        local NAME_BATCH = 8
        State.pcldNameTask = task.spawn(function()
            while Settings.Misc.pcldNames do
                task.wait(0.05)
                if not Settings.Misc.pcldNames then break end
                local targets = {}
                local currentGuiParts = {}
                for part in pairs(GlobalPCLDTracker.parts) do
                    if part and part.Parent then
                        targets[#targets + 1] = {part = part, guiPart = part}
                        currentGuiParts[part] = true
                    end
                end

                if #targets > 0 then
                    if nameCursor > #targets then nameCursor = 1 end
                    local batch = math.min(NAME_BATCH, #targets)
                    for _ = 1, batch do
                        if not Settings.Misc.pcldNames then break end
                        local target = targets[nameCursor]
                        nameCursor = (nameCursor % #targets) + 1
                        local gui = ensureGui(target.guiPart)
                        local label = gui:FindFirstChild("Label")
                        local owner = GlobalPCLDTracker.getOwnerName(target.part)
                        if label then
                            local text = owner and (owner .. " (PCLD)") or ""
                            local visible = owner ~= nil
                            if label.Text ~= text then label.Text = text end
                            if label.Visible ~= visible then label.Visible = visible end
                        end
                        task.wait()
                    end
                else
                    nameCursor = 1
                end

                for guiPart, gui in pairs(State.pcldNameGuis) do
                    if not currentGuiParts[guiPart] then
                        pcall(function() gui:Destroy() end)
                        State.pcldNameGuis[guiPart] = nil
                    end
                end
            end
        end)
    else
        if State.pcldNameTask then task.cancel(State.pcldNameTask) State.pcldNameTask = nil end
        if State.pcldNameGuis then
            for _, gui in pairs(State.pcldNameGuis) do
                pcall(function() gui:Destroy() end)
            end
            State.pcldNameGuis = nil
        end
    end
end})
