                if skyObj:IsA("Sky") then
                    nightModeV2SkySettings[skyObj.Name] = {
                        CelestialBodiesShown = skyObj.CelestialBodiesShown,
                        MoonAngularSize = skyObj.MoonAngularSize,
                        MoonTextureId = skyObj.MoonTextureId,
                        SkyboxBk = skyObj.SkyboxBk,
                        SkyboxDn = skyObj.SkyboxDn,
                        SkyboxFt = skyObj.SkyboxFt,
                        SkyboxLf = skyObj.SkyboxLf,
                        SkyboxRt = skyObj.SkyboxRt,
                        SkyboxUp = skyObj.SkyboxUp,
                        StarCount = skyObj.StarCount,
                        SunAngularSize = skyObj.SunAngularSize,
                        SunTextureId = skyObj.SunTextureId
                    }
                end
            end
        end
        local clouds = lighting:FindFirstChild("Clouds")
        if clouds then
            nightModeV2CloudsOriginal = {Color = clouds.Color, Cover = clouds.Cover, Density = clouds.Density}
        end
        nightModeV2Reflections = {}
        for _, obj in pairs(workspace:GetDescendants()) do
            if obj:IsA("BasePart") and obj.Reflectance > 0 then
                nightModeV2Reflections[obj] = obj.Reflectance
            end
        end
    end
    local function enableNightModeV2()
        if nightModeV2Active then return end
        local lighting = game:GetService("Lighting")
        if not nightModeV2Original.Technology then
            saveNightModeV2Original()
        end
        for _, effect in pairs(lighting:GetChildren()) do
            if effect:IsA("PostEffect") then
                effect.Enabled = false
            end
        end
        lighting.Technology = Enum.Technology.Legacy
        lighting.GlobalShadows = false
        lighting.ShadowSoftness = 0
        lighting.Brightness = 0.8
        lighting.EnvironmentDiffuseScale = 0.2
        lighting.EnvironmentSpecularScale = 0.2
        lighting.Ambient = Color3.fromRGB(30, 40, 50)
        lighting.ColorShift_Bottom = Color3.fromRGB(40, 50, 70)
        lighting.ColorShift_Top = Color3.fromRGB(80, 100, 120)
        lighting.OutdoorAmbient = Color3.fromRGB(50, 60, 80)
        local bloom = lighting:FindFirstChild("BloomEffect")
        if bloom then bloom.Enabled = false; bloom.Intensity = 0.05 end
        local cc = lighting:FindFirstChild("ColorCorrectionEffect")
        if cc then cc.Enabled = false; cc.Saturation = 0.6; cc.Contrast = 0.1; cc.TintColor = Color3.fromRGB(180, 200, 220) end
        local sr = lighting:FindFirstChild("SunRaysEffect")
        if sr then sr.Enabled = false; sr.Intensity = 0 end
        local atmo = lighting:FindFirstChild("Atmosphere")
        if atmo then atmo.Haze = 0.8; atmo.Density = 0.3; atmo.Glare = 0; atmo.Color = Color3.fromRGB(50, 70, 100) end
        if not Settings.Misc.visualsSkyboxEnabled then
            for _, skyObj in pairs(lighting:GetChildren()) do
                if skyObj:IsA("Sky") then
                    skyObj.CelestialBodiesShown = true
                    skyObj.MoonAngularSize = 11
                    skyObj.StarCount = 3000
                    skyObj.SkyboxBk = ""
                    skyObj.SkyboxDn = ""
                    skyObj.SkyboxFt = ""
                    skyObj.SkyboxLf = ""
                    skyObj.SkyboxRt = ""
                    skyObj.SkyboxUp = ""
                end
            end
        end
        local clouds = lighting:FindFirstChild("Clouds")
        if clouds then
            clouds.Color = Color3.fromRGB(30, 30, 40)
            clouds.Cover = 0.4
            clouds.Density = 0.7
        end
        for obj, _ in pairs(nightModeV2Reflections) do
            if obj.Parent then
                pcall(function() obj.Reflectance = 0 end)
            end
        end
        lighting.ClockTime = 0
        lighting.TimeOfDay = "00:00:00"
        nightModeV2Active = true
    end
    local function disableNightModeV2()
        if not nightModeV2Active then return end
        local lighting = game:GetService("Lighting")
        if nightModeV2Original.Technology then
            lighting.Technology = nightModeV2Original.Technology
            lighting.GlobalShadows = nightModeV2Original.GlobalShadows
            lighting.ShadowSoftness = nightModeV2Original.ShadowSoftness
            lighting.Brightness = nightModeV2Original.Brightness
            lighting.EnvironmentDiffuseScale = nightModeV2Original.EnvironmentDiffuseScale
            lighting.EnvironmentSpecularScale = nightModeV2Original.EnvironmentSpecularScale
            lighting.Ambient = nightModeV2Original.Ambient
            lighting.ColorShift_Bottom = nightModeV2Original.ColorShift_Bottom
            lighting.ColorShift_Top = nightModeV2Original.ColorShift_Top
            lighting.OutdoorAmbient = nightModeV2Original.OutdoorAmbient
            lighting.ClockTime = nightModeV2Original.ClockTime or 14
            lighting.TimeOfDay = nightModeV2Original.TimeOfDay or "14:00:00"
            lighting.FogEnd = nightModeV2Original.FogEnd or 100000
            lighting.FogStart = nightModeV2Original.FogStart or 0
            lighting.FogColor = nightModeV2Original.FogColor or Color3.fromRGB(192, 192, 192)
        end
        if nightModeV2Effects.Bloom then
            local bloom = lighting:FindFirstChild("BloomEffect")
            if bloom then bloom.Enabled = nightModeV2Effects.Bloom.Enabled; bloom.Intensity = nightModeV2Effects.Bloom.Intensity end
        end
        if nightModeV2Effects.ColorCorrection then
            local cc = lighting:FindFirstChild("ColorCorrectionEffect")
            if cc then cc.Enabled = nightModeV2Effects.ColorCorrection.Enabled; cc.Saturation = nightModeV2Effects.ColorCorrection.Saturation; cc.Contrast = nightModeV2Effects.ColorCorrection.Contrast; cc.TintColor = nightModeV2Effects.ColorCorrection.TintColor end
        end
        if nightModeV2Effects.SunRays then
            local sr = lighting:FindFirstChild("SunRaysEffect")
            if sr then sr.Enabled = nightModeV2Effects.SunRays.Enabled; sr.Intensity = nightModeV2Effects.SunRays.Intensity end
        end
        if nightModeV2Effects.Atmosphere then
            local atmo = lighting:FindFirstChild("Atmosphere")
            if atmo then atmo.Haze = nightModeV2Effects.Atmosphere.Haze; atmo.Density = nightModeV2Effects.Atmosphere.Density; atmo.Glare = nightModeV2Effects.Atmosphere.Glare; atmo.Color = nightModeV2Effects.Atmosphere.Color end
        end
        if not Settings.Misc.visualsSkyboxEnabled then
            for skyName, settings in pairs(nightModeV2SkySettings) do
                local skyObj = lighting:FindFirstChild(skyName)
                if skyObj and skyObj:IsA("Sky") then
                    for prop, value in pairs(settings) do
                        skyObj[prop] = value
                    end
                end
            end
        end
        if nightModeV2CloudsOriginal then
            local clouds = lighting:FindFirstChild("Clouds")
            if clouds then clouds.Color = nightModeV2CloudsOriginal.Color; clouds.Cover = nightModeV2CloudsOriginal.Cover; clouds.Density = nightModeV2CloudsOriginal.Density end
        end
        for obj, reflectance in pairs(nightModeV2Reflections) do
            if obj.Parent then
                pcall(function() obj.Reflectance = reflectance end)
            end
        end
        nightModeV2Original = {}
        nightModeV2Effects = {}
        nightModeV2Reflections = {}
        nightModeV2SkySettings = {}
        nightModeV2CloudsOriginal = nil
        nightModeV2Active = false
    end
    local nightModeToggling = false
    visualsOtherSec:Toggle({Text = "NightMode", Flag = "NightMode", Default = false, Callback = function(v)
        if nightModeToggling then return end
        if not v and nightModeV2Active then return end
        if v and nightModeV2Active then
            nightModeToggling = true
            pcall(function() Toggles.NightMode:SetValue(false) end)
            nightModeToggling = false
            return
        end
        nightModeActive = v
        local lighting = game:GetService("Lighting")
        if v then
            nightModeOriginal.Brightness = lighting.Brightness
            nightModeOriginal.ClockTime = lighting.ClockTime
            nightModeOriginal.FogEnd = lighting.FogEnd
            nightModeOriginal.OutdoorAmbient = lighting.OutdoorAmbient
            nightModeOriginal.Ambient = lighting.Ambient
            nightModeOriginal.FogColor = lighting.FogColor
            nightModeOriginal.FogStart = lighting.FogStart
            if not Settings.Misc.visualsSkyboxEnabled then
                State.nightModeSky = Instance.new("Sky")
                State.nightModeSky.SkyboxBk = "rbxassetid://159454299"
                State.nightModeSky.SkyboxDn = "rbxassetid://159454296"
                State.nightModeSky.SkyboxFt = "rbxassetid://159454293"
                State.nightModeSky.SkyboxLf = "rbxassetid://159454286"
                State.nightModeSky.SkyboxRt = "rbxassetid://159454300"
                State.nightModeSky.SkyboxUp = "rbxassetid://159454288"
                State.nightModeSky.Parent = lighting
            end
            lighting.Brightness = 2
            lighting.ClockTime = 0
            lighting.FogEnd = 100000
            lighting.OutdoorAmbient = Color3.fromRGB(50, 50, 80)
        else
            if State.nightModeSky then State.nightModeSky:Destroy() State.nightModeSky = nil end
            lighting.Brightness = nightModeOriginal.Brightness or 2
            lighting.ClockTime = nightModeOriginal.ClockTime or 14
            lighting.FogEnd = nightModeOriginal.FogEnd or 100000
            lighting.OutdoorAmbient = nightModeOriginal.OutdoorAmbient or Color3.fromRGB(128, 128, 128)
            lighting.FogColor = nightModeOriginal.FogColor or Color3.fromRGB(192, 192, 192)
            lighting.FogStart = nightModeOriginal.FogStart or 0
            nightModeOriginal = {}
        end
    end})
    visualsOtherSec:Toggle({Text = "NightMode V2", Flag = "NightModeV2", Default = false, Callback = function(v)
        if nightModeToggling then return end
        if not v and nightModeActive then return end
        if v and nightModeActive then
            nightModeToggling = true
            pcall(function() Toggles.NightModeV2:SetValue(false) end)
            nightModeToggling = false
            return
        end
        if v then
            enableNightModeV2()
        else
            disableNightModeV2()
        end
    end})
end
do 
    local weatherActive = false
    local selectedWeather = "Snow"
    local weatherCount = 400
    local weatherParts = {}
    local weatherHeartbeat = nil
    local weatherDiagTask = nil
    local weatherFrame = 0
    local weatherSpawning = false
    local weatherRoot = nil
    local VISIBLE_RADIUS = 220
    local function getMapBounds()
        local minX, maxX = math.huge, -math.huge
        local minZ, maxZ = math.huge, -math.huge
        local ok = pcall(function()
            for _, part in ipairs(workspace:GetDescendants()) do
                if part:IsA("BasePart") then
                    local cf = part.CFrame
                    local s = part.Size
                    for dx = -1, 1, 2 do
                        for dz = -1, 1, 2 do
                            local p = cf:PointToWorldSpace(Vector3.new(s.X * 0.5 * dx, 0, s.Z * 0.5 * dz))
                            minX = math.min(minX, p.X); maxX = math.max(maxX, p.X)
                            minZ = math.min(minZ, p.Z); maxZ = math.max(maxZ, p.Z)
                        end
                    end
                end
            end
        end)
        if not ok or minX == math.huge then
            return 0, 400, 0, 400
        end
        local w = math.max(maxX - minX, 200)
        local d = math.max(maxZ - minZ, 200)
        return (minX + maxX) * 0.5, w, (minZ + maxZ) * 0.5, d
    end
    local function getPlayerPos()
        local ch = LocalPlayer.Character
        local rp = ch and ch:FindFirstChild("HumanoidRootPart")
        return rp and rp.Position or nil
    end
    local WeatherDefs = {
        ["Snow"] = {
            Color = Color3.fromRGB(235, 240, 255),
            Material = Enum.Material.SmoothPlastic,
            Shape = Enum.PartType.Ball,
            Count = 400,
            SizeMin = Vector3.new(0.35, 0.35, 0.35),
            SizeMax = Vector3.new(0.8, 0.8, 0.8),
            FallMin = 5,
            FallMax = 9,
            Sway = 0.6,
            Spin = 0.8,
        },
        ["Rain"] = {
            Color = Color3.fromRGB(175, 205, 255),
            Material = Enum.Material.Glass,
            Count = 600,
            SizeMin = Vector3.new(0.12, 1.4, 0.12),
            SizeMax = Vector3.new(0.2, 2.2, 0.2),
            FallMin = 70,
            FallMax = 90,
            Sway = 0,
        },
        ["Leaves"] = {
            Color = Color3.fromRGB(110, 190, 100),
            Material = Enum.Material.SmoothPlastic,
            Count = 300,
            SizeMin = Vector3.new(0.5, 0.25, 0.1),
            SizeMax = Vector3.new(1.0, 0.5, 0.25),
            FallMin = 4,
            FallMax = 7,
            Sway = 1.2,
            Spin = 2.5,
        },
        ["Magic Dust"] = {
            Color = Color3.fromRGB(205, 130, 255),
            Palette = {
                Color3.fromRGB(180, 90, 255),
                Color3.fromRGB(255, 130, 230),
                Color3.fromRGB(110, 220, 255),
            },
            Material = Enum.Material.Neon,
            Count = 400,
            SizeMin = Vector3.new(0.3, 0.3, 0.3),
            SizeMax = Vector3.new(0.6, 0.6, 0.6),
            FallMin = 3,
            FallMax = 6,
            Sway = 0.5,
            Spin = 1.5,
        },
    }
    local function makePart(def, color)
        local p = Instance.new("Part")
        p.Name = "_WeatherPart"
        p.Anchored = true
        p.CanCollide = false
        p.CanQuery = false
        p.CanTouch = false
        p.CastShadow = false
        p.Locked = true
        p.Material = def.Material
        p.Shape = def.Shape or Enum.PartType.Block
        p.Color = color or def.Color
        p.Transparency = 0
        p.Parent = weatherRoot or workspace
        return p
    end
    local function pickColor(def)
        if def.Palette then
            return def.Palette[math.random(1, #def.Palette)]
        end
        return def.Color
    end
    local function freshPart(w, def)
        local p = makePart(def, w.color)
        p.Size = w.size
        return p
    end
    local function stopWeather()
        if weatherHeartbeat then
            weatherHeartbeat:Disconnect()
            weatherHeartbeat = nil
        end
        if weatherDiagTask then
            task.cancel(weatherDiagTask)
            weatherDiagTask = nil
        end
        for _, w in ipairs(weatherParts) do
            pcall(function() w.part:Destroy() end)
        end
        weatherParts = {}
        if weatherRoot then
            pcall(function() weatherRoot:Destroy() end)
            weatherRoot = nil
        end
    end
    local function startWeather()
        stopWeather()
        local def = WeatherDefs[selectedWeather]
        if not def then return end
        for _, obj in ipairs(workspace:GetChildren()) do
            if obj:IsA("BasePart") and obj.Name == "_WeatherPart" then
                obj:Destroy()
            elseif obj:IsA("Model") and obj.Name == "_WeatherRoot" then
                obj:Destroy()
            end
        end
        local root = Instance.new("Model")
        root.Name = "_WeatherRoot"
        root.Parent = workspace
        weatherRoot = root
        local rayParams = RaycastParams.new()
        rayParams.FilterType = Enum.RaycastFilterType.Exclude
        local charList = { LocalPlayer.Character }
        rayParams.FilterDescendantsInstances = charList
        local startPos = getPlayerPos()
        local cx = startPos and startPos.X or 0
        local cz = startPos and startPos.Z or 0
        local halfW = 400
        local halfD = 400
        local parts = {}
        for i = 1, weatherCount do
            local x = cx + (math.random() * 2 - 1) * halfW
            local z = cz + (math.random() * 2 - 1) * halfD
            local w2 = {
                x = x,
                z = z,
                color = pickColor(def),
                size = Vector3.new(
                    def.SizeMin.X + (def.SizeMax.X - def.SizeMin.X) * math.random(),
                    def.SizeMin.Y + (def.SizeMax.Y - def.SizeMin.Y) * math.random(),
                    def.SizeMin.Z + (def.SizeMax.Z - def.SizeMin.Z) * math.random()
                ),
                fall = def.FallMin + (def.FallMax - def.FallMin) * math.random(),
                phase = math.random() * math.pi * 2,
                swaySpeed = 0.6 + math.random() * 1.4,
                spin = (def.Spin or 0) * (math.random() - 0.5) * 2,
                rot = math.random() * math.pi * 2,
                y = 0,
                dead = false,
                deathT = 0,
            }
            if startPos then
                w2.y = startPos.Y + 20 + math.random() * 160
            else
                w2.y = 20 + math.random() * 160
            end
            w2.lastT = os.clock()
            parts[i] = w2
        end
        weatherParts = parts
        weatherFrame = 0
        warn("[Weather] started (parts): " .. tostring(selectedWeather) .. " | parts=" .. #parts)
        weatherSpawning = true
        task.spawn(function()
            local idx = 1
            local total = #parts
            while idx <= total do
                if not weatherActive or weatherParts ~= parts then
                    break
                end
                local limit = math.min(idx + 149, total)
                while idx <= limit do
                    local w2 = parts[idx]
                    idx = idx + 1
                    if not w2.part then
                        w2.part = freshPart(w2, def)
                        local cf = CFrame.new(w2.x, w2.y, w2.z)
                        if def.Spin and def.Spin ~= 0 then
                            cf = cf * CFrame.Angles(w2.rot, w2.rot * 0.7, 0)
                        end
                        w2.part.CFrame = cf
                    end
                end
                task.wait()
            end
            weatherSpawning = false
        end)
        weatherHeartbeat = RunService.Heartbeat:Connect(function(dt)
            if not weatherActive then return end
            local pos = getPlayerPos()
            if not pos then return end
            local top = pos.Y + 170
            local t = os.clock()
            local parts = weatherParts
            local n = #parts
            if n == 0 then return end
            local px = pos.X
            local pz = pos.Z
            local vis2 = VISIBLE_RADIUS * VISIBLE_RADIUS
            local frame = weatherFrame
            for i = 1, n do
                local w = parts[i]
                local p = w.part
                if not p or not p.Parent then
                    if weatherSpawning then continue end
                    p = freshPart(w, def)
                    w.part = p
                end
                local dx = w.x - px
                local dz = w.z - pz
                local near = dx * dx + dz * dz <= vis2
                if w.dead then
                    local prog = (t - w.deathT) / 0.35
                    p.Transparency = math.clamp(prog, 0, 1)
                    if prog >= 1 then
                        w.dead = false
                        w.y = top - math.random() * 20
                        w.x = px + (math.random() * 2 - 1) * halfW
                        w.z = pz + (math.random() * 2 - 1) * halfD
                        w.phase = math.random() * math.pi * 2
                        w.fall = def.FallMin + (def.FallMax - def.FallMin) * math.random()
                        w.rot = math.random() * math.pi * 2
                        w.lastT = t
                        p:Destroy()
                        w.part = freshPart(w, def)
                        local cf2 = CFrame.new(w.x, w.y, w.z)
                        if def.Spin and def.Spin ~= 0 then
                            cf2 = cf2 * CFrame.Angles(w.rot, w.rot * 0.7, 0)
                        end
                        w.part.CFrame = cf2
                    end
                    continue
                end
                local step = near and 3 or 15
                if (frame + i) % step ~= 0 then
                    continue
                end
                if w.y < -35 or w.y > top + 20 then
                    w.y = top - math.random() * 20
                    w.x = px + (math.random() * 2 - 1) * halfW
                    w.z = pz + (math.random() * 2 - 1) * halfD
                    w.phase = math.random() * math.pi * 2
                    w.fall = def.FallMin + (def.FallMax - def.FallMin) * math.random()
                    w.rot = math.random() * math.pi * 2
                    w.lastT = t
                end
                local elapsed = math.min(t - w.lastT, 0.5)
                local newY = w.y - w.fall * elapsed
                local dy = newY - w.y
                if dy < 0 then
                    charList[1] = LocalPlayer.Character
                    rayParams.FilterDescendantsInstances = charList
                    local hit = workspace:Raycast(Vector3.new(w.x, w.y, w.z), Vector3.new(0, dy, 0), rayParams)
                    if hit and hit.Instance and hit.Instance:IsA("BasePart") then
                        w.dead = true
                        w.deathT = t
                        w.y = hit.Position.Y + 0.1
                        w.lastT = t
                        p.CFrame = CFrame.new(w.x, w.y, w.z)
                        continue
                    end
                end
                w.y = newY
                w.lastT = t
                local py = w.y
                if p.Transparency ~= 0 then p.Transparency = 0 end
                if near then
                    local swayX = math.sin(t * w.swaySpeed + w.phase) * (def.Sway or 0)
                    local swayZ = math.cos(t * w.swaySpeed * 0.8 + w.phase) * (def.Sway or 0)
                    w.rot = w.rot + w.spin * dt
                    if def.Spin and def.Spin ~= 0 then
                        p.CFrame = CFrame.new(w.x + swayX, py, w.z + swayZ) * CFrame.Angles(w.rot, w.rot * 0.7, 0)
                    else
                        p.Position = Vector3.new(w.x + swayX, py, w.z + swayZ)
                    end
                else
                    p.Position = Vector3.new(w.x, py, w.z)
                end
            end
            weatherFrame = frame + 1
        end)
        weatherDiagTask = task.spawn(function()
            task.wait(5)
            if not weatherActive then return end
            local alive = 0
            local sample = "none"
            for _, w in ipairs(weatherParts) do
                if w.part and w.part.Parent then
                    alive = alive + 1
                    if sample == "none" then
                        local cf = w.part.CFrame
                        sample = ("(%.0f, %.0f, %.0f)"):format(cf.Position.X, cf.Position.Y, cf.Position.Z)
                    end
                end
            end
            warn("[Weather] alive=" .. alive .. " firstPos=" .. sample)
        end)
    end
    visualsWorldSec:Toggle({Text = "Weather", Flag = "VisualsWeather", Default = false, Callback = function(v)
        Settings.Misc.weatherEnabled = v
        weatherActive = v
        if v then
            startWeather()
        else
            stopWeather()
        end
    end})
    visualsWorldSec:Dropdown({Text = "Weather Material", Flag = "VisualsWeatherMaterial", Default = "Snow", List = {"Snow", "Rain", "Leaves", "Magic Dust"}, Callback = function(value)
        selectedWeather = value
        Settings.Misc.weatherMaterial = value
        if weatherActive then startWeather() end
    end})
    visualsWorldSec:Slider({Text = "Weather Particles Count", Flag = "VisualsWeatherCount", Minimum = 1, Maximum = 2000, Default = 400, ValueName = "count", Callback = function(value)
        weatherCount = math.floor(value)
        Settings.Misc.weatherCount = weatherCount
        if weatherActive then startWeather() end
    end})
end 
