visualsWorldSec:Toggle({Text = "Aspect Ratio", Flag = "VisualScreenFX", Default = false, Callback = function(v)
    Settings.Misc.screenStretchEnabled = v
    if v then
        if State.screenStretchConn then State.screenStretchConn:Disconnect() end
        State.screenStretchConn = game:GetService("RunService").RenderStepped:Connect(function()
            local cam = workspace.CurrentCamera
            if cam then
                cam.CFrame = applyScreenStretch(cam.CFrame)
            end
        end)
    elseif State.screenStretchConn then
        State.screenStretchConn:Disconnect()
        State.screenStretchConn = nil
    end
end})
