    Settings.Misc.screenStretchIntensity = value
end})
State.smoothCamConn = nil
State.smoothCamLastCF = nil
visualsWorldSec:Toggle({Text = "Smooth Camera", Flag = "VisualSmoothCam", Default = false, Callback = function(v)
    Settings.Misc.smoothCameraEnabled = v
    if v then
        State.smoothCamLastCF = nil
        if State.smoothCamConn then State.smoothCamConn:Disconnect() end
        State.smoothCamConn = RunService.RenderStepped:Connect(function(dt)
            local val = Settings.Misc.smoothCameraValue
            if val <= 0 then State.smoothCamLastCF = nil return end
            local cam = workspace.CurrentCamera
            if not cam then State.smoothCamLastCF = nil return end
            local raw = cam.CFrame
            local rawPos = raw.Position
            local rawRot = raw.Rotation
            if State.smoothCamLastCF then
                local alpha = 1 - math.exp(-dt * math.max(4, (20 - val) * 2))
                local nextPos = State.smoothCamLastCF:Lerp(rawPos, alpha)
                cam.CFrame = CFrame.new(nextPos) * rawRot
                State.smoothCamLastCF = nextPos
            else
                State.smoothCamLastCF = rawPos
            end
        end)
    elseif State.smoothCamConn then
        State.smoothCamConn:Disconnect()
        State.smoothCamConn = nil
        State.smoothCamLastCF = nil
    end
end})
visualsWorldSec:Slider({Text = "Camera Smooth", Flag = "VisualSmoothCamVal", Minimum = 0, Maximum = 15, Default = 0, Callback = function(value)
    Settings.Misc.smoothCameraValue = value
end})
visualsOtherSec:Toggle({Text = "SpawnLocation Spin", Flag = "SpawnLocRotate", Default = false, Callback = function(v)
    Settings.Misc.spawnLocRotate = v
    if not v then
        if State.spawnLocRotateConn then State.spawnLocRotateConn:Disconnect() State.spawnLocRotateConn = nil end
        if State.spawnLocRotateTask then task.cancel(State.spawnLocRotateTask) State.spawnLocRotateTask = nil end
        return
    end
    State.spawnLocRotateTask = task.spawn(function()
        while Settings.Misc.spawnLocRotate do
            local sl = Workspace:FindFirstChild("SpawnLocation")
            if sl then
                local speed = Settings.Misc.spawnLocSpinSpeed / 10
                sl.CFrame = sl.CFrame * CFrame.Angles(0, math.rad(speed), 0)
            end
            task.wait()
        end
    end)
end})
