local function clearTrailEffects(main)
    for _, child in ipairs(main:GetChildren()) do
        if child:IsA("Trail") or child.Name == "_trailAtt" then
            child:Destroy()
        end
    end
end
local function createTrailOnPart(main, style, offset)
    local off = offset or Vector3.new(0, 0, 0)
    local att0 = Instance.new("Attachment")
    att0.Name = "_trailAtt"
    att0.Position = Vector3.new(0, 0.5, -1) + off
    att0.Parent = main
    local att1 = Instance.new("Attachment")
    att1.Name = "_trailAtt"
    att1.Position = Vector3.new(0, -0.5, 1) + off
    att1.Parent = main
    local trail = Instance.new("Trail")
    trail.Attachment0 = att0
    trail.Attachment1 = att1
    trail.FaceCamera = true
    trail.Lifetime = trailLifeTime
    trail.Enabled = true
    trail.LightEmission = 1
    trail.LightInfluence = 0
    if style then
        trail.Color = style.Color
        trail.Transparency = style.Transparency
        trail.WidthScale = style.WidthScale
        trail.LightEmission = style.LightEmission
        trail.LightInfluence = style.LightInfluence
    end
    trail.TextureLength = 0
    trail.Parent = main
end
local function createMethodOnPart(main, method, style)
    if method == "Fire" then
        local fire = Instance.new("Fire")
        fire.Size = 4
        fire.Heat = 8
        fire.Enabled = true
        if style and style.Color.Keypoints[1] then fire.Color = style.Color.Keypoints[1].Value end
        if style and style.Color.Keypoints[2] then fire.SecondaryColor = style.Color.Keypoints[2].Value end
        fire.Parent = main
    elseif method == "Plasma" then
        local smoke = Instance.new("Smoke")
        smoke.Size = 3
        smoke.RiseVelocity = 5
        smoke.Opacity = 0.5
        if style and style.Color.Keypoints[1] then smoke.Color = style.Color.Keypoints[1].Value end
        smoke.Parent = main
    elseif method == "Neon" then
        local light = Instance.new("PointLight")
        light.Brightness = 2
        light.Range = 14
        if style and style.Color.Keypoints[1] then light.Color = style.Color.Keypoints[1].Value end
        light.Parent = main
        local sparkles = Instance.new("Sparkles")
        if style and style.Color.Keypoints[1] then sparkles.SparkleColor = style.Color.Keypoints[1].Value end
        sparkles.Parent = main
    elseif method == "Energy" then
        local att0 = Instance.new("Attachment")
        att0.Name = "_trailAtt"
        att0.Position = Vector3.new(0, 0.5, -0.5)
        att0.Parent = main
        local att1 = Instance.new("Attachment")
        att1.Name = "_trailAtt"
        att1.Position = Vector3.new(0, -0.5, 0.5)
        att1.Parent = main
        local trail = Instance.new("Trail")
        trail.Attachment0 = att0
        trail.Attachment1 = att1
        trail.FaceCamera = true
        trail.Lifetime = trailLifeTime
        trail.Enabled = true
        trail.LightEmission = 1
        trail.LightInfluence = 0
        trail.WidthScale = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0.15),
            NumberSequenceKeypoint.new(0.5, 0.1),
            NumberSequenceKeypoint.new(1, 0),
        })
        trail.Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0),
            NumberSequenceKeypoint.new(0.8, 0.3),
            NumberSequenceKeypoint.new(1, 1),
        })
        if style then trail.Color = style.Color end
        trail.TextureLength = 0
        trail.Parent = main
    end
end
local function updateTrailOnPart(main, style)
    for _, child in ipairs(main:GetChildren()) do
        if child:IsA("Trail") then
            child.Lifetime = trailLifeTime
            if style then
                child.Color = style.Color
                child.Transparency = style.Transparency
                child.WidthScale = style.WidthScale
                child.LightEmission = style.LightEmission
                child.LightInfluence = style.LightInfluence
                child.TextureLength = 0
            end
        elseif child:IsA("Fire") then
            if style and style.Color.Keypoints[1] then child.Color = style.Color.Keypoints[1].Value end
            if style and style.Color.Keypoints[2] then child.SecondaryColor = style.Color.Keypoints[2].Value end
        elseif child:IsA("Smoke") then
            if style and style.Color.Keypoints[1] then child.Color = style.Color.Keypoints[1].Value end
        elseif child:IsA("Sparkles") then
            if style and style.Color.Keypoints[1] then child.SparkleColor = style.Color.Keypoints[1].Value end
        elseif child:IsA("PointLight") then
            if style and style.Color.Keypoints[1] then child.Color = style.Color.Keypoints[1].Value end
        elseif child:IsA("ParticleEmitter") then
            if style then child.Color = style.Color end
        end
    end
end
visualsTrailSec:Toggle({Text = "Pallet Trail", Flag = "PalletTrail", Default = false, Callback = function(v)
    palletTrailActive = v
    if not v then
        if palletTrailTask then task.cancel(palletTrailTask) palletTrailTask = nil end
        local inv = workspace:FindFirstChild(LocalPlayer.Name .. "SpawnedInToys")
        if inv then
            for _, obj in ipairs(inv:GetDescendants()) do
                if obj.Name == "PalletLightBrown" then
                    local main = obj:FindFirstChild("Main")
                    if main then clearTrailEffects(main) end
                end
            end
        end
        return
    end
    palletTrailTask = task.spawn(function()
        local activePallets = {}
        local lastStyle = {}
        local lastLifetime = {}
        while palletTrailActive do
            local inv = workspace:FindFirstChild(LocalPlayer.Name .. "SpawnedInToys")
            if inv then
                for _, obj in ipairs(inv:GetDescendants()) do
                    if obj.Name == "PalletLightBrown" then
                        local main = obj:FindFirstChild("Main")
                        if main then
                            local style = trailStyles[selectedTrailStyle]
                            local currentMethod = selectedTrailMethod
                            local needRebuild = not activePallets[obj] or activePallets[obj] ~= currentMethod
                            local needUpdate = lastStyle[obj] ~= selectedTrailStyle or lastLifetime[obj] ~= trailLifeTime
                            if needRebuild then
                                clearTrailEffects(main)
                                if currentMethod == "Default" then
                                    createTrailOnPart(main, style)
                                else
                                    createMethodOnPart(main, currentMethod, style)
                                end
                                activePallets[obj] = currentMethod
                                lastStyle[obj] = selectedTrailStyle
                                lastLifetime[obj] = trailLifeTime
                            elseif needUpdate then
                                updateTrailOnPart(main, style)
                                lastStyle[obj] = selectedTrailStyle
                                lastLifetime[obj] = trailLifeTime
                            end
                        end
                    end
                end
                for obj in pairs(activePallets) do
                    if not obj.Parent then
                        activePallets[obj] = nil
                        lastStyle[obj] = nil
                        lastLifetime[obj] = nil
                    end
                end
            end
            task.wait(0.05)
        end
    end)
end})
local grabTrailActive = false
local grabTrailTask = nil
visualsTrailSec:Toggle({Text = "Grab Trail", Flag = "GrabTrail", Default = false, Callback = function(v)
    grabTrailActive = v
    if not v then
        if grabTrailTask then task.cancel(grabTrailTask) grabTrailTask = nil end
        local grabParts = workspace:FindFirstChild("GrabParts")
        if grabParts then
            for _, obj in ipairs(grabParts:GetChildren()) do
                if obj.Name == "GrabPart" then
                    clearTrailEffects(obj)
                end
            end
        end
        return
    end
    grabTrailTask = task.spawn(function()
        local activeGrabs = {}
        local lastStyle = {}
        local lastLifetime = {}
        while grabTrailActive do
            local grabParts = workspace:FindFirstChild("GrabParts")
            if grabParts then
                for _, obj in ipairs(grabParts:GetDescendants()) do
                    if obj.Name == "GrabPart" and obj:IsA("BasePart") then
                        local style = trailStyles[selectedTrailStyle]
                        local currentMethod = selectedTrailMethod
                        local needRebuild = not activeGrabs[obj] or activeGrabs[obj] ~= currentMethod
                        local needUpdate = lastStyle[obj] ~= selectedTrailStyle or lastLifetime[obj] ~= trailLifeTime
                        if needRebuild then
                            clearTrailEffects(obj)
                            if currentMethod == "Default" then
                                createTrailOnPart(obj, style)
                            else
                                createMethodOnPart(obj, currentMethod, style)
                            end
                            activeGrabs[obj] = currentMethod
                            lastStyle[obj] = selectedTrailStyle
                            lastLifetime[obj] = trailLifeTime
                        elseif needUpdate then
                            updateTrailOnPart(obj, style)
                            lastStyle[obj] = selectedTrailStyle
                            lastLifetime[obj] = trailLifeTime
                        end
                    end
                end
                for obj in pairs(activeGrabs) do
                    if not obj.Parent then
                        activeGrabs[obj] = nil
                        lastStyle[obj] = nil
                        lastLifetime[obj] = nil
                    end
                end
            else
                for obj in pairs(activeGrabs) do
                    activeGrabs[obj] = nil
                    lastStyle[obj] = nil
                    lastLifetime[obj] = nil
                end
            end
            task.wait(0.05)
        end
    end)
end})
local playerTrailActive = false
local playerTrailTask = nil
local playerTrailConn = nil
visualsTrailSec:Toggle({Text = "Player Trail", Flag = "PlayerTrail", Default = false, Callback = function(v)
    playerTrailActive = v
        if not v then
            if playerTrailTask then task.cancel(playerTrailTask) playerTrailTask = nil end
            if playerTrailConn then playerTrailConn:Disconnect() playerTrailConn = nil end
            for _, child in ipairs(workspace:GetDescendants()) do
                if child.Name == "_ptEmitter" then child:Destroy() end
            end
            return
        end
    local att = Instance.new("Attachment")
    att.Name = "_ptEmitter"
    att.Parent = workspace.Terrain
    local style = trailStyles[selectedTrailStyle]
    local currentMethod = selectedTrailMethod
    local pe = nil
    local function rebuild()
        for _, c in ipairs(att:GetChildren()) do c:Destroy() end
        if currentMethod == "Default" or currentMethod == "Energy" then
            pe = Instance.new("ParticleEmitter")
            pe.Name = "_pt"
            if style then pe.Color = style.Color end
            pe.LightEmission = 1
            pe.LightInfluence = 0
            pe.Size = NumberSequence.new({
                NumberSequenceKeypoint.new(0, 0.8),
                NumberSequenceKeypoint.new(0.5, 0.5),
                NumberSequenceKeypoint.new(1, 0),
            })
            pe.Transparency = NumberSequence.new({
                NumberSequenceKeypoint.new(0, 0),
                NumberSequenceKeypoint.new(0.6, 0.3),
                NumberSequenceKeypoint.new(1, 1),
            })
            pe.Lifetime = NumberRange.new(trailLifeTime * 0.5, trailLifeTime)
            pe.Rate = 60
            pe.Speed = NumberRange.new(1, 3)
            pe.SpreadAngle = Vector2.new(360, 360)
            pe.Drag = 2
            pe.Parent = att
        elseif currentMethod == "Fire" then
            local fire = Instance.new("Fire")
            fire.Name = "_pt"
            fire.Size = 4
            fire.Heat = 8
            if style and style.Color.Keypoints[1] then fire.Color = style.Color.Keypoints[1].Value end
            if style and style.Color.Keypoints[2] then fire.SecondaryColor = style.Color.Keypoints[2].Value end
            fire.Parent = att
        elseif currentMethod == "Plasma" then
            local smoke = Instance.new("Smoke")
            smoke.Name = "_pt"
            smoke.Size = 3
            smoke.RiseVelocity = 5
            smoke.Opacity = 0.5
            if style and style.Color.Keypoints[1] then smoke.Color = style.Color.Keypoints[1].Value end
            smoke.Parent = att
        elseif currentMethod == "Neon" then
            local light = Instance.new("PointLight")
            light.Name = "_pt"
            light.Brightness = 2
            light.Range = 14
            if style and style.Color.Keypoints[1] then light.Color = style.Color.Keypoints[1].Value end
            light.Parent = att
            local sparkles = Instance.new("Sparkles")
            sparkles.Name = "_pt"
            if style and style.Color.Keypoints[1] then sparkles.SparkleColor = style.Color.Keypoints[1].Value end
            sparkles.Parent = att
        end
    end
    rebuild()
    playerTrailConn = game:GetService("RunService").RenderStepped:Connect(function()
        if not playerTrailActive then return end
        local char = LocalPlayer.Character
        if char then
            local hrp = char:FindFirstChild("HumanoidRootPart")
            if hrp then
                att.CFrame = hrp.CFrame
            end
        end
    end)
    playerTrailTask = task.spawn(function()
        local lastMethod = currentMethod
        local lastStyleName = selectedTrailStyle
        local lastLT = trailLifeTime
        while playerTrailActive do
            currentMethod = selectedTrailMethod
            style = trailStyles[selectedTrailStyle]
            local methodChanged = lastMethod ~= currentMethod
            local styleChanged = lastStyleName ~= selectedTrailStyle
            local ltChanged = lastLT ~= trailLifeTime
            if methodChanged or styleChanged then
                rebuild()
                lastMethod = currentMethod
                lastStyleName = selectedTrailStyle
            elseif ltChanged and pe then
                pe.Lifetime = NumberRange.new(trailLifeTime * 0.5, trailLifeTime)
                lastLT = trailLifeTime
            end
            task.wait(0.05)
        end
    end)
end})
    end)()
do
    function tp(obj1, obj2)
        obj1.CFrame = CFrame.new(obj2.Position + (obj2.Velocity * (game:GetService('Stats').Network.ServerStatsItem['Data Ping']:GetValue() / 1000) * 5))
    end
    function sno(part)
        pcall(function() setNetworkOwnerEvent:FireServer(part, part.CFrame) end)
    end
    function spawntoy(toy, cf)
        if not LocalPlayer:FindFirstChild("CanSpawnToy") or not LocalPlayer.CanSpawnToy.Value then
            local c = LocalPlayer:FindFirstChild("CanSpawnToy")
            if c then c.Changed:Wait() end
        end
        local t
        local inv = LocalPlayer:FindFirstChild("Backpack") or LocalPlayer:WaitForChild("Backpack", 5)
        local toyadded = inv and inv.ChildAdded:Connect(function(c)
            if c.Name == toy then t = c; toyadded:Disconnect() end
        end)
        task.spawn(function() pcall(function() SpawnToyRF:InvokeServer(toy, cf, Vector3.new(0, 0, 0)) end) end)
        local timeout = tick() + 2
        repeat task.wait() until t or tick() > timeout
        if toyadded then pcall(function() toyadded:Disconnect() end) end
        return t
    end
    function startPlotWatch() end
    function stopPlotWatch() end
