    clickerTargetSec:Button({Text = "Refresh Players", Callback = function()
        pcall(function() clickerTargetCombo:Refresh({Text = "Select Target", List = BlobmanBetaFeature.GetPlayerList()}) end)
    end})
    clickerTargetCombo = clickerTargetSec:Dropdown({Text = "Select Target", Flag = "ClickerTargetDropdown", List = BlobmanBetaFeature.GetPlayerList(), Callback = function(value)
        local name = value:match("@(.+)$")
