    clickerTargetSec:Keybind({Text = "Select Target", Flag = "ClickerSelectTarget", Mode = "Hold", Callback = function(held)
        if held then
            local cam = Workspace.CurrentCamera
            local mPos = UserInputService:GetMouseLocation()
            local best = nil
            local bestDist = math.huge
            for _, plr in ipairs(Players:GetPlayers()) do
                if plr == LocalPlayer or not plr.Character then continue end
                local hrp = plr.Character:FindFirstChild("HumanoidRootPart")
                local head = plr.Character:FindFirstChild("Head")
                local part = hrp or head
                if part then
                    local vec, onScreen = cam:WorldToViewportPoint(part.Position)
                    if onScreen then
                        local dx = vec.X - mPos.X
                        local dy = vec.Y - mPos.Y
                        local dist = dx * dx + dy * dy
                        if dist < bestDist then
                            bestDist = dist
                            best = plr
                        end
                    end
                end
            end
            if best then
                FGM.State.SelectedClickerTarget = best
                pcall(function() clickerTargetCombo:Set(best.DisplayName .. " (@" .. best.Name .. ")") end)
            end
        end
    end})
    local clickerPalletHammerTask = nil
    local clickerPalletModel = nil
    local clickerGrabActiveFlag = false
    local function clickerGetTarget()
        return FGM.State.SelectedClickerTarget
    end
    local function startClickerPalletHammer()
        local root = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
        if not root then return end
        local palletModel = nil
        do
            local inv = BlobmanBetaFeature.getInv()
            if not inv then return end
            local conn
            conn = inv.ChildAdded:Connect(function(toy)
                if toy.Name == "PalletLightBrown" then
                    palletModel = toy
                    conn:Disconnect()
                end
            end)
            task.spawn(function()
                pcall(function() SpawnToyRF:InvokeServer("PalletLightBrown", root.CFrame * CFrame.new(0, 5, 0), Vector3.zero) end)
            end)
            local t = tick()
            while not palletModel do
                if tick() - t > 5 then conn:Disconnect() break end
                task.wait(0.01)
            end
        end
        if not palletModel then return end
        if not palletModel:FindFirstChild("SoundPart") then palletModel:WaitForChild("SoundPart", 5) end
        local palletPart = palletModel:FindFirstChild("SoundPart")
        if not palletPart then return end
        palletModel.Name = "ClickerPallet"
        clickerPalletModel = palletModel
        pcall(function() setNetworkOwnerEvent:FireServer(palletPart, palletPart.CFrame) end)
        local SEGMENTS = 8
        local IMPACT_POWER = 10
        local hammerGoingDown = true
        local segmentIndex = 0
        local lastOwnerTime = tick()
        local function destroyKickConstraints(tRoot)
            if not tRoot then return end
            local bp = tRoot:FindFirstChild("KickBodyPos")
            if bp then pcall(function() bp:Destroy() end) end
            local bg = tRoot:FindFirstChild("KickBodyGyro")
            if bg then pcall(function() bg:Destroy() end) end
        end
        local function createKickConstraints(tRoot)
            if tRoot:FindFirstChild("KickBodyPos") then return end
            for _, v in pairs(tRoot:GetChildren()) do
                if v:IsA("BodyPosition") or v:IsA("BodyGyro") then pcall(function() v:Destroy() end) end
            end
            local bodyPos = Instance.new("BodyPosition")
            bodyPos.Name = "KickBodyPos"
            bodyPos.MaxForce = Vector3.new(1000000, 1000000, 1000000)
            bodyPos.D = 500
            bodyPos.P = 50000
            bodyPos.Position = tRoot.Position
            bodyPos.Parent = tRoot
            local bodyGyro = Instance.new("BodyGyro")
            bodyGyro.Name = "KickBodyGyro"
            bodyGyro.MaxTorque = Vector3.new(1000000, 1000000, 1000000)
            bodyGyro.D = 500
            bodyGyro.P = 50000
            bodyGyro.CFrame = tRoot.CFrame
            bodyGyro.Parent = tRoot
        end
        while clickerGrabActiveFlag and palletModel.Parent do
            local target = clickerGetTarget()
            local targetChar = target and target.Character
            local targetHrp = targetChar and targetChar:FindFirstChild("HumanoidRootPart")
            if targetHrp then
                local myChar = LocalPlayer.Character
                local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
                local targetHum = targetChar:FindFirstChildOfClass("Humanoid")
                if myRoot and targetHum and targetHum.Health > 0 then
                    local savedPos = myRoot.CFrame
                    local myHead = myChar:FindFirstChild("Head")
                    local dist = (targetHrp.Position - myRoot.Position).Magnitude
                    if dist > 30 then
                        myRoot.CFrame = targetHrp.CFrame * CFrame.new(0, 2, 4)
                        myRoot.AssemblyLinearVelocity = Vector3.zero
                        myRoot.AssemblyAngularVelocity = Vector3.zero
                        destroyKickConstraints(targetHrp)
                        createKickConstraints(targetHrp)
                        pcall(function() setNetworkOwnerEvent:FireServer(targetHrp, targetHrp.CFrame) end)
                        pcall(function() destroyGrabLineEvent:FireServer(targetHrp) end)
                        local grabStart = tick()
                        while tick() - grabStart < 0.3 and clickerGrabActiveFlag do
                            task.wait(0.05)
                            pcall(function() setNetworkOwnerEvent:FireServer(targetHrp, targetHrp.CFrame) end)
                            pcall(function() destroyGrabLineEvent:FireServer(targetHrp) end)
                            local bp = targetHrp:FindFirstChild("KickBodyPos")
                            if bp then bp.Position = (myHead and myHead.Position or myRoot.Position) + myRoot.CFrame:VectorToWorldSpace(Vector3.new(0, 15, 0)) end
                        end
                        myRoot.CFrame = savedPos
                        myRoot.AssemblyLinearVelocity = Vector3.zero
                        myRoot.AssemblyAngularVelocity = Vector3.zero
                        if targetHrp and targetHrp.Parent then targetHrp.CFrame = savedPos * CFrame.new(0, 15, 0) end
                        destroyKickConstraints(targetHrp)
                    end
                end
                if not isProtectedPlayer(target.Name) then
                    pcall(function() setNetworkOwnerEvent:FireServer(targetHrp, targetHrp.CFrame) end)
                end
                local ragdolled = targetHum and targetHum:FindFirstChild("Ragdolled")
                if ragdolled and ragdolled.Value == true then
                    if tick() - lastOwnerTime > 1.0 then
                        pcall(function() setNetworkOwnerEvent:FireServer(palletPart, palletPart.CFrame) end)
                        lastOwnerTime = tick()
                    end
                    palletPart.CFrame = CFrame.new(0, 100000, 0)
                    palletPart.AssemblyLinearVelocity = Vector3.zero
                    palletPart.AssemblyAngularVelocity = Vector3.zero
                    for _, part in pairs(palletModel:GetChildren()) do
                        if part:IsA("BasePart") then
                            part.Transparency = 1
                            part.CanCollide = false
                            part.CanQuery = false
                        end
                    end
                    task.wait(0.01)
                else
                    if tick() - lastOwnerTime > 1.0 then
                        pcall(function() setNetworkOwnerEvent:FireServer(palletPart, palletPart.CFrame) end)
                        lastOwnerTime = tick()
                    end
                    local startPos = targetHrp.Position + Vector3.new(0, 50000, 0)
                    local endPos = targetHrp.Position
                    if hammerGoingDown then
                        segmentIndex = segmentIndex + 1
                        local alpha = segmentIndex / SEGMENTS
                        local nextPos = startPos:Lerp(endPos, alpha)
                        palletPart.CFrame = CFrame.new(nextPos)
                        palletPart.AssemblyLinearVelocity = Vector3.new(0, -50000, 0)
                        palletPart.AssemblyAngularVelocity = Vector3.zero
                        for _, part in pairs(palletModel:GetChildren()) do
                            if part:IsA("BasePart") then
                                part.Transparency = 1
                                part.CanCollide = false
                                part.CanQuery = false
                            end
                        end
                        if segmentIndex >= SEGMENTS then
                            palletPart.AssemblyLinearVelocity = Vector3.new(0, -IMPACT_POWER, 0)
                            hammerGoingDown = false
                        end
                    else
                        palletPart.CFrame = CFrame.new(startPos)
                        palletPart.AssemblyLinearVelocity = Vector3.zero
                        segmentIndex = 0
                        hammerGoingDown = true
                    end
                    RunService.Heartbeat:Wait()
                end
            else
                local myChar = LocalPlayer.Character
                local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
                if myRoot then
                    palletPart.CFrame = myRoot.CFrame * CFrame.new(0, 10, 0)
                    palletPart.AssemblyLinearVelocity = Vector3.zero
                end
                task.wait(0.01)
            end
        end
        if palletModel and palletModel.Parent then
            pcall(function() DeleteToyRE:FireServer(palletModel) end)
        end
        clickerPalletModel = nil
    end
    clickerTargetSec:Toggle({Text = "Grab Active", Flag = "ClickerGrabToggle", Default = false, Callback = function(v)
        clickerGrabActiveFlag = v
        if v then
            if clickerPalletModel and clickerPalletModel.Parent then
                pcall(function() DeleteToyRE:FireServer(clickerPalletModel) end)
                clickerPalletModel = nil
            end
            if clickerPalletHammerTask then task.cancel(clickerPalletHammerTask) end
            clickerPalletHammerTask = task.spawn(startClickerPalletHammer)
        else
            if clickerPalletHammerTask then
                task.cancel(clickerPalletHammerTask)
                clickerPalletHammerTask = nil
            end
            if clickerPalletModel and clickerPalletModel.Parent then
                pcall(function() DeleteToyRE:FireServer(clickerPalletModel) end)
                clickerPalletModel = nil
            end
        end
    end})
