    editorSec:Button({Text = "Export Positions", Callback = function()
        local positions = {}
        for model, _ in pairs(editorModels) do
            if model and model.Parent then
                local pivot = model:GetPivot()
                local pos = pivot.Position
                local rot = pivot - pivot.Position
                table.insert(positions, {
                    name = model.Name,
                    position = {x = math.round(pos.X * 100) / 100, y = math.round(pos.Y * 100) / 100, z = math.round(pos.Z * 100) / 100},
                    rotation = {
                        math.round(math.deg(math.atan2(rot.LookVector.Z, rot.LookVector.X)) * 100) / 100,
                        math.round(math.deg(math.asin(math.clamp(rot.UpVector.Y, -1, 1))) * 100) / 100,
                        0
                    }
                })
            end
        end
        if #positions == 0 then
            library:Notify({Title = "Editor", Description = "No objects to export", Time = 3})
            return
        end
        local json = HttpService:JSONEncode(positions)
        if setclipboard then
            setclipboard(json)
        elseif syn and syn.clipboard then
            syn.clipboard.set(json)
        end
        library:Notify({Title = "Editor", Description = "Copied " .. #positions .. " positions to clipboard", Time = 3})
    end})
end
do
    local sg = Instance.new("ScreenGui")
    sg.Name = "PingDisplay"
    sg.ResetOnSpawn = false
    sg.IgnoreGuiInset = true
    sg.DisplayOrder = 9999
    sg.Parent = LocalPlayer:WaitForChild("PlayerGui")
    local label = Instance.new("TextLabel")
    label.Name = "PingLabel"
