                __moduleReport[#__moduleReport + 1] = module.Name .. ": compile failed: " .. tostring(compileError)
                warn("[FTAP Unified] " .. __moduleReport[#__moduleReport])
            else
                if type(setfenv) == "function" then pcall(setfenv, fn, env) end
                local ok, resultOrError = pcall(fn)
                if ok then
                    __moduleReport[#__moduleReport + 1] = module.Name .. ": loaded"
                    print("[FTAP Unified] " .. module.Name .. " integrated into the RSC window")
                else
                    __moduleReport[#__moduleReport + 1] = module.Name .. ": runtime error: " .. tostring(resultOrError)
                    warn("[FTAP Unified] " .. __moduleReport[#__moduleReport])
